#[derive(Default)]
struct VacuumOperationTiming {
    establish_off_state_ms: f64,
    visual_home_ms: f64,
    rotation_reference_ms: f64,
    tip_measurement_ms: f64,
    target_centering_ms: f64,
    probe_xy_transit_ms: f64,
    probe_z_approach_ms: f64,
    vacuum_setup_ms: f64,
    contact_search_ms: f64,
    vacuum_cleanup_ms: f64,
    fine_z_reset_ms: f64,
    restore_ms: f64,
}

impl VacuumOperationTiming {
    fn json(&self) -> Value {
        json!({
            "establish_off_state_ms": self.establish_off_state_ms,
            "visual_home_ms": self.visual_home_ms,
            "rotation_reference_ms": self.rotation_reference_ms,
            "tip_measurement_ms": self.tip_measurement_ms,
            "target_centering_ms": self.target_centering_ms,
            "probe_xy_transit_ms": self.probe_xy_transit_ms,
            "probe_z_approach_ms": self.probe_z_approach_ms,
            "vacuum_setup_ms": self.vacuum_setup_ms,
            "contact_search_ms": self.contact_search_ms,
            "vacuum_cleanup_ms": self.vacuum_cleanup_ms,
            "fine_z_reset_ms": self.fine_z_reset_ms,
            "restore_ms": self.restore_ms,
        })
    }
}

fn elapsed_ms(started: Instant) -> f64 {
    started.elapsed().as_secs_f64() * 1_000.0
}

async fn record_camera_target_operation_timing(
    state: &AppState,
    operation_id: Uuid,
    mode: &str,
    simulated: bool,
    succeeded: bool,
    total_elapsed_ms: f64,
    camera_timing: Value,
) {
    if let Err(error) = state
        .machine
        .record_operation_event(
            "operation.camera_target_timing".into(),
            json!({
                "algorithm_version": CAMERA_TARGET_OPERATION_TIMING_ALGORITHM,
                "operation_id": operation_id,
                "mode": mode,
                "simulated": simulated,
                "succeeded": succeeded,
                "total_elapsed_ms": total_elapsed_ms,
                "clear_xy_feed_mm_per_min": state
                    .profile
                    .transit_motion
                    .clear_xy_feed_mm_per_min,
                "cameras": camera_timing,
            }),
        )
        .await
    {
        tracing::warn!(
            %error,
            %operation_id,
            %mode,
            "failed to record camera-target timing",
        );
    }
}

fn workspace_timing_distribution(samples: &[f64]) -> Value {
    if samples.is_empty() {
        return json!({
            "count": 0,
            "total_ms": 0.0,
            "mean_ms": null,
            "p95_ms": null,
            "maximum_ms": null,
        });
    }
    let total_ms = samples.iter().sum::<f64>();
    let mut ordered = samples.to_vec();
    ordered.sort_by(f64::total_cmp);
    let p95_index = ((ordered.len() * 95).div_ceil(100)).saturating_sub(1);
    json!({
        "count": samples.len(),
        "total_ms": total_ms,
        "mean_ms": total_ms / samples.len() as f64,
        "p95_ms": ordered[p95_index],
        "maximum_ms": ordered[ordered.len() - 1],
    })
}

fn record_workspace_motion_correction(
    timing: &mut WorkspaceScanTiming,
    planned: &PlannedMotion,
    park: bool,
) {
    let correction = [
        planned.correction.local_direction_x_mm,
        planned.correction.local_direction_y_mm,
    ];
    let magnitude = correction[0].hypot(correction[1]);
    if planned.correction.applied() {
        timing.corrected_moves = timing.corrected_moves.saturating_add(1);
    }
    timing.maximum_direction_correction_mm = timing.maximum_direction_correction_mm.max(magnitude);
    if park {
        timing.park_direction_correction_mm = Some(correction);
    }
}

fn record_workspace_capture(
    timing: &mut WorkspaceScanTiming,
    metadata: &velocitypnp_vision::CaptureMetadata,
) {
    if let Some(previous) = timing.tile_capture_sequences.last() {
        timing
            .capture_sequence_gaps
            .push(metadata.sequence.wrapping_sub(*previous));
    }
    timing
        .tile_discarded_capture_frames
        .push(metadata.settle_frames);
    timing.tile_capture_sequences.push(metadata.sequence);
    timing.camera_fourcc = Some(metadata.fourcc.clone());
    timing.camera_interval = Some([metadata.interval_numerator, metadata.interval_denominator]);
    timing
        .camera_timestamp_sources
        .insert(metadata.timestamp_source.as_str().into());
}

#[derive(Clone, PartialEq, Eq)]
struct ProfiledCameraSessionKey {
    device: PathBuf,
    width: u32,
    height: u32,
    pixel_format: CameraPixelFormat,
    frames_per_second: u32,
    timeout: Duration,
    controls: Vec<CameraControlUpdate>,
}

struct ScopedProfiledCamera {
    key: ProfiledCameraSessionKey,
    capture: Arc<PersistentGrayCapture>,
}

#[derive(Clone, Default)]
struct ProfiledCameraTiming {
    open_count: u32,
    open_failure_count: u32,
    capture_count: u32,
    capture_failure_count: u32,
    captured_frames: u32,
    discarded_frames: u32,
    open_ms: f64,
    capture_ms: f64,
}

#[derive(Default)]
struct ProfiledCaptureContext {
    sessions: HashMap<PathBuf, ScopedProfiledCamera>,
    timing: BTreeMap<String, ProfiledCameraTiming>,
}

impl ProfiledCaptureContext {
    fn timing_json(&self) -> Value {
        profiled_camera_timing_json(&self.timing, None)
    }
}

fn profiled_camera_timing_json(
    timing: &BTreeMap<String, ProfiledCameraTiming>,
    baseline: Option<&BTreeMap<String, ProfiledCameraTiming>>,
) -> Value {
    Value::Object(
        timing
            .iter()
            .map(|(role, timing)| {
                let baseline = baseline
                    .and_then(|baseline| baseline.get(role))
                    .cloned()
                    .unwrap_or_default();
                (
                    role.clone(),
                    json!({
                        "open_count": timing.open_count.saturating_sub(baseline.open_count),
                        "open_failure_count": timing.open_failure_count
                            .saturating_sub(baseline.open_failure_count),
                        "capture_count": timing.capture_count
                            .saturating_sub(baseline.capture_count),
                        "capture_failure_count": timing.capture_failure_count
                            .saturating_sub(baseline.capture_failure_count),
                        "captured_frames": timing.captured_frames
                            .saturating_sub(baseline.captured_frames),
                        "discarded_frames": timing.discarded_frames
                            .saturating_sub(baseline.discarded_frames),
                        "open_ms": (timing.open_ms - baseline.open_ms).max(0.0),
                        "capture_ms": (timing.capture_ms - baseline.capture_ms).max(0.0),
                    }),
                )
            })
            .collect(),
    )
}

