#[derive(Debug, Clone, Serialize)]
struct WorkspaceRefinementTargetResponse {
    target_index: u32,
    priority: u32,
    region: WorkspaceScanRegion,
    severity_score: f64,
    elevated_seams: u32,
    unresolved_seams: u32,
    maximum_disagreement_p95_luma: f64,
    maximum_correction_mm: f64,
    reason: String,
    completed_scan_id: Option<Uuid>,
    latest_scan_id: Option<Uuid>,
    latest_scan_status: Option<WorkspaceScanStatus>,
}

fn rank_workspace_refinement_targets(
    report: &WorkspaceSeamHealthReport,
    scans: &[WorkspaceScanReport],
    parent_scan_id: Uuid,
) -> Vec<WorkspaceRefinementTargetResponse> {
    let mut targets = report
        .target_regions
        .iter()
        .copied()
        .enumerate()
        .map(|(target_index, region)| {
            let mut elevated_seams = 0_u32;
            let mut unresolved_seams = 0_u32;
            let mut maximum_disagreement_p95_luma = 0.0_f64;
            let mut maximum_correction_mm = 0.0_f64;
            for seam in report.seams.iter().filter(|seam| {
                seam.status != WorkspaceSeamStatus::Healthy
                    && workspace_regions_overlap(region, seam.region)
            }) {
                match seam.status {
                    WorkspaceSeamStatus::Elevated => elevated_seams += 1,
                    WorkspaceSeamStatus::Unresolved => unresolved_seams += 1,
                    WorkspaceSeamStatus::Healthy => {}
                }
                maximum_disagreement_p95_luma =
                    maximum_disagreement_p95_luma.max(seam.disagreement_p95_luma);
                let correction_mm = seam
                    .correction_x_mm
                    .zip(seam.correction_y_mm)
                    .map_or(0.0, |(x_mm, y_mm)| x_mm.hypot(y_mm));
                maximum_correction_mm = maximum_correction_mm.max(correction_mm);
            }
            let disagreement_ratio = maximum_disagreement_p95_luma
                / report.disagreement_threshold_luma.max(1.0);
            let correction_ratio = maximum_correction_mm
                / report.material_shift_threshold_mm.max(f64::EPSILON);
            let area_mm2 = (region.x_max_mm - region.x_min_mm)
                * (region.y_max_mm - region.y_min_mm);
            let severity_score = f64::from(elevated_seams) * 4.0
                + f64::from(unresolved_seams) * 2.0
                + disagreement_ratio
                + correction_ratio
                + area_mm2.ln_1p() / 10.0;
            let matching = scans
                .iter()
                .filter(|scan| {
                    scan.parent_scan_id == Some(parent_scan_id)
                        && scan.refinement_target_index == Some(target_index as u32)
                        && scan
                            .refinement_algorithm_version
                            .as_deref()
                            .is_none_or(|version| version == report.algorithm_version)
                })
                .max_by_key(|scan| scan.updated_at);
            let completed = scans
                .iter()
                .filter(|scan| {
                    scan.parent_scan_id == Some(parent_scan_id)
                        && scan.refinement_target_index == Some(target_index as u32)
                        && scan.status == WorkspaceScanStatus::Succeeded
                        && scan
                            .refinement_algorithm_version
                            .as_deref()
                            .is_none_or(|version| version == report.algorithm_version)
                })
                .max_by_key(|scan| scan.updated_at);
            let reason = if elevated_seams == 0 && unresolved_seams == 0 {
                format!("localized disagreement over {area_mm2:.0} square millimeters")
            } else {
                format!(
                    "{elevated_seams} elevated and {unresolved_seams} unresolved seams; peak disagreement {maximum_disagreement_p95_luma:.1} luma"
                )
            };
            WorkspaceRefinementTargetResponse {
                target_index: target_index as u32,
                priority: 0,
                region,
                severity_score,
                elevated_seams,
                unresolved_seams,
                maximum_disagreement_p95_luma,
                maximum_correction_mm,
                reason,
                completed_scan_id: completed.map(|scan| scan.id),
                latest_scan_id: matching.map(|scan| scan.id),
                latest_scan_status: matching.map(|scan| scan.status),
            }
        })
        .collect::<Vec<_>>();
    targets.sort_by(|first, second| {
        second
            .severity_score
            .total_cmp(&first.severity_score)
            .then_with(|| first.target_index.cmp(&second.target_index))
    });
    for (index, target) in targets.iter_mut().enumerate() {
        target.priority = index as u32 + 1;
    }
    targets
}

fn workspace_regions_overlap(first: WorkspaceScanRegion, second: WorkspaceScanRegion) -> bool {
    first.x_min_mm < second.x_max_mm
        && first.x_max_mm > second.x_min_mm
        && first.y_min_mm < second.y_max_mm
        && first.y_max_mm > second.y_min_mm
}

fn effective_workspace_region_preset(
    specification: &WorkspaceScanSpecification,
    refinement: Option<&WorkspaceRefinementSource>,
) -> Option<WorkspaceRegionPreset> {
    if refinement.is_some() {
        Some(WorkspaceRegionPreset::InstalledPlates)
    } else {
        specification.region_preset
    }
}

async fn resolve_workspace_refinement_source(
    state: &AppState,
    specification: &WorkspaceScanSpecification,
) -> ApiResult<Option<WorkspaceRefinementSource>> {
    if specification.mode != WorkspaceScanMode::Refinement {
        if specification.refinement_target_index.is_some() {
            return Err(ApiError::bad_request(
                "refinement_target_index requires refinement mode",
            ));
        }
        return Ok(None);
    }
    if specification.region.is_some() || specification.region_preset.is_some() {
        return Err(ApiError::bad_request(
            "refinement mode selects its region from the parent scan",
        ));
    }
    let parent_scan_id = specification
        .parent_scan_id
        .ok_or_else(|| ApiError::bad_request("refinement mode requires parent_scan_id"))?;
    let target_index = specification
        .refinement_target_index
        .ok_or_else(|| ApiError::bad_request("refinement mode requires refinement_target_index"))?;
    let parent = state
        .store
        .get_workspace_scan(parent_scan_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("parent workspace scan not found"))?;
    if parent.status != WorkspaceScanStatus::Succeeded
        || parent.mode != WorkspaceScanMode::Reconnaissance
    {
        return Err(ApiError::bad_request(
            "workspace refinement requires a successful reconnaissance parent",
        ));
    }
    if !state.profile.accepts_profile_id(&parent.profile_id)
        || parent.calibration_id != specification.calibration_id
    {
        return Err(ApiError::bad_request(
            "workspace refinement must use its parent's profile and calibration",
        ));
    }
    let artifacts = reanalyze_retained_workspace_seams(state, &parent).await?;
    match artifacts.report.recommended_action {
        WorkspaceSeamHealthAction::TargetedRefinement
        | WorkspaceSeamHealthAction::IncreaseOverlap => {}
        WorkspaceSeamHealthAction::ReviewGeometry => {
            return Err(ApiError::bad_request(
                "workspace seam health requires geometry review before refinement",
            ));
        }
        WorkspaceSeamHealthAction::Accept => {
            return Err(ApiError::bad_request(
                "workspace seam health does not require refinement",
            ));
        }
    }
    let region = artifacts
        .report
        .target_regions
        .get(target_index as usize)
        .copied()
        .ok_or_else(|| {
            ApiError::bad_request("refinement_target_index is outside the target list")
        })?;
    Ok(Some(WorkspaceRefinementSource {
        parent_scan_id,
        profile_id: parent.profile_id,
        target_index,
        region,
        recommended_action: artifacts.report.recommended_action,
        algorithm_version: artifacts.report.algorithm_version,
    }))
}

async fn resolve_workspace_survey_parent(
    state: &AppState,
    specification: &WorkspaceScanSpecification,
) -> ApiResult<Option<WorkspaceScanReport>> {
    let Some(parent_scan_id) = specification.parent_scan_id else {
        return Ok(None);
    };
    if specification.mode == WorkspaceScanMode::Refinement {
        return Ok(None);
    }
    if specification.mode != WorkspaceScanMode::Survey {
        return Err(ApiError::bad_request(
            "parent_scan_id is supported only for survey and refinement scans",
        ));
    }
    let region = specification
        .region
        .ok_or_else(|| ApiError::bad_request("a child survey requires an explicit region"))?;
    let parent = state
        .store
        .get_workspace_scan(parent_scan_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("parent workspace scan not found"))?;
    if parent.status != WorkspaceScanStatus::Succeeded
        || parent.mode == WorkspaceScanMode::Refinement
        || parent.parent_scan_id.is_some()
    {
        return Err(ApiError::bad_request(
            "a child survey requires a successful full workspace parent",
        ));
    }
    if !state.profile.accepts_profile_id(&parent.profile_id)
        || parent.calibration_id != specification.calibration_id
    {
        return Err(ApiError::bad_request(
            "a child survey must use its parent's profile and calibration",
        ));
    }
    if region.x_min_mm < parent.region.x_min_mm
        || region.x_max_mm > parent.region.x_max_mm
        || region.y_min_mm < parent.region.y_min_mm
        || region.y_max_mm > parent.region.y_max_mm
    {
        return Err(ApiError::bad_request(
            "a child survey region must stay inside its parent scan",
        ));
    }
    Ok(Some(parent))
}

async fn reanalyze_retained_workspace_seams(
    state: &AppState,
    scan: &WorkspaceScanReport,
) -> ApiResult<WorkspaceSeamHealthArtifacts> {
    if scan.status != WorkspaceScanStatus::Succeeded
        || scan.mode != WorkspaceScanMode::Reconnaissance
    {
        return Err(ApiError::bad_request(
            "seam reanalysis requires a successful reconnaissance scan",
        ));
    }
    let summary = scan
        .seam_health
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("workspace scan has no seam diagnostics"))?;
    let read_artifact = |name: &str| -> ApiResult<Vec<u8>> {
        state
            .store
            .get_workspace_scan_artifact(scan.id, name)
            .map_err(ApiError::internal)?
            .map(|(_, data)| data)
            .ok_or_else(|| ApiError::not_found(format!("workspace artifact {name} not found")))
    };
    let mosaic = read_artifact(scan.mosaic_artifact_name.as_deref().unwrap_or("mosaic.png"))?;
    let disagreement = read_artifact(&summary.disagreement_artifact_name)?;
    let overlap_confidence = read_artifact(&summary.overlap_confidence_artifact_name)?;
    let report = read_artifact(&summary.report_artifact_name)?;
    let plan = WorkspaceScanPlan {
        region: scan.region,
        overlap_fraction: scan.overlap_fraction,
        output_mm_per_pixel: scan.output_mm_per_pixel,
        frame_width_px: scan.frame_width_px,
        frame_height_px: scan.frame_height_px,
        usable_pixel_bounds: scan.usable_pixel_bounds,
        rows: scan.rows,
        columns: scan.columns,
        tiles: scan.tiles.clone(),
    };
    tokio::task::spawn_blocking(move || {
        let mosaic = decode_gray_png(&mosaic)?;
        let disagreement = decode_gray_png(&disagreement)?;
        let overlap_confidence = decode_gray_png(&overlap_confidence)?;
        let prior: WorkspaceSeamHealthReport = serde_json::from_slice(&report)?;
        reanalyze_workspace_seam_health(&plan, &mosaic, &disagreement, &overlap_confidence, &prior)
    })
    .await
    .map_err(ApiError::internal)?
    .map_err(ApiError::internal)
}

async fn estimate_workspace_scan(
    State(state): State<AppState>,
    Json(body): Json<EstimateWorkspaceScanRequest>,
) -> ApiResult<Json<WorkspaceScanEstimate>> {
    resolve_workspace_survey_parent(&state, &body.specification).await?;
    let refinement = resolve_workspace_refinement_source(&state, &body.specification).await?;
    let top_profile = stored_camera_profile(&state, CameraRole::TopCamera)?;
    let (snapshot, top_camera_model) =
        load_workspace_camera_model(&state, body.specification.calibration_id)?;
    let (camera_model, surface_model, installed_camera_model, installed_geometry) =
        select_workspace_surface_models(
            &state,
            &snapshot,
            top_camera_model,
            effective_workspace_region_preset(&body.specification, refinement.as_ref()),
            body.specification.mode,
        )?;
    let status = state.machine.status();
    let current_pose = status.pose.unwrap_or(state.profile.home_pose);
    let motion_calibration = if status.simulated {
        None
    } else {
        Some(load_motion_calibration(
            &state,
            body.specification.calibration_id,
            "workspace scan estimate",
        )?)
    };
    let motion_planner = MotionPlanner::new(state.profile.bounds, motion_calibration);
    let (plan, estimate) = prepare_workspace_scan(
        &state,
        &body.specification,
        &top_profile,
        &camera_model,
        surface_model,
        installed_camera_model.as_ref(),
        installed_geometry.as_ref(),
        refinement.as_ref(),
        current_pose,
        motion_planner.maximum_controller_margin_mm(),
        controller_xy_acceleration_mm_per_s2(&status),
    )?;
    validate_workspace_motion_plan(
        &state.profile,
        &motion_planner,
        current_pose,
        &plan,
        estimate.feed_mm_per_min,
    )?;
    Ok(Json(estimate))
}

async fn start_workspace_scan(
    State(state): State<AppState>,
    Json(body): Json<StartWorkspaceScanRequest>,
) -> ApiResult<(StatusCode, Json<StartWorkspaceScanResponse>)> {
    if !body.confirmed_external_safety_checks {
        return Err(ApiError::bad_request(
            "workspace scan requires confirmation that the region and travel envelope are clear, both nozzles are level, and power isolation is reachable",
        ));
    }
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed {
        return Err(ApiError::bad_request(
            "workspace scan requires a homed ready machine",
        ));
    }
    if !status.simulated && status.calibration_revision != Some(body.specification.calibration_id) {
        return Err(ApiError::bad_request(format!(
            "physical workspace scanning requires fine XYZ homing with calibration {}",
            body.specification.calibration_id,
        )));
    }
    let current_pose = status
        .pose
        .ok_or_else(|| ApiError::bad_request("workspace scan requires a known machine pose"))?;
    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(&state)?;
    ensure_no_active_board_registrations(&state)?;
    ensure_no_active_board_surface_measurements(&state)?;
    ensure_no_active_strip_feeder_holdouts(&state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(&state)?;
    let survey_parent = resolve_workspace_survey_parent(&state, &body.specification).await?;
    let refinement = resolve_workspace_refinement_source(&state, &body.specification).await?;
    let top_profile = stored_camera_profile(&state, CameraRole::TopCamera)?;
    let top_path = camera_path_for_role(CameraRole::TopCamera)?;
    let (snapshot, top_camera_model) =
        load_workspace_camera_model(&state, body.specification.calibration_id)?;
    let (camera_model, surface_model, installed_camera_model, installed_geometry) =
        select_workspace_surface_models(
            &state,
            &snapshot,
            top_camera_model,
            effective_workspace_region_preset(&body.specification, refinement.as_ref()),
            body.specification.mode,
        )?;
    let motion_calibration = if status.simulated {
        None
    } else {
        Some(load_motion_calibration(
            &state,
            body.specification.calibration_id,
            "workspace scan motion",
        )?)
    };
    let motion_planner = MotionPlanner::new(state.profile.bounds, motion_calibration);
    let (plan, estimate) = prepare_workspace_scan(
        &state,
        &body.specification,
        &top_profile,
        &camera_model,
        surface_model,
        installed_camera_model.as_ref(),
        installed_geometry.as_ref(),
        refinement.as_ref(),
        current_pose,
        motion_planner.maximum_controller_margin_mm(),
        controller_xy_acceleration_mm_per_s2(&status),
    )?;
    validate_workspace_motion_plan(
        &state.profile,
        &motion_planner,
        current_pose,
        &plan,
        estimate.feed_mm_per_min,
    )?;
    state
        .machine
        .renew_lease(body.lease_id, CALIBRATION_LEASE_SECONDS)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;

    let operation = Operation::pending("vision.workspace_scan");
    let lineage = refinement.as_ref().map_or_else(
        || {
            survey_parent.as_ref().map_or(
                WorkspaceScanLineage::Standalone,
                WorkspaceScanLineage::Survey,
            )
        },
        WorkspaceScanLineage::Refinement,
    );
    let scan = pending_workspace_scan(
        &state,
        operation.id,
        snapshot.id,
        lineage,
        &plan,
        &estimate,
        WorkspaceRefinementQueueMetadata::default(),
    );
    state
        .store
        .put_operation(&operation)
        .map_err(ApiError::internal)?;
    state
        .store
        .put_workspace_scan(&scan)
        .map_err(ApiError::internal)?;
    drop(admission_guard);

    let returned = StartWorkspaceScanResponse {
        scan: scan.clone(),
        operation: operation.clone(),
        estimate,
    };
    let task_state = state.clone();
    spawn_prepared_operation(
        state,
        operation,
        execute_workspace_scan(
            task_state,
            scan,
            plan,
            camera_model,
            installed_camera_model,
            top_profile,
            top_path,
            motion_planner,
            body.lease_id,
        ),
    );
    Ok((StatusCode::ACCEPTED, Json(returned)))
}

fn ensure_no_active_workspace_scans(state: &AppState) -> ApiResult<()> {
    let active = state
        .store
        .list_workspace_scans()
        .map_err(ApiError::internal)?
        .into_iter()
        .find(|scan| {
            matches!(
                scan.status,
                WorkspaceScanStatus::Pending | WorkspaceScanStatus::Running
            )
        });
    if let Some(scan) = active {
        return Err(ApiError::bad_request(format!(
            "workspace scan {} is already active",
            scan.id
        )));
    }
    Ok(())
}

fn ensure_no_active_board_registrations(state: &AppState) -> ApiResult<()> {
    let active = state
        .store
        .list_board_registrations()
        .map_err(ApiError::internal)?
        .into_iter()
        .find(|registration| {
            matches!(
                registration.status,
                OperationStatus::Pending | OperationStatus::Running
            )
        });
    if let Some(registration) = active {
        return Err(ApiError::bad_request(format!(
            "board registration {} is already active",
            registration.id
        )));
    }
    Ok(())
}

fn ensure_no_active_board_surface_measurements(state: &AppState) -> ApiResult<()> {
    let active = state
        .store
        .list_board_surface_measurements()
        .map_err(ApiError::internal)?
        .into_iter()
        .find(|measurement| {
            matches!(
                measurement.status,
                OperationStatus::Pending | OperationStatus::Running
            )
        });
    if let Some(measurement) = active {
        return Err(ApiError::bad_request(format!(
            "board surface measurement {} is already active",
            measurement.id
        )));
    }
    Ok(())
}

fn pending_workspace_scan(
    state: &AppState,
    operation_id: Uuid,
    calibration_id: Uuid,
    lineage: WorkspaceScanLineage<'_>,
    plan: &WorkspaceScanPlan,
    estimate: &WorkspaceScanEstimate,
    queue: WorkspaceRefinementQueueMetadata,
) -> WorkspaceScanReport {
    let now = Utc::now();
    let (profile_id, parent_scan_id, refinement) = match lineage {
        WorkspaceScanLineage::Standalone => (state.profile.id.clone(), None, None),
        WorkspaceScanLineage::Survey(parent) => (parent.profile_id.clone(), Some(parent.id), None),
        WorkspaceScanLineage::Refinement(source) => (
            source.profile_id.clone(),
            Some(source.parent_scan_id),
            Some(source),
        ),
    };
    WorkspaceScanReport {
        id: Uuid::new_v4(),
        operation_id,
        calibration_id,
        profile_id,
        parent_scan_id,
        refinement_target_index: refinement.map(|source| source.target_index),
        refinement_algorithm_version: refinement.map(|source| source.algorithm_version.clone()),
        refinement_batch_operation_id: queue.batch_operation_id,
        refinement_priority: queue.priority,
        refinement_severity_score: queue.severity_score,
        refinement_priority_algorithm_version: queue
            .batch_operation_id
            .map(|_| WORKSPACE_REFINEMENT_PRIORITY_ALGORITHM.into()),
        created_at: now,
        updated_at: now,
        status: WorkspaceScanStatus::Pending,
        mode: estimate.mode,
        artifact_retention: estimate.artifact_retention,
        surface_model: estimate.surface_model,
        region: plan.region,
        raster_transform: Some(estimate.raster_transform),
        overlap_fraction: plan.overlap_fraction,
        output_mm_per_pixel: plan.output_mm_per_pixel,
        feed_mm_per_min: estimate.feed_mm_per_min,
        capture_settle_frames: estimate.capture_settle_frames,
        discarded_capture_frames: 0,
        timestamp_fresh_frames: 0,
        frame_width_px: plan.frame_width_px,
        frame_height_px: plan.frame_height_px,
        usable_pixel_bounds: plan.usable_pixel_bounds,
        rows: plan.rows,
        columns: plan.columns,
        planned_tiles: plan.tiles.len() as u32,
        captured_tiles: 0,
        mosaic_width_px: None,
        mosaic_height_px: None,
        covered_fraction: None,
        nominal_fallback_fraction: 0.0,
        estimated_duration_seconds: estimate.estimated_duration_seconds,
        estimated_retained_bytes: estimate.estimated_retained_bytes,
        artifact_quota_bytes: estimate.artifact_quota_bytes,
        retained_artifact_bytes: 0,
        persistent_capture: estimate.persistent_capture,
        accepted_registrations: 0,
        attempted_registrations: 0,
        tiles: plan.tiles.clone(),
        registrations: Vec::new(),
        mosaic_artifact_name: None,
        mosaic_layers: Vec::new(),
        parallax: None,
        height_map: None,
        seam_health: None,
        refinement_composite: None,
        board_discovery: None,
        strip_feeder_inventory: None,
        change_set: None,
        warnings: estimate.warnings.clone(),
        failure: None,
    }
}

#[allow(clippy::too_many_arguments)]
fn prepare_workspace_scan(
    state: &AppState,
    specification: &WorkspaceScanSpecification,
    top_profile: &CameraProfile,
    camera_model: &PlanarCameraModel,
    surface_model: WorkspaceSurfaceModel,
    installed_camera_model: Option<&PlanarCameraModel>,
    installed_geometry: Option<&InstalledPlateGeometryReport>,
    refinement: Option<&WorkspaceRefinementSource>,
    start_pose: Pose,
    controller_margin_mm: [f64; 2],
    xy_acceleration_mm_per_s2: Option<f64>,
) -> ApiResult<(WorkspaceScanPlan, WorkspaceScanEstimate)> {
    let mut warnings = Vec::new();
    let reconnaissance = specification.mode == WorkspaceScanMode::Reconnaissance;
    let refinement_mode = specification.mode == WorkspaceScanMode::Refinement;
    let streaming = specification.mode != WorkspaceScanMode::Precision;
    if installed_camera_model.is_some() {
        warnings.push(
            "mixed-height scan will produce separate working-plane and installed-plate mosaics"
                .into(),
        );
    }
    let planning_camera_model = installed_camera_model
        .map(|installed_model| {
            interpolate_planar_camera_model(
                camera_model,
                installed_model,
                MIN_WORKSPACE_SURFACE_FRACTION,
            )
            .map_err(ApiError::bad_request)
        })
        .transpose()?
        .unwrap_or_else(|| camera_model.clone());
    let preset_region = match effective_workspace_region_preset(specification, refinement) {
        Some(WorkspaceRegionPreset::InstalledPlates) => {
            let plate_region = installed_plates_scan_region(&state.profile, installed_geometry)?;
            let reachable_region = workspace_camera_reachable_region(
                camera_model,
                state.profile.bounds,
                top_profile.width,
                top_profile.height,
            )
            .map_err(|error| ApiError::bad_request(error.to_string()))?;
            let reachable_region = inset_workspace_region(reachable_region, controller_margin_mm)?;
            if controller_margin_mm[0] > 0.0 || controller_margin_mm[1] > 0.0 {
                warnings.push(format!(
                    "top-camera coverage reserves {:.3} mm X and {:.3} mm Y for calibrated controller corrections",
                    controller_margin_mm[0], controller_margin_mm[1],
                ));
            }
            let clipped_region = intersect_workspace_regions(plate_region, reachable_region)?;
            if let Some(warning) = workspace_camera_clip_warning(plate_region, clipped_region) {
                warnings.push(warning);
            }
            Some(clipped_region)
        }
        None => None,
    };
    let region = if let Some(refinement) = refinement {
        let preset_region = preset_region.ok_or_else(|| {
            ApiError::bad_request("workspace refinement requires installed-plate coverage")
        })?;
        warnings.push(format!(
            "refinement target {} comes from {} using {} and action {}",
            refinement.target_index,
            refinement.parent_scan_id,
            refinement.algorithm_version,
            workspace_seam_action_name(refinement.recommended_action),
        ));
        intersect_workspace_regions(refinement.region, preset_region)?
    } else {
        match (specification.region, preset_region) {
            (Some(region), None) => region,
            (None, Some(region)) => region,
            (Some(region), Some(preset_region)) => {
                intersect_workspace_regions(region, preset_region)?
            }
            (None, None) => {
                return Err(ApiError::bad_request(
                    "workspace scan requires region or region_preset",
                ));
            }
        }
    };
    if reconnaissance {
        warnings.push(
            "reconnaissance uses the installed-plate projection and monotonic camera timestamps; raised objects can have local seams until a focused height scan"
                .into(),
        );
    }
    let requested_overlap = specification.overlap_fraction.unwrap_or(if reconnaissance {
        RECONNAISSANCE_OVERLAP
    } else if refinement_mode {
        DEFAULT_LAYERED_WORKSPACE_OVERLAP
    } else if streaming {
        DEFAULT_SURVEY_OVERLAP
    } else {
        0.35
    });
    let minimum_requested_overlap = if reconnaissance {
        MIN_RECONNAISSANCE_OVERLAP
    } else {
        MIN_WORKSPACE_OVERLAP
    };
    if !(minimum_requested_overlap..=0.75).contains(&requested_overlap) {
        return Err(ApiError::bad_request(format!(
            "workspace overlap must be between {minimum_requested_overlap:.2} and 0.75 for this mode"
        )));
    }
    let minimum_layered_overlap = if installed_camera_model.is_some() {
        layered_workspace_overlap(minimum_layered_workspace_overlap(
            camera_model,
            &planning_camera_model,
        )?)
    } else {
        minimum_requested_overlap
    };
    let overlap_fraction = requested_overlap.max(minimum_layered_overlap);
    if overlap_fraction > requested_overlap {
        warnings.push(format!(
            "workspace overlap was raised from {:.1}% to {:.1}% for reliable layered reconstruction",
            requested_overlap * 100.0,
            overlap_fraction * 100.0,
        ));
    }
    let output_mm_per_pixel = specification
        .output_mm_per_pixel
        .or_else(|| reconnaissance.then_some(RECONNAISSANCE_OUTPUT_MM_PER_PIXEL))
        .or_else(|| streaming.then_some(DEFAULT_SURVEY_OUTPUT_MM_PER_PIXEL));
    if streaming && output_mm_per_pixel.is_some_and(|scale| scale < 0.05) {
        return Err(ApiError::bad_request(
            "survey output_mm_per_pixel must be at least 0.05",
        ));
    }
    let artifact_retention = specification
        .artifact_retention
        .unwrap_or(if refinement_mode {
            WorkspaceArtifactRetention::TransientSources
        } else if streaming {
            WorkspaceArtifactRetention::MosaicOnly
        } else {
            WorkspaceArtifactRetention::FullSources
        });
    if artifact_retention == WorkspaceArtifactRetention::TransientSources
        && (!matches!(
            specification.mode,
            WorkspaceScanMode::Survey | WorkspaceScanMode::Refinement
        ) || installed_camera_model.is_none())
    {
        return Err(ApiError::bad_request(
            "transient_sources requires a layered installed-plate survey",
        ));
    }
    let tile_limit = if artifact_retention == WorkspaceArtifactRetention::TransientSources {
        MAX_CHUNKED_WORKSPACE_SURVEY_TILES
    } else if streaming {
        MAX_WORKSPACE_SURVEY_TILES
    } else {
        MAX_WORKSPACE_SCAN_TILES
    };
    let max_tiles = specification.max_tiles.unwrap_or(tile_limit);
    if max_tiles == 0 || max_tiles > tile_limit {
        return Err(ApiError::bad_request(format!(
            "workspace max_tiles must be between 1 and {tile_limit} for this mode"
        )));
    }
    if installed_camera_model.is_some()
        && matches!(
            artifact_retention,
            WorkspaceArtifactRetention::FullSources | WorkspaceArtifactRetention::TransientSources
        )
    {
        warnings.push(if artifact_retention == WorkspaceArtifactRetention::TransientSources {
            "transient source chunks will produce a measured surface-height map and height-corrected mosaic without retaining source frames"
                .into()
        } else {
            "full source retention will also produce a measured surface-height map and height-corrected mosaic"
                .into()
        });
    }
    let default_quota = if streaming {
        DEFAULT_SURVEY_ARTIFACT_QUOTA_BYTES
    } else {
        DEFAULT_PRECISION_ARTIFACT_QUOTA_BYTES
    };
    let artifact_quota_bytes = specification.artifact_quota_bytes.unwrap_or(default_quota);
    if artifact_quota_bytes == 0 || artifact_quota_bytes > MAX_WORKSPACE_ARTIFACT_QUOTA_BYTES {
        return Err(ApiError::bad_request(format!(
            "workspace artifact quota must be between 1 and {MAX_WORKSPACE_ARTIFACT_QUOTA_BYTES} bytes"
        )));
    }
    let visual = state
        .profile
        .visual_homing
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let feed_mm_per_min = workspace_scan_feed(
        &state.profile,
        specification.mode,
        specification.feed_mm_per_min,
    )?;
    let mut plan = plan_workspace_scan(
        region,
        camera_model,
        state.profile.bounds,
        visual.seed_pose.z_mm,
        start_pose.rotation_deg,
        top_profile.width,
        top_profile.height,
        overlap_fraction,
        output_mm_per_pixel,
        max_tiles,
        if streaming {
            MAX_WORKSPACE_SURVEY_PIXELS
        } else {
            MAX_WORKSPACE_MOSAIC_PIXELS
        },
    )
    .map_err(|error| ApiError::bad_request(error.to_string()))?;
    for tile in &mut plan.tiles {
        tile.artifact_name = match artifact_retention {
            WorkspaceArtifactRetention::FullSources => format!("tile-{:03}.png", tile.index),
            WorkspaceArtifactRetention::Thumbnails => {
                format!("thumbnail-{:03}.png", tile.index)
            }
            WorkspaceArtifactRetention::TransientSources
            | WorkspaceArtifactRetention::MosaicOnly => String::new(),
        };
    }
    let mut estimate = workspace_scan_estimate(
        &plan,
        WorkspaceScanEstimateContext {
            mode: specification.mode,
            artifact_retention,
            surface_model,
            surface_models: if installed_camera_model.is_some() {
                vec![
                    WorkspaceSurfaceModel::TopCameraWorkingPlane,
                    WorkspaceSurfaceModel::InstalledPlatePlanes,
                ]
            } else {
                vec![surface_model]
            },
            artifact_quota_bytes,
            top_profile,
            park_pose: Pose {
                x_mm: visual.seed_pose.x_mm,
                y_mm: visual.seed_pose.y_mm,
                z_mm: visual.seed_pose.z_mm,
                rotation_deg: start_pose.rotation_deg,
            },
            park_feed_mm_per_min: state.profile.transit_motion.clear_xy_feed_mm_per_min,
            start_pose,
            feed_mm_per_min,
            xy_acceleration_mm_per_s2,
        },
    );
    estimate.warnings = warnings;
    if artifact_retention == WorkspaceArtifactRetention::TransientSources {
        let source_bytes = estimated_workspace_source_bytes(&plan);
        let chunks = estimate
            .mosaic_height_px
            .div_ceil(WORKSPACE_HEIGHT_CHUNK_PIXEL_ROWS);
        estimate.warnings.push(format!(
            "chunked reconstruction will use {chunks} output-row chunks and up to {source_bytes} transient source bytes; transient frames are deleted after reconstruction"
        ));
    }
    if estimate.estimated_retained_bytes > artifact_quota_bytes {
        return Err(ApiError::bad_request(format!(
            "workspace scan estimates {} retained bytes, above the quota of {artifact_quota_bytes}; choose mosaic_only, increase output scale, reduce the region, or raise the quota",
            estimate.estimated_retained_bytes
        )));
    }
    Ok((plan, estimate))
}

fn estimated_workspace_source_bytes(plan: &WorkspaceScanPlan) -> u64 {
    u64::from(plan.frame_width_px) * u64::from(plan.frame_height_px) * plan.tiles.len() as u64 * 11
        / 10
}

fn layered_workspace_overlap(geometric_minimum: f64) -> f64 {
    geometric_minimum.max(DEFAULT_LAYERED_WORKSPACE_OVERLAP)
}

fn minimum_layered_workspace_overlap(
    working_model: &PlanarCameraModel,
    highest_surface_model: &PlanarCameraModel,
) -> ApiResult<f64> {
    let working_scale = working_model
        .local_mm_per_pixel(working_model.center_x_px, working_model.center_y_px)
        .ok_or_else(|| ApiError::bad_request("working-plane camera scale is unavailable"))?;
    let highest_scale = highest_surface_model
        .local_mm_per_pixel(
            highest_surface_model.center_x_px,
            highest_surface_model.center_y_px,
        )
        .ok_or_else(|| ApiError::bad_request("high-surface camera scale is unavailable"))?;
    let overlap = (1.0 - highest_scale / working_scale + 0.05).max(0.2);
    if !overlap.is_finite() || overlap > 0.75 {
        return Err(ApiError::bad_request(
            "calibrated surface range needs more than 75% workspace overlap",
        ));
    }
    Ok(overlap)
}

fn select_workspace_surface_models(
    state: &AppState,
    snapshot: &CalibrationSnapshot,
    top_camera_model: PlanarCameraModel,
    region_preset: Option<WorkspaceRegionPreset>,
    mode: WorkspaceScanMode,
) -> ApiResult<(
    PlanarCameraModel,
    WorkspaceSurfaceModel,
    Option<PlanarCameraModel>,
    Option<InstalledPlateGeometryReport>,
)> {
    if region_preset != Some(WorkspaceRegionPreset::InstalledPlates) {
        if mode == WorkspaceScanMode::Reconnaissance {
            return Err(ApiError::bad_request(
                "reconnaissance mode requires the installed_plates region preset",
            ));
        }
        return Ok((
            top_camera_model,
            WorkspaceSurfaceModel::TopCameraWorkingPlane,
            None,
            None,
        ));
    }
    if !crate::calibration_artifacts::artifact_tree_is_current(
        state,
        snapshot,
        CalibrationArtifactId::InstalledPlateGeometry,
    ) {
        return Err(ApiError::bad_request(
            "installed-plates scan requires current installed plate geometry",
        ));
    }
    let geometry: InstalledPlateGeometryReport = serde_json::from_value(
        crate::calibration_artifacts::artifact_result_value(
            snapshot,
            CalibrationArtifactId::InstalledPlateGeometry,
        )
        .map_err(ApiError::bad_request)?,
    )
    .map_err(|error| {
        ApiError::bad_request(format!(
            "stored installed plate geometry is invalid: {error}"
        ))
    })?;
    if !geometry.passed {
        return Err(ApiError::bad_request(
            "installed-plates scan requires passing installed plate geometry",
        ));
    }
    let profile = state
        .profile
        .installed_geometry_calibration
        .as_ref()
        .ok_or_else(|| {
            ApiError::bad_request("active profile does not define installed plate geometry")
        })?;
    let mut mappings = Vec::new();
    for plate in &profile.plates {
        let mapping = geometry
            .registrations
            .iter()
            .find(|registration| registration.plate_id == plate.id && registration.passed)
            .and_then(|registration| registration.pixel_error_to_machine_mm)
            .ok_or_else(|| {
                ApiError::bad_request(format!(
                    "installed plate {} has no passing local camera map",
                    plate.id
                ))
            })?;
        mappings.push(mapping);
    }
    if mappings.is_empty() {
        return Err(ApiError::bad_request(
            "installed plate geometry contains no local camera maps",
        ));
    }
    let mut mean_mapping = [[0.0; 2]; 2];
    for mapping in &mappings {
        for axis in 0..2 {
            for pixel_axis in 0..2 {
                mean_mapping[axis][pixel_axis] += mapping[axis][pixel_axis];
            }
        }
    }
    for axis in &mut mean_mapping {
        for value in axis {
            *value /= mappings.len() as f64;
        }
    }
    let model = rescale_planar_camera_model(&top_camera_model, mean_mapping)
        .map_err(ApiError::bad_request)?;
    if mode == WorkspaceScanMode::Reconnaissance {
        Ok((
            model,
            WorkspaceSurfaceModel::InstalledPlatePlanes,
            None,
            Some(geometry),
        ))
    } else {
        Ok((
            top_camera_model,
            WorkspaceSurfaceModel::TopCameraWorkingPlane,
            Some(model),
            Some(geometry),
        ))
    }
}

fn installed_plates_scan_region(
    profile: &MachineProfile,
    geometry: Option<&InstalledPlateGeometryReport>,
) -> ApiResult<WorkspaceScanRegion> {
    let visual = profile
        .visual_homing
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let installed = profile
        .installed_geometry_calibration
        .as_ref()
        .ok_or_else(|| {
            ApiError::bad_request("active profile does not define installed plate geometry")
        })?;
    let mut min_x = f64::INFINITY;
    let mut max_x = f64::NEG_INFINITY;
    let mut min_y = f64::INFINITY;
    let mut max_y = f64::NEG_INFINITY;
    for plate in &installed.plates {
        if plate.column_count == 0 || plate.row_count == 0 {
            continue;
        }
        let fitted_model = geometry.and_then(|report| {
            report
                .plates
                .iter()
                .find(|fit| fit.plate_id == plate.id && fit.passed)
                .map(|fit| fit.model)
        });
        // The V3 plate source puts its outline one grid pitch outside the
        // first and last feature centers. Use those source-derived corners
        // so the preset includes the complete installed PCB surface.
        for column in [-1.0, f64::from(plate.column_count)] {
            for row in [-1.0, f64::from(plate.row_count)] {
                let nominal_x = visual.fiducial_x_mm
                    + plate.origin_offset_x_mm
                    + column * plate.column_step_x_mm
                    + row * plate.row_step_x_mm;
                let nominal_y = visual.fiducial_y_mm
                    + plate.origin_offset_y_mm
                    + column * plate.column_step_y_mm
                    + row * plate.row_step_y_mm;
                let [x, y] = fitted_model
                    .map(|model| model.apply(nominal_x, nominal_y))
                    .unwrap_or([nominal_x, nominal_y]);
                min_x = min_x.min(x);
                max_x = max_x.max(x);
                min_y = min_y.min(y);
                max_y = max_y.max(y);
            }
        }
    }
    let region = WorkspaceScanRegion {
        x_min_mm: min_x,
        x_max_mm: max_x,
        y_min_mm: min_y,
        y_max_mm: max_y,
    };
    region.validate().map_err(ApiError::bad_request)?;
    Ok(region)
}

fn intersect_workspace_regions(
    requested: WorkspaceScanRegion,
    reachable: WorkspaceScanRegion,
) -> ApiResult<WorkspaceScanRegion> {
    let intersection = WorkspaceScanRegion {
        x_min_mm: requested.x_min_mm.max(reachable.x_min_mm),
        x_max_mm: requested.x_max_mm.min(reachable.x_max_mm),
        y_min_mm: requested.y_min_mm.max(reachable.y_min_mm),
        y_max_mm: requested.y_max_mm.min(reachable.y_max_mm),
    };
    intersection.validate().map_err(|_| {
        ApiError::bad_request("installed plates are outside reachable top-camera coverage")
    })?;
    Ok(intersection)
}

fn inset_workspace_region(
    region: WorkspaceScanRegion,
    controller_margin_mm: [f64; 2],
) -> ApiResult<WorkspaceScanRegion> {
    if controller_margin_mm
        .iter()
        .any(|value| !value.is_finite() || *value < 0.0)
    {
        return Err(ApiError::bad_request(
            "calibrated controller margin is invalid",
        ));
    }
    let inset = WorkspaceScanRegion {
        x_min_mm: region.x_min_mm + controller_margin_mm[0],
        x_max_mm: region.x_max_mm - controller_margin_mm[0],
        y_min_mm: region.y_min_mm + controller_margin_mm[1],
        y_max_mm: region.y_max_mm - controller_margin_mm[1],
    };
    inset.validate().map_err(|_| {
        ApiError::bad_request("calibrated controller margin removes all camera coverage")
    })?;
    Ok(inset)
}

fn workspace_camera_clip_warning(
    requested: WorkspaceScanRegion,
    clipped: WorkspaceScanRegion,
) -> Option<String> {
    const EPSILON_MM: f64 = 1e-6;
    let mut edges = Vec::new();
    if clipped.x_min_mm > requested.x_min_mm + EPSILON_MM {
        edges.push("X-min");
    }
    if clipped.x_max_mm < requested.x_max_mm - EPSILON_MM {
        edges.push("X-max");
    }
    if clipped.y_min_mm > requested.y_min_mm + EPSILON_MM {
        edges.push("Y-min");
    }
    if clipped.y_max_mm < requested.y_max_mm - EPSILON_MM {
        edges.push("Y-max");
    }
    (!edges.is_empty()).then(|| {
        format!(
            "installed plate outline exceeds top-camera coverage at {}; scan region is clipped to reachable optical coverage",
            edges.join(", ")
        )
    })
}

fn workspace_scan_feed(
    profile: &MachineProfile,
    mode: WorkspaceScanMode,
    requested: Option<f64>,
) -> ApiResult<f64> {
    let maximum = profile.transit_motion.clear_xy_feed_mm_per_min;
    let default = if mode != WorkspaceScanMode::Precision {
        maximum
    } else {
        profile.default_feed_mm_per_min
    };
    let feed = requested.unwrap_or(default);
    if !feed.is_finite() || feed <= 0.0 || feed > maximum {
        return Err(ApiError::bad_request(format!(
            "workspace feed must be above zero and no greater than {maximum} mm/min",
        )));
    }
    Ok(feed)
}

fn validate_workspace_motion_plan(
    profile: &MachineProfile,
    planner: &MotionPlanner,
    current_pose: Pose,
    plan: &WorkspaceScanPlan,
    feed_mm_per_min: f64,
) -> ApiResult<()> {
    let mut motion = planner
        .initial_state(current_pose)
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    let mut capture_sequence = plan.tiles.iter().collect::<Vec<_>>();
    capture_sequence.sort_by_key(|tile| tile.capture_order);
    for tile in capture_sequence {
        let planned = planner
            .plan(
                &motion,
                tile.nominal_pose,
                feed_mm_per_min,
                MotionMode::Calibrated,
            )
            .map_err(|error| {
                ApiError::bad_request(format!(
                    "workspace scan feed lacks direction-response evidence: {error}"
                ))
            })?;
        planner
            .commit(&mut motion, &planned, planned.controller_target)
            .map_err(|error| ApiError::bad_request(error.to_string()))?;
    }
    let visual = profile
        .visual_homing
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let park_target = visual
        .seed_pose
        .resolve(motion.logical_pose)
        .ok_or_else(|| ApiError::bad_request("workspace datum park target is invalid"))?;
    planner
        .plan(
            &motion,
            park_target,
            profile.transit_motion.clear_xy_feed_mm_per_min,
            MotionMode::Calibrated,
        )
        .map_err(|error| {
            ApiError::bad_request(format!(
                "workspace datum park lacks direction-response evidence: {error}"
            ))
        })?;
    Ok(())
}

struct WorkspaceScanEstimateContext<'a> {
    mode: WorkspaceScanMode,
    artifact_retention: WorkspaceArtifactRetention,
    surface_model: WorkspaceSurfaceModel,
    surface_models: Vec<WorkspaceSurfaceModel>,
    artifact_quota_bytes: u64,
    top_profile: &'a CameraProfile,
    park_pose: Pose,
    park_feed_mm_per_min: f64,
    start_pose: Pose,
    feed_mm_per_min: f64,
    xy_acceleration_mm_per_s2: Option<f64>,
}

fn estimated_linear_motion_seconds(
    distance_mm: f64,
    feed_mm_per_min: f64,
    acceleration_mm_per_s2: Option<f64>,
) -> f64 {
    if distance_mm <= 0.0 {
        return 0.0;
    }
    let speed_mm_per_s = feed_mm_per_min / 60.0;
    let Some(acceleration_mm_per_s2) = acceleration_mm_per_s2 else {
        return distance_mm / speed_mm_per_s;
    };
    let full_speed_distance_mm = speed_mm_per_s * speed_mm_per_s / acceleration_mm_per_s2;
    if distance_mm >= full_speed_distance_mm {
        distance_mm / speed_mm_per_s + speed_mm_per_s / acceleration_mm_per_s2
    } else {
        2.0 * (distance_mm / acceleration_mm_per_s2).sqrt()
    }
}

fn controller_xy_acceleration_mm_per_s2(status: &velocitypnp_domain::MachineStatus) -> Option<f64> {
    let settings = &status.controller.as_ref()?.settings;
    let x = *settings
        .max_acceleration_units_per_second_squared
        .get("X")?;
    let y = *settings
        .max_acceleration_units_per_second_squared
        .get("Y")?;
    let travel = *settings
        .motion_acceleration_units_per_second_squared
        .get("T")?;
    let values = [x, y, travel];
    if values
        .iter()
        .any(|value| !value.is_finite() || *value <= 0.0)
    {
        return None;
    }
    values.into_iter().reduce(f64::min)
}

fn workspace_scan_estimate(
    plan: &WorkspaceScanPlan,
    context: WorkspaceScanEstimateContext<'_>,
) -> WorkspaceScanEstimate {
    let WorkspaceScanEstimateContext {
        mode,
        artifact_retention,
        surface_model,
        surface_models,
        artifact_quota_bytes,
        top_profile,
        park_pose,
        park_feed_mm_per_min,
        start_pose,
        feed_mm_per_min,
        xy_acceleration_mm_per_s2,
    } = context;
    let mut sequence = plan.tiles.iter().collect::<Vec<_>>();
    sequence.sort_by_key(|tile| tile.capture_order);
    let mut prior = start_pose;
    let mut movement_seconds = 0.0;
    for tile in &sequence {
        let distance_mm =
            (tile.nominal_pose.x_mm - prior.x_mm).hypot(tile.nominal_pose.y_mm - prior.y_mm);
        movement_seconds += estimated_linear_motion_seconds(
            distance_mm,
            feed_mm_per_min,
            xy_acceleration_mm_per_s2,
        );
        prior = tile.nominal_pose;
    }
    let park_distance_mm = (park_pose.x_mm - prior.x_mm).hypot(park_pose.y_mm - prior.y_mm);
    movement_seconds += estimated_linear_motion_seconds(
        park_distance_mm,
        park_feed_mm_per_min,
        xy_acceleration_mm_per_s2,
    );
    let planned_tiles = plan.tiles.len() as u32;
    let planned_registrations = if mode == WorkspaceScanMode::Reconnaissance {
        0
    } else {
        plan.rows * plan.columns.saturating_sub(1) + plan.rows.saturating_sub(1) * plan.columns
    };
    let planned_seam_diagnostics = if mode == WorkspaceScanMode::Reconnaissance {
        plan.rows * plan.columns.saturating_sub(1) + plan.rows.saturating_sub(1) * plan.columns
    } else {
        0
    };
    let mosaic_width_px = ((plan.region.x_max_mm - plan.region.x_min_mm) / plan.output_mm_per_pixel)
        .ceil() as u32
        + 1;
    let mosaic_height_px =
        ((plan.region.y_max_mm - plan.region.y_min_mm) / plan.output_mm_per_pixel).ceil() as u32
            + 1;
    let mosaic_pixels = u64::from(mosaic_width_px) * u64::from(mosaic_height_px);
    let metadata_bytes = u64::from(planned_tiles) * 512
        + u64::from(planned_registrations) * 384
        + u64::from(planned_seam_diagnostics) * 1_024
        + 16_384;
    let source_bytes = u64::from(plan.frame_width_px)
        * u64::from(plan.frame_height_px)
        * u64::from(planned_tiles)
        * 11
        / 10;
    let thumbnail_bytes = u64::from(WORKSPACE_THUMBNAIL_WIDTH)
        * u64::from(WORKSPACE_THUMBNAIL_HEIGHT)
        * u64::from(planned_tiles)
        * 11
        / 10;
    let retained_image_bytes = match artifact_retention {
        WorkspaceArtifactRetention::FullSources => source_bytes,
        WorkspaceArtifactRetention::TransientSources => 0,
        WorkspaceArtifactRetention::Thumbnails => thumbnail_bytes,
        WorkspaceArtifactRetention::MosaicOnly => 0,
    };
    let parallax_bytes = if surface_models.len() > 1 {
        if artifact_retention == WorkspaceArtifactRetention::TransientSources {
            u64::try_from(MAX_TRANSIENT_PARALLAX_OBSERVATIONS).unwrap_or(u64::MAX)
                * ESTIMATED_PARALLAX_OBSERVATION_BYTES
                + 4_096
        } else {
            u64::from(planned_registrations) * 4_096 + 4_096
        }
    } else {
        0
    };
    let height_products_enabled = matches!(
        artifact_retention,
        WorkspaceArtifactRetention::FullSources | WorkspaceArtifactRetention::TransientSources
    ) && surface_models.len() > 1;
    let height_columns = ((plan.region.x_max_mm - plan.region.x_min_mm)
        / velocitypnp_vision::WORKSPACE_HEIGHT_CELL_SIZE_MM)
        .ceil() as u64;
    let height_rows = ((plan.region.y_max_mm - plan.region.y_min_mm)
        / velocitypnp_vision::WORKSPACE_HEIGHT_CELL_SIZE_MM)
        .ceil() as u64;
    let height_product_bytes = if height_products_enabled {
        mosaic_pixels * 11 / 10 * 2
            + mosaic_pixels * 33 / 10
            + mosaic_pixels * 44 / 10
            + height_rows * height_columns * 512
            + 4_096
    } else {
        0
    };
    let seam_product_bytes = if mode == WorkspaceScanMode::Reconnaissance {
        // Disagreement, overlap confidence, RGBA overlay, and RGB preview.
        // PNG normally compresses these images below this raw-byte estimate.
        mosaic_pixels * 99 / 10 + 4_096
    } else {
        0
    };
    let estimated_retained_bytes = mosaic_pixels * 11 / 10 * surface_models.len() as u64
        + metadata_bytes
        + retained_image_bytes
        + parallax_bytes
        + height_product_bytes
        + seam_product_bytes;
    let movement_commands = planned_tiles.saturating_add(1);
    movement_seconds += f64::from(movement_commands)
        * if xy_acceleration_mm_per_s2.is_some() {
            WORKSPACE_MOTION_COMMAND_OVERHEAD_SECONDS
        } else {
            WORKSPACE_FALLBACK_COMMAND_OVERHEAD_SECONDS
        };
    let base_duration_seconds = if mode != WorkspaceScanMode::Precision {
        let capture_seconds = f64::from(top_profile.settle_frames)
            / f64::from(top_profile.frames_per_second)
            + f64::from(planned_tiles)
                * (camera_end_of_frame_guard(top_profile).as_secs_f64()
                    + WORKSPACE_CAPTURE_PIPELINE_FRAMES / f64::from(top_profile.frames_per_second));
        (movement_seconds
            + capture_seconds
            + WORKSPACE_CAMERA_OPEN_SECONDS
            + if mode == WorkspaceScanMode::Reconnaissance {
                f64::from(planned_tiles) * WORKSPACE_RECONSTRUCTION_SECONDS_PER_TILE
            } else {
                f64::from(planned_registrations)
                    * ESTIMATED_REGISTRATION_SECONDS
                    * (surface_models.len() + usize::from(surface_models.len() > 1)) as f64
            }
            + WORKSPACE_FIXED_OVERHEAD_SECONDS)
            .ceil() as u64
    } else {
        (f64::from(planned_tiles) * 5.3).ceil() as u64
    };
    let height_duration_seconds = if height_products_enabled {
        let maximum_candidate_layers = ((MAX_WORKSPACE_SURFACE_FRACTION
            - MIN_WORKSPACE_SURFACE_FRACTION)
            / WORKSPACE_HEIGHT_CANDIDATE_STEP)
            .round() as u64
            + 1;
        (f64::from(planned_tiles)
            * ESTIMATED_HEIGHT_RENDER_SECONDS_PER_TILE
            * maximum_candidate_layers as f64)
            .ceil() as u64
    } else {
        0
    };
    let estimated_duration_seconds = base_duration_seconds + height_duration_seconds;
    WorkspaceScanEstimate {
        mode,
        artifact_retention,
        surface_model,
        surface_models,
        region: plan.region,
        raster_transform: WorkspaceRasterTransform {
            top_left_x_mm: plan.region.x_min_mm,
            top_left_y_mm: plan.region.y_max_mm,
            x_mm_per_pixel: plan.output_mm_per_pixel,
            y_mm_per_pixel: -plan.output_mm_per_pixel,
        },
        overlap_fraction: plan.overlap_fraction,
        output_mm_per_pixel: plan.output_mm_per_pixel,
        feed_mm_per_min,
        capture_settle_frames: WORKSPACE_UNKNOWN_TIMESTAMP_GUARD_FRAMES,
        rows: plan.rows,
        columns: plan.columns,
        planned_tiles,
        planned_registrations,
        mosaic_width_px,
        mosaic_height_px,
        estimated_duration_seconds,
        estimated_retained_bytes,
        artifact_quota_bytes,
        persistent_capture: mode != WorkspaceScanMode::Precision,
        warnings: Vec::new(),
    }
}

fn load_workspace_camera_model(
    state: &AppState,
    calibration_id: Uuid,
) -> ApiResult<(CalibrationSnapshot, PlanarCameraModel)> {
    let mut snapshot = state
        .store
        .get_calibration(calibration_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("calibration snapshot not found"))?;
    if !state.profile.accepts_profile_id(&snapshot.profile_id) {
        return Err(ApiError::bad_request(
            "calibration snapshot does not match the active machine profile",
        ));
    }
    let changed = crate::calibration_artifacts::reconcile_snapshot_artifacts(state, &mut snapshot)
        .map_err(ApiError::bad_request)?;
    if !crate::calibration_artifacts::artifact_tree_is_current(
        state,
        &snapshot,
        CalibrationArtifactId::TopCameraPlanarModel,
    ) {
        return Err(ApiError::bad_request(
            "workspace scan requires a current top-camera planar model",
        ));
    }
    let report: PlanarCameraCalibrationReport = serde_json::from_value(
        crate::calibration_artifacts::artifact_result_value(
            &snapshot,
            CalibrationArtifactId::TopCameraPlanarModel,
        )
        .map_err(ApiError::bad_request)?,
    )
    .map_err(|error| {
        ApiError::bad_request(format!(
            "stored top-camera planar model is invalid: {error}"
        ))
    })?;
    if !report.passed {
        return Err(ApiError::bad_request(
            "workspace scan requires a passing top-camera planar model",
        ));
    }
    if changed {
        state
            .store
            .put_calibration(&snapshot)
            .map_err(ApiError::internal)?;
    }
    Ok((snapshot, report.model))
}

#[allow(clippy::too_many_arguments)]
async fn execute_workspace_scan(
    state: AppState,
    scan: WorkspaceScanReport,
    plan: WorkspaceScanPlan,
    camera_model: PlanarCameraModel,
    installed_camera_model: Option<PlanarCameraModel>,
    top_profile: CameraProfile,
    top_path: String,
    motion_planner: MotionPlanner,
    lease_id: Uuid,
) -> Result<Option<String>, String> {
    let motion_lock = state.workspace_scan_motion_lock.clone();
    let _motion_guard = motion_lock.lock().await;
    execute_workspace_scan_locked(
        state,
        scan,
        plan,
        camera_model,
        installed_camera_model,
        top_profile,
        top_path,
        motion_planner,
        lease_id,
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn execute_workspace_scan_locked(
    state: AppState,
    mut scan: WorkspaceScanReport,
    plan: WorkspaceScanPlan,
    camera_model: PlanarCameraModel,
    installed_camera_model: Option<PlanarCameraModel>,
    top_profile: CameraProfile,
    top_path: String,
    motion_planner: MotionPlanner,
    lease_id: Uuid,
) -> Result<Option<String>, String> {
    let operation_started = Instant::now();
    let mut timing = WorkspaceScanTiming::default();
    scan.status = WorkspaceScanStatus::Running;
    scan.updated_at = Utc::now();
    state
        .store
        .put_workspace_scan(&scan)
        .map_err(|error| error.to_string())?;
    let visual = state
        .profile
        .visual_homing
        .as_ref()
        .ok_or_else(|| "active profile does not define visual homing".to_string())?
        .clone();
    let use_lights = top_profile.lighting_enabled;
    let controller_pose = state
        .machine
        .status()
        .pose
        .ok_or_else(|| "workspace scan lost the machine pose".to_string())?;
    let mut motion = CalibratedMotionSequence::new(motion_planner, controller_pose)?;

    let result = capture_and_build_workspace_scan(
        &state,
        &mut scan,
        &plan,
        &camera_model,
        installed_camera_model.as_ref(),
        &top_profile,
        &top_path,
        lease_id,
        use_lights,
        &mut timing,
        &mut motion,
    )
    .await;

    let park_started = Instant::now();
    let park_feed_mm_per_min = safe_level_xy_feed(
        &state.profile,
        state.machine.status().pose,
        visual.seed_pose,
        visual.feed_mm_per_min,
    );
    let park = execute_calibrated_motion(
        &state,
        lease_id,
        &mut motion,
        visual.seed_pose,
        park_feed_mm_per_min,
    )
    .await;
    if let Ok((_, planned)) = &park {
        record_workspace_motion_correction(&mut timing, planned, true);
    }
    timing.park_ms = elapsed_ms(park_started);
    let lights_disable_started = Instant::now();
    let lights_off = if use_lights {
        state.machine.disable_actuator("lights".into()).await
    } else {
        Ok(())
    };
    timing.lights_disable_ms = elapsed_ms(lights_disable_started);
    let mut result = match (result, park, lights_off) {
        (Err(error), park, lights_off) => {
            let mut failures = vec![error];
            if let Err(error) = park {
                failures.push(format!("could not park at the datum: {error}"));
            }
            if let Err(error) = lights_off {
                failures.push(format!("could not disable the lights: {error}"));
            }
            Err(failures.join("; "))
        }
        (Ok(_), Err(error), _) => Err(format!(
            "workspace scan could not park at the datum: {error}"
        )),
        (Ok(_), Ok(_), Err(error)) => Err(format!(
            "workspace scan could not disable the lights: {error}"
        )),
        (Ok(message), Ok(_), Ok(_)) => Ok(message),
    };
    if result.is_ok() {
        scan.status = WorkspaceScanStatus::Succeeded;
        scan.updated_at = Utc::now();
        scan.failure = None;
        let finalize = persist_workspace_manifest(&state, &mut scan);
        if let Err(error) = finalize {
            result = Err(format!(
                "workspace scan could not finalize its report: {error}"
            ));
        }
    }
    if let Err(error) = &result {
        scan.status = WorkspaceScanStatus::Failed;
        scan.failure = Some(error.clone());
        scan.updated_at = Utc::now();
        if let Err(store_error) = state.store.put_workspace_scan(&scan) {
            return Err(format!(
                "{error}; also failed to persist scan failure: {store_error}"
            ));
        }
    }
    let timing_payload = json!({
        "algorithm_version": WORKSPACE_SCAN_TIMING_ALGORITHM,
        "operation_id": scan.operation_id,
        "scan_id": scan.id,
        "succeeded": result.is_ok(),
        "mode": scan.mode,
        "rows": scan.rows,
        "columns": scan.columns,
        "planned_tiles": scan.planned_tiles,
        "captured_tiles": scan.captured_tiles,
        "feed_mm_per_min": scan.feed_mm_per_min,
        "configured_settle_frames": scan.capture_settle_frames,
        "discarded_capture_frames": scan.discarded_capture_frames,
        "tile_discarded_capture_frames": timing.tile_discarded_capture_frames,
        "tile_capture_sequences": timing.tile_capture_sequences,
        "capture_sequence_gaps": timing.capture_sequence_gaps,
        "camera_fourcc": timing.camera_fourcc,
        "camera_interval": timing.camera_interval,
        "camera_timestamp_sources": timing.camera_timestamp_sources,
        "end_of_frame_guard_ms": camera_end_of_frame_guard(&top_profile).as_secs_f64() * 1_000.0,
        "unknown_source_guard_ms": camera_frame_period(&top_profile).as_secs_f64() * 1_000.0,
        "total_elapsed_ms": elapsed_ms(operation_started),
        "lights_enable_ms": timing.lights_enable_ms,
        "camera_open_ms": timing.camera_open_ms,
        "tile_motion": workspace_timing_distribution(&timing.tile_motion_ms),
        "tile_capture": workspace_timing_distribution(&timing.tile_capture_ms),
        "first_tile_capture_ms": timing.tile_capture_ms.first(),
        "later_tile_capture": workspace_timing_distribution(
            timing.tile_capture_ms.get(1..).unwrap_or_default(),
        ),
        "tile_artifact": workspace_timing_distribution(&timing.tile_artifact_ms),
        "tile_mosaic": workspace_timing_distribution(&timing.tile_mosaic_ms),
        "progress_store": workspace_timing_distribution(&timing.progress_store_ms),
        "mosaic_finalize_ms": timing.mosaic_finalize_ms,
        "park_ms": timing.park_ms,
        "corrected_moves": timing.corrected_moves,
        "maximum_direction_correction_mm": timing.maximum_direction_correction_mm,
        "park_direction_correction_mm": timing.park_direction_correction_mm,
        "lights_disable_ms": timing.lights_disable_ms,
    });
    if let Err(error) = state
        .machine
        .record_operation_event("operation.workspace_scan_timing".into(), timing_payload)
        .await
    {
        tracing::warn!(%error, scan_id = %scan.id, "failed to record workspace timing");
    }
    result.map(Some)
}

#[allow(clippy::too_many_arguments)]
async fn execute_workspace_refinement_batch(
    state: AppState,
    batch_operation_id: Uuid,
    queue: Vec<PreparedWorkspaceRefinement>,
    camera_model: PlanarCameraModel,
    installed_camera_model: Option<PlanarCameraModel>,
    top_profile: CameraProfile,
    top_path: String,
    motion_planner: MotionPlanner,
    lease_id: Uuid,
) -> Result<Option<String>, String> {
    let motion_lock = state.workspace_scan_motion_lock.clone();
    let _motion_guard = motion_lock.lock().await;
    let total = queue.len();
    for index in 0..total {
        let item = queue[index].clone();
        let progress = format!(
            "running priority {} target {} ({}/{total})",
            item.target.priority,
            item.target.target_index,
            index + 1
        );
        if let Err(error) =
            update_workspace_refinement_batch_progress(&state, batch_operation_id, progress.clone())
        {
            let message = format!("could not persist refinement batch progress: {error}");
            cancel_workspace_refinement_queue(&state, &queue[index..], &message);
            return Err(message);
        }
        let status = state.machine.status();
        if let Err(error) = status.assert_lease(lease_id, Utc::now()) {
            let message = format!(
                "refinement target {} cannot start: {error}",
                item.target.target_index
            );
            cancel_workspace_refinement_queue(&state, &queue[index..], &message);
            return Err(message);
        }
        if status.state != MachineState::Ready || !status.homed || status.pose.is_none() {
            let message = format!(
                "refinement target {} requires a homed ready machine with a known pose",
                item.target.target_index
            );
            cancel_workspace_refinement_queue(&state, &queue[index..], &message);
            return Err(message);
        }
        if let Err(error) = state
            .machine
            .renew_lease(lease_id, CALIBRATION_LEASE_SECONDS)
            .await
        {
            let message = format!(
                "refinement target {} could not renew control: {error}",
                item.target.target_index
            );
            cancel_workspace_refinement_queue(&state, &queue[index..], &message);
            return Err(message);
        }
        let mut operation = item.operation.clone();
        operation.status = OperationStatus::Running;
        operation.updated_at = Utc::now();
        operation.message = Some(progress);
        if let Err(error) = state.store.put_operation(&operation) {
            let message = format!(
                "could not mark refinement target {} running: {error}",
                item.target.target_index
            );
            cancel_workspace_refinement_queue(&state, &queue[index..], &message);
            return Err(message);
        }
        let result = execute_workspace_scan_locked(
            state.clone(),
            item.scan,
            item.plan,
            camera_model.clone(),
            installed_camera_model.clone(),
            top_profile.clone(),
            top_path.clone(),
            motion_planner.clone(),
            lease_id,
        )
        .await;
        operation.updated_at = Utc::now();
        match result {
            Ok(message) => {
                operation.status = OperationStatus::Succeeded;
                operation.message = message;
                if let Err(error) = state.store.put_operation(&operation) {
                    let message = format!(
                        "refinement target {} succeeded but its operation could not be stored: {error}",
                        item.target.target_index
                    );
                    cancel_workspace_refinement_queue(&state, &queue[index + 1..], &message);
                    return Err(message);
                }
                if let Err(error) = update_workspace_refinement_batch_progress(
                    &state,
                    batch_operation_id,
                    format!(
                        "completed {} of {total}; last target {}",
                        index + 1,
                        item.target.target_index
                    ),
                ) {
                    let message = format!("could not persist refinement batch progress: {error}");
                    cancel_workspace_refinement_queue(&state, &queue[index + 1..], &message);
                    return Err(message);
                }
            }
            Err(error) => {
                operation.status = OperationStatus::Failed;
                operation.message = Some(error.clone());
                if let Err(store_error) = state.store.put_operation(&operation) {
                    tracing::error!(
                        %store_error,
                        operation_id = %operation.id,
                        "failed to persist queued refinement operation failure"
                    );
                }
                let message = format!(
                    "refinement batch stopped at priority {} target {}: {error}",
                    item.target.priority, item.target.target_index
                );
                cancel_workspace_refinement_queue(&state, &queue[index + 1..], &message);
                return Err(message);
            }
        }
    }
    Ok(Some(format!(
        "completed {total} prioritized workspace refinement targets"
    )))
}

fn update_workspace_refinement_batch_progress(
    state: &AppState,
    operation_id: Uuid,
    message: String,
) -> Result<(), String> {
    let mut operation = state
        .store
        .get_operation(operation_id)
        .map_err(|error| error.to_string())?
        .ok_or_else(|| "refinement batch operation is missing".to_string())?;
    operation.status = OperationStatus::Running;
    operation.message = Some(message);
    operation.updated_at = Utc::now();
    state
        .store
        .put_operation(&operation)
        .map_err(|error| error.to_string())
}

fn cancel_workspace_refinement_queue(
    state: &AppState,
    queue: &[PreparedWorkspaceRefinement],
    reason: &str,
) {
    for item in queue {
        let mut scan = item.scan.clone();
        if scan.status == WorkspaceScanStatus::Pending {
            scan.status = WorkspaceScanStatus::Failed;
            scan.failure = Some(format!("not run because {reason}"));
            scan.updated_at = Utc::now();
            if let Err(error) = state.store.put_workspace_scan(&scan) {
                tracing::error!(
                    %error,
                    scan_id = %scan.id,
                    "failed to cancel queued refinement scan"
                );
            }
        }
        let mut operation = item.operation.clone();
        if operation.status == OperationStatus::Pending {
            operation.status = OperationStatus::Cancelled;
            operation.message = Some(format!("not run because {reason}"));
            operation.updated_at = Utc::now();
            if let Err(error) = state.store.put_operation(&operation) {
                tracing::error!(
                    %error,
                    operation_id = %operation.id,
                    "failed to cancel queued refinement operation"
                );
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn capture_and_build_workspace_scan(
    state: &AppState,
    scan: &mut WorkspaceScanReport,
    plan: &WorkspaceScanPlan,
    camera_model: &PlanarCameraModel,
    installed_camera_model: Option<&PlanarCameraModel>,
    top_profile: &CameraProfile,
    top_path: &str,
    lease_id: Uuid,
    use_lights: bool,
    timing: &mut WorkspaceScanTiming,
    motion: &mut CalibratedMotionSequence,
) -> Result<String, String> {
    if scan.mode != WorkspaceScanMode::Precision {
        return capture_and_build_workspace_survey(
            state,
            scan,
            plan,
            camera_model,
            installed_camera_model,
            top_profile,
            top_path,
            lease_id,
            use_lights,
            timing,
            motion,
        )
        .await;
    }
    capture_and_build_precision_workspace_scan(
        state,
        scan,
        plan,
        camera_model,
        installed_camera_model,
        top_profile,
        top_path,
        lease_id,
        use_lights,
        timing,
        motion,
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn capture_and_build_precision_workspace_scan(
    state: &AppState,
    scan: &mut WorkspaceScanReport,
    plan: &WorkspaceScanPlan,
    camera_model: &PlanarCameraModel,
    installed_camera_model: Option<&PlanarCameraModel>,
    top_profile: &CameraProfile,
    top_path: &str,
    lease_id: Uuid,
    use_lights: bool,
    timing: &mut WorkspaceScanTiming,
    motion: &mut CalibratedMotionSequence,
) -> Result<String, String> {
    if use_lights {
        let started = Instant::now();
        let result = state.machine.actuate(lease_id, "lights".into(), true).await;
        timing.lights_enable_ms += elapsed_ms(started);
        result.map_err(|error| error.to_string())?;
    }
    let _capture_guard = state.camera_capture_lock.lock().await;
    let updates = profile_control_updates(top_profile);
    let config = camera_capture_config(top_profile, top_path.to_owned());
    let camera_open_started = Instant::now();
    let camera_open = open_persistent_workspace_camera_with_retry(&config, &updates).await;
    timing.camera_open_ms += elapsed_ms(camera_open_started);
    let mut session = Some(camera_open?);
    let mut frames = vec![None; plan.tiles.len()];
    let feed_mm_per_min = scan.feed_mm_per_min;
    let mut capture_sequence = plan.tiles.iter().collect::<Vec<_>>();
    capture_sequence.sort_by_key(|tile| tile.capture_order);
    for (capture_index, tile) in capture_sequence.into_iter().enumerate() {
        let motion_started = Instant::now();
        let motion_result = execute_calibrated_motion(
            state,
            lease_id,
            motion,
            tile.nominal_pose.into(),
            feed_mm_per_min,
        )
        .await;
        timing.tile_motion_ms.push(elapsed_ms(motion_started));
        let (_, planned) = motion_result?;
        record_workspace_motion_correction(timing, &planned, false);
        let fresh_after = camera_freshness_boundary(
            top_profile,
            monotonic_timestamp().map_err(|error| error.to_string())?,
        );
        let settle_frames = if capture_index == 0 {
            top_profile.settle_frames
        } else {
            0
        };
        let capture_started = Instant::now();
        let capture_result = capture_persistent_workspace_frame(
            &mut session,
            &config,
            &updates,
            settle_frames,
            top_profile.settle_frames,
            Some(fresh_after),
        )
        .await;
        timing.tile_capture_ms.push(elapsed_ms(capture_started));
        let capture = capture_result?;
        record_workspace_capture(timing, &capture.metadata);
        scan.discarded_capture_frames = scan
            .discarded_capture_frames
            .saturating_add(capture.metadata.settle_frames);
        if capture.metadata.fresh_after_boundary {
            scan.timestamp_fresh_frames = scan.timestamp_fresh_frames.saturating_add(1);
        }
        let frame = capture.frame;
        let artifact_started = Instant::now();
        persist_workspace_tile_artifact(state, scan, tile, &frame, None)?;
        timing.tile_artifact_ms.push(elapsed_ms(artifact_started));
        frames[tile.index as usize] = Some(frame);
        scan.captured_tiles += 1;
        scan.updated_at = Utc::now();
        let progress_started = Instant::now();
        state
            .store
            .put_workspace_scan(scan)
            .map_err(|error| error.to_string())?;
        timing.progress_store_ms.push(elapsed_ms(progress_started));
    }
    let frames = frames
        .into_iter()
        .collect::<Option<Vec<_>>>()
        .ok_or_else(|| "workspace scan did not capture every planned tile".to_string())?;
    drop(session.take());
    let build_plan = plan.clone();
    let parallax_working_model = camera_model.clone();
    let parallax_installed_model = installed_camera_model.cloned();
    let mut build_models = vec![(
        WorkspaceSurfaceModel::TopCameraWorkingPlane,
        camera_model.clone(),
    )];
    if let Some(installed_camera_model) = installed_camera_model {
        build_models.push((
            WorkspaceSurfaceModel::InstalledPlatePlanes,
            installed_camera_model.clone(),
        ));
    }
    let finalize_started = Instant::now();
    let (mosaics, parallax) = tokio::task::spawn_blocking(move || {
        let parallax = parallax_installed_model
            .as_ref()
            .map(|installed_model| {
                measure_workspace_parallax(
                    &build_plan,
                    &parallax_working_model,
                    installed_model,
                    &frames,
                )
            })
            .transpose()?;
        let mosaics = build_models
            .into_iter()
            .map(|(surface_model, model)| {
                build_workspace_mosaic(&build_plan, &model, &frames)
                    .map(|mosaic| (surface_model, mosaic))
            })
            .collect::<anyhow::Result<Vec<_>>>()?;
        anyhow::Ok((mosaics, parallax))
    })
    .await
    .map_err(|error| error.to_string())?
    .map_err(|error| error.to_string())?;
    let height_artifacts = build_retained_workspace_height_artifacts(
        state,
        scan,
        plan,
        camera_model,
        installed_camera_model,
        parallax.as_ref(),
    )
    .await?;
    let result = complete_workspace_mosaics(state, scan, mosaics, parallax, height_artifacts);
    timing.mosaic_finalize_ms += elapsed_ms(finalize_started);
    result
}

#[allow(clippy::too_many_arguments)]
async fn capture_and_build_workspace_survey(
    state: &AppState,
    scan: &mut WorkspaceScanReport,
    plan: &WorkspaceScanPlan,
    camera_model: &PlanarCameraModel,
    installed_camera_model: Option<&PlanarCameraModel>,
    top_profile: &CameraProfile,
    top_path: &str,
    lease_id: Uuid,
    use_lights: bool,
    timing: &mut WorkspaceScanTiming,
    motion: &mut CalibratedMotionSequence,
) -> Result<String, String> {
    if use_lights {
        let started = Instant::now();
        let result = state.machine.actuate(lease_id, "lights".into(), true).await;
        timing.lights_enable_ms += elapsed_ms(started);
        result.map_err(|error| error.to_string())?;
    }
    let transient_sources =
        if scan.artifact_retention == WorkspaceArtifactRetention::TransientSources {
            Some(TransientWorkspaceSources::create(scan.id)?)
        } else {
            None
        };
    let _capture_guard = state.camera_capture_lock.lock().await;
    let updates = profile_control_updates(top_profile);
    let config = camera_capture_config(top_profile, top_path.to_owned());
    let camera_open_started = Instant::now();
    let camera_open = open_persistent_workspace_camera_with_retry(&config, &updates).await;
    timing.camera_open_ms += elapsed_ms(camera_open_started);
    let mut session = Some(camera_open?);
    let primary_stream = if scan.mode == WorkspaceScanMode::Reconnaissance {
        WorkspaceMosaicStream::new_with_seam_diagnostics(plan.clone(), camera_model.clone())
    } else {
        WorkspaceMosaicStream::new(plan.clone(), camera_model.clone())
    }
    .map_err(|error| error.to_string())?;
    let mut layer_streams = vec![(scan.surface_model, primary_stream)];
    if let Some(installed_camera_model) = installed_camera_model {
        layer_streams.push((
            WorkspaceSurfaceModel::InstalledPlatePlanes,
            WorkspaceMosaicStream::new(plan.clone(), installed_camera_model.clone())
                .map_err(|error| error.to_string())?,
        ));
    }
    let mut streams = Some(layer_streams);
    let mut parallax_stream = if scan.mode == WorkspaceScanMode::Reconnaissance {
        None
    } else {
        installed_camera_model.map(|installed_camera_model| {
            WorkspaceParallaxStream::new(
                plan.clone(),
                camera_model.clone(),
                installed_camera_model.clone(),
            )
        })
    }
    .transpose()
    .map_err(|error| error.to_string())?;
    let mut capture_sequence = plan.tiles.iter().collect::<Vec<_>>();
    capture_sequence.sort_by_key(|tile| tile.capture_order);
    let feed_mm_per_min = scan.feed_mm_per_min;

    for (capture_index, tile) in capture_sequence.into_iter().enumerate() {
        if capture_index > 0 && capture_index as u32 % 100 == 0 {
            state
                .machine
                .renew_lease(lease_id, CALIBRATION_LEASE_SECONDS)
                .await
                .map_err(|error| error.to_string())?;
        }
        let motion_started = Instant::now();
        let motion_result = execute_calibrated_motion(
            state,
            lease_id,
            motion,
            tile.nominal_pose.into(),
            feed_mm_per_min,
        )
        .await;
        timing.tile_motion_ms.push(elapsed_ms(motion_started));
        let (_, planned) = motion_result?;
        record_workspace_motion_correction(timing, &planned, false);
        let fresh_after = Some(camera_freshness_boundary(
            top_profile,
            monotonic_timestamp().map_err(|error| error.to_string())?,
        ));
        let settle_frames = if capture_index == 0 {
            top_profile.settle_frames
        } else {
            0
        };
        let capture_started = Instant::now();
        let capture_result = capture_persistent_workspace_frame(
            &mut session,
            &config,
            &updates,
            settle_frames,
            top_profile.settle_frames,
            fresh_after,
        )
        .await;
        timing.tile_capture_ms.push(elapsed_ms(capture_started));
        let capture = capture_result?;
        record_workspace_capture(timing, &capture.metadata);
        scan.discarded_capture_frames = scan
            .discarded_capture_frames
            .saturating_add(capture.metadata.settle_frames);
        if capture.metadata.fresh_after_boundary {
            scan.timestamp_fresh_frames = scan.timestamp_fresh_frames.saturating_add(1);
        }
        let frame = capture.frame;
        let artifact_started = Instant::now();
        persist_workspace_tile_artifact(state, scan, tile, &frame, transient_sources.as_ref())?;
        timing.tile_artifact_ms.push(elapsed_ms(artifact_started));

        let mosaic_started = Instant::now();
        let mut active_streams = streams
            .take()
            .ok_or_else(|| "workspace mosaic streams are unavailable".to_string())?;
        let active_parallax_stream = parallax_stream.take();
        let tile_index = tile.index;
        let (returned_streams, returned_parallax_stream, row_completed) =
            tokio::task::spawn_blocking(move || {
                let mut row_completed = false;
                for (layer_index, (_, stream)) in active_streams.iter_mut().enumerate() {
                    let completed = stream.push_frame(tile_index, frame.clone())?;
                    if layer_index == 0 {
                        row_completed = completed;
                    }
                }
                let returned_parallax_stream = if let Some(mut stream) = active_parallax_stream {
                    stream.push_frame(tile_index, frame)?;
                    Some(stream)
                } else {
                    None
                };
                anyhow::Ok((active_streams, returned_parallax_stream, row_completed))
            })
            .await
            .map_err(|error| error.to_string())?
            .map_err(|error| error.to_string())?;
        timing.tile_mosaic_ms.push(elapsed_ms(mosaic_started));
        streams = Some(returned_streams);
        parallax_stream = returned_parallax_stream;

        scan.captured_tiles += 1;
        scan.updated_at = Utc::now();
        if row_completed
            || scan.captured_tiles % WORKSPACE_PROGRESS_TILE_INTERVAL == 0
            || scan.captured_tiles == scan.planned_tiles
        {
            let progress_started = Instant::now();
            state
                .store
                .put_workspace_scan(scan)
                .map_err(|error| error.to_string())?;
            timing.progress_store_ms.push(elapsed_ms(progress_started));
        }
    }
    let finalize_started = Instant::now();
    drop(session.take());
    let streams = streams
        .take()
        .ok_or_else(|| "workspace mosaic streams are unavailable".to_string())?;
    let (mosaics, parallax) = tokio::task::spawn_blocking(move || {
        let mosaics = streams
            .into_iter()
            .map(|(surface_model, stream)| stream.finish().map(|mosaic| (surface_model, mosaic)))
            .collect::<anyhow::Result<Vec<_>>>()?;
        let parallax = parallax_stream
            .map(WorkspaceParallaxStream::finish)
            .transpose()?;
        anyhow::Ok((mosaics, parallax))
    })
    .await
    .map_err(|error| error.to_string())?
    .map_err(|error| error.to_string())?;
    let height_artifacts = if let Some(transient_sources) = transient_sources.as_ref() {
        build_chunked_workspace_height_artifacts(
            state,
            scan,
            plan,
            camera_model,
            installed_camera_model,
            parallax.as_ref(),
            transient_sources,
        )
        .await?
    } else {
        build_retained_workspace_height_artifacts(
            state,
            scan,
            plan,
            camera_model,
            installed_camera_model,
            parallax.as_ref(),
        )
        .await?
    };
    let result = complete_workspace_mosaics(state, scan, mosaics, parallax, height_artifacts);
    timing.mosaic_finalize_ms += elapsed_ms(finalize_started);
    result
}

async fn build_retained_workspace_height_artifacts(
    state: &AppState,
    scan: &WorkspaceScanReport,
    plan: &WorkspaceScanPlan,
    working_model: &PlanarCameraModel,
    installed_model: Option<&PlanarCameraModel>,
    parallax: Option<&WorkspaceParallaxReport>,
) -> Result<Option<WorkspaceHeightArtifacts>, String> {
    if scan.artifact_retention != WorkspaceArtifactRetention::FullSources {
        return Ok(None);
    }
    let (Some(installed_model), Some(parallax)) = (installed_model, parallax) else {
        return Ok(None);
    };
    let store = state.store.clone();
    let scan_id = scan.id;
    let plan = plan.clone();
    let working_model = working_model.clone();
    let installed_model = installed_model.clone();
    let parallax = parallax.clone();
    let camera_aperture_diameter_range = state.profile.bottom_vision.as_ref().map(|bottom| {
        (
            bottom.head_geometry.bottom_camera_reference_min_diameter_px,
            bottom.head_geometry.bottom_camera_reference_max_diameter_px,
        )
    });
    tokio::task::spawn_blocking(move || {
        build_workspace_height_map(plan.region, &parallax).and_then(|map| {
            let mut composite =
                render_workspace_height_mosaic_with_consistency(&plan, &map, |fraction| {
                    render_retained_workspace_height_layer(
                        &store,
                        scan_id,
                        &plan,
                        &working_model,
                        &installed_model,
                        fraction,
                    )
                })?;
            let camera_aperture = camera_aperture_diameter_range
                .map(|(minimum_diameter_px, maximum_diameter_px)| {
                    composite_workspace_camera_aperture(
                        &plan,
                        &map,
                        &installed_model,
                        minimum_diameter_px,
                        maximum_diameter_px,
                        &mut composite,
                        |tile| read_retained_workspace_source(&store, scan_id, tile),
                    )
                })
                .transpose()?
                .flatten();
            Ok(Some(WorkspaceHeightArtifacts {
                map,
                composite,
                camera_aperture,
            }))
        })
    })
    .await
    .map_err(|error| error.to_string())?
    .map_err(|error| error.to_string())
}

async fn build_chunked_workspace_height_artifacts(
    state: &AppState,
    _scan: &WorkspaceScanReport,
    plan: &WorkspaceScanPlan,
    working_model: &PlanarCameraModel,
    installed_model: Option<&PlanarCameraModel>,
    parallax: Option<&WorkspaceParallaxReport>,
    transient_sources: &TransientWorkspaceSources,
) -> Result<Option<WorkspaceHeightArtifacts>, String> {
    let (Some(installed_model), Some(parallax)) = (installed_model, parallax) else {
        return Ok(None);
    };
    let plan = plan.clone();
    let working_model = working_model.clone();
    let installed_model = installed_model.clone();
    let parallax = parallax.clone();
    let source_directory = transient_sources.directory.clone();
    let camera_aperture_diameter_range = state.profile.bottom_vision.as_ref().map(|bottom| {
        (
            bottom.head_geometry.bottom_camera_reference_min_diameter_px,
            bottom.head_geometry.bottom_camera_reference_max_diameter_px,
        )
    });
    tokio::task::spawn_blocking(move || {
        let map = build_workspace_height_map(plan.region, &parallax)?;
        let chunks = workspace_height_chunk_plans(&plan, &map, &working_model, &installed_model)?;
        let mut composites = Vec::with_capacity(chunks.len());
        let mut camera_aperture = None;
        for chunk in chunks {
            let source_frames = load_transient_workspace_sources(&source_directory, &chunk.plan)?;
            let mut composite = render_workspace_height_mosaic_with_consistency_parallel(
                &chunk.plan,
                &map,
                |fraction| {
                    render_cached_workspace_height_layer(
                        &chunk.plan,
                        &working_model,
                        &installed_model,
                        &source_frames,
                        fraction,
                    )
                },
            )?;
            if let Some((minimum_diameter_px, maximum_diameter_px)) = camera_aperture_diameter_range
            {
                if let Some(mut aperture) = composite_workspace_camera_aperture(
                    &chunk.plan,
                    &map,
                    &installed_model,
                    minimum_diameter_px,
                    maximum_diameter_px,
                    &mut composite,
                    |tile| {
                        source_frames
                            .get(tile.index as usize)
                            .map(|frame| frame.as_ref().clone())
                            .context("camera aperture source tile is outside its chunk")
                    },
                )? {
                    remap_workspace_camera_aperture(&mut aperture, &chunk.global_tile_indices)?;
                    let replace = camera_aperture.as_ref().is_none_or(
                        |current: &WorkspaceCameraApertureComposite| {
                            aperture.supporting_detections > current.supporting_detections
                                || (aperture.supporting_detections == current.supporting_detections
                                    && aperture.source_center_error_px
                                        < current.source_center_error_px)
                        },
                    );
                    if replace {
                        camera_aperture = Some(aperture);
                    }
                }
            }
            composites.push((chunk.core_start_row, chunk.core_row_count, composite));
        }
        Ok(Some(WorkspaceHeightArtifacts {
            map,
            composite: merge_workspace_height_chunks(&plan, composites)?,
            camera_aperture,
        }))
    })
    .await
    .map_err(|error| error.to_string())?
    .map_err(|error: anyhow::Error| error.to_string())
}

struct WorkspaceHeightChunk {
    plan: WorkspaceScanPlan,
    global_tile_indices: Vec<u32>,
    core_start_row: u32,
    core_row_count: u32,
}

fn workspace_height_chunk_plans(
    plan: &WorkspaceScanPlan,
    map: &WorkspaceHeightMap,
    working_model: &PlanarCameraModel,
    installed_model: &PlanarCameraModel,
) -> anyhow::Result<Vec<WorkspaceHeightChunk>> {
    let output_height = workspace_mosaic_axis_pixels(
        plan.region.y_max_mm - plan.region.y_min_mm,
        plan.output_mm_per_pixel,
    )?;
    let (footprint_min_y, footprint_max_y) =
        workspace_height_footprint_y_range(plan, map, working_model, installed_model)?;
    let mut chunks = Vec::new();
    for first_pixel_row in (0..output_height).step_by(WORKSPACE_HEIGHT_CHUNK_PIXEL_ROWS as usize) {
        let final_pixel_row =
            (first_pixel_row + WORKSPACE_HEIGHT_CHUNK_PIXEL_ROWS - 1).min(output_height - 1);
        let first_render_row =
            first_pixel_row.saturating_sub(WORKSPACE_HEIGHT_CHUNK_HALO_PIXEL_ROWS);
        let final_render_row =
            (final_pixel_row + WORKSPACE_HEIGHT_CHUNK_HALO_PIXEL_ROWS).min(output_height - 1);
        let region = WorkspaceScanRegion {
            x_min_mm: plan.region.x_min_mm,
            x_max_mm: plan.region.x_max_mm,
            y_min_mm: if final_render_row == output_height - 1 {
                plan.region.y_min_mm
            } else {
                plan.region.y_max_mm - f64::from(final_render_row) * plan.output_mm_per_pixel
            },
            y_max_mm: plan.region.y_max_mm - f64::from(first_render_row) * plan.output_mm_per_pixel,
        };
        let source_rows = (0..plan.rows)
            .filter(|row| {
                let tile = &plan.tiles[(row * plan.columns) as usize];
                tile.nominal_pose.y_mm + footprint_max_y >= region.y_min_mm
                    && tile.nominal_pose.y_mm + footprint_min_y <= region.y_max_mm
            })
            .collect::<Vec<_>>();
        let first_source_row = source_rows
            .first()
            .copied()
            .context("workspace height chunk has no source row")?
            .saturating_sub(1);
        let final_source_row = source_rows
            .last()
            .copied()
            .context("workspace height chunk has no source row")?
            .saturating_add(1)
            .min(plan.rows - 1);
        let rows = final_source_row - first_source_row + 1;
        let mut tiles = Vec::with_capacity((rows * plan.columns) as usize);
        let mut global_tile_indices = Vec::with_capacity(tiles.capacity());
        for local_row in 0..rows {
            let global_row = first_source_row + local_row;
            for column in 0..plan.columns {
                let global_index = global_row * plan.columns + column;
                let mut tile = plan.tiles[global_index as usize].clone();
                tile.index = local_row * plan.columns + column;
                tile.row = local_row;
                tile.artifact_name = transient_workspace_source_name(global_index);
                global_tile_indices.push(global_index);
                tiles.push(tile);
            }
        }
        chunks.push(WorkspaceHeightChunk {
            plan: WorkspaceScanPlan {
                region,
                overlap_fraction: plan.overlap_fraction,
                output_mm_per_pixel: plan.output_mm_per_pixel,
                frame_width_px: plan.frame_width_px,
                frame_height_px: plan.frame_height_px,
                usable_pixel_bounds: plan.usable_pixel_bounds,
                rows,
                columns: plan.columns,
                tiles,
            },
            global_tile_indices,
            core_start_row: first_pixel_row - first_render_row,
            core_row_count: final_pixel_row - first_pixel_row + 1,
        });
    }
    Ok(chunks)
}

fn workspace_height_footprint_y_range(
    plan: &WorkspaceScanPlan,
    map: &WorkspaceHeightMap,
    working_model: &PlanarCameraModel,
    installed_model: &PlanarCameraModel,
) -> anyhow::Result<(f64, f64)> {
    const EDGE_INTERVALS: u32 = 64;

    let bounds = plan.usable_pixel_bounds;
    let left = f64::from(bounds.left);
    let right = f64::from(bounds.right - 1);
    let top = f64::from(bounds.top);
    let bottom = f64::from(bounds.bottom - 1);
    let mut minimum_y = f64::INFINITY;
    let mut maximum_y = f64::NEG_INFINITY;
    for fraction in &map.candidate_fractions {
        let model = interpolate_planar_camera_model(working_model, installed_model, *fraction)
            .map_err(anyhow::Error::msg)?;
        for index in 0..=EDGE_INTERVALS {
            let position = f64::from(index) / f64::from(EDGE_INTERVALS);
            let x = left + (right - left) * position;
            let y = top + (bottom - top) * position;
            for (sample_x, sample_y) in [(left, y), (right, y), (x, top), (x, bottom)] {
                let correction = model
                    .correction_at(sample_x, sample_y)
                    .context("workspace height model exceeds calibrated support")?;
                minimum_y = minimum_y.min(correction[1]);
                maximum_y = maximum_y.max(correction[1]);
            }
        }
    }
    anyhow::ensure!(
        minimum_y.is_finite() && maximum_y.is_finite() && maximum_y > minimum_y,
        "workspace height camera footprint is invalid"
    );
    Ok((minimum_y, maximum_y))
}

#[cfg(test)]
fn render_transient_workspace_height_layer(
    source_directory: &FilePath,
    plan: &WorkspaceScanPlan,
    working_model: &PlanarCameraModel,
    installed_model: &PlanarCameraModel,
    fraction: f64,
) -> anyhow::Result<WorkspaceMosaic> {
    let model = interpolate_planar_camera_model(working_model, installed_model, fraction)
        .map_err(anyhow::Error::msg)?;
    let mut stream = WorkspaceMosaicStream::new_without_registration(plan.clone(), model)?;
    let mut capture_sequence = plan.tiles.iter().collect::<Vec<_>>();
    capture_sequence.sort_by_key(|tile| tile.capture_order);
    for tile in capture_sequence {
        let frame = read_transient_workspace_source(source_directory, tile)?;
        stream.push_frame(tile.index, frame)?;
    }
    stream.finish()
}

fn load_transient_workspace_sources(
    source_directory: &FilePath,
    plan: &WorkspaceScanPlan,
) -> anyhow::Result<Vec<Arc<GrayFrame>>> {
    let mut frames = std::iter::repeat_with(|| None)
        .take(plan.tiles.len())
        .collect::<Vec<_>>();
    for tile in &plan.tiles {
        let slot = frames
            .get_mut(tile.index as usize)
            .context("workspace source tile is outside its chunk")?;
        anyhow::ensure!(slot.is_none(), "workspace source tile index is duplicated");
        *slot = Some(Arc::new(read_transient_workspace_source(
            source_directory,
            tile,
        )?));
    }
    frames
        .into_iter()
        .map(|frame| frame.context("workspace source cache has a missing tile"))
        .collect()
}

fn render_cached_workspace_height_layer(
    plan: &WorkspaceScanPlan,
    working_model: &PlanarCameraModel,
    installed_model: &PlanarCameraModel,
    source_frames: &[Arc<GrayFrame>],
    fraction: f64,
) -> anyhow::Result<WorkspaceMosaic> {
    let model = interpolate_planar_camera_model(working_model, installed_model, fraction)
        .map_err(anyhow::Error::msg)?;
    let mut stream = WorkspaceMosaicStream::new_without_registration(plan.clone(), model)?;
    let mut capture_sequence = plan.tiles.iter().collect::<Vec<_>>();
    capture_sequence.sort_by_key(|tile| tile.capture_order);
    for tile in capture_sequence {
        let frame = source_frames
            .get(tile.index as usize)
            .context("workspace source tile is outside its cache")?;
        stream.push_shared_frame(tile.index, Arc::clone(frame))?;
    }
    stream.finish()
}

fn remap_workspace_camera_aperture(
    aperture: &mut WorkspaceCameraApertureComposite,
    global_tile_indices: &[u32],
) -> anyhow::Result<()> {
    aperture.source_tile_index = *global_tile_indices
        .get(aperture.source_tile_index as usize)
        .context("camera aperture source tile is outside its chunk")?;
    for tile_index in &mut aperture.source_tile_indices {
        *tile_index = *global_tile_indices
            .get(*tile_index as usize)
            .context("camera aperture supporting tile is outside its chunk")?;
    }
    Ok(())
}

fn merge_workspace_height_chunks(
    plan: &WorkspaceScanPlan,
    chunks: Vec<(u32, u32, WorkspaceHeightComposite)>,
) -> anyhow::Result<WorkspaceHeightComposite> {
    let width = workspace_mosaic_axis_pixels(
        plan.region.x_max_mm - plan.region.x_min_mm,
        plan.output_mm_per_pixel,
    )?;
    let height = workspace_mosaic_axis_pixels(
        plan.region.y_max_mm - plan.region.y_min_mm,
        plan.output_mm_per_pixel,
    )?;
    let first = chunks
        .first()
        .context("workspace height render produced no chunks")?;
    let mut frame = GrayFrame {
        width,
        height,
        pixels: Vec::with_capacity(width as usize * height as usize),
    };
    let mut class_overlay = RgbaFrame {
        width,
        height,
        pixels: Vec::with_capacity(width as usize * height as usize * 4),
    };
    let mut class_preview = RgbFrame {
        width,
        height,
        pixels: Vec::with_capacity(width as usize * height as usize * 3),
    };
    let mut confidence_frame = GrayFrame {
        width,
        height,
        pixels: Vec::with_capacity(width as usize * height as usize),
    };
    for (core_start_row, core_row_count, chunk) in &chunks {
        anyhow::ensure!(
            chunk.frame.width == width
                && chunk.class_overlay.width == width
                && chunk.class_preview.width == width
                && chunk.confidence_frame.width == width,
            "workspace height chunk widths differ"
        );
        append_workspace_chunk_rows(
            &mut frame.pixels,
            &chunk.frame.pixels,
            width,
            1,
            *core_start_row,
            *core_row_count,
        )?;
        append_workspace_chunk_rows(
            &mut class_overlay.pixels,
            &chunk.class_overlay.pixels,
            width,
            4,
            *core_start_row,
            *core_row_count,
        )?;
        append_workspace_chunk_rows(
            &mut class_preview.pixels,
            &chunk.class_preview.pixels,
            width,
            3,
            *core_start_row,
            *core_row_count,
        )?;
        append_workspace_chunk_rows(
            &mut confidence_frame.pixels,
            &chunk.confidence_frame.pixels,
            width,
            1,
            *core_start_row,
            *core_row_count,
        )?;
    }
    anyhow::ensure!(
        frame.pixels.len() == width as usize * height as usize
            && class_overlay.pixels.len() == width as usize * height as usize * 4
            && class_preview.pixels.len() == width as usize * height as usize * 3
            && confidence_frame.pixels.len() == width as usize * height as usize,
        "workspace height chunks do not cover the final mosaic"
    );
    Ok(WorkspaceHeightComposite {
        frame,
        class_overlay,
        class_preview,
        confidence_frame,
        height_preview: first.2.height_preview.clone(),
        candidate_fractions: first.2.candidate_fractions.clone(),
    })
}

fn append_workspace_chunk_rows(
    target: &mut Vec<u8>,
    source: &[u8],
    width: u32,
    channels: usize,
    first_row: u32,
    row_count: u32,
) -> anyhow::Result<()> {
    let row_bytes = width as usize * channels;
    let start = first_row as usize * row_bytes;
    let end = (first_row + row_count) as usize * row_bytes;
    let rows = source
        .get(start..end)
        .context("workspace height chunk crop is outside its frame")?;
    target.extend_from_slice(rows);
    Ok(())
}

fn workspace_mosaic_axis_pixels(span_mm: f64, mm_per_pixel: f64) -> anyhow::Result<u32> {
    let pixels = (span_mm / mm_per_pixel).ceil() + 1.0;
    anyhow::ensure!(
        pixels.is_finite() && pixels >= 2.0 && pixels <= f64::from(u32::MAX),
        "workspace mosaic dimensions are invalid"
    );
    Ok(pixels as u32)
}

fn render_retained_workspace_height_layer(
    store: &Store,
    scan_id: Uuid,
    plan: &WorkspaceScanPlan,
    working_model: &PlanarCameraModel,
    installed_model: &PlanarCameraModel,
    fraction: f64,
) -> anyhow::Result<WorkspaceMosaic> {
    let model = interpolate_planar_camera_model(working_model, installed_model, fraction)
        .map_err(anyhow::Error::msg)?;
    let mut stream = WorkspaceMosaicStream::new_without_registration(plan.clone(), model)?;
    let mut capture_sequence = plan.tiles.iter().collect::<Vec<_>>();
    capture_sequence.sort_by_key(|tile| tile.capture_order);
    for tile in capture_sequence {
        let frame = read_retained_workspace_source(store, scan_id, tile)?;
        stream.push_frame(tile.index, frame)?;
    }
    stream.finish()
}

fn read_retained_workspace_source(
    store: &Store,
    scan_id: Uuid,
    tile: &WorkspaceScanTile,
) -> anyhow::Result<GrayFrame> {
    let (media_type, encoded) = store
        .get_workspace_scan_artifact(scan_id, &tile.artifact_name)?
        .ok_or_else(|| {
            anyhow::anyhow!(
                "workspace scan source artifact {} is absent",
                tile.artifact_name
            )
        })?;
    anyhow::ensure!(
        media_type == "image/png",
        "workspace scan source artifact {} is not a PNG",
        tile.artifact_name
    );
    decode_gray_png(&encoded).map_err(|error| {
        anyhow::anyhow!(
            "workspace scan source artifact {} is invalid: {error}",
            tile.artifact_name
        )
    })
}

async fn capture_persistent_workspace_frame(
    session: &mut Option<Arc<PersistentGrayCapture>>,
    config: &V4l2CaptureConfig,
    control_updates: &[CameraControlUpdate],
    settle_frames: u32,
    reopen_settle_frames: u32,
    fresh_after: Option<CaptureFreshnessBoundary>,
) -> Result<velocitypnp_vision::CapturedGrayFrame, String> {
    let mut last_error = String::new();
    for attempt in 1..=MAX_CAMERA_CAPTURE_ATTEMPTS {
        if session.is_none() {
            match open_persistent_workspace_camera(config, control_updates).await {
                Ok(reopened) => *session = Some(reopened),
                Err(error) => {
                    last_error = error;
                    if attempt < MAX_CAMERA_CAPTURE_ATTEMPTS {
                        tokio::time::sleep(CAMERA_CAPTURE_RETRY_DELAY).await;
                    }
                    continue;
                }
            }
        }
        let active = Arc::clone(
            session
                .as_ref()
                .ok_or_else(|| "persistent camera session is unavailable".to_string())?,
        );
        let requested_settle_frames = if attempt == 1 {
            settle_frames
        } else {
            reopen_settle_frames
        };
        let requested_fresh_after = (attempt == 1).then_some(fresh_after).flatten();
        match tokio::task::spawn_blocking(move || {
            let capture = if let Some(boundary) = requested_fresh_after {
                active.capture_fresh_after(
                    boundary,
                    requested_settle_frames.max(WORKSPACE_INVALID_TIMESTAMP_SETTLE_FRAMES),
                    WORKSPACE_MAX_FRESH_CAPTURE_FRAMES,
                )
            } else {
                active.capture(requested_settle_frames)
            }?;
            Ok::<_, anyhow::Error>(capture)
        })
        .await
        {
            Ok(Ok(frame)) => return Ok(frame),
            Ok(Err(error)) => last_error = error.to_string(),
            Err(error) => last_error = error.to_string(),
        }
        if attempt == MAX_CAMERA_CAPTURE_ATTEMPTS {
            break;
        }
        drop(session.take());
        tokio::time::sleep(CAMERA_CAPTURE_RETRY_DELAY).await;
    }
    Err(format!(
        "persistent workspace capture failed after {MAX_CAMERA_CAPTURE_ATTEMPTS} attempts: {last_error}"
    ))
}

async fn open_persistent_workspace_camera(
    config: &V4l2CaptureConfig,
    control_updates: &[CameraControlUpdate],
) -> Result<Arc<PersistentGrayCapture>, String> {
    if !control_updates.is_empty() {
        let control_device = config.device.clone();
        let updates = control_updates.to_vec();
        tokio::task::spawn_blocking(move || apply_camera_controls(control_device, &updates))
            .await
            .map_err(|error| error.to_string())?
            .map_err(|error| error.to_string())?;
    }
    let open_config = config.clone();
    let session = tokio::task::spawn_blocking(move || PersistentGrayCapture::open(open_config))
        .await
        .map_err(|error| error.to_string())?
        .map_err(|error| error.to_string())?;
    Ok(Arc::new(session))
}

async fn open_persistent_workspace_camera_with_retry(
    config: &V4l2CaptureConfig,
    control_updates: &[CameraControlUpdate],
) -> Result<Arc<PersistentGrayCapture>, String> {
    let mut last_error = String::new();
    for attempt in 1..=MAX_CAMERA_CAPTURE_ATTEMPTS {
        match open_persistent_workspace_camera(config, control_updates).await {
            Ok(session) => return Ok(session),
            Err(error) => last_error = error,
        }
        if attempt < MAX_CAMERA_CAPTURE_ATTEMPTS {
            tokio::time::sleep(CAMERA_CAPTURE_RETRY_DELAY).await;
        }
    }
    Err(format!(
        "persistent workspace camera open failed after {MAX_CAMERA_CAPTURE_ATTEMPTS} attempts: {last_error}"
    ))
}

fn complete_workspace_mosaics(
    state: &AppState,
    scan: &mut WorkspaceScanReport,
    mosaics: Vec<(WorkspaceSurfaceModel, WorkspaceMosaic)>,
    parallax: Option<WorkspaceParallaxReport>,
    height_artifacts: Option<WorkspaceHeightArtifacts>,
) -> Result<String, String> {
    if mosaics.is_empty() {
        return Err("workspace scan produced no surface mosaics".into());
    }
    scan.mosaic_layers.clear();
    scan.seam_health = None;
    for (layer_index, (surface_model, mosaic)) in mosaics.into_iter().enumerate() {
        let artifact_name = if layer_index == 0 {
            "mosaic.png".to_string()
        } else {
            format!("mosaic-{}.png", workspace_surface_model_name(surface_model))
        };
        let accepted_registrations = mosaic
            .registrations
            .iter()
            .filter(|registration| registration.accepted)
            .count() as u32;
        let attempted_registrations = mosaic.registrations.len() as u32;
        let applied_corrections = mosaic
            .tiles
            .iter()
            .filter(|tile| {
                tile.placement_correction_x_mm != 0.0 || tile.placement_correction_y_mm != 0.0
            })
            .count() as u32;
        if mosaic.covered_fraction < MIN_WORKSPACE_COVERAGE {
            return Err(format!(
                "{} workspace mosaic covered only {:.1}% of the requested region",
                workspace_surface_model_name(surface_model),
                mosaic.covered_fraction * 100.0
            ));
        }
        let mosaic_png = encode_gray_png(&mosaic.frame).map_err(|error| error.to_string())?;
        persist_workspace_artifact(state, scan, &artifact_name, "image/png", &mosaic_png)?;
        scan.mosaic_layers.push(WorkspaceMosaicLayerReport {
            surface_model,
            artifact_name: artifact_name.clone(),
            covered_fraction: mosaic.covered_fraction,
            nominal_fallback_fraction: mosaic.nominal_fallback_fraction,
            accepted_registrations,
            attempted_registrations,
            applied_corrections,
        });
        if accepted_registrations < attempted_registrations {
            scan.warnings.push(format!(
                "{} layer used calibrated machine placement for {} of {} overlaps",
                workspace_surface_model_name(surface_model),
                attempted_registrations - accepted_registrations,
                attempted_registrations,
            ));
        }
        if layer_index == 0 {
            if let Some(seam_health) = mosaic.seam_health.as_ref() {
                persist_workspace_seam_health(state, scan, &mosaic, seam_health)?;
            }
            scan.mosaic_width_px = Some(mosaic.frame.width);
            scan.mosaic_height_px = Some(mosaic.frame.height);
            scan.covered_fraction = Some(mosaic.covered_fraction);
            scan.nominal_fallback_fraction = mosaic.nominal_fallback_fraction;
            scan.accepted_registrations = accepted_registrations;
            scan.attempted_registrations = attempted_registrations;
            scan.tiles = mosaic.tiles;
            scan.registrations = mosaic.registrations;
            scan.mosaic_artifact_name = Some(artifact_name);
        }
    }
    scan.parallax = None;
    if let Some(parallax) = parallax {
        let artifact_name = "surface-height-observations.json";
        let observation_limit =
            if scan.artifact_retention == WorkspaceArtifactRetention::TransientSources {
                MAX_TRANSIENT_PARALLAX_OBSERVATIONS
            } else {
                usize::MAX
            };
        let artifact = workspace_parallax_artifact(&parallax, observation_limit);
        let retained_observations = artifact.retained_observations;
        let encoded = serde_json::to_vec_pretty(&artifact).map_err(|error| error.to_string())?;
        persist_workspace_artifact(state, scan, artifact_name, "application/json", &encoded)?;
        scan.parallax = Some(WorkspaceParallaxSummary {
            artifact_name: artifact_name.into(),
            working_plane_fraction: parallax.working_plane_fraction,
            installed_plate_fraction: parallax.installed_plate_fraction,
            attempted_pairs: parallax.attempted_pairs,
            pairs_with_overlap: parallax.pairs_with_overlap,
            descriptor_matches: parallax.descriptor_matches,
            accepted_observations: parallax.accepted_observations,
        });
        if parallax.accepted_observations == 0 {
            scan.warnings
                .push("parallax analysis found no supported local height observations".into());
        }
        if retained_observations < parallax.accepted_observations {
            scan.warnings.push(format!(
                "retained a distributed sample of {retained_observations} from {} accepted parallax observations after height reconstruction",
                parallax.accepted_observations,
            ));
        }
    }
    scan.height_map = None;
    if let Some(height_artifacts) = height_artifacts {
        persist_workspace_height_artifacts(state, scan, height_artifacts)?;
    }
    scan.updated_at = Utc::now();
    state
        .store
        .put_workspace_scan(scan)
        .map_err(|error| error.to_string())?;
    Ok(format!(
        "Captured {} tiles into {} surface mosaics with {:.1}% primary coverage; {}/{} primary overlap registrations accepted{}{}",
        scan.captured_tiles,
        scan.mosaic_layers.len(),
        scan.covered_fraction.unwrap_or(0.0) * 100.0,
        scan.accepted_registrations,
        scan.attempted_registrations,
        if scan.height_map.is_some() {
            "; generated a surface-height map and height-corrected mosaic"
        } else {
            ""
        },
        scan.seam_health.as_ref().map_or(String::new(), |health| {
            format!(
                "; seam health recommends {} after {} healthy, {} elevated, and {} unresolved overlaps",
                workspace_seam_action_name(health.recommended_action),
                health.healthy_seams,
                health.elevated_seams,
                health.unresolved_seams,
            )
        }),
    ))
}

#[derive(Serialize)]
struct PersistedWorkspaceParallaxReport<'a> {
    working_plane_fraction: f64,
    installed_plate_fraction: f64,
    attempted_pairs: u32,
    pairs_with_overlap: u32,
    raw_matches: u32,
    descriptor_matches: u32,
    accepted_observations: u32,
    retained_observations: u32,
    observations: Vec<&'a WorkspaceParallaxObservation>,
}

fn workspace_parallax_artifact(
    report: &WorkspaceParallaxReport,
    observation_limit: usize,
) -> PersistedWorkspaceParallaxReport<'_> {
    let retained = report.observations.len().min(observation_limit);
    let observations: Vec<&WorkspaceParallaxObservation> = if retained == report.observations.len()
    {
        report.observations.iter().collect()
    } else if retained < 2 {
        report.observations.iter().take(retained).collect()
    } else {
        (0..retained)
            .map(|index| {
                let source_index = index * (report.observations.len() - 1) / (retained - 1);
                &report.observations[source_index]
            })
            .collect()
    };
    PersistedWorkspaceParallaxReport {
        working_plane_fraction: report.working_plane_fraction,
        installed_plate_fraction: report.installed_plate_fraction,
        attempted_pairs: report.attempted_pairs,
        pairs_with_overlap: report.pairs_with_overlap,
        raw_matches: report.raw_matches,
        descriptor_matches: report.descriptor_matches,
        accepted_observations: report.accepted_observations,
        retained_observations: observations.len() as u32,
        observations,
    }
}

fn persist_workspace_seam_health(
    state: &AppState,
    scan: &mut WorkspaceScanReport,
    mosaic: &WorkspaceMosaic,
    artifacts: &WorkspaceSeamHealthArtifacts,
) -> Result<(), String> {
    let report_json =
        serde_json::to_vec_pretty(&artifacts.report).map_err(|error| error.to_string())?;
    let disagreement_png =
        encode_gray_png(&mosaic.disagreement).map_err(|error| error.to_string())?;
    let confidence_png =
        encode_gray_png(&artifacts.overlap_confidence).map_err(|error| error.to_string())?;
    let overlay_png = encode_rgba_png(&artifacts.overlay).map_err(|error| error.to_string())?;
    let preview_png = encode_rgb_png(&artifacts.preview).map_err(|error| error.to_string())?;
    for (name, media_type, data) in [
        (
            WORKSPACE_SEAM_HEALTH_ARTIFACT,
            "application/json",
            report_json.as_slice(),
        ),
        (
            WORKSPACE_DISAGREEMENT_ARTIFACT,
            "image/png",
            disagreement_png.as_slice(),
        ),
        (
            WORKSPACE_OVERLAP_CONFIDENCE_ARTIFACT,
            "image/png",
            confidence_png.as_slice(),
        ),
        (
            WORKSPACE_SEAM_OVERLAY_ARTIFACT,
            "image/png",
            overlay_png.as_slice(),
        ),
        (
            WORKSPACE_SEAM_PREVIEW_ARTIFACT,
            "image/png",
            preview_png.as_slice(),
        ),
    ] {
        persist_workspace_artifact(state, scan, name, media_type, data)?;
    }
    let report = &artifacts.report;
    scan.seam_health = Some(WorkspaceSeamHealthSummary {
        report_artifact_name: WORKSPACE_SEAM_HEALTH_ARTIFACT.into(),
        disagreement_artifact_name: WORKSPACE_DISAGREEMENT_ARTIFACT.into(),
        overlap_confidence_artifact_name: WORKSPACE_OVERLAP_CONFIDENCE_ARTIFACT.into(),
        overlay_artifact_name: WORKSPACE_SEAM_OVERLAY_ARTIFACT.into(),
        preview_artifact_name: WORKSPACE_SEAM_PREVIEW_ARTIFACT.into(),
        total_seams: report.total_seams,
        healthy_seams: report.healthy_seams,
        elevated_seams: report.elevated_seams,
        unresolved_seams: report.unresolved_seams,
        target_regions: report.target_regions.len() as u32,
        overlap_pixel_fraction: report.overlap_pixel_fraction,
        disagreement_p50_luma: report.disagreement_p50_luma,
        disagreement_p95_luma: report.disagreement_p95_luma,
        recommended_action: report.recommended_action,
    });
    match report.recommended_action {
        WorkspaceSeamHealthAction::Accept => {}
        WorkspaceSeamHealthAction::TargetedRefinement => scan.warnings.push(format!(
            "seam diagnostics selected {} local regions for a refinement scan",
            report.target_regions.len(),
        )),
        WorkspaceSeamHealthAction::ReviewGeometry => scan.warnings.push(format!(
            "{} elevated overlaps have a coherent displacement; review workspace geometry before rescanning",
            report.elevated_seams,
        )),
        WorkspaceSeamHealthAction::IncreaseOverlap => scan.warnings.push(format!(
            "{} overlaps have elevated disagreement without a unique translation; rescan their regions with more overlap",
            report.unresolved_seams,
        )),
    }
    Ok(())
}

fn workspace_seam_action_name(action: WorkspaceSeamHealthAction) -> &'static str {
    match action {
        WorkspaceSeamHealthAction::Accept => "accept",
        WorkspaceSeamHealthAction::TargetedRefinement => "targeted refinement",
        WorkspaceSeamHealthAction::ReviewGeometry => "geometry review",
        WorkspaceSeamHealthAction::IncreaseOverlap => "increased overlap",
    }
}

fn persist_workspace_height_artifacts(
    state: &AppState,
    scan: &mut WorkspaceScanReport,
    artifacts: WorkspaceHeightArtifacts,
) -> Result<(), String> {
    let map_json = serde_json::to_vec_pretty(&artifacts.map).map_err(|error| error.to_string())?;
    let preview_png =
        encode_gray_png(&artifacts.composite.height_preview).map_err(|error| error.to_string())?;
    let confidence_png = encode_gray_png(&artifacts.composite.confidence_frame)
        .map_err(|error| error.to_string())?;
    let corrected_png =
        encode_gray_png(&artifacts.composite.frame).map_err(|error| error.to_string())?;
    let class_overlay_png =
        encode_rgba_png(&artifacts.composite.class_overlay).map_err(|error| error.to_string())?;
    let class_preview_png =
        encode_rgb_png(&artifacts.composite.class_preview).map_err(|error| error.to_string())?;
    persist_workspace_artifact(
        state,
        scan,
        WORKSPACE_HEIGHT_MAP_ARTIFACT,
        "application/json",
        &map_json,
    )?;
    persist_workspace_artifact(
        state,
        scan,
        WORKSPACE_HEIGHT_PREVIEW_ARTIFACT,
        "image/png",
        &preview_png,
    )?;
    persist_workspace_artifact(
        state,
        scan,
        WORKSPACE_HEIGHT_CONFIDENCE_ARTIFACT,
        "image/png",
        &confidence_png,
    )?;
    persist_workspace_artifact(
        state,
        scan,
        WORKSPACE_HEIGHT_CORRECTED_MOSAIC_ARTIFACT,
        "image/png",
        &corrected_png,
    )?;
    persist_workspace_artifact(
        state,
        scan,
        WORKSPACE_HEIGHT_CLASS_OVERLAY_ARTIFACT,
        "image/png",
        &class_overlay_png,
    )?;
    persist_workspace_artifact(
        state,
        scan,
        WORKSPACE_HEIGHT_CLASS_PREVIEW_ARTIFACT,
        "image/png",
        &class_preview_png,
    )?;
    let total_cells = artifacts.map.rows * artifacts.map.columns;
    if artifacts.map.unknown_cells > 0 {
        scan.warnings.push(format!(
            "height map left {} of {total_cells} cells unknown; the corrected mosaic selects the lower-disagreement endpoint projection in those cells",
            artifacts.map.unknown_cells,
        ));
    }
    if let Some(aperture) = &artifacts.camera_aperture {
        let projection_source = if aperture.projection_fitted_from_detections {
            "a self-fitted depth projection"
        } else {
            "the calibrated projection fallback"
        };
        scan.warnings.push(format!(
            "bottom-camera aperture at X={:.3}, Y={:.3} mm uses {} and {} aligned source tiles inside its {:.3} mm radius; tile {} is the most centered view",
            aperture.center_x_mm,
            aperture.center_y_mm,
            projection_source,
            aperture.source_tile_indices.len(),
            aperture.radius_mm,
            aperture.source_tile_index,
        ));
    }
    scan.height_map = Some(WorkspaceHeightMapSummary {
        map_artifact_name: WORKSPACE_HEIGHT_MAP_ARTIFACT.into(),
        preview_artifact_name: WORKSPACE_HEIGHT_PREVIEW_ARTIFACT.into(),
        confidence_artifact_name: WORKSPACE_HEIGHT_CONFIDENCE_ARTIFACT.into(),
        corrected_mosaic_artifact_name: WORKSPACE_HEIGHT_CORRECTED_MOSAIC_ARTIFACT.into(),
        class_overlay_artifact_name: WORKSPACE_HEIGHT_CLASS_OVERLAY_ARTIFACT.into(),
        class_preview_artifact_name: WORKSPACE_HEIGHT_CLASS_PREVIEW_ARTIFACT.into(),
        cell_size_mm: artifacts.map.cell_size_mm,
        rows: artifacts.map.rows,
        columns: artifacts.map.columns,
        measured_cells: artifacts.map.measured_cells,
        inferred_cells: artifacts.map.inferred_cells,
        unknown_cells: artifacts.map.unknown_cells,
        candidate_fractions: artifacts.composite.candidate_fractions,
        camera_aperture: artifacts.camera_aperture.as_ref().map(|aperture| {
            WorkspaceCameraApertureSummary {
                center_x_mm: aperture.center_x_mm,
                center_y_mm: aperture.center_y_mm,
                radius_mm: aperture.radius_mm,
                projection_mm_per_pixel: aperture.projection_mm_per_pixel,
                projection_residual_p95_mm: aperture.projection_residual_p95_mm,
                projection_fitted_from_detections: aperture.projection_fitted_from_detections,
                source_tile_index: aperture.source_tile_index,
                source_tile_indices: aperture.source_tile_indices.clone(),
                source_center_error_px: aperture.source_center_error_px,
                supporting_detections: aperture.supporting_detections,
            }
        }),
    });
    Ok(())
}

fn workspace_surface_model_name(surface_model: WorkspaceSurfaceModel) -> &'static str {
    match surface_model {
        WorkspaceSurfaceModel::TopCameraWorkingPlane => "top-camera-working-plane",
        WorkspaceSurfaceModel::InstalledPlatePlanes => "installed-plate-planes",
    }
}

struct TransientWorkspaceSources {
    directory: PathBuf,
}

impl TransientWorkspaceSources {
    fn create(scan_id: Uuid) -> Result<Self, String> {
        let directory =
            std::env::temp_dir().join(format!("velocitypnp-workspace-sources-{scan_id}"));
        fs::create_dir(&directory).map_err(|error| {
            format!(
                "could not create transient workspace directory {}: {error}",
                directory.display()
            )
        })?;
        Ok(Self { directory })
    }

    fn write(&self, tile_index: u32, frame: &GrayFrame) -> Result<(), String> {
        let encoded = encode_gray_png(frame).map_err(|error| error.to_string())?;
        let path = self
            .directory
            .join(transient_workspace_source_name(tile_index));
        fs::write(&path, encoded)
            .map_err(|error| format!("could not write {}: {error}", path.display()))
    }
}

impl Drop for TransientWorkspaceSources {
    fn drop(&mut self) {
        if let Err(error) = fs::remove_dir_all(&self.directory) {
            tracing::warn!(
                %error,
                directory = %self.directory.display(),
                "could not remove transient workspace sources"
            );
        }
    }
}

fn transient_workspace_source_name(tile_index: u32) -> String {
    format!("tile-{tile_index:05}.png")
}

fn read_transient_workspace_source(
    directory: &FilePath,
    tile: &WorkspaceScanTile,
) -> anyhow::Result<GrayFrame> {
    let name = if tile.artifact_name.is_empty() {
        transient_workspace_source_name(tile.index)
    } else {
        tile.artifact_name.clone()
    };
    let path = directory.join(name);
    let encoded = fs::read(&path).with_context(|| format!("could not read {}", path.display()))?;
    decode_gray_png(&encoded).with_context(|| format!("could not decode {}", path.display()))
}

fn persist_workspace_tile_artifact(
    state: &AppState,
    scan: &mut WorkspaceScanReport,
    tile: &velocitypnp_domain::WorkspaceScanTile,
    frame: &GrayFrame,
    transient_sources: Option<&TransientWorkspaceSources>,
) -> Result<(), String> {
    let encoded = match scan.artifact_retention {
        WorkspaceArtifactRetention::MosaicOnly => return Ok(()),
        WorkspaceArtifactRetention::TransientSources => {
            return transient_sources
                .ok_or_else(|| "transient workspace source store is unavailable".to_string())?
                .write(tile.index, frame);
        }
        WorkspaceArtifactRetention::FullSources => {
            encode_gray_png(frame).map_err(|error| error.to_string())?
        }
        WorkspaceArtifactRetention::Thumbnails => {
            let thumbnail =
                resize_gray_frame(frame, WORKSPACE_THUMBNAIL_WIDTH, WORKSPACE_THUMBNAIL_HEIGHT)
                    .map_err(|error| error.to_string())?;
            encode_gray_png(&thumbnail).map_err(|error| error.to_string())?
        }
    };
    persist_workspace_artifact(state, scan, &tile.artifact_name, "image/png", &encoded)
}

fn persist_workspace_artifact(
    state: &AppState,
    scan: &mut WorkspaceScanReport,
    name: &str,
    media_type: &str,
    data: &[u8],
) -> Result<(), String> {
    let replaced_bytes = state
        .store
        .get_workspace_scan_artifact(scan.id, name)
        .map_err(|error| error.to_string())?
        .map_or(0_u64, |(_, existing)| existing.len() as u64);
    let retained = scan
        .retained_artifact_bytes
        .checked_sub(replaced_bytes)
        .ok_or_else(|| "workspace retained artifact size is inconsistent".to_string())?
        .checked_add(data.len() as u64)
        .ok_or_else(|| "workspace retained artifact size overflowed".to_string())?;
    if retained > scan.artifact_quota_bytes {
        return Err(format!(
            "workspace artifacts need {retained} bytes, above the quota of {}",
            scan.artifact_quota_bytes
        ));
    }
    state
        .store
        .put_workspace_scan_artifact(scan.id, name, media_type, data)
        .map_err(|error| error.to_string())?;
    scan.retained_artifact_bytes = retained;
    Ok(())
}

fn persist_workspace_manifest(
    state: &AppState,
    scan: &mut WorkspaceScanReport,
) -> Result<(), String> {
    let artifact_bytes = state
        .store
        .workspace_scan_artifact_bytes_except(scan.id, "manifest.json")
        .map_err(|error| error.to_string())?;
    let mut total_bytes = artifact_bytes;
    let manifest = 'manifest: {
        for _ in 0..8 {
            scan.retained_artifact_bytes = total_bytes;
            let manifest = serde_json::to_vec_pretty(scan).map_err(|error| error.to_string())?;
            let next_total = artifact_bytes
                .checked_add(manifest.len() as u64)
                .ok_or_else(|| "workspace retained artifact size overflowed".to_string())?;
            if next_total == total_bytes {
                break 'manifest manifest;
            }
            total_bytes = next_total;
        }
        return Err("workspace manifest size did not converge".into());
    };
    if total_bytes > scan.artifact_quota_bytes {
        return Err(format!(
            "workspace artifacts need {total_bytes} bytes, above the quota of {}",
            scan.artifact_quota_bytes
        ));
    }
    state
        .store
        .put_workspace_scan_artifact(scan.id, "manifest.json", "application/json", &manifest)
        .map_err(|error| error.to_string())?;
    state
        .store
        .put_workspace_scan(scan)
        .map_err(|error| error.to_string())
}

async fn list_workspace_scans(State(state): State<AppState>) -> ApiResult<Json<Value>> {
    Ok(Json(json!({
        "scans": state
            .store
            .list_workspace_scans()
            .map_err(ApiError::internal)?
    })))
}

fn workspace_scan_summary(scan: &WorkspaceScanReport) -> Value {
    let display_artifact_name = scan
        .refinement_composite
        .as_ref()
        .filter(|summary| summary.accepted)
        .map(|summary| summary.mosaic_artifact_name.as_str())
        .or_else(|| {
            scan.height_map
                .as_ref()
                .map(|summary| summary.corrected_mosaic_artifact_name.as_str())
        })
        .or(scan.mosaic_artifact_name.as_deref());
    json!({
        "id": scan.id,
        "profile_id": scan.profile_id,
        "created_at": scan.created_at,
        "updated_at": scan.updated_at,
        "status": scan.status,
        "mode": scan.mode,
        "parent_scan_id": scan.parent_scan_id,
        "region": scan.region,
        "raster_transform": scan.raster_transform,
        "planned_tiles": scan.planned_tiles,
        "captured_tiles": scan.captured_tiles,
        "mosaic_width_px": scan.mosaic_width_px,
        "mosaic_height_px": scan.mosaic_height_px,
        "display_artifact_name": display_artifact_name,
        "height_map_available": scan.height_map.is_some(),
        "refinement_composite": scan.refinement_composite.as_ref().map(|summary| json!({
            "accepted": summary.accepted,
        })),
        "board_discovery": scan.board_discovery,
        "strip_feeder_inventory": scan.strip_feeder_inventory,
        "change_set": scan.change_set,
        "failure": scan.failure,
    })
}

async fn list_workspace_scan_summaries(State(state): State<AppState>) -> ApiResult<Json<Value>> {
    let scans = state
        .store
        .list_workspace_scans()
        .map_err(ApiError::internal)?;
    Ok(Json(json!({
        "scans": scans.iter().map(workspace_scan_summary).collect::<Vec<_>>()
    })))
}

async fn get_workspace_scan(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<WorkspaceScanReport>> {
    state
        .store
        .get_workspace_scan(id)
        .map_err(ApiError::internal)?
        .map(Json)
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))
}

const WORKSPACE_DISPLAY_PATCH_ALGORITHM: &str = "workspace_display_patch.v1";
const DISPLAY_PATCH_MAX_TRANSLATION_MM: f64 = 2.5;
const DISPLAY_PATCH_MAX_RESIDUAL_MM: f64 = 0.15;

async fn get_workspace_display_patches(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<Value>> {
    let mut patches = state
        .store
        .list_workspace_display_patches()
        .map_err(ApiError::internal)?
        .into_iter()
        .filter(|patch| patch.base_scan_id == id)
        .collect::<Vec<_>>();
    patches.sort_by(|left, right| right.source_created_at.cmp(&left.source_created_at));
    Ok(Json(json!({ "patches": patches })))
}

async fn rebuild_workspace_display_patches(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<Value>> {
    let base = state
        .store
        .get_workspace_scan(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))?;
    if base.status != WorkspaceScanStatus::Succeeded {
        return Err(ApiError::bad_request(
            "display patches require a completed base scan",
        ));
    }
    let patches = evaluate_workspace_display_patches(&state, &base)?;
    let current_ids = patches
        .iter()
        .map(|patch| patch.id)
        .collect::<BTreeSet<_>>();
    for mut stale in state
        .store
        .list_workspace_display_patches()
        .map_err(ApiError::internal)?
        .into_iter()
        .filter(|patch| patch.base_scan_id == base.id && !current_ids.contains(&patch.id))
    {
        stale.accepted = false;
        stale.rejection_reason = Some("Not selected by the latest display evaluation".into());
        stale.evaluated_at = Utc::now();
        state
            .store
            .put_workspace_display_patch(&stale)
            .map_err(ApiError::internal)?;
    }
    for patch in &patches {
        state
            .store
            .put_workspace_display_patch(patch)
            .map_err(ApiError::internal)?;
    }
    Ok(Json(json!({ "patches": patches })))
}

fn evaluate_workspace_display_patches(
    state: &AppState,
    base: &WorkspaceScanReport,
) -> ApiResult<Vec<WorkspaceDisplayPatch>> {
    let mut scans = state
        .store
        .list_workspace_scans()
        .map_err(ApiError::internal)?
        .into_iter()
        .filter(|scan| workspace_display_source_is_eligible(base, scan))
        .collect::<Vec<_>>();
    scans.sort_by(|left, right| right.created_at.cmp(&left.created_at));
    let previous = state
        .store
        .list_workspace_display_patches()
        .map_err(ApiError::internal)?;
    let mut patches = evaluate_board_display_patches(state, base, &scans, &previous)?;
    patches.extend(evaluate_feeder_display_patches(
        state, base, &scans, &previous,
    )?);
    patches.sort_by(|left, right| {
        left.kind
            .cmp(&right.kind)
            .then_with(|| left.object_label.cmp(&right.object_label))
    });
    Ok(patches)
}

fn workspace_display_source_is_eligible(
    base: &WorkspaceScanReport,
    scan: &WorkspaceScanReport,
) -> bool {
    scan.id != base.id
        && scan.status == WorkspaceScanStatus::Succeeded
        && scan.profile_id == base.profile_id
        && scan.calibration_id == base.calibration_id
        && scan.parent_scan_id == Some(base.id)
        && scan.created_at > base.created_at
        && scan.output_mm_per_pixel <= base.output_mm_per_pixel
        && scan.raster_transform.is_some()
        && scan.mosaic_width_px.is_some()
        && scan.mosaic_height_px.is_some()
}

fn evaluate_board_display_patches(
    state: &AppState,
    base: &WorkspaceScanReport,
    scans: &[WorkspaceScanReport],
    previous: &[WorkspaceDisplayPatch],
) -> ApiResult<Vec<WorkspaceDisplayPatch>> {
    let boards = state.store.list_boards().map_err(ApiError::internal)?;
    let mut registrations = state
        .store
        .list_board_registrations()
        .map_err(ApiError::internal)?
        .into_iter()
        .filter(|registration| {
            registration.passed
                && registration.profile_id == base.profile_id
                && registration.calibration_id == base.calibration_id
                && registration.design_to_machine.is_some()
                && registration.board_instance.is_some()
        })
        .collect::<Vec<_>>();
    registrations.sort_by(|left, right| right.updated_at.cmp(&left.updated_at));
    let mut seen_boards = BTreeSet::new();
    let mut patches = Vec::new();
    for registration in registrations {
        if !seen_boards.insert(registration.board_id) {
            continue;
        }
        let Some(board) = boards
            .iter()
            .find(|board| board.id == registration.board_id)
        else {
            continue;
        };
        let Some(bounds) = board.outline_bounds else {
            continue;
        };
        let transform = registration.design_to_machine.expect("filtered transform");
        let Some(instance) = registration.board_instance.as_ref() else {
            continue;
        };
        let clip = board_clip_polygon(bounds, transform);
        let fiducials = board
            .placements
            .iter()
            .filter(|placement| placement.fiducial)
            .collect::<Vec<_>>();
        if fiducials.len() < 3 {
            continue;
        }
        for scan in scans {
            if !polygon_is_inside_region(&clip, scan.region) {
                continue;
            }
            let Some(artifact_name) = workspace_display_artifact_name(scan) else {
                continue;
            };
            let Some((_, encoded)) = state
                .store
                .get_workspace_scan_artifact(scan.id, &artifact_name)
                .map_err(ApiError::internal)?
            else {
                continue;
            };
            let frame = match decode_gray_png(&encoded) {
                Ok(frame) => frame,
                Err(_) => continue,
            };
            let raster = scan.raster_transform.expect("filtered raster transform");
            let scale_mm_per_px = raster.x_mm_per_pixel.abs().max(raster.y_mm_per_pixel.abs());
            if !scale_mm_per_px.is_finite() || scale_mm_per_px <= 0.0 {
                continue;
            }
            let mut measured_points = Vec::new();
            let mut target_points = Vec::new();
            for fiducial in &fiducials {
                let target = transform.apply(fiducial.pose.x_mm, fiducial.pose.y_mm);
                let expected_x_px = (target.0 - raster.top_left_x_mm) / raster.x_mm_per_pixel;
                let expected_y_px = (target.1 - raster.top_left_y_mm) / raster.y_mm_per_pixel;
                if let Some(detection) = detect_board_fiducial_near(
                    &frame,
                    expected_x_px,
                    expected_y_px,
                    BOARD_REGISTRATION_SEARCH_RADIUS_MM / scale_mm_per_px,
                    BOARD_REGISTRATION_FIDUCIAL_DIAMETER_MM / scale_mm_per_px,
                    BOARD_REGISTRATION_FIDUCIAL_DIAMETER_TOLERANCE_MM / scale_mm_per_px,
                ) {
                    let measured_x = raster.top_left_x_mm + detection.x_px * raster.x_mm_per_pixel;
                    let measured_y = raster.top_left_y_mm + detection.y_px * raster.y_mm_per_pixel;
                    measured_points.push((measured_x, measured_y));
                    target_points.push(target);
                }
            }
            let Some(fit) = fit_rigid_transform(&measured_points, &target_points) else {
                continue;
            };
            let maximum_correction_mm = measured_points
                .iter()
                .zip(&target_points)
                .map(|(measured, target)| (target.0 - measured.0).hypot(target.1 - measured.1))
                .fold(0.0_f64, f64::max);
            if measured_points.len() < 3
                || maximum_correction_mm > DISPLAY_PATCH_MAX_TRANSLATION_MM
                || fit.residuals.p95_mm > DISPLAY_PATCH_MAX_RESIDUAL_MM
                || fit.residuals.max_mm > DISPLAY_PATCH_MAX_RESIDUAL_MM
            {
                continue;
            }
            patches.push(WorkspaceDisplayPatch {
                id: previous_patch_id(
                    previous,
                    base.id,
                    scan.id,
                    WorkspaceDisplayPatchKind::Board,
                    instance.id,
                ),
                algorithm_version: WORKSPACE_DISPLAY_PATCH_ALGORITHM.into(),
                base_scan_id: base.id,
                source_scan_id: scan.id,
                profile_id: base.profile_id.clone(),
                calibration_id: base.calibration_id,
                kind: WorkspaceDisplayPatchKind::Board,
                object_id: instance.id,
                object_label: instance.label.clone(),
                artifact_name,
                source_raster_transform: raster,
                source_width_px: scan.mosaic_width_px.expect("filtered width"),
                source_height_px: scan.mosaic_height_px.expect("filtered height"),
                source_to_base: fit.transform,
                clip_polygon_machine_mm: clip,
                anchor_count: measured_points.len() as u32,
                alignment_residuals: fit.residuals,
                accepted: true,
                rejection_reason: None,
                findings: vec![format!(
                    "Matched {} registered board fiducials",
                    measured_points.len(),
                )],
                source_created_at: scan.created_at,
                evaluated_at: Utc::now(),
            });
            break;
        }
    }
    Ok(patches)
}

fn evaluate_feeder_display_patches(
    state: &AppState,
    base: &WorkspaceScanReport,
    scans: &[WorkspaceScanReport],
    previous: &[WorkspaceDisplayPatch],
) -> ApiResult<Vec<WorkspaceDisplayPatch>> {
    let mut registrations = state
        .store
        .list_strip_feeder_registrations()
        .map_err(ApiError::internal)?
        .into_iter()
        .filter(|registration| {
            registration.profile_id == base.profile_id
                && registration.calibration_id == base.calibration_id
        })
        .collect::<Vec<_>>();
    registrations.sort_by(|left, right| right.updated_at.cmp(&left.updated_at));
    let mut seen_lanes = BTreeSet::new();
    registrations.retain(|registration| {
        let center = registration.pick_centerline_machine_mm[0][0]
            + registration.pick_centerline_machine_mm[1][0];
        seen_lanes.insert((center * 10.0).round() as i64)
    });
    let mut accepted_objects = BTreeSet::new();
    let mut patches = Vec::new();
    for scan in scans.iter().filter(|scan| scan.height_map.is_some()) {
        let raster = scan.raster_transform.expect("filtered raster transform");
        let Some(artifact_name) = scan
            .height_map
            .as_ref()
            .map(|summary| summary.corrected_mosaic_artifact_name.clone())
        else {
            continue;
        };
        let artifacts = state
            .store
            .list_workspace_scan_artifacts(scan.id)
            .map_err(ApiError::internal)?;
        for (report_name, _) in artifacts.into_iter().filter(|(name, media_type)| {
            name.starts_with("strip-feeder-vision-")
                && name.ends_with(".json")
                && media_type == "application/json"
        }) {
            let Some((_, data)) = state
                .store
                .get_workspace_scan_artifact(scan.id, &report_name)
                .map_err(ApiError::internal)?
            else {
                continue;
            };
            let report = match serde_json::from_slice::<StripFeederVisionReport>(&data) {
                Ok(report) => report,
                Err(_) => continue,
            };
            for proposal in report.proposals.iter().filter(|proposal| {
                !proposal.review_required
                    && proposal.confidence >= 0.8
                    && proposal.sprocket_pitch_residual_p95_mm <= DISPLAY_PATCH_MAX_RESIDUAL_MM
                    && proposal.pocket_centers_machine_mm.len() >= 8
            }) {
                let mut best: Option<(&StripFeederRegistration, [f64; 2], Residuals, usize)> = None;
                for registration in &registrations {
                    if accepted_objects.contains(&registration.id)
                        || (registration.tape_width_mm
                            - proposal.tape_width_mm.unwrap_or(registration.tape_width_mm))
                        .abs()
                            > 1.0
                        || (registration.tape_pitch_mm
                            - proposal
                                .component_pitch_mm
                                .unwrap_or(registration.tape_pitch_mm))
                        .abs()
                            > 0.25
                        || angle_difference_deg(
                            registration.tape_rotation_deg,
                            proposal.tape_rotation_deg,
                        )
                        .abs()
                            > 1.0
                    {
                        continue;
                    }
                    let offsets = lattice_offsets(
                        &proposal.pocket_centers_machine_mm,
                        &registration.pocket_centers_machine_mm,
                        DISPLAY_PATCH_MAX_TRANSLATION_MM,
                    );
                    let Some((translation, residuals)) = fit_display_translation(&offsets) else {
                        continue;
                    };
                    if offsets.len() < 8
                        || translation[0].hypot(translation[1]) > DISPLAY_PATCH_MAX_TRANSLATION_MM
                        || residuals.p95_mm > DISPLAY_PATCH_MAX_RESIDUAL_MM
                        || residuals.max_mm > DISPLAY_PATCH_MAX_RESIDUAL_MM
                    {
                        continue;
                    }
                    let replace = best.as_ref().is_none_or(|(_, _, current, count)| {
                        offsets.len() > *count
                            || (offsets.len() == *count && residuals.p95_mm < current.p95_mm)
                    });
                    if replace {
                        best = Some((registration, translation, residuals, offsets.len()));
                    }
                }
                let Some((registration, translation, residuals, anchor_count)) = best else {
                    continue;
                };
                accepted_objects.insert(registration.id);
                patches.push(WorkspaceDisplayPatch {
                    id: previous_patch_id(
                        previous,
                        base.id,
                        scan.id,
                        WorkspaceDisplayPatchKind::FeederLane,
                        registration.id,
                    ),
                    algorithm_version: WORKSPACE_DISPLAY_PATCH_ALGORITHM.into(),
                    base_scan_id: base.id,
                    source_scan_id: scan.id,
                    profile_id: base.profile_id.clone(),
                    calibration_id: base.calibration_id,
                    kind: WorkspaceDisplayPatchKind::FeederLane,
                    object_id: registration.id,
                    object_label: registration.name.clone(),
                    artifact_name: artifact_name.clone(),
                    source_raster_transform: raster,
                    source_width_px: scan.mosaic_width_px.expect("filtered width"),
                    source_height_px: scan.mosaic_height_px.expect("filtered height"),
                    source_to_base: velocitypnp_domain::Transform2d::rigid(
                        translation[0],
                        translation[1],
                        0.0,
                    ),
                    clip_polygon_machine_mm: feeder_lane_clip(registration),
                    anchor_count: anchor_count as u32,
                    alignment_residuals: residuals,
                    accepted: true,
                    rejection_reason: None,
                    findings: vec![format!("Matched {anchor_count} registered feeder pockets",)],
                    source_created_at: scan.created_at,
                    evaluated_at: Utc::now(),
                });
            }
        }
    }
    Ok(patches)
}

fn workspace_display_artifact_name(scan: &WorkspaceScanReport) -> Option<String> {
    scan.height_map
        .as_ref()
        .map(|summary| summary.corrected_mosaic_artifact_name.clone())
        .or_else(|| scan.mosaic_artifact_name.clone())
}

fn previous_patch_id(
    previous: &[WorkspaceDisplayPatch],
    base_scan_id: Uuid,
    source_scan_id: Uuid,
    kind: WorkspaceDisplayPatchKind,
    object_id: Uuid,
) -> Uuid {
    previous
        .iter()
        .find(|patch| {
            patch.base_scan_id == base_scan_id
                && patch.source_scan_id == source_scan_id
                && patch.kind == kind
                && patch.object_id == object_id
        })
        .map(|patch| patch.id)
        .unwrap_or_else(Uuid::new_v4)
}

fn board_clip_polygon(
    bounds: velocitypnp_domain::BoardOutlineBounds,
    transform: velocitypnp_domain::Transform2d,
) -> Vec<[f64; 2]> {
    [
        [bounds.min_x_mm, bounds.min_y_mm],
        [bounds.max_x_mm, bounds.min_y_mm],
        [bounds.max_x_mm, bounds.max_y_mm],
        [bounds.min_x_mm, bounds.max_y_mm],
    ]
    .into_iter()
    .map(|point| {
        let transformed = transform.apply(point[0], point[1]);
        [transformed.0, transformed.1]
    })
    .collect()
}

fn polygon_is_inside_region(points: &[[f64; 2]], region: WorkspaceScanRegion) -> bool {
    points.iter().all(|point| {
        (region.x_min_mm..=region.x_max_mm).contains(&point[0])
            && (region.y_min_mm..=region.y_max_mm).contains(&point[1])
    })
}

fn lattice_offsets(
    source: &[[f64; 2]],
    target: &[[f64; 2]],
    maximum_distance_mm: f64,
) -> Vec<[f64; 2]> {
    let mut used = BTreeSet::new();
    source
        .iter()
        .filter_map(|source_point| {
            let (target_index, target_point, distance) = target
                .iter()
                .enumerate()
                .filter(|(index, _)| !used.contains(index))
                .map(|(index, point)| {
                    (
                        index,
                        point,
                        (point[0] - source_point[0]).hypot(point[1] - source_point[1]),
                    )
                })
                .min_by(|left, right| left.2.total_cmp(&right.2))?;
            if distance > maximum_distance_mm {
                return None;
            }
            used.insert(target_index);
            Some([
                target_point[0] - source_point[0],
                target_point[1] - source_point[1],
            ])
        })
        .collect()
}

fn fit_display_translation(offsets: &[[f64; 2]]) -> Option<([f64; 2], Residuals)> {
    if offsets.is_empty() {
        return None;
    }
    let mut x = offsets.iter().map(|offset| offset[0]).collect::<Vec<_>>();
    let mut y = offsets.iter().map(|offset| offset[1]).collect::<Vec<_>>();
    x.sort_by(f64::total_cmp);
    y.sort_by(f64::total_cmp);
    let translation = [x[x.len() / 2], y[y.len() / 2]];
    let residuals = summarize_residuals(
        offsets
            .iter()
            .map(|offset| (offset[0] - translation[0]).hypot(offset[1] - translation[1])),
    )?;
    Some((translation, residuals))
}

fn feeder_lane_clip(registration: &StripFeederRegistration) -> Vec<[f64; 2]> {
    let [start, end] = registration.pick_centerline_machine_mm;
    let delta = [end[0] - start[0], end[1] - start[1]];
    let length = delta[0].hypot(delta[1]);
    let normal = if length > 0.0 {
        [-delta[1] / length, delta[0] / length]
    } else {
        [1.0, 0.0]
    };
    let half_width = registration.tape_width_mm / 2.0;
    [
        [
            start[0] + normal[0] * half_width,
            start[1] + normal[1] * half_width,
        ],
        [
            end[0] + normal[0] * half_width,
            end[1] + normal[1] * half_width,
        ],
        [
            end[0] - normal[0] * half_width,
            end[1] - normal[1] * half_width,
        ],
        [
            start[0] - normal[0] * half_width,
            start[1] - normal[1] * half_width,
        ],
    ]
    .into()
}

async fn get_workspace_refinement_targets(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<WorkspaceRefinementTargetsResponse>> {
    let scan = state
        .store
        .get_workspace_scan(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))?;
    let artifacts = reanalyze_retained_workspace_seams(&state, &scan).await?;
    let scans = state
        .store
        .list_workspace_scans()
        .map_err(ApiError::internal)?;
    let targets = rank_workspace_refinement_targets(&artifacts.report, &scans, scan.id);
    let remaining_targets = targets
        .iter()
        .filter(|target| target.completed_scan_id.is_none())
        .count() as u32;
    Ok(Json(WorkspaceRefinementTargetsResponse {
        parent_scan_id: scan.id,
        algorithm_version: artifacts.report.algorithm_version,
        recommended_action: artifacts.report.recommended_action,
        priority_algorithm_version: WORKSPACE_REFINEMENT_PRIORITY_ALGORITHM,
        target_regions: artifacts.report.target_regions,
        targets,
        remaining_targets,
    }))
}

async fn start_workspace_refinement_batch(
    State(state): State<AppState>,
    Path(parent_scan_id): Path<Uuid>,
    Json(body): Json<StartWorkspaceRefinementBatchRequest>,
) -> ApiResult<(StatusCode, Json<StartWorkspaceRefinementBatchResponse>)> {
    if !body.confirmed_external_safety_checks {
        return Err(ApiError::bad_request(
            "workspace refinement requires confirmation that all target regions and the travel envelope are clear, both nozzles are level, and power isolation is reachable",
        ));
    }
    let max_targets = body
        .max_targets
        .unwrap_or(MAX_WORKSPACE_REFINEMENT_BATCH_TARGETS);
    if max_targets == 0 || max_targets > MAX_WORKSPACE_REFINEMENT_BATCH_TARGETS {
        return Err(ApiError::bad_request(format!(
            "max_targets must be between 1 and {MAX_WORKSPACE_REFINEMENT_BATCH_TARGETS}"
        )));
    }
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed {
        return Err(ApiError::bad_request(
            "workspace refinement requires a homed ready machine",
        ));
    }
    if !status.simulated && status.calibration_revision != Some(body.calibration_id) {
        return Err(ApiError::bad_request(format!(
            "physical workspace refinement requires fine XYZ homing with calibration {}",
            body.calibration_id,
        )));
    }
    let current_pose = status
        .pose
        .ok_or_else(|| ApiError::bad_request("workspace refinement requires a known pose"))?;
    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(&state)?;
    ensure_no_active_board_registrations(&state)?;
    ensure_no_active_board_surface_measurements(&state)?;
    ensure_no_active_strip_feeder_holdouts(&state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(&state)?;
    let parent = state
        .store
        .get_workspace_scan(parent_scan_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("parent workspace scan not found"))?;
    if parent.status != WorkspaceScanStatus::Succeeded
        || parent.mode != WorkspaceScanMode::Reconnaissance
    {
        return Err(ApiError::bad_request(
            "workspace refinement requires a successful reconnaissance parent",
        ));
    }
    if !state.profile.accepts_profile_id(&parent.profile_id)
        || parent.calibration_id != body.calibration_id
    {
        return Err(ApiError::bad_request(
            "workspace refinement must use its parent's profile and calibration",
        ));
    }
    let artifacts = reanalyze_retained_workspace_seams(&state, &parent).await?;
    match artifacts.report.recommended_action {
        WorkspaceSeamHealthAction::TargetedRefinement
        | WorkspaceSeamHealthAction::IncreaseOverlap => {}
        WorkspaceSeamHealthAction::ReviewGeometry => {
            return Err(ApiError::bad_request(
                "workspace seam health requires geometry review before refinement",
            ));
        }
        WorkspaceSeamHealthAction::Accept => {
            return Err(ApiError::bad_request(
                "workspace seam health does not require refinement",
            ));
        }
    }
    let scans = state
        .store
        .list_workspace_scans()
        .map_err(ApiError::internal)?;
    let ranked = rank_workspace_refinement_targets(&artifacts.report, &scans, parent.id);
    let completed_target_indices = ranked
        .iter()
        .filter(|target| target.completed_scan_id.is_some())
        .map(|target| target.target_index)
        .collect::<Vec<_>>();
    let selected = ranked
        .into_iter()
        .filter(|target| target.completed_scan_id.is_none())
        .take(max_targets as usize)
        .collect::<Vec<_>>();
    if selected.is_empty() {
        return Err(ApiError::bad_request(
            "all current workspace refinement targets already succeeded",
        ));
    }

    let top_profile = stored_camera_profile(&state, CameraRole::TopCamera)?;
    let top_path = camera_path_for_role(CameraRole::TopCamera)?;
    let (snapshot, top_camera_model) = load_workspace_camera_model(&state, body.calibration_id)?;
    let motion_calibration = if status.simulated {
        None
    } else {
        Some(load_motion_calibration(
            &state,
            body.calibration_id,
            "workspace refinement motion",
        )?)
    };
    let motion_planner = MotionPlanner::new(state.profile.bounds, motion_calibration);
    let (camera_model, surface_model, installed_camera_model, installed_geometry) =
        select_workspace_surface_models(
            &state,
            &snapshot,
            top_camera_model,
            Some(WorkspaceRegionPreset::InstalledPlates),
            WorkspaceScanMode::Refinement,
        )?;
    let batch_operation = Operation::pending("vision.workspace_refinement_batch");
    let batch_operation_id = batch_operation.id;
    let return_pose = state
        .profile
        .visual_homing
        .as_ref()
        .and_then(|visual| visual.seed_pose.resolve(current_pose))
        .unwrap_or(state.profile.home_pose);
    let mut prepared = Vec::with_capacity(selected.len());
    for (queue_index, target) in selected.into_iter().enumerate() {
        let refinement = WorkspaceRefinementSource {
            parent_scan_id: parent.id,
            profile_id: parent.profile_id.clone(),
            target_index: target.target_index,
            region: target.region,
            recommended_action: artifacts.report.recommended_action,
            algorithm_version: artifacts.report.algorithm_version.clone(),
        };
        let specification = WorkspaceScanSpecification {
            calibration_id: body.calibration_id,
            mode: WorkspaceScanMode::Refinement,
            artifact_retention: Some(WorkspaceArtifactRetention::TransientSources),
            region: None,
            region_preset: None,
            parent_scan_id: Some(parent.id),
            refinement_target_index: Some(target.target_index),
            overlap_fraction: body.overlap_fraction,
            output_mm_per_pixel: body.output_mm_per_pixel,
            feed_mm_per_min: body.feed_mm_per_min,
            max_tiles: None,
            artifact_quota_bytes: body.artifact_quota_bytes,
        };
        let start_pose = if queue_index == 0 {
            current_pose
        } else {
            return_pose
        };
        let (plan, estimate) = prepare_workspace_scan(
            &state,
            &specification,
            &top_profile,
            &camera_model,
            surface_model,
            installed_camera_model.as_ref(),
            installed_geometry.as_ref(),
            Some(&refinement),
            start_pose,
            motion_planner.maximum_controller_margin_mm(),
            controller_xy_acceleration_mm_per_s2(&status),
        )?;
        validate_workspace_motion_plan(
            &state.profile,
            &motion_planner,
            start_pose,
            &plan,
            estimate.feed_mm_per_min,
        )?;
        let operation = Operation::pending("vision.workspace_refinement");
        let scan = pending_workspace_scan(
            &state,
            operation.id,
            snapshot.id,
            WorkspaceScanLineage::Refinement(&refinement),
            &plan,
            &estimate,
            WorkspaceRefinementQueueMetadata {
                batch_operation_id: Some(batch_operation.id),
                priority: Some(target.priority),
                severity_score: Some(target.severity_score),
            },
        );
        prepared.push(PreparedWorkspaceRefinement {
            target,
            scan,
            operation,
            estimate,
            plan,
        });
    }
    let estimated_duration_seconds = prepared.iter().try_fold(0_u64, |total, item| {
        total
            .checked_add(item.estimate.estimated_duration_seconds)
            .ok_or_else(|| ApiError::bad_request("refinement duration estimate overflow"))
    })?;
    let estimated_retained_bytes = prepared.iter().try_fold(0_u64, |total, item| {
        total
            .checked_add(item.estimate.estimated_retained_bytes)
            .ok_or_else(|| ApiError::bad_request("refinement storage estimate overflow"))
    })?;
    state
        .machine
        .renew_lease(body.lease_id, CALIBRATION_LEASE_SECONDS)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    state
        .store
        .put_operation(&batch_operation)
        .map_err(ApiError::internal)?;
    for item in &prepared {
        state
            .store
            .put_operation(&item.operation)
            .map_err(ApiError::internal)?;
        state
            .store
            .put_workspace_scan(&item.scan)
            .map_err(ApiError::internal)?;
    }
    let items = prepared
        .iter()
        .map(|item| WorkspaceRefinementBatchItemResponse {
            target: item.target.clone(),
            scan: item.scan.clone(),
            operation: item.operation.clone(),
            estimate: item.estimate.clone(),
        })
        .collect();
    let response = StartWorkspaceRefinementBatchResponse {
        operation: batch_operation.clone(),
        parent_scan_id: parent.id,
        algorithm_version: artifacts.report.algorithm_version,
        recommended_action: artifacts.report.recommended_action,
        priority_algorithm_version: WORKSPACE_REFINEMENT_PRIORITY_ALGORITHM,
        completed_target_indices,
        items,
        estimated_duration_seconds,
        estimated_retained_bytes,
    };
    drop(admission_guard);
    let task_state = state.clone();
    spawn_prepared_operation(
        state,
        batch_operation,
        execute_workspace_refinement_batch(
            task_state,
            batch_operation_id,
            prepared,
            camera_model,
            installed_camera_model,
            top_profile,
            top_path,
            motion_planner,
            body.lease_id,
        ),
    );
    Ok((StatusCode::ACCEPTED, Json(response)))
}

async fn build_workspace_refinement_composite(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<WorkspaceRefinementCompositeSummary>> {
    let mut parent = state
        .store
        .get_workspace_scan(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))?;
    if parent.status != WorkspaceScanStatus::Succeeded
        || parent.mode != WorkspaceScanMode::Reconnaissance
    {
        return Err(ApiError::bad_request(
            "refinement composition requires a successful reconnaissance scan",
        ));
    }
    let parent_transform = parent.raster_transform.ok_or_else(|| {
        ApiError::bad_request("reconnaissance scan has no machine-coordinate raster transform")
    })?;
    let parent_artifact_name = parent
        .mosaic_artifact_name
        .as_deref()
        .unwrap_or("mosaic.png");
    let (parent_media_type, parent_data) = state
        .store
        .get_workspace_scan_artifact(parent.id, parent_artifact_name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("reconnaissance mosaic artifact not found"))?;
    if parent_media_type != "image/png" {
        return Err(ApiError::internal(anyhow::anyhow!(
            "reconnaissance mosaic artifact is not a PNG"
        )));
    }
    let parent_width = parent.mosaic_width_px.ok_or_else(|| {
        ApiError::internal(anyhow::anyhow!("reconnaissance mosaic width is absent"))
    })?;
    let parent_height = parent.mosaic_height_px.ok_or_else(|| {
        ApiError::internal(anyhow::anyhow!("reconnaissance mosaic height is absent"))
    })?;

    let seam_artifacts = reanalyze_retained_workspace_seams(&state, &parent).await?;
    let scans = state
        .store
        .list_workspace_scans()
        .map_err(ApiError::internal)?;
    let mut targets = rank_workspace_refinement_targets(&seam_artifacts.report, &scans, parent.id);
    targets.sort_by_key(|target| target.target_index);
    let mut missing_target_indices = Vec::new();
    let mut encoded_patches = Vec::new();
    for target in &targets {
        let Some(scan_id) = target.completed_scan_id else {
            missing_target_indices.push(target.target_index);
            continue;
        };
        let child = scans
            .iter()
            .find(|scan| scan.id == scan_id)
            .ok_or_else(|| {
                ApiError::internal(anyhow::anyhow!("completed refinement scan is absent"))
            })?;
        if child.calibration_id != parent.calibration_id || child.profile_id != parent.profile_id {
            missing_target_indices.push(target.target_index);
            continue;
        }
        let Some(height_map) = child.height_map.as_ref() else {
            missing_target_indices.push(target.target_index);
            continue;
        };
        let artifact_name = height_map.corrected_mosaic_artifact_name.clone();
        let (media_type, data) = state
            .store
            .get_workspace_scan_artifact(child.id, &artifact_name)
            .map_err(ApiError::internal)?
            .ok_or_else(|| {
                ApiError::not_found(format!(
                    "refinement target {} corrected mosaic not found",
                    target.target_index,
                ))
            })?;
        if media_type != "image/png" {
            return Err(ApiError::internal(anyhow::anyhow!(
                "refinement target {} corrected mosaic is not a PNG",
                target.target_index,
            )));
        }
        let expected_width = child.mosaic_width_px.ok_or_else(|| {
            ApiError::internal(anyhow::anyhow!(
                "refinement target {} mosaic width is absent",
                target.target_index,
            ))
        })?;
        let expected_height = child.mosaic_height_px.ok_or_else(|| {
            ApiError::internal(anyhow::anyhow!(
                "refinement target {} mosaic height is absent",
                target.target_index,
            ))
        })?;
        let raster_transform = child.raster_transform.ok_or_else(|| {
            ApiError::internal(anyhow::anyhow!(
                "refinement target {} has no raster transform",
                target.target_index,
            ))
        })?;
        encoded_patches.push(EncodedWorkspaceRefinementPatch {
            target_index: target.target_index,
            scan_id: child.id,
            artifact_name,
            encoded: data,
            expected_width,
            expected_height,
            raster_transform,
            covered_fraction: child.covered_fraction.unwrap_or(0.0),
            tiles: child.tiles.clone(),
        });
    }
    let composite = tokio::task::spawn_blocking(move || {
        let parent_frame = decode_gray_png(&parent_data)?;
        anyhow::ensure!(
            parent_frame.width == parent_width && parent_frame.height == parent_height,
            "reconnaissance mosaic dimensions do not match its report"
        );
        let patches = encoded_patches
            .into_iter()
            .map(|patch| {
                let frame = decode_gray_png(&patch.encoded)?;
                anyhow::ensure!(
                    frame.width == patch.expected_width && frame.height == patch.expected_height,
                    "refinement target {} mosaic dimensions do not match its report",
                    patch.target_index,
                );
                Ok(WorkspaceRefinementPatch {
                    target_index: patch.target_index,
                    scan_id: patch.scan_id,
                    artifact_name: patch.artifact_name,
                    frame,
                    raster_transform: patch.raster_transform,
                    covered_fraction: patch.covered_fraction,
                    tiles: patch.tiles,
                })
            })
            .collect::<anyhow::Result<Vec<_>>>()?;
        compose_workspace_refinements(&parent_frame, parent_transform, &patches)
    })
    .await
    .map_err(ApiError::internal)?
    .map_err(ApiError::internal)?;
    let accepted_target_count = composite
        .patches
        .iter()
        .filter(|patch| patch.accepted)
        .count() as u32;
    let mut findings = Vec::new();
    if !missing_target_indices.is_empty() {
        findings.push(format!(
            "{} current targets have no compatible successful height-corrected refinement",
            missing_target_indices.len(),
        ));
    }
    let rejected_targets = composite
        .patches
        .iter()
        .filter(|patch| !patch.accepted)
        .map(|patch| patch.target_index.to_string())
        .collect::<Vec<_>>();
    if !rejected_targets.is_empty() {
        findings.push(format!(
            "quality review is required for targets {}",
            rejected_targets.join(", "),
        ));
    }
    if seam_artifacts.report.recommended_action == WorkspaceSeamHealthAction::ReviewGeometry {
        findings.push("the parent seam policy requires a geometry review".into());
    }
    let accepted = missing_target_indices.is_empty()
        && accepted_target_count == targets.len() as u32
        && seam_artifacts.report.recommended_action != WorkspaceSeamHealthAction::ReviewGeometry;
    if accepted {
        findings
            .push("all current refinement targets passed the automatic composition gate".into());
    }
    let summary = WorkspaceRefinementCompositeSummary {
        algorithm_version: WORKSPACE_REFINEMENT_COMPOSITE_ALGORITHM.into(),
        source_algorithm_version: seam_artifacts.report.algorithm_version,
        source_recommended_action: seam_artifacts.report.recommended_action,
        mosaic_artifact_name: WORKSPACE_REFINED_MOSAIC_ARTIFACT.into(),
        quality_report_artifact_name: WORKSPACE_REFINEMENT_QUALITY_ARTIFACT.into(),
        quality_preview_artifact_name: WORKSPACE_REFINEMENT_QUALITY_PREVIEW_ARTIFACT.into(),
        thresholds: WorkspaceRefinementQualityThresholds {
            minimum_coverage_fraction: MIN_REFINEMENT_COMPOSITE_COVERAGE,
            minimum_texture_retention_ratio: MIN_REFINEMENT_TEXTURE_RETENTION_RATIO,
            boundary_review_p95_luma: MAX_REFINEMENT_BOUNDARY_DISAGREEMENT_P95_LUMA,
            seam_discontinuity_review_ratio: MAX_REFINEMENT_SEAM_DISCONTINUITY_RATIO,
        },
        accepted,
        target_count: targets.len() as u32,
        composed_target_count: composite.patches.len() as u32,
        accepted_target_count,
        missing_target_indices,
        patches: composite.patches,
        findings,
    };
    let mosaic_png = encode_gray_png(&composite.frame).map_err(ApiError::internal)?;
    let preview_png = encode_rgb_png(&composite.quality_preview).map_err(ApiError::internal)?;
    let report_json = serde_json::to_vec_pretty(&summary).map_err(ApiError::internal)?;
    persist_workspace_artifact(
        &state,
        &mut parent,
        WORKSPACE_REFINED_MOSAIC_ARTIFACT,
        "image/png",
        &mosaic_png,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    persist_workspace_artifact(
        &state,
        &mut parent,
        WORKSPACE_REFINEMENT_QUALITY_PREVIEW_ARTIFACT,
        "image/png",
        &preview_png,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    persist_workspace_artifact(
        &state,
        &mut parent,
        WORKSPACE_REFINEMENT_QUALITY_ARTIFACT,
        "application/json",
        &report_json,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    parent.refinement_composite = Some(summary.clone());
    parent.updated_at = Utc::now();
    persist_workspace_manifest(&state, &mut parent)
        .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    Ok(Json(summary))
}

async fn build_workspace_board_discovery(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<WorkspaceBoardDiscoveryReport>> {
    let mut scan = state
        .store
        .get_workspace_scan(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))?;
    if scan.status != WorkspaceScanStatus::Succeeded {
        return Err(ApiError::bad_request(
            "board discovery requires a successful workspace scan",
        ));
    }
    let raster_transform = scan.raster_transform.ok_or_else(|| {
        ApiError::bad_request("workspace scan has no machine-coordinate raster transform")
    })?;
    let source_mosaic_artifact_name = scan
        .refinement_composite
        .as_ref()
        .filter(|summary| summary.accepted)
        .map(|summary| summary.mosaic_artifact_name.clone())
        .or_else(|| {
            scan.height_map
                .as_ref()
                .map(|summary| summary.corrected_mosaic_artifact_name.clone())
        })
        .ok_or_else(|| {
            ApiError::bad_request(
                "board discovery requires a height-aware scan or accepted refinement composite",
            )
        })?;
    let (mosaic_media_type, mosaic_data) = state
        .store
        .get_workspace_scan_artifact(scan.id, &source_mosaic_artifact_name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("board discovery source mosaic not found"))?;
    if mosaic_media_type != "image/png" {
        return Err(ApiError::internal(anyhow::anyhow!(
            "board discovery source mosaic is not a PNG"
        )));
    }
    let mut height_scan_ids = Vec::new();
    if scan.height_map.is_some() {
        height_scan_ids.push(scan.id);
    }
    if let Some(composite) = scan
        .refinement_composite
        .as_ref()
        .filter(|summary| summary.accepted)
    {
        height_scan_ids.extend(
            composite
                .patches
                .iter()
                .filter(|patch| patch.accepted)
                .map(|patch| patch.scan_id),
        );
    }
    height_scan_ids.sort_unstable();
    height_scan_ids.dedup();
    let mut height_sources = Vec::new();
    let mut height_data = Vec::new();
    let mut camera_apertures = Vec::new();
    for height_scan_id in height_scan_ids {
        let height_scan = state
            .store
            .get_workspace_scan(height_scan_id)
            .map_err(ApiError::internal)?
            .ok_or_else(|| ApiError::not_found("board discovery height-source scan not found"))?;
        if height_scan.calibration_id != scan.calibration_id
            || height_scan.profile_id != scan.profile_id
        {
            return Err(ApiError::bad_request(
                "board discovery height sources use different machine geometry",
            ));
        }
        let height_map_artifact_name = height_scan
            .height_map
            .as_ref()
            .ok_or_else(|| ApiError::not_found("height-source scan has no surface-height map"))?
            .map_artifact_name
            .clone();
        if let Some(aperture) = height_scan
            .height_map
            .as_ref()
            .and_then(|summary| summary.camera_aperture.clone())
        {
            camera_apertures.push(aperture);
        }
        let (height_media_type, data) = state
            .store
            .get_workspace_scan_artifact(height_scan_id, &height_map_artifact_name)
            .map_err(ApiError::internal)?
            .ok_or_else(|| ApiError::not_found("workspace surface-height map not found"))?;
        if height_media_type != "application/json" {
            return Err(ApiError::internal(anyhow::anyhow!(
                "workspace surface-height map is not JSON"
            )));
        }
        height_sources.push(WorkspaceBoardHeightSource {
            scan_id: height_scan_id,
            artifact_name: height_map_artifact_name,
        });
        height_data.push(data);
    }
    if height_sources.is_empty() {
        return Err(ApiError::bad_request(
            "board discovery found no compatible surface-height evidence",
        ));
    }
    let camera_aperture = camera_apertures
        .into_iter()
        .max_by_key(|aperture| aperture.supporting_detections);
    let calibration = state
        .store
        .get_calibration(scan.calibration_id)
        .map_err(ApiError::internal)?;
    let installed_plate_geometry = calibration
        .as_ref()
        .and_then(|calibration| {
            calibration
                .artifacts
                .get(&CalibrationArtifactId::InstalledPlateGeometry)
        })
        .map(|artifact| {
            serde_json::from_value::<InstalledPlateGeometryReport>(artifact.value.clone())
        })
        .transpose()
        .map_err(ApiError::internal)?;
    let discovery_context = build_workspace_discovery_context(
        &state.profile,
        installed_plate_geometry.as_ref(),
        camera_aperture.as_ref(),
    )
    .map_err(ApiError::internal)?;
    let board_designs = state.store.list_boards().map_err(ApiError::internal)?;
    let scan_region = scan.region;
    let discovery = tokio::task::spawn_blocking(move || {
        let mosaic = decode_gray_png(&mosaic_data)?;
        let height_maps = height_data
            .iter()
            .map(|data| serde_json::from_slice::<WorkspaceHeightMap>(data))
            .collect::<Result<Vec<_>, _>>()?;
        let height_map = merge_workspace_height_maps(scan_region, &height_maps)?;
        discover_workspace_objects(
            &mosaic,
            raster_transform,
            &height_map,
            &board_designs,
            &source_mosaic_artifact_name,
            &height_sources,
            &discovery_context,
            &DeterministicWorkspaceObjectClassifier,
        )
    })
    .await
    .map_err(ApiError::internal)?
    .map_err(ApiError::internal)?;
    let report_json = serde_json::to_vec_pretty(&discovery.report).map_err(ApiError::internal)?;
    let preview_png = encode_rgb_png(&discovery.preview).map_err(ApiError::internal)?;
    persist_workspace_artifact(
        &state,
        &mut scan,
        WORKSPACE_BOARD_DISCOVERY_REPORT_ARTIFACT,
        "application/json",
        &report_json,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    for evidence in &discovery.evidence {
        let encoded = encode_gray_png(&evidence.frame).map_err(ApiError::internal)?;
        persist_workspace_artifact(
            &state,
            &mut scan,
            &evidence.artifact_name,
            "image/png",
            &encoded,
        )
        .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    }
    persist_workspace_artifact(
        &state,
        &mut scan,
        WORKSPACE_BOARD_DISCOVERY_PREVIEW_ARTIFACT,
        "image/png",
        &preview_png,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    scan.board_discovery = Some(WorkspaceBoardDiscoverySummary {
        algorithm_version: discovery.report.algorithm_version.clone(),
        source_mosaic_artifact_name: discovery.report.source_mosaic_artifact_name.clone(),
        report_artifact_name: WORKSPACE_BOARD_DISCOVERY_REPORT_ARTIFACT.into(),
        preview_artifact_name: WORKSPACE_BOARD_DISCOVERY_PREVIEW_ARTIFACT.into(),
        candidate_count: discovery.report.candidates.len() as u32,
        matched_candidate_count: discovery
            .report
            .candidates
            .iter()
            .filter(|candidate| !candidate.design_matches.is_empty())
            .count() as u32,
        board_design_count: discovery.report.board_design_count,
        height_source_count: discovery.report.height_sources.len() as u32,
    });
    scan.updated_at = Utc::now();
    persist_workspace_manifest(&state, &mut scan)
        .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    Ok(Json(discovery.report))
}

fn load_workspace_object_report(
    state: &AppState,
    scan: &WorkspaceScanReport,
) -> ApiResult<WorkspaceBoardDiscoveryReport> {
    let summary = scan
        .board_discovery
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("workspace scan has no semantic object proposals"))?;
    if summary.algorithm_version != WORKSPACE_BOARD_DISCOVERY_ALGORITHM {
        return Err(ApiError::bad_request(format!(
            "workspace scan uses unsupported object proposal algorithm {}",
            summary.algorithm_version
        )));
    }
    let (media_type, data) = state
        .store
        .get_workspace_scan_artifact(scan.id, &summary.report_artifact_name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace object proposal report not found"))?;
    if media_type != "application/json" {
        return Err(ApiError::internal(anyhow::anyhow!(
            "workspace object proposal report is not JSON"
        )));
    }
    let report: WorkspaceBoardDiscoveryReport =
        serde_json::from_slice(&data).map_err(ApiError::internal)?;
    if report.algorithm_version != WORKSPACE_BOARD_DISCOVERY_ALGORITHM {
        return Err(ApiError::bad_request(format!(
            "workspace object report uses unsupported algorithm {}",
            report.algorithm_version
        )));
    }
    Ok(report)
}

#[derive(Debug, Deserialize)]
struct BuildStripFeederVisionRequest {
    candidate_index: u32,
}

fn permits_strip_feeder_vision(candidate: &velocitypnp_domain::WorkspaceBoardCandidate) -> bool {
    if candidate.known_fixture_id.is_some() {
        return false;
    }
    candidate
        .classification
        .as_ref()
        .is_some_and(|classification| {
            classification.class == WorkspaceObjectClass::Feeder
                || (candidate.plate_role == Some(velocitypnp_domain::InstalledPlateRole::Staging)
                    && classification.class == WorkspaceObjectClass::Unknown
                    && classification.evidence.iter().any(|evidence| {
                        evidence.suggested_class == WorkspaceObjectClass::Feeder
                            && evidence.confidence >= 0.5
                    }))
        })
}

async fn build_strip_feeder_vision(
    State(state): State<AppState>,
    Path(scan_id): Path<Uuid>,
    Json(body): Json<BuildStripFeederVisionRequest>,
) -> ApiResult<Json<StripFeederVisionReport>> {
    let mut scan = state
        .store
        .get_workspace_scan(scan_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))?;
    if scan.status != WorkspaceScanStatus::Succeeded {
        return Err(ApiError::bad_request(
            "strip feeder vision requires a successful workspace scan",
        ));
    }
    let object_report = load_workspace_object_report(&state, &scan)?;
    let candidate = object_report
        .candidates
        .into_iter()
        .find(|candidate| candidate.candidate_index == body.candidate_index)
        .ok_or_else(|| ApiError::not_found("workspace feeder candidate not found"))?;
    if !permits_strip_feeder_vision(&candidate) {
        return Err(ApiError::bad_request(
            "strip feeder vision requires feeder evidence on a non-fixture candidate",
        ));
    }
    let source_artifact_name = candidate
        .evidence_artifact_name
        .clone()
        .ok_or_else(|| ApiError::bad_request("feeder candidate has no normalized evidence"))?;
    let (media_type, data) = state
        .store
        .get_workspace_scan_artifact(scan.id, &source_artifact_name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("feeder candidate evidence not found"))?;
    if media_type != "image/png" {
        return Err(ApiError::internal(anyhow::anyhow!(
            "feeder candidate evidence is not a PNG"
        )));
    }
    let analysis = tokio::task::spawn_blocking(move || {
        let crop = decode_gray_png(&data)?;
        analyze_strip_feeder_candidate(&crop, &candidate)
    })
    .await
    .map_err(ApiError::internal)?
    .map_err(ApiError::internal)?;
    let report_artifact_name = format!("strip-feeder-vision-{:03}.json", body.candidate_index);
    let preview_artifact_name = format!("strip-feeder-vision-{:03}.png", body.candidate_index);
    let report = StripFeederVisionReport {
        algorithm_version: STRIP_FEEDER_VISION_ALGORITHM.into(),
        source_scan_id: scan.id,
        source_candidate_index: body.candidate_index,
        source_artifact_name,
        report_artifact_name: report_artifact_name.clone(),
        preview_artifact_name: preview_artifact_name.clone(),
        created_at: Utc::now(),
        proposals: analysis.proposals,
        rejected_lattices: analysis.rejected_lattices,
        warnings: analysis.warnings,
    };
    let report_json = serde_json::to_vec_pretty(&report).map_err(ApiError::internal)?;
    let preview_png = encode_rgb_png(&analysis.preview).map_err(ApiError::internal)?;
    persist_workspace_artifact(
        &state,
        &mut scan,
        &report_artifact_name,
        "application/json",
        &report_json,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    persist_workspace_artifact(
        &state,
        &mut scan,
        &preview_artifact_name,
        "image/png",
        &preview_png,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    scan.updated_at = Utc::now();
    persist_workspace_manifest(&state, &mut scan)
        .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    Ok(Json(report))
}

const STRIP_FEEDER_OCCUPANCY_ALGORITHM: &str = "strip_feeder_occupancy_refresh.v1";
const STRIP_FEEDER_OCCUPANCY_ARTIFACT_PREFIX: &str = "strip-feeder-occupancy-";

#[derive(Debug, Deserialize)]
struct RefreshStripFeederOccupancyRequest {
    candidate_index: u32,
    registration_id: Uuid,
}

async fn refresh_strip_feeder_occupancy(
    State(state): State<AppState>,
    Path(scan_id): Path<Uuid>,
    Json(body): Json<RefreshStripFeederOccupancyRequest>,
) -> ApiResult<Json<StripFeederOccupancyRefreshReport>> {
    let mut scan = state
        .store
        .get_workspace_scan(scan_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))?;
    if scan.status != WorkspaceScanStatus::Succeeded {
        return Err(ApiError::bad_request(
            "feeder occupancy refresh requires a successful workspace scan",
        ));
    }
    let registration = state
        .store
        .get_strip_feeder_registration(body.registration_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("strip feeder registration not found"))?;
    if registration.profile_id != scan.profile_id
        || registration.calibration_id != scan.calibration_id
    {
        return Err(ApiError::bad_request(
            "strip feeder registration uses different machine geometry",
        ));
    }
    let vision_artifact_name = format!("strip-feeder-vision-{:03}.json", body.candidate_index);
    let (media_type, vision_data) = state
        .store
        .get_workspace_scan_artifact(scan.id, &vision_artifact_name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("strip feeder vision report not found"))?;
    if media_type != "application/json" {
        return Err(ApiError::internal(anyhow::anyhow!(
            "strip feeder vision report is not JSON"
        )));
    }
    let vision: StripFeederVisionReport =
        serde_json::from_slice(&vision_data).map_err(ApiError::internal)?;
    if vision.algorithm_version != STRIP_FEEDER_VISION_ALGORITHM
        || vision.source_scan_id != scan.id
        || vision.source_candidate_index != body.candidate_index
    {
        return Err(ApiError::bad_request(
            "strip feeder vision report is stale or incompatible",
        ));
    }
    let (proposal, translation) = select_rescan_feeder_proposal(&vision.proposals, &registration)
        .ok_or_else(|| {
        ApiError::bad_request("rescan did not find the registered feeder lane")
    })?;
    let raster = scan.raster_transform.ok_or_else(|| {
        ApiError::bad_request("feeder occupancy refresh requires a workspace raster transform")
    })?;
    let mosaic_artifact_name = workspace_display_artifact_name(&scan)
        .ok_or_else(|| ApiError::bad_request("workspace scan has no mosaic"))?;
    let (media_type, mosaic_data) = state
        .store
        .get_workspace_scan_artifact(scan.id, &mosaic_artifact_name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace rescan mosaic not found"))?;
    if media_type != "image/png" {
        return Err(ApiError::internal(anyhow::anyhow!(
            "workspace rescan mosaic is not a PNG"
        )));
    }
    let mosaic = decode_gray_png(&mosaic_data).map_err(ApiError::internal)?;
    let report_artifact_name = format!(
        "{STRIP_FEEDER_OCCUPANCY_ARTIFACT_PREFIX}{:03}-{}.json",
        body.candidate_index, registration.id,
    );
    let model = state.source_component_model.clone();
    let model_available = model.is_some();
    let registration_for_task = registration.clone();
    let proposal_for_task = proposal.clone();
    let analysis = tokio::task::spawn_blocking(move || {
        build_rescan_occupancy_observations(
            &mosaic,
            raster,
            &registration_for_task,
            &proposal_for_task,
            translation,
            model.as_deref(),
        )
    })
    .await
    .map_err(ApiError::internal)?;
    let mut warnings = analysis.warnings;
    if !model_available {
        warnings.push(
            "the source-component model is unavailable; deterministic occupancy was retained"
                .into(),
        );
    }
    let report = StripFeederOccupancyRefreshReport {
        algorithm_version: STRIP_FEEDER_OCCUPANCY_ALGORITHM.into(),
        source_scan_id: scan.id,
        source_candidate_index: body.candidate_index,
        source_proposal_index: proposal.proposal_index,
        registration_id: registration.id,
        report_artifact_name: report_artifact_name.clone(),
        created_at: Utc::now(),
        model_available,
        observations: analysis.observations,
        warnings,
    };
    let report_json = serde_json::to_vec_pretty(&report).map_err(ApiError::internal)?;
    persist_workspace_artifact(
        &state,
        &mut scan,
        &report_artifact_name,
        "application/json",
        &report_json,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    scan.updated_at = Utc::now();
    persist_workspace_manifest(&state, &mut scan)
        .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    state
        .store
        .apply_strip_feeder_occupancy_refresh(
            report.registration_id,
            &report.observations,
            report.created_at,
        )
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    state
        .store
        .put_strip_feeder_occupancy_refresh(&report)
        .map_err(ApiError::internal)?;
    Ok(Json(report))
}

const BOARD_POPULATION_REFRESH_ALGORITHM: &str = "board_population_refresh.v1";
const BOARD_POPULATION_ARTIFACT_PREFIX: &str = "board-population-";

#[derive(Debug, Deserialize)]
struct RefreshBoardPopulationRequest {
    job_id: Uuid,
    board_instance_id: Uuid,
}

async fn refresh_board_population(
    State(state): State<AppState>,
    Path(scan_id): Path<Uuid>,
    Json(body): Json<RefreshBoardPopulationRequest>,
) -> ApiResult<Json<BoardPopulationRefreshReport>> {
    let mut scan = state
        .store
        .get_workspace_scan(scan_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))?;
    if scan.status != WorkspaceScanStatus::Succeeded {
        return Err(ApiError::bad_request(
            "board population refresh requires a successful workspace scan",
        ));
    }
    let raster = scan.raster_transform.ok_or_else(|| {
        ApiError::bad_request("board population refresh requires a workspace raster transform")
    })?;
    if raster.x_mm_per_pixel.abs().max(raster.y_mm_per_pixel.abs()) > 0.08 {
        return Err(ApiError::bad_request(
            "board population refresh requires a scan at 0.08 mm per pixel or finer",
        ));
    }
    let model = state.placement_verification_model.clone().ok_or_else(|| {
        ApiError::bad_request("board population refresh requires the approved placement model")
    })?;
    let job = state
        .store
        .get_job(body.job_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("job not found"))?;
    let board_instance = job
        .boards
        .iter()
        .find(|instance| instance.id == body.board_instance_id)
        .cloned()
        .ok_or_else(|| ApiError::not_found("job board instance not found"))?;
    let board = state
        .store
        .get_board(board_instance.board_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("board design not found"))?;
    if board_instance.design_to_machine.is_none() {
        return Err(ApiError::bad_request(
            "board population refresh requires a registered board transform",
        ));
    }
    let board_design_id = board_instance.board_id;
    let design_to_machine = board_instance
        .design_to_machine
        .expect("validated board transform");
    let mosaic_artifact_name = workspace_display_artifact_name(&scan)
        .ok_or_else(|| ApiError::bad_request("workspace scan has no mosaic"))?;
    let (media_type, mosaic_data) = state
        .store
        .get_workspace_scan_artifact(scan.id, &mosaic_artifact_name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace rescan mosaic not found"))?;
    if media_type != "image/png" {
        return Err(ApiError::internal(anyhow::anyhow!(
            "workspace rescan mosaic is not a PNG"
        )));
    }
    let mosaic = decode_gray_png(&mosaic_data).map_err(ApiError::internal)?;
    let (observations, warnings) = tokio::task::spawn_blocking(move || {
        build_board_population_observations(
            model.as_ref(),
            &mosaic,
            raster,
            &board_instance,
            &board,
        )
    })
    .await
    .map_err(ApiError::internal)?;
    if observations.is_empty() {
        return Err(ApiError::bad_request(
            "board rescan did not produce usable placement observations",
        ));
    }
    let report_artifact_name = format!(
        "{BOARD_POPULATION_ARTIFACT_PREFIX}{}.json",
        body.board_instance_id,
    );
    let report = BoardPopulationRefreshReport {
        algorithm_version: BOARD_POPULATION_REFRESH_ALGORITHM.into(),
        source_scan_id: scan.id,
        profile_id: scan.profile_id.clone(),
        calibration_id: scan.calibration_id,
        job_id: body.job_id,
        board_instance_id: body.board_instance_id,
        board_design_id,
        design_to_machine,
        report_artifact_name: report_artifact_name.clone(),
        created_at: Utc::now(),
        observations,
        warnings,
    };
    let report_json = serde_json::to_vec_pretty(&report).map_err(ApiError::internal)?;
    persist_workspace_artifact(
        &state,
        &mut scan,
        &report_artifact_name,
        "application/json",
        &report_json,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    scan.updated_at = Utc::now();
    persist_workspace_manifest(&state, &mut scan)
        .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    state
        .store
        .put_board_population_refresh(&report)
        .map_err(ApiError::internal)?;
    Ok(Json(report))
}

fn build_board_population_observations(
    model: &PlacementVerificationModel,
    mosaic: &GrayFrame,
    raster: WorkspaceRasterTransform,
    instance: &BoardInstance,
    board: &BoardDesign,
) -> (Vec<BoardPlacementScanObservation>, Vec<String>) {
    let Some(transform) = instance.design_to_machine else {
        return (
            Vec::new(),
            vec!["the board has no machine transform".into()],
        );
    };
    let mut observations = Vec::new();
    let mut warnings = Vec::new();
    let mapping = [[raster.x_mm_per_pixel, 0.0], [0.0, raster.y_mm_per_pixel]];
    for placement in board.placements.iter().filter(|placement| {
        placement.enabled && !placement.fiducial && placement.side == instance.side
    }) {
        let (x_mm, y_mm) = transform.apply(placement.pose.x_mm, placement.pose.y_mm);
        let target_px = [
            (x_mm - raster.top_left_x_mm) / raster.x_mm_per_pixel,
            (y_mm - raster.top_left_y_mm) / raster.y_mm_per_pixel,
        ];
        let margin_x = 0.5 * velocitypnp_vision::PLACEMENT_VERIFICATION_CROP_SPAN_MM
            / raster.x_mm_per_pixel.abs();
        let margin_y = 0.5 * velocitypnp_vision::PLACEMENT_VERIFICATION_CROP_SPAN_MM
            / raster.y_mm_per_pixel.abs();
        if target_px[0] < margin_x
            || target_px[1] < margin_y
            || target_px[0] + margin_x >= f64::from(mosaic.width)
            || target_px[1] + margin_y >= f64::from(mosaic.height)
        {
            warnings.push(format!(
                "{} is outside the usable board-rescan raster",
                placement.reference,
            ));
            continue;
        }
        let target_rotation_deg = if instance.side == BoardSide::Top {
            top_side_placement_rotation_deg(transform, placement.pose.rotation_deg)
        } else {
            let angle = placement.pose.rotation_deg.to_radians();
            let x_axis = transform.matrix[0] * angle.cos() + transform.matrix[1] * angle.sin();
            let y_axis = transform.matrix[3] * angle.cos() + transform.matrix[4] * angle.sin();
            y_axis.atan2(x_axis).to_degrees()
        };
        let crop = match normalize_placement_verification_crop(
            mosaic,
            target_px,
            mapping,
            target_rotation_deg,
        ) {
            Ok(crop) => crop,
            Err(error) => {
                warnings.push(format!("{}: {error}", placement.reference));
                continue;
            }
        };
        let prediction =
            match model.predict_gray(crop.frame.width, crop.frame.height, &crop.frame.pixels) {
                Ok(prediction) => prediction,
                Err(error) => {
                    warnings.push(format!(
                        "{} placement inference failed: {error}",
                        placement.reference,
                    ));
                    continue;
                }
            };
        let (occupancy, review_required, findings) =
            resolve_board_population_prediction(&prediction);
        observations.push(BoardPlacementScanObservation {
            placement_reference: placement.reference.clone(),
            center_machine_mm: [x_mm, y_mm],
            confidence: prediction.class_confidence,
            prediction,
            occupancy,
            review_required,
            findings,
        });
    }
    (observations, warnings)
}

fn resolve_board_population_prediction(
    prediction: &velocitypnp_domain::PlacementVerificationModelPrediction,
) -> (BoardPlacementOccupancy, bool, Vec<String>) {
    let mut findings = prediction.findings.clone();
    let (occupancy, review_required) = if !prediction.confidence_gate_passed {
        findings.push("the placement model did not pass its confidence gate".into());
        (BoardPlacementOccupancy::Uncertain, true)
    } else {
        match prediction.class {
            PlacementVerificationClass::Empty => (BoardPlacementOccupancy::Empty, false),
            PlacementVerificationClass::ComponentFlat => {
                (BoardPlacementOccupancy::Populated, false)
            }
            PlacementVerificationClass::ComponentOnEdge
            | PlacementVerificationClass::MultipleComponents => {
                findings.push("the observed placement condition requires operator review".into());
                (BoardPlacementOccupancy::Uncertain, true)
            }
        }
    };
    (occupancy, review_required, findings)
}

async fn list_board_population_refreshes(State(state): State<AppState>) -> ApiResult<Json<Value>> {
    Ok(Json(json!({
        "refreshes": state
            .store
            .list_board_population_refreshes()
            .map_err(ApiError::internal)?,
    })))
}

fn select_rescan_feeder_proposal<'a>(
    proposals: &'a [StripFeederLaneProposal],
    registration: &StripFeederRegistration,
) -> Option<(&'a StripFeederLaneProposal, [f64; 2])> {
    proposals
        .iter()
        .filter(|proposal| {
            proposal
                .tape_width_mm
                .is_some_and(|width| (width - registration.tape_width_mm).abs() <= 1.0)
                && proposal
                    .component_pitch_mm
                    .is_some_and(|pitch| (pitch - registration.tape_pitch_mm).abs() <= 0.25)
                && angle_difference_deg(proposal.tape_rotation_deg, registration.tape_rotation_deg)
                    .abs()
                    <= 2.0
        })
        .filter_map(|proposal| {
            let offsets = lattice_offsets(
                &proposal.pocket_centers_machine_mm,
                &registration.pocket_centers_machine_mm,
                3.0,
            );
            let (translation, residuals) = fit_display_translation(&offsets)?;
            (offsets.len() >= 3 && residuals.p95_mm <= 0.35).then_some((
                proposal,
                translation,
                offsets.len(),
                residuals.p95_mm,
            ))
        })
        .max_by(|first, second| {
            first
                .2
                .cmp(&second.2)
                .then_with(|| second.3.total_cmp(&first.3))
        })
        .map(|(proposal, translation, _, _)| (proposal, translation))
}

struct RescanOccupancyAnalysis {
    observations: Vec<StripFeederPocketScanObservation>,
    warnings: Vec<String>,
}

fn build_rescan_occupancy_observations(
    mosaic: &GrayFrame,
    raster: WorkspaceRasterTransform,
    registration: &StripFeederRegistration,
    proposal: &StripFeederLaneProposal,
    translation: [f64; 2],
    model: Option<&SourceComponentModel>,
) -> RescanOccupancyAnalysis {
    let mut observations = Vec::new();
    let mut warnings = Vec::new();
    for pocket in &registration.pockets {
        let matched = proposal
            .pocket_observations
            .iter()
            .filter_map(|observation| {
                let corrected = [
                    observation.center_machine_mm[0] + translation[0],
                    observation.center_machine_mm[1] + translation[1],
                ];
                let distance = (corrected[0] - pocket.nominal_center_machine_mm[0])
                    .hypot(corrected[1] - pocket.nominal_center_machine_mm[1]);
                (distance <= registration.tape_pitch_mm * 0.35).then_some((observation, distance))
            })
            .min_by(|first, second| first.1.total_cmp(&second.1));
        let Some((deterministic, _)) = matched else {
            continue;
        };
        let mut findings = Vec::new();
        let model_prediction = model.and_then(|model| {
            let crop = match crop_workspace_source_component(
                mosaic,
                raster,
                deterministic.center_machine_mm,
                proposal.tape_rotation_deg,
                proposal.tape_width_mm.unwrap_or(registration.tape_width_mm),
                proposal
                    .component_pitch_mm
                    .unwrap_or(registration.tape_pitch_mm),
            ) {
                Ok(crop) => crop,
                Err(error) => {
                    findings.push(error.to_string());
                    return None;
                }
            };
            match model.predict_gray(crop.width, crop.height, &crop.pixels) {
                Ok(prediction) => Some(prediction),
                Err(error) => {
                    findings.push(format!("source-component inference failed: {error}"));
                    None
                }
            }
        });
        let model_analysis_failed = model.is_some() && model_prediction.is_none();
        let (occupancy, confidence, mut review_required) = resolve_rescan_occupancy(
            deterministic.occupancy,
            deterministic.confidence,
            model_prediction.as_ref(),
            &mut findings,
        );
        review_required |= model_analysis_failed;
        observations.push(StripFeederPocketScanObservation {
            pocket_index: pocket.pocket_index,
            center_machine_mm: deterministic.center_machine_mm,
            deterministic_occupancy: deterministic.occupancy,
            deterministic_confidence: deterministic.confidence,
            model_prediction,
            occupancy,
            confidence,
            review_required,
            findings,
        });
    }
    if observations.len() < registration.pockets.len() {
        warnings.push(format!(
            "{} of {} registered pockets had usable rescan evidence",
            observations.len(),
            registration.pockets.len(),
        ));
    }
    RescanOccupancyAnalysis {
        observations,
        warnings,
    }
}

fn resolve_rescan_occupancy(
    deterministic: StripPocketOccupancy,
    deterministic_confidence: f64,
    prediction: Option<&SourceComponentModelPrediction>,
    findings: &mut Vec<String>,
) -> (StripPocketOccupancy, f64, bool) {
    let Some(prediction) = prediction else {
        return (
            deterministic,
            deterministic_confidence,
            deterministic == StripPocketOccupancy::Uncertain,
        );
    };
    if !prediction.confidence_gate_passed {
        findings.push("the source-component model did not pass its confidence gate".into());
        return (deterministic, deterministic_confidence, true);
    }
    let learned = if prediction.class.occupied() {
        StripPocketOccupancy::Occupied
    } else {
        StripPocketOccupancy::Empty
    };
    if deterministic == StripPocketOccupancy::Uncertain {
        findings.push("the gated model resolved uncertain deterministic occupancy".into());
        return (
            learned,
            prediction.class_confidence,
            prediction.class == SourceComponentClass::ComponentOnEdge,
        );
    }
    if deterministic == learned {
        return (
            deterministic,
            deterministic_confidence.min(prediction.class_confidence),
            prediction.class == SourceComponentClass::ComponentOnEdge,
        );
    }
    findings.push("learned and deterministic occupancy disagree".into());
    (
        StripPocketOccupancy::Uncertain,
        deterministic_confidence.min(prediction.class_confidence),
        true,
    )
}

const STRIP_FEEDER_INVENTORY_REPORT_ARTIFACT: &str = "strip-feeder-inventory.json";
const STRIP_FEEDER_INVENTORY_PREVIEW_ARTIFACT: &str = "mosaic-strip-feeder-inventory.png";

#[derive(Debug, Deserialize)]
struct BuildStripFeederInventoryRequest {
    evidence_sources: Vec<StripFeederInventoryEvidenceSourceRequest>,
}

#[derive(Debug, Deserialize)]
struct StripFeederInventoryEvidenceSourceRequest {
    scan_id: Uuid,
    candidate_index: u32,
}

async fn build_strip_feeder_inventory_report(
    State(state): State<AppState>,
    Path(scan_id): Path<Uuid>,
    Json(body): Json<BuildStripFeederInventoryRequest>,
) -> ApiResult<Json<StripFeederInventoryReport>> {
    if body.evidence_sources.is_empty() {
        return Err(ApiError::bad_request(
            "strip feeder inventory requires one or more evidence sources",
        ));
    }
    let mut scan = state
        .store
        .get_workspace_scan(scan_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))?;
    if scan.status != WorkspaceScanStatus::Succeeded {
        return Err(ApiError::bad_request(
            "strip feeder inventory requires a successful workspace scan",
        ));
    }
    let raster_transform = scan.raster_transform.ok_or_else(|| {
        ApiError::bad_request(
            "strip feeder inventory requires a machine-coordinate raster transform",
        )
    })?;
    let source_mosaic_artifact_name = scan
        .board_discovery
        .as_ref()
        .map(|summary| summary.preview_artifact_name.clone())
        .or_else(|| {
            scan.refinement_composite
                .as_ref()
                .filter(|summary| summary.accepted)
                .map(|summary| summary.mosaic_artifact_name.clone())
        })
        .or_else(|| {
            scan.height_map
                .as_ref()
                .map(|summary| summary.corrected_mosaic_artifact_name.clone())
        })
        .or_else(|| scan.mosaic_artifact_name.clone())
        .ok_or_else(|| ApiError::bad_request("workspace scan has no mosaic"))?;
    let (media_type, mosaic_data) = state
        .store
        .get_workspace_scan_artifact(scan.id, &source_mosaic_artifact_name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("strip feeder inventory source mosaic not found"))?;
    if media_type != "image/png" {
        return Err(ApiError::internal(anyhow::anyhow!(
            "strip feeder inventory source mosaic is not a PNG"
        )));
    }

    let mut reports = Vec::with_capacity(body.evidence_sources.len());
    let mut corrected_sources = Vec::with_capacity(body.evidence_sources.len());
    for source in body.evidence_sources {
        let evidence_scan = state
            .store
            .get_workspace_scan(source.scan_id)
            .map_err(ApiError::internal)?
            .ok_or_else(|| ApiError::not_found("strip feeder evidence scan not found"))?;
        if evidence_scan.status != WorkspaceScanStatus::Succeeded {
            return Err(ApiError::bad_request(
                "strip feeder inventory evidence requires a successful scan",
            ));
        }
        if evidence_scan.profile_id != scan.profile_id
            || evidence_scan.calibration_id != scan.calibration_id
        {
            return Err(ApiError::bad_request(
                "strip feeder inventory evidence uses different machine geometry",
            ));
        }
        let artifact_name = format!("strip-feeder-vision-{:03}.json", source.candidate_index);
        let (media_type, data) = state
            .store
            .get_workspace_scan_artifact(source.scan_id, &artifact_name)
            .map_err(ApiError::internal)?
            .ok_or_else(|| ApiError::not_found("strip feeder vision report not found"))?;
        if media_type != "application/json" {
            return Err(ApiError::internal(anyhow::anyhow!(
                "strip feeder vision report is not JSON"
            )));
        }
        let report: StripFeederVisionReport =
            serde_json::from_slice(&data).map_err(ApiError::internal)?;
        if report.algorithm_version != STRIP_FEEDER_VISION_ALGORITHM {
            return Err(ApiError::bad_request(format!(
                "strip feeder evidence uses unsupported algorithm {}",
                report.algorithm_version
            )));
        }
        if report.source_scan_id != source.scan_id
            || report.source_candidate_index != source.candidate_index
        {
            return Err(ApiError::internal(anyhow::anyhow!(
                "strip feeder vision report source does not match its artifact"
            )));
        }
        let object_report = load_workspace_object_report(&state, &evidence_scan)?;
        let candidate = object_report
            .candidates
            .iter()
            .find(|candidate| candidate.candidate_index == source.candidate_index)
            .ok_or_else(|| ApiError::not_found("strip feeder source candidate not found"))?;
        if candidate.evidence_artifact_name.as_deref() != Some(&report.source_artifact_name) {
            return Err(ApiError::internal(anyhow::anyhow!(
                "strip feeder report does not match its normalized source evidence"
            )));
        }
        let corrected_artifact_name = object_report.source_mosaic_artifact_name;
        let height_corrected = evidence_scan.height_map.as_ref().is_some_and(|summary| {
            summary.corrected_mosaic_artifact_name == corrected_artifact_name
        });
        let refined = evidence_scan
            .refinement_composite
            .as_ref()
            .is_some_and(|summary| {
                summary.accepted && summary.mosaic_artifact_name == corrected_artifact_name
            });
        if !height_corrected && !refined {
            return Err(ApiError::bad_request(
                "strip feeder recognition requires a height-corrected evidence mosaic",
            ));
        }
        if !corrected_sources
            .iter()
            .any(|(scan_id, _, _, _)| *scan_id == source.scan_id)
        {
            let source_raster = evidence_scan.raster_transform.ok_or_else(|| {
                ApiError::bad_request(
                    "strip feeder evidence has no machine-coordinate raster transform",
                )
            })?;
            let (media_type, data) = state
                .store
                .get_workspace_scan_artifact(source.scan_id, &corrected_artifact_name)
                .map_err(ApiError::internal)?
                .ok_or_else(|| {
                    ApiError::not_found("height-corrected strip feeder mosaic not found")
                })?;
            if media_type != "image/png" {
                return Err(ApiError::internal(anyhow::anyhow!(
                    "height-corrected strip feeder mosaic is not a PNG"
                )));
            }
            corrected_sources.push((source.scan_id, corrected_artifact_name, source_raster, data));
        }
        reports.push(report);
    }

    let workspace_scan_id = scan.id;
    let report_source_name = source_mosaic_artifact_name.clone();
    let inventory = tokio::task::spawn_blocking(move || {
        let background = decode_rgb_png(&mosaic_data)?;
        let source_mosaics = corrected_sources
            .into_iter()
            .map(|(scan_id, artifact_name, raster_transform, data)| {
                Ok(StripFeederInventorySourceMosaic {
                    scan_id,
                    artifact_name,
                    raster_transform,
                    frame: decode_gray_png(&data)?,
                })
            })
            .collect::<anyhow::Result<Vec<_>>>()?;
        build_strip_feeder_inventory(StripFeederInventoryBuild {
            background: &background,
            raster: raster_transform,
            workspace_scan_id,
            source_mosaic_artifact_name: &report_source_name,
            reports: &reports,
            source_mosaics: &source_mosaics,
            report_artifact_name: STRIP_FEEDER_INVENTORY_REPORT_ARTIFACT,
            preview_artifact_name: STRIP_FEEDER_INVENTORY_PREVIEW_ARTIFACT,
        })
    })
    .await
    .map_err(ApiError::internal)?
    .map_err(ApiError::internal)?;
    let report_json = serde_json::to_vec_pretty(&inventory.report).map_err(ApiError::internal)?;
    let preview_png = encode_rgb_png(&inventory.preview).map_err(ApiError::internal)?;
    persist_workspace_artifact(
        &state,
        &mut scan,
        STRIP_FEEDER_INVENTORY_REPORT_ARTIFACT,
        "application/json",
        &report_json,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    persist_workspace_artifact(
        &state,
        &mut scan,
        STRIP_FEEDER_INVENTORY_PREVIEW_ARTIFACT,
        "image/png",
        &preview_png,
    )
    .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    scan.strip_feeder_inventory = Some(StripFeederInventorySummary {
        algorithm_version: STRIP_FEEDER_INVENTORY_ALGORITHM.into(),
        report_artifact_name: STRIP_FEEDER_INVENTORY_REPORT_ARTIFACT.into(),
        preview_artifact_name: STRIP_FEEDER_INVENTORY_PREVIEW_ARTIFACT.into(),
        lane_count: inventory.report.lane_count,
        populated_lane_count: inventory.report.populated_lane_count,
        present_count: inventory.report.present_count,
        absent_count: inventory.report.absent_count,
        uncertain_count: inventory.report.uncertain_count,
        coverage_complete: inventory.report.coverage_complete,
        recommended_rescan_region: inventory.report.recommended_rescan_region,
    });
    scan.updated_at = Utc::now();
    persist_workspace_manifest(&state, &mut scan)
        .map_err(|error| ApiError::internal(anyhow::anyhow!(error)))?;
    Ok(Json(inventory.report))
}

#[derive(Debug, Clone, Serialize)]
struct InventoryRegistrationBinding {
    inventory_index: u32,
    created: bool,
    registration: StripFeederRegistration,
}

async fn promote_strip_feeder_inventory(
    State(state): State<AppState>,
    Path(scan_id): Path<Uuid>,
) -> ApiResult<(StatusCode, Json<Value>)> {
    let (scan, inventory) = load_strip_feeder_inventory(&state, scan_id)?;
    let bindings = promote_inventory_registrations(&state, &scan, &inventory)?;
    let created_count = bindings.iter().filter(|binding| binding.created).count();
    Ok((
        StatusCode::CREATED,
        Json(json!({
            "workspace_scan_id": scan_id,
            "created_count": created_count,
            "registrations": bindings,
        })),
    ))
}

fn load_strip_feeder_inventory(
    state: &AppState,
    scan_id: Uuid,
) -> ApiResult<(WorkspaceScanReport, StripFeederInventoryReport)> {
    let scan = state
        .store
        .get_workspace_scan(scan_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))?;
    if scan.status != WorkspaceScanStatus::Succeeded {
        return Err(ApiError::bad_request(
            "strip feeder inventory requires a successful workspace scan",
        ));
    }
    let summary = scan.strip_feeder_inventory.as_ref().ok_or_else(|| {
        ApiError::bad_request("workspace scan has no persisted strip feeder inventory")
    })?;
    if summary.algorithm_version != STRIP_FEEDER_INVENTORY_ALGORITHM {
        return Err(ApiError::bad_request(format!(
            "strip feeder inventory uses unsupported algorithm {}",
            summary.algorithm_version,
        )));
    }
    let (media_type, data) = state
        .store
        .get_workspace_scan_artifact(scan.id, &summary.report_artifact_name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("strip feeder inventory report not found"))?;
    if media_type != "application/json" {
        return Err(ApiError::internal(anyhow::anyhow!(
            "strip feeder inventory report is not JSON"
        )));
    }
    let inventory: StripFeederInventoryReport =
        serde_json::from_slice(&data).map_err(ApiError::internal)?;
    if inventory.algorithm_version != STRIP_FEEDER_INVENTORY_ALGORITHM
        || inventory.workspace_scan_id != scan.id
    {
        return Err(ApiError::bad_request(
            "strip feeder inventory report is stale or incompatible",
        ));
    }
    Ok((scan, inventory))
}

fn promote_inventory_registrations(
    state: &AppState,
    scan: &WorkspaceScanReport,
    inventory: &StripFeederInventoryReport,
) -> ApiResult<Vec<InventoryRegistrationBinding>> {
    let mut existing = state
        .store
        .list_strip_feeder_registrations()
        .map_err(ApiError::internal)?;
    let mut bindings = Vec::with_capacity(inventory.lanes.len());
    for lane in &inventory.lanes {
        let matched = existing
            .iter()
            .filter(|registration| {
                registration.profile_id == scan.profile_id
                    && registration.calibration_id == scan.calibration_id
            })
            .filter_map(|registration| {
                inventory_registration_distance_mm(lane, registration)
                    .map(|distance| (registration, distance))
            })
            .min_by(|(first, first_distance), (second, second_distance)| {
                inventory_registration_rank(first, *first_distance)
                    .total_cmp(&inventory_registration_rank(second, *second_distance))
            })
            .map(|(registration, _)| registration.clone());
        let (registration, created) = if let Some(registration) = matched {
            (registration, false)
        } else {
            let registration = registration_from_inventory_lane(scan, lane)?;
            state
                .store
                .put_strip_feeder_registration(&registration)
                .map_err(ApiError::internal)?;
            existing.push(registration.clone());
            (registration, true)
        };
        bindings.push(InventoryRegistrationBinding {
            inventory_index: lane.inventory_index,
            created,
            registration,
        });
    }
    Ok(bindings)
}

fn inventory_registration_rank(registration: &StripFeederRegistration, distance_mm: f64) -> f64 {
    let unbound_penalty = if registration.active_feeder_id.is_some() {
        0.0
    } else {
        10.0
    };
    let unidentified_penalty = if registration.part_key.is_some() {
        0.0
    } else {
        1.0
    };
    unbound_penalty + unidentified_penalty + distance_mm
}

fn inventory_registration_distance_mm(
    lane: &StripFeederInventoryLane,
    registration: &StripFeederRegistration,
) -> Option<f64> {
    let width_mm = lane.proposal.tape_width_mm?;
    let pitch_mm = lane.proposal.component_pitch_mm?;
    let centerline = lane.proposal.pick_centerline_machine_mm?;
    if (width_mm - registration.tape_width_mm).abs() > 0.25
        || (pitch_mm - registration.tape_pitch_mm).abs() > 0.25
        || angle_difference_deg(
            lane.proposal.tape_rotation_deg,
            registration.tape_rotation_deg,
        )
        .abs()
            > 2.0
    {
        return None;
    }
    let direction = [
        registration.pick_centerline_machine_mm[1][0]
            - registration.pick_centerline_machine_mm[0][0],
        registration.pick_centerline_machine_mm[1][1]
            - registration.pick_centerline_machine_mm[0][1],
    ];
    let length = direction[0].hypot(direction[1]);
    if length <= 1e-9 || !length.is_finite() {
        return None;
    }
    let midpoint = [
        0.5 * (centerline[0][0] + centerline[1][0]),
        0.5 * (centerline[0][1] + centerline[1][1]),
    ];
    let delta = [
        midpoint[0] - registration.pick_centerline_machine_mm[0][0],
        midpoint[1] - registration.pick_centerline_machine_mm[0][1],
    ];
    let distance_mm = (delta[0] * direction[1] - delta[1] * direction[0]).abs() / length;
    (distance_mm <= 1.5).then_some(distance_mm)
}

fn registration_from_inventory_lane(
    scan: &WorkspaceScanReport,
    lane: &StripFeederInventoryLane,
) -> ApiResult<StripFeederRegistration> {
    let proposal = &lane.proposal;
    let tape_width_mm = proposal.tape_width_mm.ok_or_else(|| {
        ApiError::bad_request("inventory lane tape width requires operator review")
    })?;
    let tape_pitch_mm = proposal.component_pitch_mm.ok_or_else(|| {
        ApiError::bad_request("inventory lane component pitch requires operator review")
    })?;
    let pick_centerline_machine_mm = proposal.pick_centerline_machine_mm.ok_or_else(|| {
        ApiError::bad_request("inventory lane centerline requires operator review")
    })?;
    if proposal.pocket_centers_machine_mm.is_empty() {
        return Err(ApiError::bad_request(
            "inventory lane has no pocket-center hypotheses",
        ));
    }
    let now = Utc::now();
    let pockets = proposal
        .pocket_centers_machine_mm
        .iter()
        .enumerate()
        .filter_map(|(index, center)| {
            let pocket_index = u32::try_from(index).ok()?;
            let observation = proposal
                .pocket_observations
                .iter()
                .find(|observation| observation.pocket_index == pocket_index);
            let occupancy = observation
                .map(|observation| observation.occupancy)
                .unwrap_or(StripPocketOccupancy::Uncertain);
            Some(StripFeederPocketState {
                pocket_index,
                nominal_center_machine_mm: *center,
                measured_center_machine_mm: observation.map(|item| item.center_machine_mm),
                occupancy,
                occupancy_confidence: observation.map_or(0.0, |item| item.confidence),
                status: match occupancy {
                    StripPocketOccupancy::Occupied => StripFeederPocketStatus::Available,
                    StripPocketOccupancy::Empty => StripFeederPocketStatus::Empty,
                    StripPocketOccupancy::Uncertain => StripFeederPocketStatus::NeedsReview,
                },
                attempt_count: 0,
                consecutive_failure_count: 0,
                reservation_id: None,
                last_qualification_id: None,
                last_outcome: None,
                updated_at: now,
            })
        })
        .collect();
    Ok(StripFeederRegistration {
        id: Uuid::new_v4(),
        profile_id: scan.profile_id.clone(),
        calibration_id: scan.calibration_id,
        source_scan_id: lane.source_scan_id,
        source_candidate_index: lane.source_candidate_index,
        source_proposal_index: lane.source_proposal_index,
        created_at: now,
        updated_at: now,
        status: StripFeederRegistrationStatus::VisionDraft,
        name: format!("Inventory feeder {}", lane.inventory_index + 1),
        part_key: None,
        part_rotation_deg: None,
        tape_width_mm,
        tape_pitch_mm,
        tape_rotation_deg: proposal.tape_rotation_deg,
        pick_centerline_machine_mm,
        pocket_centers_machine_mm: proposal.pocket_centers_machine_mm.clone(),
        pockets,
        selected_pocket_machine_mm: None,
        selected_pocket_index: None,
        pickup_z_mm: None,
        surveyed_part_size_mm: proposal.component_size_mm,
        measured_part_size_mm: None,
        measured_part_rotation_deg: None,
        measured_part_confidence: None,
        active_feeder_id: None,
        latest_live_holdout_id: None,
        latest_pickup_qualification_id: None,
        pickup_sequence_passed: false,
        latest_pickup_sequence_qualification_ids: Vec::new(),
        latest_placement_validation_id: None,
        vision_confidence: proposal.confidence,
        vision_review_required: proposal.review_required,
        findings: vec![
            format!(
                "promoted from workspace feeder inventory {} lane {}",
                scan.id,
                lane.inventory_index + 1,
            ),
            "part identity and orientation are not assigned".into(),
            "live pocket occupancy and pickup Z are not measured".into(),
        ],
    })
}

#[derive(Debug, Deserialize)]
struct StartStripFeederSourceCaptureRequest {
    lease_id: Uuid,
    #[serde(default = "default_inventory_capture_occupied_count")]
    occupied_count: u32,
    #[serde(default = "default_inventory_capture_empty_count")]
    empty_count: u32,
    #[serde(default)]
    lane_indices: Vec<u32>,
    #[serde(default)]
    confirmed_external_safety_checks: bool,
}

fn default_inventory_capture_occupied_count() -> u32 {
    12
}

fn default_inventory_capture_empty_count() -> u32 {
    12
}

#[derive(Debug, Serialize)]
struct StartStripFeederSourceCaptureResponse {
    capture: StripFeederSourceCaptureRun,
    operation: Operation,
}

#[derive(Debug, Clone)]
struct InventorySourceCaptureTarget {
    inventory_index: u32,
    registration_id: Uuid,
    source_scan_id: Uuid,
    source_candidate_index: u32,
    source_proposal_index: u32,
    observation: StripFeederPocketObservation,
}

async fn start_strip_feeder_source_capture(
    State(state): State<AppState>,
    Path(scan_id): Path<Uuid>,
    Json(body): Json<StartStripFeederSourceCaptureRequest>,
) -> ApiResult<(StatusCode, Json<StartStripFeederSourceCaptureResponse>)> {
    if !body.confirmed_external_safety_checks {
        return Err(ApiError::bad_request(
            "feeder source capture requires confirmation that the tape is fixed, both nozzles are level, the travel envelope is clear, and power isolation is reachable",
        ));
    }
    let total_count = body.occupied_count.saturating_add(body.empty_count);
    if total_count == 0 || total_count > 48 {
        return Err(ApiError::bad_request(
            "feeder source capture requires between 1 and 48 images",
        ));
    }
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed || status.pose.is_none() {
        return Err(ApiError::bad_request(
            "feeder source capture requires a homed ready machine",
        ));
    }
    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(&state)?;
    ensure_no_active_board_registrations(&state)?;
    ensure_no_active_board_surface_measurements(&state)?;
    ensure_no_active_strip_feeder_holdouts(&state)?;
    ensure_no_active_strip_feeder_source_captures(&state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(&state)?;
    let (scan, inventory) = load_strip_feeder_inventory(&state, scan_id)?;
    if !state.profile.accepts_profile_id(&scan.profile_id) {
        return Err(ApiError::bad_request(
            "feeder source inventory uses a different machine profile",
        ));
    }
    if !status.simulated && status.calibration_revision != Some(scan.calibration_id) {
        return Err(ApiError::bad_request(format!(
            "feeder source capture requires fine XYZ homing with calibration {}",
            scan.calibration_id,
        )));
    }
    let bindings = promote_inventory_registrations(&state, &scan, &inventory)?;
    let selected_lanes = body.lane_indices.iter().copied().collect::<BTreeSet<_>>();
    if selected_lanes.len() != body.lane_indices.len() {
        return Err(ApiError::bad_request(
            "feeder source capture lane indices must be unique",
        ));
    }
    if let Some(index) = selected_lanes.iter().find(|index| {
        !inventory
            .lanes
            .iter()
            .any(|lane| lane.inventory_index == **index)
    }) {
        return Err(ApiError::bad_request(format!(
            "feeder source capture lane index {index} is absent",
        )));
    }
    let targets = select_inventory_source_capture_targets(
        &inventory,
        &bindings,
        &selected_lanes,
        body.occupied_count,
        body.empty_count,
    )?;
    if targets.iter().any(|target| {
        !state.profile.bounds.contains(Pose {
            x_mm: target.observation.center_machine_mm[0],
            y_mm: target.observation.center_machine_mm[1],
            z_mm: state.profile.safe_z_mm,
            rotation_deg: 0.0,
        })
    }) {
        return Err(ApiError::bad_request(
            "feeder source capture target is outside machine bounds",
        ));
    }
    let camera_profile = stored_camera_profile(&state, CameraRole::TopCamera)?;
    let camera_path = camera_path_for_role(CameraRole::TopCamera)?;
    let visual = state
        .profile
        .visual_homing
        .as_ref()
        .cloned()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let targets = order_inventory_source_capture_targets(
        targets,
        [visual.seed_pose.x_mm, visual.seed_pose.y_mm],
    );
    let operation = Operation::pending("vision.strip_feeder_source_capture");
    let now = Utc::now();
    let capture = StripFeederSourceCaptureRun {
        id: Uuid::new_v4(),
        operation_id: operation.id,
        workspace_scan_id: scan.id,
        profile_id: scan.profile_id,
        calibration_id: scan.calibration_id,
        status: OperationStatus::Pending,
        created_at: now,
        updated_at: now,
        requested_occupied_count: body.occupied_count,
        requested_empty_count: body.empty_count,
        lane_indices: if selected_lanes.is_empty() {
            inventory
                .lanes
                .iter()
                .map(|lane| lane.inventory_index)
                .collect()
        } else {
            selected_lanes.iter().copied().collect()
        },
        samples: Vec::new(),
        message: None,
    };
    state
        .machine
        .renew_lease(body.lease_id, 1_800)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    state
        .store
        .put_operation(&operation)
        .map_err(ApiError::internal)?;
    state
        .store
        .put_strip_feeder_source_capture(&capture)
        .map_err(ApiError::internal)?;
    drop(admission_guard);
    let response = StartStripFeederSourceCaptureResponse {
        capture: capture.clone(),
        operation: operation.clone(),
    };
    let task_state = state.clone();
    spawn_prepared_operation(
        state,
        operation,
        execute_strip_feeder_source_capture_task(
            task_state,
            capture,
            targets,
            camera_profile,
            camera_path,
            visual,
            body.lease_id,
        ),
    );
    Ok((StatusCode::ACCEPTED, Json(response)))
}

fn select_inventory_source_capture_targets(
    inventory: &StripFeederInventoryReport,
    bindings: &[InventoryRegistrationBinding],
    selected_lanes: &BTreeSet<u32>,
    occupied_count: u32,
    empty_count: u32,
) -> ApiResult<Vec<InventorySourceCaptureTarget>> {
    let registration_ids = bindings
        .iter()
        .map(|binding| (binding.inventory_index, binding.registration.id))
        .collect::<BTreeMap<_, _>>();
    let mut targets = select_inventory_occupancy_targets(
        inventory,
        &registration_ids,
        selected_lanes,
        StripPocketOccupancy::Occupied,
        occupied_count,
    )?;
    targets.extend(select_inventory_occupancy_targets(
        inventory,
        &registration_ids,
        selected_lanes,
        StripPocketOccupancy::Empty,
        empty_count,
    )?);
    Ok(targets)
}

fn select_inventory_occupancy_targets(
    inventory: &StripFeederInventoryReport,
    registration_ids: &BTreeMap<u32, Uuid>,
    selected_lanes: &BTreeSet<u32>,
    occupancy: StripPocketOccupancy,
    count: u32,
) -> ApiResult<Vec<InventorySourceCaptureTarget>> {
    let mut by_lane = BTreeMap::new();
    for lane in &inventory.lanes {
        if !selected_lanes.is_empty() && !selected_lanes.contains(&lane.inventory_index) {
            continue;
        }
        let registration_id = registration_ids
            .get(&lane.inventory_index)
            .copied()
            .ok_or_else(|| ApiError::internal("inventory lane has no registration binding"))?;
        let mut observations = lane
            .proposal
            .pocket_observations
            .iter()
            .filter(|observation| observation.occupancy == occupancy)
            .cloned()
            .collect::<Vec<_>>();
        observations.sort_by_key(|observation| observation.pocket_index);
        let mut spread = Vec::with_capacity(observations.len());
        let mut take_first = true;
        while !observations.is_empty() {
            let index = if take_first {
                0
            } else {
                observations.len() - 1
            };
            spread.push(observations.remove(index));
            take_first = !take_first;
        }
        if !spread.is_empty() {
            by_lane.insert(lane.inventory_index, (lane, registration_id, spread));
        }
    }
    let available = by_lane
        .values()
        .map(|(_, _, observations)| observations.len())
        .sum::<usize>();
    if available < count as usize {
        return Err(ApiError::bad_request(format!(
            "feeder inventory has only {available} {occupancy:?} pockets in the selected lanes",
        )));
    }
    let mut selected = Vec::with_capacity(count as usize);
    let mut round = 0;
    while selected.len() < count as usize {
        let mut progressed = false;
        for (inventory_index, (lane, registration_id, observations)) in &by_lane {
            let Some(observation) = observations.get(round).cloned() else {
                continue;
            };
            selected.push(InventorySourceCaptureTarget {
                inventory_index: *inventory_index,
                registration_id: *registration_id,
                source_scan_id: lane.source_scan_id,
                source_candidate_index: lane.source_candidate_index,
                source_proposal_index: lane.source_proposal_index,
                observation,
            });
            progressed = true;
            if selected.len() == count as usize {
                break;
            }
        }
        if !progressed {
            break;
        }
        round += 1;
    }
    Ok(selected)
}

fn order_inventory_source_capture_targets(
    mut targets: Vec<InventorySourceCaptureTarget>,
    start_machine_mm: [f64; 2],
) -> Vec<InventorySourceCaptureTarget> {
    let mut ordered = Vec::with_capacity(targets.len());
    let mut current = start_machine_mm;
    while !targets.is_empty() {
        let nearest = targets
            .iter()
            .enumerate()
            .min_by(|(_, first), (_, second)| {
                let distance = |target: &InventorySourceCaptureTarget| {
                    (target.observation.center_machine_mm[0] - current[0])
                        .hypot(target.observation.center_machine_mm[1] - current[1])
                };
                distance(first).total_cmp(&distance(second))
            })
            .map(|(index, _)| index)
            .expect("a non-empty target list has a nearest item");
        let target = targets.remove(nearest);
        current = target.observation.center_machine_mm;
        ordered.push(target);
    }
    ordered
}

fn ensure_no_active_strip_feeder_source_captures(state: &AppState) -> ApiResult<()> {
    let active = state
        .store
        .list_strip_feeder_source_captures()
        .map_err(ApiError::internal)?
        .into_iter()
        .any(|run| {
            matches!(
                run.status,
                OperationStatus::Pending | OperationStatus::Running
            )
        });
    if active {
        return Err(ApiError::bad_request(
            "a strip feeder source capture is already active",
        ));
    }
    Ok(())
}

struct SourceComponentShadowArtifacts {
    report: SourceComponentShadowReport,
    crop: GrayFrame,
    preview: RgbFrame,
}

struct HeldPartShadowArtifacts {
    report: HeldPartShadowReport,
    preview: RgbFrame,
}

fn centered_gray_crop(
    frame: &GrayFrame,
    center_px: [f64; 2],
    size: u32,
) -> Result<(GrayFrame, [u32; 2]), String> {
    if frame.width < size || frame.height < size {
        return Err(format!(
            "held-part source frame {}x{} is smaller than the {size}-pixel crop",
            frame.width, frame.height
        ));
    }
    let half = f64::from(size) / 2.0;
    let left = (center_px[0] - half)
        .round()
        .clamp(0.0, f64::from(frame.width - size)) as u32;
    let top = (center_px[1] - half)
        .round()
        .clamp(0.0, f64::from(frame.height - size)) as u32;
    let mut pixels = Vec::with_capacity((size * size) as usize);
    for y in top..top + size {
        let start = (y * frame.width + left) as usize;
        pixels.extend_from_slice(&frame.pixels[start..start + size as usize]);
    }
    Ok((
        GrayFrame {
            width: size,
            height: size,
            pixels,
        },
        [left, top],
    ))
}

fn shift_held_part_outline(
    outline: Option<[[f64; 2]; 4]>,
    origin: [u32; 2],
) -> Option<[[f64; 2]; 4]> {
    outline.map(|mut points| {
        for point in &mut points {
            point[0] -= f64::from(origin[0]);
            point[1] -= f64::from(origin[1]);
        }
        points
    })
}

fn outline_axis_rotation_deg(outline: [[f64; 2]; 4]) -> f64 {
    let edges = [
        [outline[1][0] - outline[0][0], outline[1][1] - outline[0][1]],
        [outline[2][0] - outline[1][0], outline[2][1] - outline[1][1]],
    ];
    let axis = if edges[0][0].hypot(edges[0][1]) >= edges[1][0].hypot(edges[1][1]) {
        edges[0]
    } else {
        edges[1]
    };
    axis[1].atan2(axis[0]).to_degrees().rem_euclid(180.0)
}

fn undirected_rotation_delta_deg(first: f64, second: f64) -> f64 {
    ((first - second + 90.0).rem_euclid(180.0) - 90.0).abs()
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum HeldPartControlPolicy {
    ShadowOnly,
    ReleaseNozzleClear,
}

fn build_held_part_shadow_report(
    deterministic: &HeldPartInspectionArtifacts,
    deterministic_outline_px: Option<[[f64; 2]; 4]>,
    prediction: HeldPartModelPrediction,
    artifact_stem: &str,
    control_policy: HeldPartControlPolicy,
) -> HeldPartShadowReport {
    let learned_occupied = prediction.class.occupied();
    let occupancy_agreement = deterministic.report.detected == learned_occupied;
    let deterministic_center_px = deterministic
        .report
        .center_x_px
        .zip(deterministic.report.center_y_px)
        .map(|(x, y)| [x, y]);
    let center_delta_px = deterministic_center_px
        .filter(|_| deterministic.report.detected && learned_occupied)
        .map(|center| {
            (center[0] - prediction.pose.center_px[0])
                .hypot(center[1] - prediction.pose.center_px[1])
        });
    let rotation_delta_deg_mod_180 = deterministic_outline_px
        .filter(|_| learned_occupied && prediction.pose.valid)
        .map(|outline| {
            undirected_rotation_delta_deg(
                outline_axis_rotation_deg(outline),
                prediction.pose.rotation_deg_mod_180,
            )
        });
    let deterministic_occupied_rejected =
        deterministic.report.detected && !deterministic.report.passed;
    let release_clear_authorized = control_policy == HeldPartControlPolicy::ReleaseNozzleClear
        && prediction.class == HeldPartClass::BareNozzle
        && prediction.confidence_gate_passed
        && prediction.class_confidence >= HELD_PART_RELEASE_BARE_PROBABILITY_GATE
        && prediction.class_margin >= HELD_PART_RELEASE_BARE_MARGIN_GATE;
    let review_required = deterministic_occupied_rejected
        || !prediction.confidence_gate_passed
        || !occupancy_agreement
        || prediction.class == HeldPartClass::ComponentOnEdge
        || center_delta_px.is_some_and(|delta| delta > MAXIMUM_HELD_PART_CENTER_DELTA_PX)
        || rotation_delta_deg_mod_180
            .is_some_and(|delta| delta > MAXIMUM_HELD_PART_ROTATION_DELTA_DEG);
    let mut findings = prediction.findings.clone();
    if release_clear_authorized {
        findings.push(
            "the high-confidence bare-nozzle result is authorized for release verification".into(),
        );
    } else {
        findings.push("the learned result is shadow evidence and cannot control motion".into());
    }
    if deterministic_occupied_rejected {
        findings.push("the deterministic held-part inspection did not pass".into());
    }
    if !occupancy_agreement {
        findings.push("learned and deterministic occupancy disagree".into());
    }
    if prediction.class == HeldPartClass::ComponentOnEdge {
        findings.push("the learned model marks the component as on edge".into());
    }
    if center_delta_px.is_some_and(|delta| delta > MAXIMUM_HELD_PART_CENTER_DELTA_PX) {
        findings.push(format!(
            "learned and deterministic centers differ by more than \
             {MAXIMUM_HELD_PART_CENTER_DELTA_PX:.1} pixels"
        ));
    }
    if rotation_delta_deg_mod_180.is_some_and(|delta| delta > MAXIMUM_HELD_PART_ROTATION_DELTA_DEG)
    {
        findings.push(format!(
            "learned and deterministic axes differ by more than \
             {MAXIMUM_HELD_PART_ROTATION_DELTA_DEG:.1} degrees"
        ));
    }
    HeldPartShadowReport {
        algorithm_version: HELD_PART_SHADOW_ALGORITHM.into(),
        deterministic_algorithm_version: deterministic.report.algorithm_version.clone(),
        deterministic_detected: deterministic.report.detected,
        deterministic_passed: deterministic.report.passed,
        deterministic_confidence: deterministic.report.confidence,
        deterministic_center_px,
        deterministic_outline_px,
        prediction,
        occupancy_agreement,
        center_delta_px,
        rotation_delta_deg_mod_180,
        review_required,
        control_authorized: release_clear_authorized,
        report_artifact_name: format!("{artifact_stem}-held-part-shadow.json"),
        preview_artifact_name: format!("{artifact_stem}-held-part-shadow.png"),
        findings,
    }
}

fn analyze_held_part_shadow(
    model: &HeldPartModel,
    bare: &GrayFrame,
    observed: &GrayFrame,
    deterministic: &HeldPartInspectionArtifacts,
    frame_center_px: [f64; 2],
    artifact_stem: &str,
    control_policy: HeldPartControlPolicy,
) -> Result<HeldPartShadowArtifacts, String> {
    let (bare_crop, origin) =
        centered_gray_crop(bare, frame_center_px, HELD_PART_MODEL_CROP_SIZE_PX)?;
    let (observed_crop, observed_origin) =
        centered_gray_crop(observed, frame_center_px, HELD_PART_MODEL_CROP_SIZE_PX)?;
    if origin != observed_origin {
        return Err("held-part pair crop origins differ".into());
    }
    let deterministic_outline_px = shift_held_part_outline(deterministic.outline_px, origin);
    let mut crop_deterministic = deterministic.clone();
    if let Some(value) = crop_deterministic.report.center_x_px.as_mut() {
        *value -= f64::from(origin[0]);
    }
    if let Some(value) = crop_deterministic.report.center_y_px.as_mut() {
        *value -= f64::from(origin[1]);
    }
    let prediction = model
        .predict_gray_pair(
            observed_crop.width,
            observed_crop.height,
            &bare_crop.pixels,
            &observed_crop.pixels,
        )
        .map_err(|error| error.to_string())?;
    let report = build_held_part_shadow_report(
        &crop_deterministic,
        deterministic_outline_px,
        prediction,
        artifact_stem,
        control_policy,
    );
    let preview = render_held_part_shadow_preview(
        &observed_crop,
        report.deterministic_outline_px,
        &report.prediction,
        report.review_required,
    );
    Ok(HeldPartShadowArtifacts { report, preview })
}

fn persist_held_part_shadow_artifacts(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    artifacts: &HeldPartShadowArtifacts,
) -> Result<(), String> {
    let report = serde_json::to_vec_pretty(&artifacts.report).map_err(|error| error.to_string())?;
    let preview = encode_rgb_png(&artifacts.preview).map_err(|error| error.to_string())?;
    persist_transfer_data_artifact(
        state,
        prepared,
        &artifacts.report.report_artifact_name,
        "application/json",
        &report,
    )?;
    persist_transfer_data_artifact(
        state,
        prepared,
        &artifacts.report.preview_artifact_name,
        "image/png",
        &preview,
    )
}

#[allow(clippy::too_many_arguments)]
async fn analyze_and_persist_held_part_shadow(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    bare: &GrayFrame,
    observed: &GrayFrame,
    deterministic: &HeldPartInspectionArtifacts,
    frame_center_px: [f64; 2],
    artifact_name: &str,
    control_policy: HeldPartControlPolicy,
) -> Option<HeldPartShadowReport> {
    let model = state.held_part_model.clone()?;
    let bare = bare.clone();
    let observed = observed.clone();
    let deterministic = deterministic.clone();
    let artifact_stem = artifact_name
        .strip_suffix(".png")
        .unwrap_or(artifact_name)
        .to_string();
    let analysis = match tokio::task::spawn_blocking(move || {
        analyze_held_part_shadow(
            &model,
            &bare,
            &observed,
            &deterministic,
            frame_center_px,
            &artifact_stem,
            control_policy,
        )
    })
    .await
    {
        Ok(Ok(analysis)) => analysis,
        Ok(Err(error)) => {
            tracing::warn!(%error, "held-part shadow inference failed");
            return None;
        }
        Err(error) => {
            tracing::warn!(%error, "held-part shadow task failed");
            return None;
        }
    };
    if let Err(error) = persist_held_part_shadow_artifacts(state, prepared, &analysis) {
        tracing::warn!(%error, "held-part shadow persistence failed");
        return None;
    }
    Some(analysis.report)
}

struct PlacementVerificationArtifacts {
    active: velocitypnp_domain::PlacedPartInspectionReport,
    comparison: PlacementVerificationComparisonReport,
    crop: GrayFrame,
    preview: RgbFrame,
}

#[allow(clippy::too_many_arguments)]
fn analyze_placement_verification(
    model: &PlacementVerificationModel,
    after: &GrayFrame,
    deterministic: &PlacedPartInspectionArtifacts,
    top_mapping: [[f64; 2]; 2],
    expected_width_mm: f64,
    expected_length_mm: f64,
    expected_rotation_deg: f64,
    maximum_center_offset_mm: f64,
    orientation: PartOrientation,
) -> Result<PlacementVerificationArtifacts, String> {
    let target_center_px = [
        deterministic.report.expected_center_x_px,
        deterministic.report.expected_center_y_px,
    ];
    let crop = normalize_placement_verification_crop(
        after,
        target_center_px,
        top_mapping,
        expected_rotation_deg,
    )
    .map_err(|error| error.to_string())?;
    let prediction = model
        .predict_gray(crop.frame.width, crop.frame.height, &crop.frame.pixels)
        .map_err(|error| error.to_string())?;
    build_placement_verification_artifacts(
        crop,
        deterministic,
        prediction,
        expected_width_mm,
        expected_length_mm,
        expected_rotation_deg,
        maximum_center_offset_mm,
        orientation,
    )
}

#[allow(clippy::too_many_arguments)]
fn build_placement_verification_artifacts(
    crop: velocitypnp_vision::PlacementVerificationCrop,
    deterministic: &PlacedPartInspectionArtifacts,
    prediction: velocitypnp_domain::PlacementVerificationModelPrediction,
    expected_width_mm: f64,
    expected_length_mm: f64,
    expected_rotation_deg: f64,
    maximum_center_offset_mm: f64,
    orientation: PartOrientation,
) -> Result<PlacementVerificationArtifacts, String> {
    let learned_occupied = prediction.class.occupied();
    let occupancy_agreement = deterministic.report.detected == learned_occupied;
    let scale_mm_per_px = velocitypnp_vision::PLACEMENT_VERIFICATION_CROP_SPAN_MM
        / f64::from(velocitypnp_vision::PLACEMENT_VERIFICATION_CROP_SIZE_PX);
    let crop_center = 0.5 * f64::from(velocitypnp_vision::PLACEMENT_VERIFICATION_CROP_SIZE_PX);
    let local_offset_mm = [
        (prediction.pose.center_px[0] - crop_center) * scale_mm_per_px,
        (prediction.pose.center_px[1] - crop_center) * scale_mm_per_px,
    ];
    let radians = expected_rotation_deg.to_radians();
    let learned_offset_mm = [
        radians.cos() * local_offset_mm[0] - radians.sin() * local_offset_mm[1],
        radians.sin() * local_offset_mm[0] + radians.cos() * local_offset_mm[1],
    ];
    let learned_offset_norm = learned_offset_mm[0].hypot(learned_offset_mm[1]);
    let learned_length_mm = prediction.pose.size_px[0] * scale_mm_per_px;
    let learned_width_mm = prediction.pose.size_px[1] * scale_mm_per_px;
    let learned_rotation_error_deg =
        ((prediction.pose.rotation_deg_mod_180 + 90.0).rem_euclid(180.0)) - 90.0;
    let learned_rotation_deg =
        ((expected_rotation_deg + learned_rotation_error_deg + 90.0).rem_euclid(180.0)) - 90.0;
    let size_passed = (MINIMUM_PLACEMENT_SIZE_RATIO..=MAXIMUM_PLACEMENT_SIZE_RATIO)
        .contains(&(learned_width_mm / expected_width_mm))
        && (MINIMUM_PLACEMENT_SIZE_RATIO..=MAXIMUM_PLACEMENT_SIZE_RATIO)
            .contains(&(learned_length_mm / expected_length_mm));
    let trained_class = matches!(
        prediction.class,
        PlacementVerificationClass::Empty | PlacementVerificationClass::ComponentFlat
    );
    let orientation_supported = orientation == PartOrientation::AxisSymmetric;
    let control_authorized = prediction.confidence_gate_passed
        && trained_class
        && occupancy_agreement
        && deterministic.report.target_registered
        && orientation_supported
        && (prediction.class == PlacementVerificationClass::Empty
            || (prediction.pose.valid && size_passed));
    let center_delta_mm = deterministic
        .report
        .offset_x_mm
        .zip(deterministic.report.offset_y_mm)
        .filter(|_| prediction.class == PlacementVerificationClass::ComponentFlat)
        .map(|(x, y)| (x - learned_offset_mm[0]).hypot(y - learned_offset_mm[1]));
    let rotation_delta_deg_mod_180 = deterministic
        .report
        .rotation_error_deg
        .filter(|_| prediction.class == PlacementVerificationClass::ComponentFlat)
        .map(|value| undirected_rotation_delta_deg(value, learned_rotation_error_deg));
    let mut findings = prediction.findings.clone();
    if !occupancy_agreement {
        findings.push("learned and deterministic placement occupancy disagree".into());
    }
    if !trained_class {
        findings.push("the predicted condition has no reviewed training examples".into());
    }
    if !orientation_supported {
        findings.push("the undirected model cannot verify this orientation policy".into());
    }
    if prediction.class == PlacementVerificationClass::ComponentFlat && !size_passed {
        findings.push(format!(
            "learned package size {learned_width_mm:.3} by \
             {learned_length_mm:.3} mm is outside the expected bounds",
        ));
    }
    let mut active = deterministic.report.clone();
    if control_authorized {
        active.algorithm_version = PLACEMENT_VERIFICATION_CONTROL_ALGORITHM.into();
        active.placement_condition = Some(prediction.class);
        active.confidence = prediction.class_confidence;
        active.artifact_name = BOARD_PLACEMENT_MODEL_INSPECTION_ARTIFACT.into();
        active.findings = findings.clone();
        match prediction.class {
            PlacementVerificationClass::Empty => {
                active.detected = false;
                active.center_x_px = None;
                active.center_y_px = None;
                active.offset_x_mm = None;
                active.offset_y_mm = None;
                active.offset_mm = None;
                active.width_mm = None;
                active.length_mm = None;
                active.rotation_deg = None;
                active.rotation_error_deg = None;
                active.passed = false;
                active
                    .findings
                    .push("the promoted model found no component at the target".into());
            }
            PlacementVerificationClass::ComponentFlat => {
                let source_center = crop.source_pixel(prediction.pose.center_px);
                active.detected = true;
                active.center_x_px = Some(source_center[0]);
                active.center_y_px = Some(source_center[1]);
                active.offset_x_mm = Some(learned_offset_mm[0]);
                active.offset_y_mm = Some(learned_offset_mm[1]);
                active.offset_mm = Some(learned_offset_norm);
                active.width_mm = Some(learned_width_mm);
                active.length_mm = Some(learned_length_mm);
                active.rotation_deg = Some(learned_rotation_deg);
                active.rotation_error_deg = Some(learned_rotation_error_deg);
                active.orientation = orientation;
                active.orientation_rotation_deg = None;
                active.orientation_contrast_luma = None;
                active.orientation_confidence = 0.0;
                active.orientation_matched = None;
                active.passed = learned_offset_norm <= maximum_center_offset_mm
                    && learned_rotation_error_deg.abs() <= MAX_PLACED_PART_ROTATION_ERROR_DEG;
                active.findings.push(format!(
                    "the promoted model found a flat package at X{:+.3} Y{:+.3} mm and {:+.2} degrees",
                    learned_offset_mm[0],
                    learned_offset_mm[1],
                    learned_rotation_error_deg,
                ));
            }
            PlacementVerificationClass::ComponentOnEdge
            | PlacementVerificationClass::MultipleComponents => unreachable!(),
        }
    } else if prediction.confidence_gate_passed && !occupancy_agreement {
        active.passed = false;
        active
            .findings
            .push("learned and deterministic placement evidence requires review".into());
    }
    let review_required = !control_authorized;
    let preview = render_placement_verification_preview(
        &crop.frame,
        &prediction,
        expected_width_mm,
        expected_length_mm,
        review_required,
    );
    if control_authorized {
        findings.push("the learned result is the active placement inspection".into());
    } else {
        findings.push("deterministic CV remains active for this inspection".into());
    }
    let comparison = PlacementVerificationComparisonReport {
        algorithm_version: PLACEMENT_VERIFICATION_COMPARISON_ALGORITHM.into(),
        deterministic: deterministic.report.clone(),
        prediction,
        occupancy_agreement,
        center_delta_mm,
        rotation_delta_deg_mod_180,
        review_required,
        control_authorized,
        report_artifact_name: BOARD_PLACEMENT_MODEL_REPORT_ARTIFACT.into(),
        preview_artifact_name: BOARD_PLACEMENT_MODEL_INSPECTION_ARTIFACT.into(),
        crop_artifact_name: BOARD_PLACEMENT_MODEL_CROP_ARTIFACT.into(),
        findings,
    };
    Ok(PlacementVerificationArtifacts {
        active,
        comparison,
        crop: crop.frame,
        preview,
    })
}

#[allow(clippy::too_many_arguments)]
async fn analyze_and_persist_placement_verification(
    state: &AppState,
    execution_id: Uuid,
    after: &GrayFrame,
    deterministic: &PlacedPartInspectionArtifacts,
    top_mapping: [[f64; 2]; 2],
    expected_width_mm: f64,
    expected_length_mm: f64,
    expected_rotation_deg: f64,
    maximum_center_offset_mm: f64,
    orientation: PartOrientation,
) -> Option<PlacementVerificationArtifacts> {
    let model = state.placement_verification_model.clone()?;
    let after = after.clone();
    let deterministic = deterministic.clone();
    let analysis = match tokio::task::spawn_blocking(move || {
        analyze_placement_verification(
            &model,
            &after,
            &deterministic,
            top_mapping,
            expected_width_mm,
            expected_length_mm,
            expected_rotation_deg,
            maximum_center_offset_mm,
            orientation,
        )
    })
    .await
    {
        Ok(Ok(analysis)) => analysis,
        Ok(Err(error)) => {
            tracing::warn!(%error, %execution_id, "placement-verification inference failed");
            return None;
        }
        Err(error) => {
            tracing::warn!(%error, %execution_id, "placement-verification task failed");
            return None;
        }
    };
    let report = match serde_json::to_vec_pretty(&analysis.comparison) {
        Ok(report) => report,
        Err(error) => {
            tracing::warn!(%error, %execution_id, "placement-verification report failed");
            return None;
        }
    };
    let crop = match encode_gray_png(&analysis.crop) {
        Ok(crop) => crop,
        Err(error) => {
            tracing::warn!(%error, %execution_id, "placement-verification crop failed");
            return None;
        }
    };
    let preview = match encode_rgb_png(&analysis.preview) {
        Ok(preview) => preview,
        Err(error) => {
            tracing::warn!(%error, %execution_id, "placement-verification preview failed");
            return None;
        }
    };
    for (name, media_type, data) in [
        (
            BOARD_PLACEMENT_MODEL_REPORT_ARTIFACT,
            "application/json",
            report.as_slice(),
        ),
        (
            BOARD_PLACEMENT_MODEL_CROP_ARTIFACT,
            "image/png",
            crop.as_slice(),
        ),
        (
            BOARD_PLACEMENT_MODEL_INSPECTION_ARTIFACT,
            "image/png",
            preview.as_slice(),
        ),
    ] {
        if let Err(error) =
            state
                .store
                .put_placement_execution_artifact(execution_id, name, media_type, data)
        {
            tracing::warn!(%error, %execution_id, "placement-verification persistence failed");
            return None;
        }
    }
    Some(analysis)
}

#[derive(Clone, Copy)]
struct SourceComponentShadowContext {
    camera_pose: Pose,
    pocket_machine_mm: [f64; 2],
    prior_inventory_occupancy: StripPocketOccupancy,
    prior_inventory_confidence: f64,
}

fn build_source_component_shadow_report(
    deterministic: &StripFeederSourceComponentDraft,
    prediction: SourceComponentModelPrediction,
    prior_inventory_occupancy: StripPocketOccupancy,
    prior_inventory_confidence: f64,
    crop: &GrayFrame,
    artifact_stem: &str,
) -> SourceComponentShadowReport {
    let learned_occupied = prediction.class.occupied();
    let occupancy_agreement = occupancy_matches(deterministic.occupancy, learned_occupied);
    let learned_prior_inventory_agreement =
        occupancy_matches(prior_inventory_occupancy, learned_occupied);
    let deterministic_prior_inventory_agreement = match deterministic.occupancy {
        StripPocketOccupancy::Occupied => {
            prior_inventory_occupancy == StripPocketOccupancy::Occupied
        }
        StripPocketOccupancy::Empty => prior_inventory_occupancy == StripPocketOccupancy::Empty,
        StripPocketOccupancy::Uncertain => false,
    };
    let center_delta_px = deterministic
        .center_px
        .filter(|_| learned_occupied)
        .map(|center| {
            (center[0] - prediction.pose.center_px[0])
                .hypot(center[1] - prediction.pose.center_px[1])
        });
    let maximum_center_delta_px =
        f64::from(crop.width.min(crop.height)) * MAXIMUM_SOURCE_COMPONENT_CENTER_DELTA_FRACTION;
    let center_agreement = match (deterministic.occupancy, learned_occupied) {
        (StripPocketOccupancy::Occupied, true) => {
            center_delta_px.is_some_and(|delta| delta <= maximum_center_delta_px)
        }
        (StripPocketOccupancy::Empty, false) => true,
        _ => false,
    };
    let on_edge = prediction.class == SourceComponentClass::ComponentOnEdge;
    let review_required = deterministic.review_required
        || !prediction.confidence_gate_passed
        || !occupancy_agreement
        || !learned_prior_inventory_agreement
        || !deterministic_prior_inventory_agreement
        || !center_agreement
        || on_edge;
    let mut findings = prediction.findings.clone();
    findings.push("the learned result is shadow evidence and cannot control motion".into());
    if deterministic.review_required {
        findings.push("the deterministic detector requires review".into());
    }
    if deterministic.occupancy == StripPocketOccupancy::Uncertain {
        findings.push("the deterministic occupancy is uncertain".into());
    } else if !occupancy_agreement {
        findings.push("learned and deterministic occupancy disagree".into());
    }
    if !learned_prior_inventory_agreement {
        findings.push("learned occupancy disagrees with the prior inventory".into());
    }
    if !deterministic_prior_inventory_agreement {
        findings.push("deterministic occupancy disagrees with the prior inventory".into());
    }
    if !center_agreement {
        findings.push(format!(
            "learned and deterministic centers differ by more than {maximum_center_delta_px:.1} pixels"
        ));
    }
    if on_edge {
        findings.push("the learned model marks the component as on edge".into());
    }
    SourceComponentShadowReport {
        algorithm_version: SOURCE_COMPONENT_SHADOW_ALGORITHM.into(),
        prior_inventory_occupancy: Some(prior_inventory_occupancy),
        prior_inventory_confidence: Some(prior_inventory_confidence),
        deterministic_algorithm_version: deterministic.algorithm_version.clone(),
        deterministic_occupancy: deterministic.occupancy,
        deterministic_confidence: deterministic.occupancy_confidence,
        deterministic_center_px: deterministic.center_px,
        deterministic_outline_px: deterministic.outline_px,
        prediction,
        occupancy_agreement,
        learned_prior_inventory_agreement: Some(learned_prior_inventory_agreement),
        deterministic_prior_inventory_agreement: Some(deterministic_prior_inventory_agreement),
        center_delta_px,
        review_required,
        control_authorized: false,
        report_artifact_name: format!("{artifact_stem}-source-component-shadow.json"),
        preview_artifact_name: format!("{artifact_stem}-source-component-shadow.png"),
        crop_artifact_name: format!("{artifact_stem}-source-component-crop.png"),
        findings,
    }
}

fn occupancy_matches(expected: StripPocketOccupancy, occupied: bool) -> bool {
    matches!(
        (expected, occupied),
        (StripPocketOccupancy::Occupied, true) | (StripPocketOccupancy::Empty, false)
    )
}

fn analyze_source_component_shadow(
    model: &SourceComponentModel,
    frame: &GrayFrame,
    camera_model: &PlanarCameraModel,
    registration: &StripFeederRegistration,
    context: SourceComponentShadowContext,
    artifact_stem: &str,
) -> Result<SourceComponentShadowArtifacts, String> {
    let deterministic = draft_strip_feeder_source_component(
        frame,
        context.camera_pose,
        context.pocket_machine_mm,
        camera_model,
        registration,
    )
    .map_err(|error| error.to_string())?;
    let prediction = model
        .predict_gray(
            deterministic.crop.width,
            deterministic.crop.height,
            &deterministic.crop.pixels,
        )
        .map_err(|error| error.to_string())?;
    let report = build_source_component_shadow_report(
        &deterministic.report,
        prediction,
        context.prior_inventory_occupancy,
        context.prior_inventory_confidence,
        &deterministic.crop,
        artifact_stem,
    );
    let preview = render_source_component_shadow_preview(
        &deterministic.crop,
        deterministic.report.outline_px,
        &report.prediction,
        report.review_required,
    );
    Ok(SourceComponentShadowArtifacts {
        report,
        crop: deterministic.crop,
        preview,
    })
}

fn persist_source_component_shadow_artifacts(
    state: &AppState,
    capture_id: Uuid,
    artifacts: &SourceComponentShadowArtifacts,
) -> Result<(), String> {
    let report = serde_json::to_vec_pretty(&artifacts.report).map_err(|error| error.to_string())?;
    let crop = encode_gray_png(&artifacts.crop).map_err(|error| error.to_string())?;
    let preview = encode_rgb_png(&artifacts.preview).map_err(|error| error.to_string())?;
    for (name, media_type, data) in [
        (
            artifacts.report.report_artifact_name.as_str(),
            "application/json",
            report.as_slice(),
        ),
        (
            artifacts.report.crop_artifact_name.as_str(),
            "image/png",
            crop.as_slice(),
        ),
        (
            artifacts.report.preview_artifact_name.as_str(),
            "image/png",
            preview.as_slice(),
        ),
    ] {
        state
            .store
            .put_strip_feeder_source_capture_artifact(capture_id, name, media_type, data)
            .map_err(|error| error.to_string())?;
    }
    Ok(())
}

async fn analyze_and_persist_source_component_shadow(
    state: &AppState,
    capture_id: Uuid,
    frame: GrayFrame,
    registration: StripFeederRegistration,
    context: SourceComponentShadowContext,
    artifact_name: &str,
) -> Option<SourceComponentShadowReport> {
    let model = state.source_component_model.clone()?;
    let camera_model = match load_workspace_camera_model(state, registration.calibration_id) {
        Ok((_, model)) => model,
        Err(error) => {
            tracing::warn!(%error.message, capture_id = %capture_id, "source-component shadow camera model is unavailable");
            return None;
        }
    };
    let artifact_stem = artifact_name
        .strip_suffix(".png")
        .unwrap_or(artifact_name)
        .to_string();
    let analysis = match tokio::task::spawn_blocking(move || {
        analyze_source_component_shadow(
            &model,
            &frame,
            &camera_model,
            &registration,
            context,
            &artifact_stem,
        )
    })
    .await
    {
        Ok(Ok(analysis)) => analysis,
        Ok(Err(error)) => {
            tracing::warn!(%error, capture_id = %capture_id, "source-component shadow inference failed");
            return None;
        }
        Err(error) => {
            tracing::warn!(%error, capture_id = %capture_id, "source-component shadow task failed");
            return None;
        }
    };
    if let Err(error) = persist_source_component_shadow_artifacts(state, capture_id, &analysis) {
        tracing::warn!(%error, capture_id = %capture_id, "source-component shadow persistence failed");
        return None;
    }
    Some(analysis.report)
}

#[allow(clippy::too_many_arguments)]
async fn execute_strip_feeder_source_capture_task(
    state: AppState,
    mut run: StripFeederSourceCaptureRun,
    targets: Vec<InventorySourceCaptureTarget>,
    camera_profile: CameraProfile,
    camera_path: String,
    visual: VisualHomingProfile,
    lease_id: Uuid,
) -> Result<Option<String>, String> {
    let task_started = Instant::now();
    let operation_id = run.operation_id;
    let simulated = state.machine.status().simulated;
    run.status = OperationStatus::Running;
    run.updated_at = Utc::now();
    state
        .store
        .put_strip_feeder_source_capture(&run)
        .map_err(|error| error.to_string())?;
    let (result, camera_timing) = if simulated {
        (
            execute_strip_feeder_source_capture(
                &state,
                &mut run,
                targets,
                &camera_profile,
                &camera_path,
                &visual,
                lease_id,
            )
            .await,
            json!({}),
        )
    } else {
        let operation_state = state.clone();
        with_profiled_camera_reuse(
            &state,
            execute_strip_feeder_source_capture(
                &operation_state,
                &mut run,
                targets,
                &camera_profile,
                &camera_path,
                &visual,
                lease_id,
            ),
        )
        .await
    };
    record_camera_target_operation_timing(
        &state,
        operation_id,
        "strip_feeder_source_capture",
        simulated,
        result.is_ok(),
        elapsed_ms(task_started),
        camera_timing,
    )
    .await;
    match result {
        Ok(()) => {
            let occupied = run
                .samples
                .iter()
                .filter(|sample| sample.expected_occupancy == StripPocketOccupancy::Occupied)
                .count();
            let empty = run.samples.len() - occupied;
            let message = format!(
                "Captured {} centered feeder source images: {occupied} expected occupied and {empty} expected empty",
                run.samples.len(),
            );
            run.status = OperationStatus::Succeeded;
            run.message = Some(message.clone());
            run.updated_at = Utc::now();
            state
                .store
                .put_strip_feeder_source_capture(&run)
                .map_err(|error| error.to_string())?;
            Ok(Some(message))
        }
        Err(message) => {
            run.status = OperationStatus::Failed;
            run.message = Some(message.clone());
            run.updated_at = Utc::now();
            if let Err(error) = state.store.put_strip_feeder_source_capture(&run) {
                tracing::error!(%error, capture_id = %run.id, "failed to persist feeder source capture failure");
            }
            Err(message)
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn execute_strip_feeder_source_capture(
    state: &AppState,
    run: &mut StripFeederSourceCaptureRun,
    targets: Vec<InventorySourceCaptureTarget>,
    camera_profile: &CameraProfile,
    camera_path: &str,
    visual: &VisualHomingProfile,
    lease_id: Uuid,
) -> Result<(), String> {
    let _motion_guard = state.workspace_scan_motion_lock.lock().await;
    execute_visual_home(
        state,
        VisualHomingRequest {
            lease_id,
            apply_offset: true,
            move_to_seed: true,
        },
    )
    .await
    .map_err(|error| {
        format!(
            "visual home before feeder source capture failed: {}",
            error.message
        )
    })?;
    let mut motion = operation_motion_sequence(
        state,
        run.calibration_id,
        "strip feeder source capture motion",
    )?;
    if camera_profile.lighting_enabled {
        state
            .machine
            .actuate(lease_id, "lights".into(), true)
            .await
            .map_err(|error| error.to_string())?;
    }
    let capture_result = capture_inventory_source_targets(
        state,
        run,
        targets,
        camera_profile,
        camera_path,
        visual,
        lease_id,
        &mut motion,
    )
    .await;
    let return_feed_mm_per_min = safe_level_xy_feed(
        &state.profile,
        Some(motion.state.logical_pose),
        visual.seed_pose,
        visual.feed_mm_per_min,
    );
    let return_result = execute_calibrated_motion(
        state,
        lease_id,
        &mut motion,
        visual.seed_pose,
        return_feed_mm_per_min,
    )
    .await;
    let lights_result = if camera_profile.lighting_enabled {
        state.machine.disable_actuator("lights".into()).await
    } else {
        Ok(())
    };
    if let Err(error) = return_result {
        return Err(format!("feeder source capture return move failed: {error}"));
    }
    if let Err(error) = lights_result {
        return Err(format!(
            "feeder source capture light cleanup failed: {error}"
        ));
    }
    capture_result
}

#[allow(clippy::too_many_arguments)]
async fn capture_inventory_source_targets(
    state: &AppState,
    run: &mut StripFeederSourceCaptureRun,
    targets: Vec<InventorySourceCaptureTarget>,
    camera_profile: &CameraProfile,
    camera_path: &str,
    visual: &VisualHomingProfile,
    lease_id: Uuid,
    motion: &mut CalibratedMotionSequence,
) -> Result<(), String> {
    for target in targets {
        state
            .machine
            .renew_lease(lease_id, 1_800)
            .await
            .map_err(|error| error.to_string())?;
        let requested_pose = Pose {
            x_mm: target.observation.center_machine_mm[0],
            y_mm: target.observation.center_machine_mm[1],
            z_mm: state.profile.safe_z_mm,
            rotation_deg: 0.0,
        };
        let camera_pose =
            jog_board_registration_target(state, lease_id, requested_pose, visual, motion).await?;
        let frame = capture_profiled_frame(state, camera_profile, camera_path)
            .await
            .map_err(|error| error.message)?;
        let artifact_name = format!(
            "lane-{:03}-pocket-{:03}.png",
            target.inventory_index, target.observation.pocket_index,
        );
        let encoded = encode_gray_png(&frame).map_err(|error| error.to_string())?;
        state
            .store
            .put_strip_feeder_source_capture_artifact(run.id, &artifact_name, "image/png", &encoded)
            .map_err(|error| error.to_string())?;
        let source_component_shadow = if state.source_component_model.is_some() {
            match state
                .store
                .get_strip_feeder_registration(target.registration_id)
                .map_err(|error| error.to_string())?
            {
                Some(registration) => {
                    analyze_and_persist_source_component_shadow(
                        state,
                        run.id,
                        frame.clone(),
                        registration,
                        SourceComponentShadowContext {
                            camera_pose,
                            pocket_machine_mm: target.observation.center_machine_mm,
                            prior_inventory_occupancy: target.observation.occupancy,
                            prior_inventory_confidence: target.observation.confidence,
                        },
                        &artifact_name,
                    )
                    .await
                }
                None => {
                    tracing::warn!(
                        registration_id = %target.registration_id,
                        capture_id = %run.id,
                        "source-component shadow registration is unavailable"
                    );
                    None
                }
            }
        } else {
            None
        };
        run.samples.push(StripFeederSourceCaptureSample {
            inventory_index: target.inventory_index,
            registration_id: target.registration_id,
            source_scan_id: target.source_scan_id,
            source_candidate_index: target.source_candidate_index,
            source_proposal_index: target.source_proposal_index,
            pocket_index: target.observation.pocket_index,
            expected_occupancy: target.observation.occupancy,
            expected_occupancy_confidence: target.observation.confidence,
            pocket_machine_mm: target.observation.center_machine_mm,
            camera_pose,
            artifact_name,
            source_component_shadow,
        });
        run.updated_at = Utc::now();
        state
            .store
            .put_strip_feeder_source_capture(run)
            .map_err(|error| error.to_string())?;
    }
    Ok(())
}

