#[derive(Debug, Deserialize)]
struct StartStripFeederLiveHoldoutRequest {
    lease_id: Uuid,
    #[serde(default)]
    pocket_index: Option<u32>,
    #[serde(default = "default_strip_feeder_holdout_sample_count")]
    sample_count: u32,
    confirmed_external_safety_checks: bool,
}

#[derive(Debug, Serialize)]
struct StartStripFeederLiveHoldoutResponse {
    holdout: StripFeederLiveHoldoutRun,
    operation: Operation,
}

fn default_strip_feeder_holdout_sample_count() -> u32 {
    3
}

const STRIP_FEEDER_HOLDOUT_ALONG_OFFSET_MM: f64 = 4.0;

fn strip_feeder_holdout_capture_targets(
    registration: &StripFeederRegistration,
    predicted_pocket_machine_mm: [f64; 2],
    safe_z_mm: f64,
) -> ApiResult<Vec<Pose>> {
    let direction = [
        registration.pick_centerline_machine_mm[1][0]
            - registration.pick_centerline_machine_mm[0][0],
        registration.pick_centerline_machine_mm[1][1]
            - registration.pick_centerline_machine_mm[0][1],
    ];
    let length = direction[0].hypot(direction[1]);
    if !length.is_finite() || length <= 1e-9 {
        return Err(ApiError::bad_request(
            "strip feeder draft centerline has no direction",
        ));
    }
    let along = [direction[0] / length, direction[1] / length];
    let cross = [-along[1], along[0]];
    let sprocket_offset_mm = registration.tape_width_mm * 0.5 - 0.5;
    if !sprocket_offset_mm.is_finite() || sprocket_offset_mm <= 0.0 {
        return Err(ApiError::bad_request(
            "strip feeder draft tape width is invalid",
        ));
    }
    let pose = |cross_mm: f64, along_mm: f64| Pose {
        x_mm: predicted_pocket_machine_mm[0] + cross[0] * cross_mm + along[0] * along_mm,
        y_mm: predicted_pocket_machine_mm[1] + cross[1] * cross_mm + along[1] * along_mm,
        z_mm: safe_z_mm,
        rotation_deg: 0.0,
    };
    Ok(vec![
        pose(-sprocket_offset_mm, -STRIP_FEEDER_HOLDOUT_ALONG_OFFSET_MM),
        pose(-sprocket_offset_mm, STRIP_FEEDER_HOLDOUT_ALONG_OFFSET_MM),
        pose(0.0, 0.0),
        pose(sprocket_offset_mm, STRIP_FEEDER_HOLDOUT_ALONG_OFFSET_MM),
        pose(sprocket_offset_mm, -STRIP_FEEDER_HOLDOUT_ALONG_OFFSET_MM),
    ])
}

async fn start_strip_feeder_live_holdout(
    State(state): State<AppState>,
    Path(registration_id): Path<Uuid>,
    Json(body): Json<StartStripFeederLiveHoldoutRequest>,
) -> ApiResult<(StatusCode, Json<StartStripFeederLiveHoldoutResponse>)> {
    if !body.confirmed_external_safety_checks {
        return Err(ApiError::bad_request(
            "live pocket holdout requires confirmation that the tape is fixed, both nozzles are level, the travel envelope is clear, and power isolation is reachable",
        ));
    }
    if !(3..=5).contains(&body.sample_count) {
        return Err(ApiError::bad_request(
            "live pocket holdout sample_count must be between 3 and 5",
        ));
    }
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed || status.pose.is_none() {
        return Err(ApiError::bad_request(
            "live pocket holdout requires a homed ready machine",
        ));
    }
    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(&state)?;
    ensure_no_active_board_registrations(&state)?;
    ensure_no_active_board_surface_measurements(&state)?;
    ensure_no_active_strip_feeder_holdouts(&state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(&state)?;
    let registration = state
        .store
        .get_strip_feeder_registration(registration_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("strip feeder registration not found"))?;
    if !state.profile.accepts_profile_id(&registration.profile_id) {
        return Err(ApiError::bad_request(
            "live pocket holdout registration uses a different machine profile",
        ));
    }
    if !status.simulated && status.calibration_revision != Some(registration.calibration_id) {
        return Err(ApiError::bad_request(format!(
            "live pocket holdout requires fine XYZ homing with calibration {}",
            registration.calibration_id,
        )));
    }
    if registration.pocket_centers_machine_mm.is_empty() {
        return Err(ApiError::bad_request(
            "strip feeder registration has no pocket hypotheses",
        ));
    }
    let pocket_index = live_holdout_pocket_index(&registration, body.pocket_index)?;
    let predicted_pocket_machine_mm = registration
        .pocket_centers_machine_mm
        .get(pocket_index)
        .copied()
        .ok_or_else(|| ApiError::bad_request("live pocket index is outside the draft"))?;
    let capture_targets = strip_feeder_holdout_capture_targets(
        &registration,
        predicted_pocket_machine_mm,
        state.profile.safe_z_mm,
    )?;
    if capture_targets
        .iter()
        .any(|target| !state.profile.bounds.contains(*target))
    {
        return Err(ApiError::bad_request(
            "live pocket holdout capture sweep is outside machine bounds",
        ));
    }
    let (_, camera_model) = load_workspace_camera_model(&state, registration.calibration_id)?;
    let camera_profile = stored_camera_profile(&state, CameraRole::TopCamera)?;
    let camera_path = camera_path_for_role(CameraRole::TopCamera)?;
    let visual = state
        .profile
        .visual_homing
        .as_ref()
        .cloned()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let operation = Operation::pending("vision.strip_feeder_live_holdout");
    let now = Utc::now();
    let holdout = StripFeederLiveHoldoutRun {
        id: Uuid::new_v4(),
        operation_id: operation.id,
        registration_id,
        profile_id: registration.profile_id.clone(),
        calibration_id: registration.calibration_id,
        status: OperationStatus::Pending,
        created_at: now,
        updated_at: now,
        sample_count: body.sample_count,
        pocket_index: pocket_index as u32,
        requested_pocket_only: body.pocket_index.is_some(),
        predicted_pocket_machine_mm,
        report: None,
        message: None,
    };
    state
        .machine
        .renew_lease(body.lease_id, 900)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    state
        .store
        .put_operation(&operation)
        .map_err(ApiError::internal)?;
    state
        .store
        .put_strip_feeder_live_holdout(&holdout)
        .map_err(ApiError::internal)?;
    drop(admission_guard);
    let response = StartStripFeederLiveHoldoutResponse {
        holdout: holdout.clone(),
        operation: operation.clone(),
    };
    let task_state = state.clone();
    spawn_prepared_operation(
        state,
        operation,
        execute_strip_feeder_live_holdout_task(
            task_state,
            holdout,
            registration,
            camera_model,
            camera_profile,
            camera_path,
            visual,
            body.lease_id,
        ),
    );
    Ok((StatusCode::ACCEPTED, Json(response)))
}

fn live_holdout_pocket_index(
    registration: &StripFeederRegistration,
    requested: Option<u32>,
) -> ApiResult<usize> {
    requested.map_or_else(
        || {
            registration
                .next_available_pocket(None)
                .map(|pocket| pocket.pocket_index as usize)
                .ok_or_else(|| {
                    ApiError::bad_request(
                        "strip feeder has no available occupied pocket for live holdout",
                    )
                })
        },
        |index| Ok(index as usize),
    )
}

fn ensure_no_active_strip_feeder_holdouts(state: &AppState) -> ApiResult<()> {
    let active = state
        .store
        .list_strip_feeder_live_holdouts()
        .map_err(ApiError::internal)?
        .into_iter()
        .any(|run| {
            matches!(
                run.status,
                OperationStatus::Pending | OperationStatus::Running
            )
        });
    if active {
        return Err(ApiError::bad_request(
            "a strip feeder live holdout is already active",
        ));
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
async fn execute_strip_feeder_live_holdout_task(
    state: AppState,
    mut run: StripFeederLiveHoldoutRun,
    mut registration: StripFeederRegistration,
    camera_model: PlanarCameraModel,
    camera_profile: CameraProfile,
    camera_path: String,
    visual: VisualHomingProfile,
    lease_id: Uuid,
) -> Result<Option<String>, String> {
    let task_started = Instant::now();
    let operation_id = run.operation_id;
    let simulated = state.machine.status().simulated;
    run.status = OperationStatus::Running;
    run.updated_at = Utc::now();
    state
        .store
        .put_strip_feeder_live_holdout(&run)
        .map_err(|error| error.to_string())?;
    let (result, camera_timing) = if simulated {
        (
            execute_strip_feeder_live_holdout(
                &state,
                &run,
                &registration,
                &camera_model,
                &camera_profile,
                &camera_path,
                &visual,
                lease_id,
            )
            .await,
            json!({}),
        )
    } else {
        let operation_state = state.clone();
        with_profiled_camera_reuse(
            &state,
            execute_strip_feeder_live_holdout(
                &operation_state,
                &run,
                &registration,
                &camera_model,
                &camera_profile,
                &camera_path,
                &visual,
                lease_id,
            ),
        )
        .await
    };
    record_camera_target_operation_timing(
        &state,
        operation_id,
        "strip_feeder_live_holdout",
        simulated,
        result.is_ok(),
        elapsed_ms(task_started),
        camera_timing,
    )
    .await;
    match result {
        Ok(report) => {
            let message = if report.passed {
                format!(
                    "Live pocket holdout passed with {} sprocket centers, {:.3} mm correction, and {:.0}% occupancy confidence",
                    report.sprocket_center_count,
                    report.correction_magnitude_mm,
                    report.occupancy_confidence * 100.0,
                )
            } else {
                format!(
                    "Live pocket holdout rejected the draft: {}",
                    report.findings.join("; "),
                )
            };
            run.status = if report.passed {
                OperationStatus::Succeeded
            } else {
                OperationStatus::Failed
            };
            run.report = Some(report.clone());
            run.message = Some(message.clone());
            run.updated_at = Utc::now();
            state
                .store
                .put_strip_feeder_live_holdout(&run)
                .map_err(|error| error.to_string())?;
            registration.latest_live_holdout_id = Some(run.id);
            if report.passed {
                registration.selected_pocket_machine_mm = report.measured_pocket_machine_mm;
                registration.selected_pocket_index = nearest_strip_feeder_pocket_index(
                    &registration.pocket_centers_machine_mm,
                    report.predicted_pocket_machine_mm,
                )
                .or(Some(run.pocket_index));
                registration.ensure_pocket_state();
                if let Some(pocket) = registration
                    .pockets
                    .iter_mut()
                    .find(|pocket| Some(pocket.pocket_index) == registration.selected_pocket_index)
                {
                    pocket.measured_center_machine_mm = report.measured_pocket_machine_mm;
                    pocket.occupancy = report.occupancy;
                    pocket.occupancy_confidence = report.occupancy_confidence;
                    if !matches!(
                        pocket.status,
                        StripFeederPocketStatus::Consumed | StripFeederPocketStatus::Reserved
                    ) {
                        pocket.status = StripFeederPocketStatus::Available;
                    }
                    pocket.updated_at = Utc::now();
                }
                registration.findings.retain(|finding| {
                    !finding.contains("live pocket occupancy") && !finding.contains("live holdout")
                });
                registration.findings.push(
                    if registration.pickup_z_mm.is_some() {
                        "live pocket position and occupancy passed"
                    } else {
                        "live pocket position and occupancy passed; pickup Z remains unmeasured"
                    }
                    .into(),
                );
                sync_active_strip_feeder(&state, &registration)?;
                if registration.part_key.is_some()
                    && registration.part_rotation_deg.is_some()
                    && matches!(
                        registration.status,
                        StripFeederRegistrationStatus::VisionDraft
                            | StripFeederRegistrationStatus::LiveValidationRequired
                    )
                {
                    registration.status = StripFeederRegistrationStatus::LiveValidationRequired;
                }
            }
            registration.updated_at = Utc::now();
            state
                .store
                .put_strip_feeder_registration(&registration)
                .map_err(|error| error.to_string())?;
            if report.passed {
                Ok(Some(message))
            } else {
                Err(message)
            }
        }
        Err(message) => {
            run.status = OperationStatus::Failed;
            run.message = Some(message.clone());
            run.updated_at = Utc::now();
            if let Err(error) = state.store.put_strip_feeder_live_holdout(&run) {
                tracing::error!(%error, holdout_id = %run.id, "failed to persist rejected strip feeder holdout");
            }
            Err(message)
        }
    }
}

fn sync_active_strip_feeder(
    state: &AppState,
    registration: &StripFeederRegistration,
) -> Result<(), String> {
    let (Some(feeder_id), Some(pickup_z_mm), Some(part_rotation_deg)) = (
        registration.active_feeder_id,
        registration.pickup_z_mm,
        registration.part_rotation_deg,
    ) else {
        return Ok(());
    };
    let feeder = state
        .store
        .list_feeders()
        .map_err(|error| error.to_string())?
        .into_iter()
        .find(|feeder| feeder.id() == feeder_id)
        .ok_or_else(|| "active strip feeder disappeared during live holdout".to_string())?;
    let Feeder::Strip {
        id,
        name,
        part_key,
        first_pick,
        tape_pitch_mm,
        tape_width_mm,
        tape_rotation_deg,
        ..
    } = feeder
    else {
        return Err("active feeder is not a strip feeder".into());
    };
    let first_pick = registration
        .selected_pocket_machine_mm
        .map_or(first_pick, |center| Pose {
            x_mm: center[0],
            y_mm: center[1],
            z_mm: pickup_z_mm,
            rotation_deg: part_rotation_deg,
        });
    let remaining = registration
        .pockets
        .iter()
        .filter(|pocket| {
            pocket.status == StripFeederPocketStatus::Available
                && pocket.occupancy == StripPocketOccupancy::Occupied
        })
        .count()
        .try_into()
        .ok();
    state
        .store
        .put_feeder(&Feeder::Strip {
            id,
            name,
            part_key,
            first_pick,
            tape_pitch_mm,
            tape_width_mm,
            tape_rotation_deg,
            remaining,
        })
        .map_err(|error| error.to_string())
}

fn settle_source_component_empty(
    state: &AppState,
    registration_id: Uuid,
    reservation_id: Uuid,
) -> Result<StripFeederRegistration, String> {
    let registration = state
        .store
        .settle_strip_feeder_pocket(
            registration_id,
            reservation_id,
            StripFeederPocketOutcome::ObservedEmpty,
            false,
        )
        .map_err(|error| error.to_string())?;
    sync_active_strip_feeder(state, &registration)?;
    Ok(registration)
}

#[allow(clippy::too_many_arguments)]
async fn execute_strip_feeder_live_holdout(
    state: &AppState,
    run: &StripFeederLiveHoldoutRun,
    registration: &StripFeederRegistration,
    camera_model: &PlanarCameraModel,
    camera_profile: &CameraProfile,
    camera_path: &str,
    visual: &VisualHomingProfile,
    lease_id: Uuid,
) -> Result<velocitypnp_domain::StripFeederLiveHoldoutReport, String> {
    let _motion_guard = state.workspace_scan_motion_lock.lock().await;
    execute_visual_home(
        state,
        VisualHomingRequest {
            lease_id,
            apply_offset: true,
            move_to_seed: true,
        },
    )
    .await
    .map_err(|error| {
        format!(
            "visual home before live pocket holdout failed: {}",
            error.message
        )
    })?;
    let mut motion = operation_motion_sequence(
        state,
        run.calibration_id,
        "strip feeder live holdout motion",
    )?;
    if camera_profile.lighting_enabled {
        state
            .machine
            .actuate(lease_id, "lights".into(), true)
            .await
            .map_err(|error| error.to_string())?;
    }
    let measurement = measure_strip_feeder_live_holdout(
        state,
        run,
        registration,
        camera_model,
        camera_profile,
        camera_path,
        visual,
        lease_id,
        &mut motion,
    )
    .await;
    let return_feed_mm_per_min = safe_level_xy_feed(
        &state.profile,
        Some(motion.state.logical_pose),
        visual.seed_pose,
        visual.feed_mm_per_min,
    );
    let return_result = execute_calibrated_motion(
        state,
        lease_id,
        &mut motion,
        visual.seed_pose,
        return_feed_mm_per_min,
    )
    .await;
    let lights_result = if camera_profile.lighting_enabled {
        state.machine.disable_actuator("lights".into()).await
    } else {
        Ok(())
    };
    if let Err(error) = return_result {
        return Err(format!("live pocket holdout return move failed: {error}"));
    }
    if let Err(error) = lights_result {
        return Err(format!("live pocket holdout light cleanup failed: {error}"));
    }
    measurement
}

#[allow(clippy::too_many_arguments)]
async fn measure_strip_feeder_live_holdout(
    state: &AppState,
    run: &StripFeederLiveHoldoutRun,
    registration: &StripFeederRegistration,
    camera_model: &PlanarCameraModel,
    camera_profile: &CameraProfile,
    camera_path: &str,
    visual: &VisualHomingProfile,
    lease_id: Uuid,
    motion: &mut CalibratedMotionSequence,
) -> Result<velocitypnp_domain::StripFeederLiveHoldoutReport, String> {
    let targets = strip_feeder_holdout_capture_targets(
        registration,
        run.predicted_pocket_machine_mm,
        state.profile.safe_z_mm,
    )
    .map_err(|error| error.message)?;
    state
        .machine
        .renew_lease(lease_id, 900)
        .await
        .map_err(|error| error.to_string())?;
    let mut frames = Vec::with_capacity(targets.len() * run.sample_count as usize);
    let mut camera_poses = Vec::with_capacity(frames.capacity());
    for target in targets {
        let measured_pose =
            jog_board_registration_target(state, lease_id, target, visual, motion).await?;
        let captured =
            capture_profiled_frames(state, camera_profile, camera_path, run.sample_count)
                .await
                .map_err(|error| error.message)?;
        camera_poses.extend(std::iter::repeat_n(measured_pose, captured.len()));
        frames.extend(captured);
    }
    let tape_pitch_mm = registration.tape_pitch_mm;
    let registration = registration.clone();
    let camera_model = camera_model.clone();
    let predicted = run.predicted_pocket_machine_mm;
    let retained_step = run.sample_count.max(1) as usize;
    let (mut analysis, retained_frames) = tokio::task::spawn_blocking(move || {
        let analysis = analyze_live_strip_feeder_holdout(
            &frames,
            &camera_poses,
            &camera_model,
            &registration,
            predicted,
            "live-pocket-holdout.png",
        )?;
        let retained_frames = frames
            .iter()
            .zip(&camera_poses)
            .step_by(retained_step)
            .enumerate()
            .map(|(index, (frame, pose))| {
                Ok((
                    format!("source-pocket-frame-{index:03}.png"),
                    *pose,
                    encode_gray_png(frame)?,
                ))
            })
            .collect::<anyhow::Result<Vec<_>>>()?;
        Ok::<_, anyhow::Error>((analysis, retained_frames))
    })
    .await
    .map_err(|error| error.to_string())?
    .map_err(|error| error.to_string())?;
    if run.requested_pocket_only {
        enforce_requested_holdout_pocket(
            &mut analysis.report,
            run.predicted_pocket_machine_mm,
            tape_pitch_mm,
        );
    }
    let encoded = encode_rgb_png(&analysis.preview).map_err(|error| error.to_string())?;
    state
        .store
        .put_strip_feeder_holdout_artifact(
            run.id,
            &analysis.report.artifact_name,
            "image/png",
            &encoded,
        )
        .map_err(|error| error.to_string())?;
    let mut report = analysis.report;
    for (name, pose, encoded) in retained_frames {
        state
            .store
            .put_strip_feeder_holdout_artifact(run.id, &name, "image/png", &encoded)
            .map_err(|error| error.to_string())?;
        report.source_frame_artifact_names.push(name);
        report.source_frame_camera_poses.push(pose);
    }
    Ok(report)
}

fn enforce_requested_holdout_pocket(
    report: &mut velocitypnp_domain::StripFeederLiveHoldoutReport,
    requested_pocket_machine_mm: [f64; 2],
    tape_pitch_mm: f64,
) {
    let selected_offset_mm = (report.predicted_pocket_machine_mm[0]
        - requested_pocket_machine_mm[0])
        .hypot(report.predicted_pocket_machine_mm[1] - requested_pocket_machine_mm[1]);
    if selected_holdout_matches_request(
        report.predicted_pocket_machine_mm,
        requested_pocket_machine_mm,
        tape_pitch_mm,
    ) {
        return;
    }
    report.passed = false;
    report
        .findings
        .retain(|finding| !finding.contains("passed the live holdout"));
    report.findings.push(format!(
        "the live holdout selected a pocket {selected_offset_mm:.3} mm from the explicitly requested pocket",
    ));
}

fn selected_holdout_matches_request(
    selected_pocket_machine_mm: [f64; 2],
    requested_pocket_machine_mm: [f64; 2],
    tape_pitch_mm: f64,
) -> bool {
    (selected_pocket_machine_mm[0] - requested_pocket_machine_mm[0])
        .hypot(selected_pocket_machine_mm[1] - requested_pocket_machine_mm[1])
        <= 0.45 * tape_pitch_mm
}

async fn get_strip_feeder_live_holdout(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<StripFeederLiveHoldoutRun>> {
    state
        .store
        .get_strip_feeder_live_holdout(id)
        .map_err(ApiError::internal)?
        .map(Json)
        .ok_or_else(|| ApiError::not_found("strip feeder live holdout not found"))
}

async fn get_strip_feeder_live_holdout_artifact(
    State(state): State<AppState>,
    Path((id, name)): Path<(Uuid, String)>,
) -> ApiResult<Response> {
    let (media_type, data) = state
        .store
        .get_strip_feeder_holdout_artifact(id, &name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("strip feeder live holdout artifact not found"))?;
    Response::builder()
        .status(StatusCode::OK)
        .header(header::CONTENT_TYPE, media_type)
        .header(header::CACHE_CONTROL, "no-store")
        .body(axum::body::Body::from(data))
        .map_err(ApiError::internal)
}

#[derive(Debug, Deserialize)]
struct StartStripFeederPickupQualificationRequest {
    lease_id: Uuid,
    nozzle_id: String,
    #[serde(default)]
    pocket_index: Option<u32>,
    #[serde(default)]
    fallback_drop_surface_machine_mm: Option<[f64; 2]>,
    #[serde(default)]
    rotation_capture_offsets_deg: Vec<f64>,
    #[serde(default = "default_pickup_cycle_count")]
    cycle_count: u32,
    confirmed_external_safety_checks: bool,
}

fn default_pickup_cycle_count() -> u32 {
    1
}

#[derive(Debug, Serialize)]
struct StartStripFeederPickupQualificationResponse {
    qualification: StripFeederPickupQualificationRun,
    operation: Operation,
}

struct PreparedStripFeederPickup {
    run: StripFeederPickupQualificationRun,
    registration: StripFeederRegistration,
    lease_id: Uuid,
    geometry: CalibratedNozzleGeometry,
    head_reference: CalibratedHeadReference,
    height_model: Option<NozzleHeightModel>,
    height_model_has_working_plane_transfer: bool,
    /// Additional, qualified transfer correction. Placement XY subtracts this
    /// value together with the nozzle height-model correction.
    placement_transfer_correction_mm: [f64; 2],
    calibration_pickup_retry_offsets_mm: Vec<[f64; 2]>,
    calibration_pickup_seating_depth_mm: f64,
    expected_part_size_mm: Option<[f64; 2]>,
    expected_part_size_source: &'static str,
    reference_contact: VacuumProbeReport,
    vacuum_characterization: VacuumSensorCharacterizationReport,
    top_camera_model: PlanarCameraModel,
    top_camera_profile: CameraProfile,
    top_camera_path: String,
    part_orientation: PartOrientation,
    source_rotation_deg: f64,
    rotation_capture_offsets_deg: Vec<f64>,
    artifact_target: TransferArtifactTarget,
    motion_planner: MotionPlanner,
    clear_xy_feed_mm_per_min: f64,
    carried_xy_feed_mm_per_min: f64,
    clear_z_feed_mm_per_min: f64,
    carried_z_feed_mm_per_min: f64,
    precision_z_approach_mm: f64,
}

struct SourceComponentPickControl {
    center_machine_mm: [f64; 2],
    artifact_names: Vec<String>,
    findings: Vec<String>,
    rejection: Option<SourceComponentPickRejection>,
    learned_control_authorized: bool,
}

struct SourceComponentPickRejection {
    message: String,
    observed_empty: bool,
}

fn source_empty_observation_is_confirmed(
    model_reported_empty: bool,
    deterministic_occupancy: StripPocketOccupancy,
) -> bool {
    model_reported_empty && deterministic_occupancy == StripPocketOccupancy::Empty
}

fn source_component_class_rejection(
    class: SourceComponentClass,
    confidence_gate_passed: bool,
    deterministic_occupancy: StripPocketOccupancy,
) -> Option<&'static str> {
    if confidence_gate_passed && class == SourceComponentClass::ComponentOnEdge {
        Some("the source-component model found a component on edge")
    } else if source_empty_observation_is_confirmed(
        confidence_gate_passed && class == SourceComponentClass::Empty,
        deterministic_occupancy,
    ) {
        Some("the source-component model and top-camera CV confirm an empty source pocket")
    } else {
        None
    }
}

fn source_component_pose_can_control(
    prediction: &SourceComponentModelPrediction,
    prior_inventory_occupancy: Option<StripPocketOccupancy>,
    deterministic_occupancy: StripPocketOccupancy,
) -> bool {
    if !prediction.confidence_gate_passed || !prediction.pose.valid {
        return false;
    }
    match prediction.class {
        SourceComponentClass::ComponentFlat => true,
        SourceComponentClass::Empty => {
            prior_inventory_occupancy == Some(StripPocketOccupancy::Occupied)
                && deterministic_occupancy == StripPocketOccupancy::Occupied
        }
        SourceComponentClass::ComponentOnEdge => false,
    }
}

fn learned_source_component_measurement(
    prediction: &SourceComponentModelPrediction,
    center_machine_mm: [f64; 2],
    nominal_pocket_machine_mm: [f64; 2],
    deterministic_center_machine_mm: [f64; 2],
    maximum_offset_mm: f64,
) -> Result<Option<([f64; 2], f64, f64)>, String> {
    if !prediction.confidence_gate_passed || !prediction.pose.valid {
        return Ok(None);
    }
    if !center_machine_mm.into_iter().all(f64::is_finite) {
        return Err("learned source-component center is invalid".into());
    }
    let nominal_offset_mm = (center_machine_mm[0] - nominal_pocket_machine_mm[0])
        .hypot(center_machine_mm[1] - nominal_pocket_machine_mm[1]);
    if nominal_offset_mm > maximum_offset_mm {
        return Err(format!(
            "learned source-component center correction {nominal_offset_mm:.3} mm exceeds the configured bound"
        ));
    }
    let cv_delta_mm = (center_machine_mm[0] - deterministic_center_machine_mm[0])
        .hypot(center_machine_mm[1] - deterministic_center_machine_mm[1]);
    Ok(Some((center_machine_mm, nominal_offset_mm, cv_delta_mm)))
}

async fn select_source_component_pick_center(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    frame: &GrayFrame,
    camera_pose: Pose,
    nominal_pocket_machine_mm: [f64; 2],
    deterministic_center_machine_mm: [f64; 2],
) -> Result<SourceComponentPickControl, String> {
    let Some(model) = state.source_component_model.clone() else {
        return Ok(SourceComponentPickControl {
            center_machine_mm: deterministic_center_machine_mm,
            artifact_names: Vec::new(),
            findings: vec![
                "the source-component model is unavailable; top-camera CV supplied the bounded pickup center"
                    .into(),
            ],
            rejection: None,
            learned_control_authorized: false,
        });
    };
    let pocket = prepared
        .registration
        .pockets
        .iter()
        .find(|pocket| pocket.pocket_index == prepared.run.pocket_index);
    let context = SourceComponentShadowContext {
        camera_pose,
        pocket_machine_mm: nominal_pocket_machine_mm,
        prior_inventory_occupancy: pocket
            .map_or(StripPocketOccupancy::Uncertain, |pocket| pocket.occupancy),
        prior_inventory_confidence: pocket.map_or(0.0, |pocket| pocket.occupancy_confidence),
    };
    let frame = frame.clone();
    let camera_model = prepared.top_camera_model.clone();
    let registration = prepared.registration.clone();
    let mut analysis = match tokio::task::spawn_blocking(move || {
        analyze_source_component_shadow(
            &model,
            &frame,
            &camera_model,
            &registration,
            context,
            "source-pocket-pick",
        )
    })
    .await
    {
        Ok(Ok(analysis)) => analysis,
        Ok(Err(error)) => {
            return Ok(SourceComponentPickControl {
                center_machine_mm: deterministic_center_machine_mm,
                artifact_names: Vec::new(),
                findings: vec![format!(
                    "source-component inference failed; top-camera CV supplied the bounded pickup center: {error}"
                )],
                rejection: None,
                learned_control_authorized: false,
            });
        }
        Err(error) => {
            return Ok(SourceComponentPickControl {
                center_machine_mm: deterministic_center_machine_mm,
                artifact_names: Vec::new(),
                findings: vec![format!(
                    "source-component inference task failed; top-camera CV supplied the bounded pickup center: {error}"
                )],
                rejection: None,
                learned_control_authorized: false,
            });
        }
    };
    let prediction = &analysis.report.prediction;
    let maximum_offset_mm = state
        .profile
        .strip_feeder_pickup
        .as_ref()
        .unwrap()
        .maximum_part_offset_mm;
    let model_reported_empty =
        prediction.confidence_gate_passed && prediction.class == SourceComponentClass::Empty;
    let confirmed_empty = source_empty_observation_is_confirmed(
        model_reported_empty,
        analysis.report.deterministic_occupancy,
    );
    let mut rejection = source_component_class_rejection(
        prediction.class,
        prediction.confidence_gate_passed,
        analysis.report.deterministic_occupancy,
    )
    .map(str::to_owned);
    let deterministic_center_result = source_component_deterministic_machine_center(
        &analysis.crop,
        analysis.report.deterministic_center_px,
        nominal_pocket_machine_mm,
        &prepared.registration,
        deterministic_center_machine_mm,
    );
    let deterministic_center_error = deterministic_center_result.as_ref().err().cloned();
    let deterministic_component_center_machine_mm =
        deterministic_center_result.unwrap_or(deterministic_center_machine_mm);
    let deterministic_nominal_offset_mm = (deterministic_component_center_machine_mm[0]
        - nominal_pocket_machine_mm[0])
        .hypot(deterministic_component_center_machine_mm[1] - nominal_pocket_machine_mm[1]);
    let learned_measurement = if source_component_pose_can_control(
        prediction,
        analysis.report.prior_inventory_occupancy,
        analysis.report.deterministic_occupancy,
    ) && rejection.is_none()
    {
        match source_component_crop_pixel_to_machine(
            &analysis.crop,
            prediction.pose.center_px,
            nominal_pocket_machine_mm,
            &prepared.registration,
        ) {
            Ok(center_machine_mm) => match learned_source_component_measurement(
                prediction,
                center_machine_mm,
                nominal_pocket_machine_mm,
                deterministic_component_center_machine_mm,
                maximum_offset_mm,
            ) {
                Ok(measurement) => measurement,
                Err(error) => {
                    rejection = Some(error);
                    None
                }
            },
            Err(error) => {
                rejection = Some(error.to_string());
                None
            }
        }
    } else {
        None
    };
    if learned_measurement.is_none() && rejection.is_none() {
        if let Some(error) = deterministic_center_error.as_ref() {
            rejection = Some(error.clone());
        } else if deterministic_nominal_offset_mm > maximum_offset_mm {
            rejection = Some(format!(
                "CV source-component center correction {deterministic_nominal_offset_mm:.3} mm exceeds the configured bound"
            ));
        }
    }

    analysis.report.algorithm_version = SOURCE_COMPONENT_PICK_CONTROL_ALGORITHM.into();
    analysis
        .report
        .findings
        .retain(|finding| !finding.contains("shadow evidence"));
    if model_reported_empty && !confirmed_empty {
        analysis.report.findings.push(
            "the learned empty result conflicts with occupied inventory and top-camera occupancy evidence; the bounded learned pose can still control pickup"
                .into(),
        );
    }
    let learned_control_authorized = learned_measurement.is_some();
    let (center_machine_mm, method_finding) = if let Some((
        learned_center_machine_mm,
        learned_nominal_offset_mm,
        learned_cv_delta_mm,
    )) = learned_measurement
    {
        analysis.report.control_authorized = true;
        analysis.report.findings.push(format!(
            "the learned flat-component center is authorized for this pickup; it is {learned_nominal_offset_mm:.3} mm from nominal and {learned_cv_delta_mm:.3} mm from CV"
        ));
        if deterministic_center_error.is_some()
            || deterministic_nominal_offset_mm > maximum_offset_mm
            || learned_cv_delta_mm > maximum_offset_mm
        {
            analysis.report.findings.push(
                "deterministic CV center evidence remains review-only; the bounded learned center controls pickup"
                    .into(),
            );
        }
        let method_finding = if model_reported_empty {
            "occupied inventory and top-camera occupancy evidence overrode the learned empty class; the bounded learned pose supplied the pickup center"
                .into()
        } else {
            format!(
                "the source-component model supplied the pickup center with {:.1}% class confidence",
                100.0 * prediction.class_confidence
            )
        };
        (learned_center_machine_mm, method_finding)
    } else if let Some(error) = rejection.as_deref() {
        analysis.report.control_authorized = false;
        analysis.report.review_required = true;
        analysis
            .report
            .findings
            .push(format!("pickup control rejected this prediction: {error}"));
        (
            deterministic_component_center_machine_mm,
            "the source-component control gate rejected motion".into(),
        )
    } else {
        analysis.report.findings.push(
            "the learned result did not pass the pickup-control gate; bounded top-camera CV supplied the pickup center"
                .into(),
        );
        (
            deterministic_component_center_machine_mm,
            "the source-component model was inconclusive; bounded component CV supplied the pickup center"
                .into(),
        )
    };
    analysis.report.report_artifact_name =
        "source-pocket-pick-source-component-control.json".into();
    analysis.report.preview_artifact_name =
        "source-pocket-pick-source-component-control.png".into();
    analysis.report.crop_artifact_name = "source-pocket-pick-source-component-crop.png".into();
    analysis.preview = render_source_component_shadow_preview(
        &analysis.crop,
        analysis.report.deterministic_outline_px,
        &analysis.report.prediction,
        analysis.report.review_required,
    );
    let report_data =
        serde_json::to_vec_pretty(&analysis.report).map_err(|error| error.to_string())?;
    persist_transfer_data_artifact(
        state,
        prepared,
        &analysis.report.report_artifact_name,
        "application/json",
        &report_data,
    )?;
    persist_transfer_gray_artifact(
        state,
        prepared,
        &analysis.report.crop_artifact_name,
        &analysis.crop,
    )?;
    persist_transfer_rgb_artifact(
        state,
        prepared,
        &analysis.report.preview_artifact_name,
        &analysis.preview,
    )?;
    Ok(SourceComponentPickControl {
        center_machine_mm,
        artifact_names: vec![
            analysis.report.report_artifact_name,
            analysis.report.crop_artifact_name,
            analysis.report.preview_artifact_name,
        ],
        findings: vec![method_finding],
        rejection: rejection.map(|message| SourceComponentPickRejection {
            message,
            observed_empty: confirmed_empty,
        }),
        learned_control_authorized,
    })
}

fn source_component_deterministic_machine_center(
    crop: &GrayFrame,
    deterministic_center_px: Option<[f64; 2]>,
    nominal_pocket_machine_mm: [f64; 2],
    registration: &StripFeederRegistration,
    fallback_center_machine_mm: [f64; 2],
) -> Result<[f64; 2], String> {
    deterministic_center_px.map_or(Ok(fallback_center_machine_mm), |center_px| {
        source_component_crop_pixel_to_machine(
            crop,
            center_px,
            nominal_pocket_machine_mm,
            registration,
        )
        .map_err(|error| error.to_string())
    })
}

struct SourcePoseReference {
    qualification_id: Uuid,
    frame: GrayFrame,
    camera_pose: Pose,
    pocket_machine_mm: [f64; 2],
}

fn load_source_pose_references(
    state: &AppState,
    registration: &StripFeederRegistration,
) -> Result<Vec<SourcePoseReference>, String> {
    let mut qualification_ids = Vec::new();
    if let Some(id) = registration.latest_pickup_qualification_id {
        qualification_ids.push(id);
    }
    for id in registration
        .latest_pickup_sequence_qualification_ids
        .iter()
        .rev()
        .copied()
    {
        if !qualification_ids.contains(&id) {
            qualification_ids.push(id);
        }
    }
    let mut references = Vec::new();
    for qualification_id in qualification_ids {
        let Some(run) = state
            .store
            .get_strip_feeder_pickup_qualification(qualification_id)
            .map_err(|error| error.to_string())?
        else {
            continue;
        };
        let Some(report) = run.report.as_ref() else {
            continue;
        };
        let Some(return_verification) = report.return_verification.as_ref() else {
            continue;
        };
        if run.registration_id != registration.id
            || run.calibration_id != registration.calibration_id
            || run.status != OperationStatus::Succeeded
            || !report.passed
            || !report.vacuum_acquired
            || !report.vacuum_held_after_transfer
            || !report
                .inspection
                .as_ref()
                .is_some_and(|inspection| inspection.passed)
            || !return_verification.passed
            || return_verification.before_occupancy != StripPocketOccupancy::Occupied
        {
            continue;
        }
        let Some(camera_pose) = return_verification.before_camera_pose else {
            continue;
        };
        let Some((media_type, data)) = state
            .store
            .get_strip_feeder_pickup_artifact(qualification_id, SOURCE_POCKET_BEFORE_ARTIFACT)
            .map_err(|error| error.to_string())?
        else {
            continue;
        };
        if media_type != "image/png" {
            continue;
        }
        let frame = decode_gray_png(&data).map_err(|error| error.to_string())?;
        references.push(SourcePoseReference {
            qualification_id,
            frame,
            camera_pose,
            pocket_machine_mm: report.pocket_machine_mm,
        });
    }
    if references.is_empty() {
        Err("feeder has no retained successful pickup-pose reference".into())
    } else {
        Ok(references)
    }
}

#[allow(clippy::too_many_arguments)]
fn inspect_source_pose_against_references(
    references: Vec<SourcePoseReference>,
    candidate: &GrayFrame,
    candidate_camera_pose: Pose,
    candidate_pocket_machine_mm: [f64; 2],
    camera_model: &PlanarCameraModel,
    registration: &StripFeederRegistration,
    allow_face_texture_change: bool,
    artifact_name: &str,
) -> Result<StripFeederSourcePoseArtifacts, String> {
    let mut best: Option<StripFeederSourcePoseArtifacts> = None;
    for reference in references {
        let inspection = inspect_strip_feeder_source_pose(
            &reference.frame,
            reference.camera_pose,
            reference.pocket_machine_mm,
            reference.qualification_id,
            candidate,
            candidate_camera_pose,
            candidate_pocket_machine_mm,
            camera_model,
            registration,
            allow_face_texture_change,
            artifact_name,
        )
        .map_err(|error| error.to_string())?;
        let rank = |inspection: &StripFeederSourcePoseArtifacts| {
            (
                inspection.report.passed,
                inspection.report.appearance_similarity.unwrap_or(-1.0),
            )
        };
        if best
            .as_ref()
            .is_none_or(|current| rank(&inspection) > rank(current))
        {
            best = Some(inspection);
        }
    }
    best.ok_or_else(|| "feeder has no usable successful pickup-pose reference".into())
}

#[derive(Clone, Copy)]
enum TransferArtifactTarget {
    PickupQualification(Uuid),
    PlacementExecution(Uuid),
}

fn registration_part_orientation(
    state: &AppState,
    registration: &StripFeederRegistration,
) -> ApiResult<(PartOrientation, f64)> {
    let orientation = if let Some(part_key) = registration.part_key.as_deref() {
        let part = state
            .store
            .list_parts()
            .map_err(ApiError::internal)?
            .into_iter()
            .find(|part| part.key == part_key)
            .ok_or_else(|| ApiError::bad_request("feeder part is missing from the part library"))?;
        part.resolved_orientation().ok_or_else(|| {
            ApiError::bad_request("feeder part has no orientation-aware vision policy")
        })?
    } else {
        PartOrientation::AxisSymmetric
    };
    orientation.validate().map_err(ApiError::bad_request)?;
    let source_rotation_deg = registration.part_rotation_deg.unwrap_or(0.0);
    if !source_rotation_deg.is_finite() {
        return Err(ApiError::bad_request("feeder part rotation is invalid"));
    }
    if orientation.is_directed() && registration.part_rotation_deg.is_none() {
        return Err(ApiError::bad_request(
            "directed part orientation requires a registered feeder part angle",
        ));
    }
    Ok((orientation, source_rotation_deg))
}

fn validate_held_part_rotation_capture_offsets(
    offsets_deg: &[f64],
    profile: &MachineProfile,
) -> Result<(), String> {
    if offsets_deg.len() > MAXIMUM_HELD_PART_ROTATION_CAPTURES {
        return Err(format!(
            "held-part rotation capture permits at most \
             {MAXIMUM_HELD_PART_ROTATION_CAPTURES} angles"
        ));
    }
    let maximum_deg = profile
        .bottom_vision
        .as_ref()
        .ok_or_else(|| "active profile does not define bottom vision".to_string())?
        .head_geometry
        .rotation_angle_offsets_deg
        .iter()
        .map(|offset| offset.abs())
        .fold(0.0_f64, f64::max);
    for (index, offset) in offsets_deg.iter().copied().enumerate() {
        if !offset.is_finite() || offset.abs() < 1e-6 || offset.abs() > maximum_deg + 1e-6 {
            return Err(format!(
                "rotation capture angle {index} must be finite, nonzero, and within \
                 +/-{maximum_deg:.1} degrees"
            ));
        }
        if offsets_deg[..index]
            .iter()
            .any(|prior| (prior - offset).abs() < 1e-6)
        {
            return Err(format!(
                "rotation capture angle {offset:.3} degrees is repeated"
            ));
        }
    }
    Ok(())
}

async fn start_strip_feeder_pickup_qualification(
    State(state): State<AppState>,
    Path(registration_id): Path<Uuid>,
    Json(body): Json<StartStripFeederPickupQualificationRequest>,
) -> ApiResult<(
    StatusCode,
    Json<StartStripFeederPickupQualificationResponse>,
)> {
    if !body.confirmed_external_safety_checks {
        return Err(ApiError::bad_request(
            "pickup qualification requires confirmation that the tape is fixed and uncovered, both nozzles are level, the travel envelope and fallback drop target are clear, and power isolation is reachable",
        ));
    }
    if body.nozzle_id.trim().is_empty() {
        return Err(ApiError::bad_request(
            "pickup qualification needs a nozzle ID",
        ));
    }
    if !(1..=5).contains(&body.cycle_count) {
        return Err(ApiError::bad_request(
            "pickup qualification cycle_count must be between 1 and 5",
        ));
    }
    validate_held_part_rotation_capture_offsets(&body.rotation_capture_offsets_deg, &state.profile)
        .map_err(ApiError::bad_request)?;
    if body
        .fallback_drop_surface_machine_mm
        .is_some_and(|point| point.into_iter().any(|value| !value.is_finite()))
    {
        return Err(ApiError::bad_request(
            "pickup fallback drop coordinates must be finite",
        ));
    }
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed || status.pose.is_none() {
        return Err(ApiError::bad_request(
            "pickup qualification requires a homed ready machine",
        ));
    }
    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(&state)?;
    ensure_no_active_board_registrations(&state)?;
    ensure_no_active_board_surface_measurements(&state)?;
    ensure_no_active_strip_feeder_holdouts(&state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(&state)?;
    let pickup_profile = state.profile.strip_feeder_pickup.as_ref().ok_or_else(|| {
        ApiError::bad_request("active profile does not define strip-feeder pickup")
    })?;
    pickup_profile.validate().map_err(ApiError::bad_request)?;
    state
        .profile
        .transit_motion
        .validate(state.profile.maximum_feed_mm_per_min)
        .map_err(ApiError::bad_request)?;
    let registration = state
        .store
        .get_strip_feeder_registration(registration_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("strip feeder registration not found"))?;
    if !state.profile.accepts_profile_id(&registration.profile_id) {
        return Err(ApiError::bad_request(
            "pickup registration uses a different machine profile",
        ));
    }
    let (part_orientation, source_rotation_deg) =
        registration_part_orientation(&state, &registration)?;
    if !status.simulated && status.calibration_revision != Some(registration.calibration_id) {
        return Err(ApiError::bad_request(format!(
            "pickup qualification requires fine XYZ homing with calibration {}",
            registration.calibration_id,
        )));
    }
    let preferred_pocket_index = body.pocket_index.or(registration.selected_pocket_index);
    let selected_pocket = registration
        .next_available_pocket(preferred_pocket_index)
        .ok_or_else(|| ApiError::bad_request("strip feeder has no available occupied pocket"))?;
    if body
        .pocket_index
        .is_some_and(|index| index != selected_pocket.pocket_index)
    {
        return Err(ApiError::bad_request(
            "requested pickup pocket is not available and occupied",
        ));
    }
    let latest_holdout_id = registration
        .latest_live_holdout_id
        .ok_or_else(|| ApiError::bad_request("pickup qualification needs a live holdout"))?;
    let latest_holdout = state
        .store
        .get_strip_feeder_live_holdout(latest_holdout_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::bad_request("latest live holdout is missing"))?;
    if latest_holdout.status != OperationStatus::Succeeded
        || latest_holdout.calibration_id != registration.calibration_id
    {
        return Err(ApiError::bad_request(
            "pickup qualification needs a current passed live holdout",
        ));
    }
    let holdout_report = latest_holdout
        .report
        .as_ref()
        .filter(|report| report.passed)
        .ok_or_else(|| {
            ApiError::bad_request("pickup qualification needs a current passed live holdout")
        })?;
    let selected_pocket_machine_mm = [
        selected_pocket.nominal_center_machine_mm[0] + holdout_report.correction_x_mm,
        selected_pocket.nominal_center_machine_mm[1] + holdout_report.correction_y_mm,
    ];
    if selected_pocket_machine_mm
        .into_iter()
        .any(|value| !value.is_finite())
    {
        return Err(ApiError::bad_request(
            "live holdout produced an invalid pocket correction",
        ));
    }
    let bottom = state
        .profile
        .bottom_vision
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define bottom vision"))?;
    let (_, top_camera_model) = load_workspace_camera_model(&state, registration.calibration_id)?;
    let top_camera_profile = stored_camera_profile(&state, CameraRole::TopCamera)?;
    let top_camera_path = camera_path_for_role(CameraRole::TopCamera)?;
    let nozzle = bottom
        .nozzles
        .iter()
        .find(|nozzle| nozzle.nozzle_id == body.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("unknown pickup nozzle"))?;
    let sensor_id = sensor_id_for_nozzle(&body.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("pickup nozzle has no vacuum sensor"))?;
    if !state
        .profile
        .sensors
        .iter()
        .any(|sensor| sensor.id == sensor_id && sensor.actuator_id.as_deref() == Some(sensor_id))
    {
        return Err(ApiError::bad_request(
            "active profile has no matching vacuum actuator and sensor",
        ));
    }
    let mut snapshot = state
        .store
        .get_calibration(registration.calibration_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("pickup calibration snapshot not found"))?;
    let artifacts_changed =
        crate::calibration_artifacts::reconcile_snapshot_artifacts(&state, &mut snapshot)
            .map_err(ApiError::bad_request)?;
    let runtime_artifact = CalibrationArtifactId::runtime_tip_transform(&body.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("unknown pickup nozzle"))?;
    let contact_artifact = CalibrationArtifactId::vacuum_contact(&body.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("unknown pickup nozzle"))?;
    let characterization_artifact = CalibrationArtifactId::vacuum_characterization(&body.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("unknown pickup nozzle"))?;
    for (artifact, message) in [
        (runtime_artifact, "current runtime tip transform"),
        (contact_artifact, "current reference contact"),
        (characterization_artifact, "current vacuum characterization"),
    ] {
        if !crate::calibration_artifacts::artifact_tree_is_current(&state, &snapshot, artifact) {
            return Err(ApiError::bad_request(format!(
                "pickup qualification requires a {message}"
            )));
        }
    }
    let reference_contact: VacuumProbeReport = serde_json::from_value(
        crate::calibration_artifacts::artifact_result_value(&snapshot, contact_artifact)
            .map_err(ApiError::bad_request)?,
    )
    .map_err(|_| ApiError::bad_request("stored vacuum contact is invalid"))?;
    let vacuum_characterization: VacuumSensorCharacterizationReport = serde_json::from_value(
        crate::calibration_artifacts::artifact_result_value(&snapshot, characterization_artifact)
            .map_err(ApiError::bad_request)?,
    )
    .map_err(|_| ApiError::bad_request("stored vacuum characterization is invalid"))?;
    if !reference_contact.passed
        || reference_contact.contact_nozzle_z_mm.is_none()
        || !vacuum_characterization.passed
        || !vacuum_characterization.reference_seal_validated
        || vacuum_characterization.sensor_id != sensor_id
    {
        return Err(ApiError::bad_request(
            "pickup qualification requires passed contact and vacuum references",
        ));
    }
    let geometry = calibrated_nozzle_geometry(&snapshot, &body.nozzle_id)?;
    if geometry.tip_id != nozzle.expected_tip_id {
        return Err(ApiError::bad_request(
            "pickup nozzle tip does not match the active profile",
        ));
    }
    let visual = state
        .profile
        .visual_homing
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let head_reference = calibrated_head_reference(&snapshot, visual.pixel_error_to_machine_mm)?;
    let height_model = calibrated_nozzle_height_model(&snapshot, &body.nozzle_id)?;
    let height_model_has_working_plane_transfer = height_model
        .as_ref()
        .is_some_and(|model| has_calibrated_working_plane_transfer(&snapshot, model));
    let contact_z_mm = reference_contact.contact_nozzle_z_mm.unwrap();
    let search_start_nozzle_z_mm = contact_z_mm + pickup_profile.search_start_above_reference_mm;
    let search_end_nozzle_z_mm = contact_z_mm + pickup_profile.search_end_above_reference_mm;
    let z_kinematics = state
        .profile
        .z_kinematics
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define Z kinematics"))?;
    for nozzle_z_mm in [search_start_nozzle_z_mm, search_end_nozzle_z_mm] {
        z_kinematics
            .controller_z(&body.nozzle_id, nozzle_z_mm)
            .ok_or_else(|| ApiError::bad_request("pickup Z search is outside machine bounds"))?;
    }
    let approximate_head_x_mm = selected_pocket_machine_mm[0] - geometry.head_offset_x_mm;
    let approximate_head_y_mm = selected_pocket_machine_mm[1] - geometry.head_offset_y_mm;
    for point in std::iter::once([approximate_head_x_mm, approximate_head_y_mm]).chain(
        body.fallback_drop_surface_machine_mm.map(|point| {
            [
                point[0] - geometry.head_offset_x_mm,
                point[1] - geometry.head_offset_y_mm,
            ]
        }),
    ) {
        if !state.profile.bounds.contains(Pose {
            x_mm: point[0],
            y_mm: point[1],
            z_mm: z_kinematics.level_controller_z_mm,
            rotation_deg: status.pose.unwrap().rotation_deg,
        }) {
            return Err(ApiError::bad_request(
                "pickup or fallback target is outside machine bounds",
            ));
        }
    }
    if artifacts_changed {
        state
            .store
            .put_calibration(&snapshot)
            .map_err(ApiError::internal)?;
    }
    let motion_calibration = load_job_motion_calibration(&state, registration.calibration_id)?;
    state
        .machine
        .renew_lease(body.lease_id, 900)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    let operation = Operation::pending("vision.strip_feeder_pickup_qualification");
    let now = Utc::now();
    let mut run = StripFeederPickupQualificationRun {
        id: Uuid::new_v4(),
        operation_id: operation.id,
        registration_id,
        profile_id: registration.profile_id.clone(),
        calibration_id: registration.calibration_id,
        status: OperationStatus::Pending,
        created_at: now,
        updated_at: now,
        nozzle_id: body.nozzle_id,
        pocket_index: selected_pocket.pocket_index,
        fallback_drop_surface_machine_mm: body.fallback_drop_surface_machine_mm,
        rotation_capture_offsets_deg: body.rotation_capture_offsets_deg.clone(),
        requested_cycle_count: body.cycle_count,
        benchmark_cycles: Vec::new(),
        report: None,
        message: None,
    };
    let mut registration = state
        .store
        .reserve_strip_feeder_pocket(registration.id, run.id, Some(selected_pocket.pocket_index))
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    run.pocket_index = registration.selected_pocket_index.unwrap_or_default();
    registration.selected_pocket_machine_mm = Some(selected_pocket_machine_mm);
    if let Err(error) = state
        .store
        .put_strip_feeder_registration(&registration)
        .and_then(|_| state.store.put_operation(&operation))
        .and_then(|_| state.store.put_strip_feeder_pickup_qualification(&run))
    {
        let _ = state.store.settle_strip_feeder_pocket(
            registration.id,
            run.id,
            StripFeederPocketOutcome::RetryableFailure,
            false,
        );
        return Err(ApiError::internal(error));
    }
    drop(admission_guard);
    let response = StartStripFeederPickupQualificationResponse {
        qualification: run.clone(),
        operation: operation.clone(),
    };
    let task_state = state.clone();
    let artifact_target = TransferArtifactTarget::PickupQualification(run.id);
    let expected_part_size_mm = registration.surveyed_part_size_mm;
    let prepared = PreparedStripFeederPickup {
        run,
        registration,
        lease_id: body.lease_id,
        geometry,
        head_reference,
        height_model,
        height_model_has_working_plane_transfer,
        placement_transfer_correction_mm: [0.0, 0.0],
        calibration_pickup_retry_offsets_mm: Vec::new(),
        calibration_pickup_seating_depth_mm: 0.0,
        expected_part_size_mm,
        expected_part_size_source: "feeder survey",
        reference_contact,
        vacuum_characterization,
        top_camera_model,
        top_camera_profile,
        top_camera_path,
        part_orientation,
        source_rotation_deg,
        rotation_capture_offsets_deg: body.rotation_capture_offsets_deg,
        artifact_target,
        motion_planner: MotionPlanner::new(state.profile.bounds, Some(motion_calibration)),
        clear_xy_feed_mm_per_min: state.profile.transit_motion.clear_xy_feed_mm_per_min,
        carried_xy_feed_mm_per_min: state.profile.transit_motion.carried_xy_feed_mm_per_min,
        clear_z_feed_mm_per_min: state.profile.transit_motion.clear_z_feed_mm_per_min,
        carried_z_feed_mm_per_min: state.profile.transit_motion.carried_z_feed_mm_per_min,
        precision_z_approach_mm: state.profile.transit_motion.precision_z_approach_mm,
    };
    spawn_prepared_operation(
        state,
        operation,
        execute_strip_feeder_pickup_task(task_state, prepared),
    );
    Ok((StatusCode::ACCEPTED, Json(response)))
}

async fn execute_strip_feeder_pickup_task(
    state: AppState,
    mut prepared: PreparedStripFeederPickup,
) -> Result<Option<String>, String> {
    let task_started = Instant::now();
    let _motion_guard = state.workspace_scan_motion_lock.lock().await;
    prepared.run.status = OperationStatus::Running;
    prepared.run.updated_at = Utc::now();
    state
        .store
        .put_strip_feeder_pickup_qualification(&prepared.run)
        .map_err(|error| error.to_string())?;
    let simulated = state.machine.status().simulated;
    let (mut result, benchmark_cycles, camera_timing, physical_execution_ms) = if simulated {
        let (result, cycles) = execute_simulated_pickup_benchmark(&state, &prepared).await;
        (result, cycles, json!({}), None)
    } else {
        let physical_started = Instant::now();
        let ((result, cycles), camera_timing) = with_profiled_camera_reuse(
            &state,
            execute_physical_pickup_benchmark(&state, &prepared),
        )
        .await;
        (
            result,
            cycles,
            camera_timing,
            Some(elapsed_ms(physical_started)),
        )
    };
    prepared.run.benchmark_cycles = benchmark_cycles;
    if prepared.run.requested_cycle_count > 1 {
        if let Ok(report) = &mut result {
            report.findings.push(format!(
                "the benchmark completed {} of {} requested cycles; retained artifacts are from the final cycle",
                prepared.run.benchmark_cycles.len(),
                prepared.run.requested_cycle_count,
            ));
        }
    }
    let outcome = match result {
        Ok(report) => {
            let passed = report.passed;
            let message = if passed {
                if prepared.run.requested_cycle_count > 1 {
                    format!(
                        "Pickup benchmark passed {} cycles at nozzle Z{:.3}; every recorded cycle passed",
                        prepared.run.benchmark_cycles.len(),
                        report.pickup_nozzle_z_mm.unwrap_or_default(),
                    )
                } else {
                    format!(
                        "Pickup qualification passed at nozzle Z{:.3}; bottom vision and verified return passed",
                        report.pickup_nozzle_z_mm.unwrap_or_default(),
                    )
                }
            } else {
                format!(
                    "Pickup qualification stopped after {} cycles: {}",
                    prepared.run.benchmark_cycles.len(),
                    report.findings.join("; ")
                )
            };
            prepared.run.status = if passed {
                OperationStatus::Succeeded
            } else {
                OperationStatus::Failed
            };
            prepared.run.report = Some(report.clone());
            prepared.run.message = Some(message.clone());
            prepared.run.updated_at = Utc::now();
            state
                .store
                .put_strip_feeder_pickup_qualification(&prepared.run)
                .map_err(|error| error.to_string())?;
            let registration = settle_registration_after_pickup(
                &state,
                prepared.run.registration_id,
                prepared.run.id,
                &report,
            )?;
            update_registration_after_pickup(&state, registration, prepared.run.id, &report)?;
            if passed {
                Ok(Some(message))
            } else {
                Err(message)
            }
        }
        Err(error) => {
            if !state.machine.status().simulated {
                if let Err(cleanup_error) = state
                    .machine
                    .disable_actuator(prepared.vacuum_characterization.sensor_id.clone())
                    .await
                {
                    tracing::error!(%cleanup_error, qualification_id = %prepared.run.id, "failed to disable vacuum after pickup error");
                }
                if let Err(cleanup_error) =
                    lift_and_restore_after_pickup(&state, prepared.lease_id).await
                {
                    tracing::error!(%cleanup_error, qualification_id = %prepared.run.id, "failed to restore level visual home after pickup error");
                }
            }
            prepared.run.status = OperationStatus::Failed;
            prepared.run.message = Some(error.clone());
            prepared.run.updated_at = Utc::now();
            if let Err(store_error) = state
                .store
                .put_strip_feeder_pickup_qualification(&prepared.run)
            {
                tracing::error!(%store_error, qualification_id = %prepared.run.id, "failed to persist pickup failure");
            }
            if let Err(store_error) = state.store.settle_strip_feeder_pocket(
                prepared.run.registration_id,
                prepared.run.id,
                StripFeederPocketOutcome::Interrupted,
                false,
            ) {
                tracing::error!(%store_error, qualification_id = %prepared.run.id, "failed to quarantine interrupted feeder pocket");
            }
            if let Err(store_error) = invalidate_registration_after_pickup_error(
                &state,
                prepared.run.registration_id,
                prepared.run.id,
            ) {
                tracing::error!(%store_error, qualification_id = %prepared.run.id, "failed to invalidate interrupted pickup evidence");
            }
            Err(error)
        }
    };
    let timing_payload = json!({
        "algorithm_version": STRIP_FEEDER_PICKUP_TIMING_ALGORITHM,
        "operation_id": prepared.run.operation_id,
        "qualification_id": prepared.run.id,
        "simulated": simulated,
        "succeeded": outcome.is_ok(),
        "requested_cycle_count": prepared.run.requested_cycle_count,
        "completed_cycle_count": prepared.run.benchmark_cycles.len(),
        "clear_xy_feed_mm_per_min": prepared.clear_xy_feed_mm_per_min,
        "carried_xy_feed_mm_per_min": prepared.carried_xy_feed_mm_per_min,
        "clear_z_feed_mm_per_min": prepared.clear_z_feed_mm_per_min,
        "carried_z_feed_mm_per_min": prepared.carried_z_feed_mm_per_min,
        "precision_z_approach_mm": prepared.precision_z_approach_mm,
        "total_elapsed_ms": elapsed_ms(task_started),
        "physical_execution_ms": physical_execution_ms,
        "cameras": camera_timing,
    });
    if let Err(error) = state
        .machine
        .record_operation_event(
            "operation.strip_feeder_pickup_timing".into(),
            timing_payload,
        )
        .await
    {
        tracing::warn!(
            %error,
            qualification_id = %prepared.run.id,
            "failed to record pickup timing",
        );
    }
    outcome
}

async fn execute_simulated_pickup_benchmark(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
) -> (
    Result<StripFeederPickupQualificationReport, String>,
    Vec<StripFeederPickupBenchmarkCycle>,
) {
    let mut cycles = Vec::new();
    let mut final_result = None;
    for cycle_index in 0..prepared.run.requested_cycle_count {
        let started = Instant::now();
        let result = execute_simulated_strip_feeder_pickup(state, prepared).await;
        cycles.push(summarize_pickup_benchmark_cycle(
            cycle_index + 1,
            elapsed_ms(started),
            json!({}),
            &result,
        ));
        if let Err(error) = persist_pickup_benchmark_progress(state, prepared, &cycles) {
            return (Err(error), cycles);
        }
        let stop = !matches!(&result, Ok(report) if report.passed);
        final_result = Some(result);
        if stop {
            break;
        }
    }
    (
        final_result.unwrap_or_else(|| Err("pickup benchmark ran no cycles".into())),
        cycles,
    )
}

async fn execute_physical_pickup_benchmark(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
) -> (
    Result<StripFeederPickupQualificationReport, String>,
    Vec<StripFeederPickupBenchmarkCycle>,
) {
    let mut cycles = Vec::new();
    let mut final_result = None;
    for cycle_index in 0..prepared.run.requested_cycle_count {
        let started = Instant::now();
        let (result, camera_timing) = with_profiled_camera_reuse(
            state,
            execute_physical_strip_feeder_pickup(state, prepared),
        )
        .await;
        cycles.push(summarize_pickup_benchmark_cycle(
            cycle_index + 1,
            elapsed_ms(started),
            camera_timing,
            &result,
        ));
        if let Err(error) = persist_pickup_benchmark_progress(state, prepared, &cycles) {
            return (Err(error), cycles);
        }
        let stop = !matches!(&result, Ok(report) if report.passed);
        final_result = Some(result);
        if stop {
            break;
        }
    }
    (
        final_result.unwrap_or_else(|| Err("pickup benchmark ran no cycles".into())),
        cycles,
    )
}

fn persist_pickup_benchmark_progress(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    cycles: &[StripFeederPickupBenchmarkCycle],
) -> Result<(), String> {
    let mut run = prepared.run.clone();
    run.status = OperationStatus::Running;
    run.benchmark_cycles = cycles.to_vec();
    run.message = Some(format!(
        "completed {} of {} pickup benchmark cycles",
        cycles.len(),
        run.requested_cycle_count,
    ));
    run.updated_at = Utc::now();
    state
        .store
        .put_strip_feeder_pickup_qualification(&run)
        .map_err(|error| error.to_string())
}

fn summarize_pickup_benchmark_cycle(
    cycle_index: u32,
    elapsed_ms: f64,
    camera_timing: Value,
    result: &Result<StripFeederPickupQualificationReport, String>,
) -> StripFeederPickupBenchmarkCycle {
    match result {
        Ok(report) => StripFeederPickupBenchmarkCycle {
            cycle_index,
            elapsed_ms,
            passed: report.passed,
            camera_timing,
            pickup_nozzle_z_mm: report.pickup_nozzle_z_mm,
            held_median_raw_value: report.held_median_raw_value,
            bottom_centering_residual_mm: report
                .alignment
                .as_ref()
                .and_then(|alignment| alignment.final_centering_residual_mm),
            return_center_shift_mm: report
                .return_verification
                .as_ref()
                .and_then(|verification| verification.return_center_shift_mm),
            message: if report.passed {
                "vacuum, bottom vision, release, and pocket return passed".into()
            } else {
                report.findings.join("; ")
            },
        },
        Err(error) => StripFeederPickupBenchmarkCycle {
            cycle_index,
            elapsed_ms,
            passed: false,
            camera_timing,
            pickup_nozzle_z_mm: None,
            held_median_raw_value: None,
            bottom_centering_residual_mm: None,
            return_center_shift_mm: None,
            message: error.clone(),
        },
    }
}

fn settle_registration_after_pickup(
    state: &AppState,
    registration_id: Uuid,
    qualification_id: Uuid,
    report: &StripFeederPickupQualificationReport,
) -> Result<StripFeederRegistration, String> {
    let pickup_evidence_passed = report.vacuum_acquired
        && report.vacuum_held_after_transfer
        && report
            .inspection
            .as_ref()
            .is_some_and(|inspection| inspection.passed);
    let outcome = match report.disposition {
        StripFeederPickupDisposition::ReturnedToPocket
            if report.released
                && report
                    .return_verification
                    .as_ref()
                    .is_some_and(|verification| verification.passed)
                && pickup_evidence_passed =>
        {
            StripFeederPocketOutcome::Returned
        }
        StripFeederPickupDisposition::ReturnedToPocket
            if report.released
                && report
                    .return_verification
                    .as_ref()
                    .is_some_and(|verification| verification.passed) =>
        {
            StripFeederPocketOutcome::RetryableFailure
        }
        StripFeederPickupDisposition::DroppedAtFallback if pickup_evidence_passed => {
            StripFeederPocketOutcome::Consumed
        }
        StripFeederPickupDisposition::NotReleased if !report.vacuum_acquired => {
            StripFeederPocketOutcome::RetryableFailure
        }
        _ => StripFeederPocketOutcome::ReleaseUncertain,
    };
    state
        .store
        .settle_strip_feeder_pocket(
            registration_id,
            qualification_id,
            outcome,
            pickup_evidence_passed,
        )
        .map_err(|error| error.to_string())
}

fn simulated_held_part_frame(
    bare: &GrayFrame,
    rotation_offset_deg: f64,
    orientation: PartOrientation,
) -> GrayFrame {
    let mut held = bare.clone();
    let center = [f64::from(bare.width) * 0.5, f64::from(bare.height) * 0.5];
    let radians = rotation_offset_deg.to_radians();
    let cosine = radians.cos();
    let sine = radians.sin();
    for y in 0..bare.height {
        for x in 0..bare.width {
            let dx = f64::from(x) + 0.5 - center[0];
            let dy = f64::from(y) + 0.5 - center[1];
            let local_x = cosine * dx + sine * dy;
            let local_y = -sine * dx + cosine * dy;
            if local_x.abs() <= 30.0 && local_y.abs() <= 15.0 {
                let luma = match orientation {
                    PartOrientation::BrighterEnd { .. } if local_x >= 10.0 => 240,
                    PartOrientation::DarkerEnd { .. } if local_x >= 10.0 => 105,
                    _ => 190,
                };
                held.pixels[(y * bare.width + x) as usize] = luma;
            }
        }
    }
    held
}

async fn execute_simulated_strip_feeder_pickup(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
) -> Result<StripFeederPickupQualificationReport, String> {
    let pickup = state.profile.strip_feeder_pickup.as_ref().unwrap();
    let contact_z_mm = prepared
        .reference_contact
        .contact_nozzle_z_mm
        .ok_or_else(|| "simulated pickup has no reference contact".to_string())?;
    let pickup_z_mm = contact_z_mm + 1.0;
    let controller_z_mm = state
        .profile
        .z_kinematics
        .as_ref()
        .unwrap()
        .controller_z(&prepared.run.nozzle_id, pickup_z_mm)
        .ok_or_else(|| "simulated pickup Z is outside bounds".to_string())?;
    let width = 320_u32;
    let height = 240_u32;
    let bare = GrayFrame {
        width,
        height,
        pixels: vec![80; (width * height) as usize],
    };
    let held = simulated_held_part_frame(&bare, 0.0, prepared.part_orientation);
    let inspection = inspect_held_part_difference_with_orientation(
        &bare,
        &held,
        [160.0, 120.0],
        [[0.02, 0.0], [0.0, 0.02]],
        pickup.maximum_part_offset_mm,
        pickup.minimum_part_size_mm,
        pickup.maximum_part_size_mm,
        prepared.part_orientation,
        HELD_PART_INSPECTION_ARTIFACT,
    )
    .map_err(|error| error.to_string())?;
    persist_transfer_gray_artifact(state, prepared, BARE_NOZZLE_ARTIFACT, &bare)?;
    persist_pickup_gray_artifact(state, prepared.run.id, HELD_PART_ARTIFACT, &held)?;
    persist_pickup_rgb_artifact(
        state,
        prepared.run.id,
        HELD_PART_INSPECTION_ARTIFACT,
        &inspection.preview,
    )?;
    persist_pickup_gray_artifact(state, prepared.run.id, SOURCE_POCKET_BEFORE_ARTIFACT, &held)?;
    persist_pickup_gray_artifact(state, prepared.run.id, SOURCE_POCKET_AFTER_ARTIFACT, &held)?;
    persist_pickup_rgb_artifact(
        state,
        prepared.run.id,
        POCKET_RETURN_INSPECTION_ARTIFACT,
        &inspection.preview,
    )?;
    let open = prepared
        .vacuum_characterization
        .pump_on_open
        .raw_values
        .clone();
    let held_values = prepared
        .vacuum_characterization
        .sealed_reference
        .raw_values
        .clone();
    let held_median = median_raw(&held_values);
    let sample = VacuumProbeSample {
        nozzle_z_mm: pickup_z_mm,
        controller_z_mm,
        raw_values: held_values.clone(),
        median_raw_value: held_median.unwrap_or_default(),
        signal_delta_counts: held_median
            .zip(median_raw(&open))
            .map_or(0.0, |(held, open)| (held - open).abs()),
    };
    let vacuum_held = held_median
        .is_some_and(|value| vacuum_value_is_acquired(&prepared.vacuum_characterization, value));
    let mut rotation_captures = Vec::new();
    let mut rotation_artifact_names = Vec::new();
    for (index, offset_deg) in prepared
        .rotation_capture_offsets_deg
        .iter()
        .copied()
        .enumerate()
    {
        let bare_artifact_name = format!("rotation-capture-{index:03}-bare-nozzle.png");
        let held_artifact_name = format!("rotation-capture-{index:03}-held-part.png");
        let inspection_artifact_name = format!("rotation-capture-{index:03}-inspection.png");
        let rotated = simulated_held_part_frame(&bare, offset_deg, prepared.part_orientation);
        let rotated_inspection = inspect_held_part_difference_with_orientation(
            &bare,
            &rotated,
            [160.0, 120.0],
            [[0.02, 0.0], [0.0, 0.02]],
            pickup.maximum_part_offset_mm,
            pickup.minimum_part_size_mm,
            pickup.maximum_part_size_mm,
            prepared.part_orientation,
            &inspection_artifact_name,
        )
        .map_err(|error| error.to_string())?;
        persist_pickup_gray_artifact(state, prepared.run.id, &bare_artifact_name, &bare)?;
        persist_pickup_gray_artifact(state, prepared.run.id, &held_artifact_name, &rotated)?;
        persist_pickup_rgb_artifact(
            state,
            prepared.run.id,
            &inspection_artifact_name,
            &rotated_inspection.preview,
        )?;
        rotation_artifact_names.extend([
            bare_artifact_name.clone(),
            held_artifact_name.clone(),
            inspection_artifact_name.clone(),
        ]);
        rotation_captures.push(HeldPartRotationCapture {
            capture_index: index as u32,
            requested_rotation_offset_deg: offset_deg,
            bare_rotation_offset_deg: offset_deg,
            held_rotation_offset_deg: offset_deg,
            bare_artifact_name,
            held_artifact_name,
            inspection_artifact_name,
            vacuum_raw_values: held_values.clone(),
            vacuum_median_raw_value: held_median,
            vacuum_held,
            inspection: rotated_inspection.report,
            shadow: None,
        });
    }
    let released = true;
    let inspection_report = inspection.report;
    let resolved_rotation_deg = resolved_held_part_rotation_deg(
        &inspection_report,
        prepared.part_orientation,
        prepared.source_rotation_deg,
    );
    let rotation_residual_deg = resolved_rotation_deg.map(|measured| {
        held_part_rotation_error_deg(
            measured,
            prepared.source_rotation_deg,
            prepared.part_orientation,
        )
    });
    let alignment = HeldPartAlignmentReport {
        algorithm_version: "held_part_alignment.simulated".into(),
        orientation: prepared.part_orientation,
        source_rotation_deg: prepared.source_rotation_deg,
        target_rotation_deg: prepared.source_rotation_deg,
        commanded_x_mm: 0.0,
        commanded_y_mm: 0.0,
        commanded_rotation_deg: 0.0,
        final_centering_residual_mm: inspection_report.centering_correction_mm,
        final_rotation_residual_deg: rotation_residual_deg,
        final_resolved_rotation_deg: resolved_rotation_deg,
        passed: inspection_report.passed
            && rotation_residual_deg.is_some_and(|error| error.abs() <= 1.0),
        observations: vec![HeldPartAlignmentObservation {
            iteration: 0,
            head_machine_mm: [0.0, 0.0],
            nozzle_rotation_offset_deg: 0.0,
            inspection: inspection_report.clone(),
        }],
        artifact_names: vec![HELD_PART_INSPECTION_ARTIFACT.into()],
        findings: vec!["simulator retained held-part alignment evidence".into()],
    };
    let post_release_inspection = inspect_held_part_difference(
        &bare,
        &bare,
        [160.0, 120.0],
        [[0.02, 0.0], [0.0, 0.02]],
        pickup.maximum_part_offset_mm,
        pickup.minimum_part_size_mm,
        pickup.maximum_part_size_mm,
        POST_RELEASE_NOZZLE_INSPECTION_ARTIFACT,
    )
    .map_err(|error| error.to_string())?;
    persist_pickup_gray_artifact(state, prepared.run.id, POST_RELEASE_NOZZLE_ARTIFACT, &bare)?;
    persist_pickup_rgb_artifact(
        state,
        prepared.run.id,
        POST_RELEASE_NOZZLE_INSPECTION_ARTIFACT,
        &post_release_inspection.preview,
    )?;
    let nozzle_clear =
        !post_release_matches_held_part(&inspection_report, &post_release_inspection.report);
    let passed = vacuum_held && alignment.passed && released && nozzle_clear;
    Ok(StripFeederPickupQualificationReport {
        algorithm_version: STRIP_FEEDER_PICKUP_ALGORITHM.into(),
        clear_xy_feed_mm_per_min: prepared.clear_xy_feed_mm_per_min,
        carried_xy_feed_mm_per_min: prepared.carried_xy_feed_mm_per_min,
        clear_z_feed_mm_per_min: prepared.clear_z_feed_mm_per_min,
        carried_z_feed_mm_per_min: prepared.carried_z_feed_mm_per_min,
        precision_z_approach_mm: prepared.precision_z_approach_mm,
        nozzle_id: prepared.run.nozzle_id.clone(),
        tip_id: prepared.geometry.tip_id.clone(),
        sensor_id: prepared.vacuum_characterization.sensor_id.clone(),
        pocket_machine_mm: prepared.registration.selected_pocket_machine_mm.unwrap(),
        pickup_nozzle_z_mm: Some(pickup_z_mm),
        pickup_controller_z_mm: Some(controller_z_mm),
        open_nozzle_raw_values: open,
        pickup_samples: vec![sample],
        held_raw_values: held_values,
        held_median_raw_value: held_median,
        vacuum_acquired: vacuum_held,
        vacuum_held_after_transfer: vacuum_held,
        inspection: Some(inspection_report),
        alignment: Some(alignment),
        rotation_captures,
        disposition: StripFeederPickupDisposition::ReturnedToPocket,
        release_surface_machine_mm: prepared.registration.selected_pocket_machine_mm,
        release_raw_values: prepared.vacuum_characterization.pump_off.raw_values.clone(),
        released,
        nozzle_release_verification: Some(NozzleReleaseVerificationReport {
            algorithm_version: NOZZLE_RELEASE_VERIFICATION_ALGORITHM.into(),
            attempt_count: 1,
            retry_performed: false,
            nozzle_clear,
            passed: nozzle_clear,
            observations: vec![post_release_inspection.report],
            artifact_names: vec![
                POST_RELEASE_NOZZLE_ARTIFACT.into(),
                POST_RELEASE_NOZZLE_INSPECTION_ARTIFACT.into(),
            ],
            findings: vec!["simulator confirmed that the nozzle is clear after release".into()],
        }),
        return_verification: Some(velocitypnp_domain::StripFeederPocketReturnReport {
            algorithm_version: "strip_feeder_pocket_return.simulated".into(),
            nominal_center_machine_mm: prepared.registration.selected_pocket_machine_mm,
            before_camera_pose: None,
            before_occupancy: StripPocketOccupancy::Occupied,
            before_confidence: 1.0,
            before_measured_center_machine_mm: prepared.registration.selected_pocket_machine_mm,
            before_center_offset_mm: Some(0.0),
            after_camera_pose: None,
            after_occupancy: StripPocketOccupancy::Occupied,
            after_confidence: 1.0,
            after_measured_center_machine_mm: prepared.registration.selected_pocket_machine_mm,
            after_center_offset_mm: Some(0.0),
            return_center_shift_mm: Some(0.0),
            appearance_similarity: Some(1.0),
            passed: true,
            artifact_name: POCKET_RETURN_INSPECTION_ARTIFACT.into(),
            findings: vec!["simulator retained the source-pocket return state".into()],
        }),
        passed,
        artifact_names: [
            vec![
                BARE_NOZZLE_ARTIFACT.into(),
                HELD_PART_ARTIFACT.into(),
                HELD_PART_INSPECTION_ARTIFACT.into(),
                POST_RELEASE_NOZZLE_ARTIFACT.into(),
                POST_RELEASE_NOZZLE_INSPECTION_ARTIFACT.into(),
                SOURCE_POCKET_BEFORE_ARTIFACT.into(),
                SOURCE_POCKET_AFTER_ARTIFACT.into(),
                POCKET_RETURN_INSPECTION_ARTIFACT.into(),
            ],
            rotation_artifact_names,
        ]
        .concat(),
        findings: vec![
            "simulator exercised pickup persistence, inspection, and release policy".into(),
        ],
    })
}

struct BareNozzleRotationCapture {
    capture_index: u32,
    requested_offset_deg: f64,
    actual_offset_deg: f64,
    artifact_name: String,
    frame: GrayFrame,
}

fn signed_rotation_offset_deg(actual_deg: f64, reference_deg: f64) -> f64 {
    (actual_deg - reference_deg + 180.0).rem_euclid(360.0) - 180.0
}

async fn capture_bare_nozzle_rotation_sweep(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    camera_profile: &CameraProfile,
    camera_path: &str,
    sample_count: u32,
) -> Result<Vec<BareNozzleRotationCapture>, String> {
    if prepared.rotation_capture_offsets_deg.is_empty() {
        return Ok(Vec::new());
    }
    let reference_deg = state
        .machine
        .calibration_rotation_reference(prepared.lease_id, prepared.run.nozzle_id.clone())
        .await
        .map_err(|error| error.to_string())?;
    let result = async {
        let mut captures = Vec::with_capacity(prepared.rotation_capture_offsets_deg.len());
        for (index, requested_offset_deg) in prepared
            .rotation_capture_offsets_deg
            .iter()
            .copied()
            .enumerate()
        {
            let actual_deg = state
                .machine
                .calibration_rotate_nozzle(
                    prepared.lease_id,
                    prepared.run.nozzle_id.clone(),
                    requested_offset_deg,
                )
                .await
                .map_err(|error| error.to_string())?;
            let frame = capture_bottom_mean_with_lights(
                state,
                prepared.lease_id,
                camera_profile,
                camera_path,
                sample_count,
            )
            .await?;
            let artifact_name = format!("rotation-capture-{index:03}-bare-nozzle.png");
            persist_transfer_gray_artifact(state, prepared, &artifact_name, &frame)?;
            captures.push(BareNozzleRotationCapture {
                capture_index: index as u32,
                requested_offset_deg,
                actual_offset_deg: signed_rotation_offset_deg(actual_deg, reference_deg),
                artifact_name,
                frame,
            });
        }
        Ok::<_, String>(captures)
    }
    .await;
    let restore = state
        .machine
        .calibration_rotate_nozzle(prepared.lease_id, prepared.run.nozzle_id.clone(), 0.0)
        .await
        .map(|_| ())
        .map_err(|error| error.to_string());
    match (result, restore) {
        (Ok(captures), Ok(())) => Ok(captures),
        (Err(error), Ok(())) => Err(error),
        (Ok(_), Err(error)) => Err(format!(
            "failed to restore rotation after bare-nozzle capture: {error}"
        )),
        (Err(error), Err(restore_error)) => Err(format!(
            "{error}; bare-nozzle rotation restore also failed: {restore_error}"
        )),
    }
}

#[allow(clippy::too_many_arguments)]
async fn capture_held_part_rotation_sweep(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    bare_captures: &[BareNozzleRotationCapture],
    camera_profile: &CameraProfile,
    camera_path: &str,
    sensor_id: &str,
    expected_size_mm: Option<[f64; 2]>,
) -> Result<Vec<HeldPartRotationCapture>, String> {
    if bare_captures.is_empty() {
        return Ok(Vec::new());
    }
    let pickup = state.profile.strip_feeder_pickup.as_ref().unwrap();
    let bottom = state.profile.bottom_vision.as_ref().unwrap();
    let reference_deg = state
        .machine
        .calibration_rotation_reference(prepared.lease_id, prepared.run.nozzle_id.clone())
        .await
        .map_err(|error| error.to_string())?;
    let result = async {
        let mut captures = Vec::with_capacity(bare_captures.len());
        for bare in bare_captures {
            let actual_deg = state
                .machine
                .calibration_rotate_nozzle(
                    prepared.lease_id,
                    prepared.run.nozzle_id.clone(),
                    bare.requested_offset_deg,
                )
                .await
                .map_err(|error| error.to_string())?;
            let vacuum_raw_values = collect_sensor_values(
                state,
                prepared.lease_id,
                sensor_id,
                pickup.held_sample_count,
            )
            .await?;
            let vacuum_median_raw_value = median_raw(&vacuum_raw_values);
            let vacuum_held = vacuum_median_raw_value.is_some_and(|value| {
                vacuum_value_is_acquired(&prepared.vacuum_characterization, value)
            });
            if !vacuum_held {
                return Err(format!(
                    "vacuum hold was lost at rotation capture offset {:.1} degrees",
                    bare.requested_offset_deg
                ));
            }
            let held = capture_bottom_mean_with_lights(
                state,
                prepared.lease_id,
                camera_profile,
                camera_path,
                pickup.inspection_sample_count,
            )
            .await?;
            let held_artifact_name =
                format!("rotation-capture-{:03}-held-part.png", bare.capture_index);
            let inspection_artifact_name =
                format!("rotation-capture-{:03}-inspection.png", bare.capture_index);
            persist_transfer_gray_artifact(state, prepared, &held_artifact_name, &held)?;
            let mut inspection = inspect_held_part_difference_with_orientation(
                &bare.frame,
                &held,
                [bottom.frame_center_x_px, bottom.frame_center_y_px],
                prepared.head_reference.bottom_camera_mapping,
                pickup.maximum_part_offset_mm,
                pickup.minimum_part_size_mm,
                pickup.maximum_part_size_mm,
                prepared.part_orientation,
                &inspection_artifact_name,
            )
            .map_err(|error| error.to_string())?;
            apply_rotated_retained_part_size_gate(&mut inspection.report, expected_size_mm);
            persist_transfer_rgb_artifact(
                state,
                prepared,
                &inspection_artifact_name,
                &inspection.preview,
            )?;
            let shadow = analyze_and_persist_held_part_shadow(
                state,
                prepared,
                &bare.frame,
                &held,
                &inspection,
                [bottom.frame_center_x_px, bottom.frame_center_y_px],
                &inspection_artifact_name,
                HeldPartControlPolicy::ShadowOnly,
            )
            .await;
            captures.push(HeldPartRotationCapture {
                capture_index: bare.capture_index,
                requested_rotation_offset_deg: bare.requested_offset_deg,
                bare_rotation_offset_deg: bare.actual_offset_deg,
                held_rotation_offset_deg: signed_rotation_offset_deg(actual_deg, reference_deg),
                bare_artifact_name: bare.artifact_name.clone(),
                held_artifact_name,
                inspection_artifact_name,
                vacuum_raw_values,
                vacuum_median_raw_value,
                vacuum_held,
                inspection: inspection.report,
                shadow,
            });
        }
        Ok::<_, String>(captures)
    }
    .await;
    let restore = state
        .machine
        .calibration_rotate_nozzle(prepared.lease_id, prepared.run.nozzle_id.clone(), 0.0)
        .await
        .map(|_| ())
        .map_err(|error| error.to_string());
    match (result, restore) {
        (Ok(captures), Ok(())) => Ok(captures),
        (Err(error), Ok(())) => Err(error),
        (Ok(_), Err(error)) => Err(format!(
            "failed to restore rotation after held-part capture: {error}"
        )),
        (Err(error), Err(restore_error)) => Err(format!(
            "{error}; held-part rotation restore also failed: {restore_error}"
        )),
    }
}

async fn execute_physical_strip_feeder_pickup(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
) -> Result<StripFeederPickupQualificationReport, String> {
    let nozzle_id = &prepared.run.nozzle_id;
    let sensor_id = &prepared.vacuum_characterization.sensor_id;
    let pickup_profile = state.profile.strip_feeder_pickup.as_ref().unwrap();
    let vacuum_profile = state.profile.vacuum_calibration.as_ref().unwrap();
    let z_kinematics = state.profile.z_kinematics.as_ref().unwrap();
    let bottom = state.profile.bottom_vision.as_ref().unwrap();
    let camera_profile =
        stored_camera_profile(state, CameraRole::BottomCamera).map_err(|error| error.message)?;
    let camera_path =
        camera_path_for_role(CameraRole::BottomCamera).map_err(|error| error.message)?;
    let nominal_pocket_machine_mm = prepared.registration.selected_pocket_machine_mm.unwrap();
    let contact_z_mm = prepared
        .reference_contact
        .contact_nozzle_z_mm
        .ok_or_else(|| "pickup reference contact has no nozzle Z".to_string())?;
    let search = VacuumProbeSearch {
        start_nozzle_z_mm: contact_z_mm + pickup_profile.search_start_above_reference_mm,
        end_nozzle_z_mm: contact_z_mm + pickup_profile.search_end_above_reference_mm,
    };
    let mut artifact_names = Vec::new();
    let mut findings = Vec::new();

    state
        .machine
        .disable_actuator(sensor_id.clone())
        .await
        .map_err(|error| format!("pickup could not establish the vacuum-off state: {error}"))?;
    let (source_before, source_before_pose) = capture_top_pocket_mean(
        state,
        prepared,
        nominal_pocket_machine_mm,
        pickup_profile.inspection_sample_count,
    )
    .await?;
    persist_transfer_gray_artifact(
        state,
        prepared,
        SOURCE_POCKET_BEFORE_ARTIFACT,
        &source_before,
    )?;
    artifact_names.push(SOURCE_POCKET_BEFORE_ARTIFACT.into());
    let source_inspection_frame = source_before.clone();
    let source_registration = prepared.registration.clone();
    let source_camera_model = prepared.top_camera_model.clone();
    let source_inspection = tokio::task::spawn_blocking(move || {
        inspect_strip_feeder_pocket_return(
            &source_inspection_frame,
            source_before_pose,
            &source_inspection_frame,
            source_before_pose,
            &source_camera_model,
            &source_registration,
            nominal_pocket_machine_mm,
            SOURCE_POCKET_PICK_INSPECTION_ARTIFACT,
        )
    })
    .await
    .map_err(|error| error.to_string())?
    .map_err(|error| error.to_string())?;
    persist_transfer_rgb_artifact(
        state,
        prepared,
        SOURCE_POCKET_PICK_INSPECTION_ARTIFACT,
        &source_inspection.preview,
    )?;
    artifact_names.push(SOURCE_POCKET_PICK_INSPECTION_ARTIFACT.into());
    if source_inspection.report.before_occupancy != StripPocketOccupancy::Occupied {
        return Err("top vision did not confirm a part in the qualification pocket".into());
    }
    let deterministic_center_machine_mm = source_inspection
        .report
        .before_measured_center_machine_mm
        .ok_or_else(|| "top vision did not locate the qualification-pocket part".to_string())?;
    let source_center_correction_mm = (deterministic_center_machine_mm[0]
        - nominal_pocket_machine_mm[0])
        .hypot(deterministic_center_machine_mm[1] - nominal_pocket_machine_mm[1]);
    if source_center_correction_mm > pickup_profile.maximum_part_offset_mm {
        return Err(format!(
            "qualification-pocket part center correction \
             {source_center_correction_mm:.3} mm exceeds the configured bound"
        ));
    }
    findings.push(format!(
        "top-camera CV measured a pickup-center correction of \
         {source_center_correction_mm:.3} mm from the nominal pocket center"
    ));
    let source_control = select_source_component_pick_center(
        state,
        prepared,
        &source_before,
        source_before_pose,
        nominal_pocket_machine_mm,
        deterministic_center_machine_mm,
    )
    .await?;
    artifact_names.extend(source_control.artifact_names);
    findings.extend(source_control.findings);
    if let Some(rejection) = source_control.rejection {
        return Err(rejection.message);
    }
    let pocket_machine_mm = source_control.center_machine_mm;

    execute_visual_home(
        state,
        VisualHomingRequest {
            lease_id: prepared.lease_id,
            apply_offset: true,
            move_to_seed: true,
        },
    )
    .await
    .map_err(|error| error.message)?;
    let current_tip_offset = measure_current_tip_offset(
        state,
        prepared.lease_id,
        nozzle_id,
        &prepared.head_reference,
        None,
    )
    .await?;
    let bottom_pose = state
        .machine
        .status()
        .pose
        .ok_or_else(|| "pickup lost the centered bottom-camera pose".to_string())?;
    let bare = capture_bottom_mean_with_lights(
        state,
        prepared.lease_id,
        &camera_profile,
        &camera_path,
        pickup_profile.inspection_sample_count,
    )
    .await?;
    persist_transfer_gray_artifact(state, prepared, BARE_NOZZLE_ARTIFACT, &bare)?;
    artifact_names.push(BARE_NOZZLE_ARTIFACT.into());
    let bare_rotation_captures = capture_bare_nozzle_rotation_sweep(
        state,
        prepared,
        &camera_profile,
        &camera_path,
        pickup_profile.inspection_sample_count,
    )
    .await?;
    artifact_names.extend(
        bare_rotation_captures
            .iter()
            .map(|capture| capture.artifact_name.clone()),
    );

    let alignment_nozzle_z_mm = 0.5 * (search.start_nozzle_z_mm + search.end_nozzle_z_mm);
    let height_correction = prepared
        .height_model
        .as_ref()
        .filter(|_| prepared.height_model_has_working_plane_transfer)
        .and_then(|model| model.tip_offset_correction_at(alignment_nozzle_z_mm))
        .unwrap_or([0.0, 0.0]);
    let pickup_head_x_mm = pocket_machine_mm[0] - current_tip_offset.x_mm - height_correction[0];
    let pickup_head_y_mm = pocket_machine_mm[1] - current_tip_offset.y_mm - height_correction[1];
    let approach_controller_z_mm = z_kinematics
        .controller_z(nozzle_id, search.start_nozzle_z_mm)
        .ok_or_else(|| "pickup approach Z is outside bounds".to_string())?;
    let level_target = JogTarget {
        x_mm: pickup_head_x_mm,
        y_mm: pickup_head_y_mm,
        z_mm: z_kinematics.level_controller_z_mm,
        rotation_deg: None,
    };
    execute_pickup_xy_transit(
        state,
        prepared,
        level_target,
        prepared.clear_xy_feed_mm_per_min,
    )
    .await?;
    move_vertical_at_current_xy(
        state,
        prepared.lease_id,
        approach_controller_z_mm,
        prepared.clear_z_feed_mm_per_min,
    )
    .await?;
    let setup = async {
        state
            .machine
            .actuate(prepared.lease_id, sensor_id.clone(), true)
            .await
            .map_err(|error| error.to_string())?;
        tokio::time::sleep(Duration::from_millis(vacuum_profile.vacuum_settle_ms)).await;
        Ok::<(), String>(())
    }
    .await;
    if let Err(error) = setup {
        let _ = state.machine.disable_actuator(sensor_id.clone()).await;
        let _ = lift_and_restore_after_pickup(state, prepared.lease_id).await;
        return Err(error);
    }
    let descent = execute_vacuum_probe_descent(
        state,
        prepared.lease_id,
        nozzle_id,
        sensor_id,
        pickup_head_x_mm,
        pickup_head_y_mm,
        search,
        Some(&prepared.vacuum_characterization),
        None,
    )
    .await;
    let (open_nozzle_raw_values, pickup_samples, contact) = match descent {
        Ok(result) => result,
        Err(error) => {
            let _ = state.machine.disable_actuator(sensor_id.clone()).await;
            let _ = lift_and_restore_after_pickup(state, prepared.lease_id).await;
            return Err(error);
        }
    };
    let Some(contact) = contact else {
        state
            .machine
            .disable_actuator(sensor_id.clone())
            .await
            .map_err(|error| error.to_string())?;
        lift_and_restore_after_pickup(state, prepared.lease_id).await?;
        findings.push(format!(
            "no vacuum transition occurred from nozzle Z{:.3} through Z{:.3}",
            search.start_nozzle_z_mm, search.end_nozzle_z_mm,
        ));
        return Ok(StripFeederPickupQualificationReport {
            algorithm_version: STRIP_FEEDER_PICKUP_ALGORITHM.into(),
            clear_xy_feed_mm_per_min: prepared.clear_xy_feed_mm_per_min,
            carried_xy_feed_mm_per_min: prepared.carried_xy_feed_mm_per_min,
            clear_z_feed_mm_per_min: prepared.clear_z_feed_mm_per_min,
            carried_z_feed_mm_per_min: prepared.carried_z_feed_mm_per_min,
            precision_z_approach_mm: prepared.precision_z_approach_mm,
            nozzle_id: nozzle_id.clone(),
            tip_id: prepared.geometry.tip_id.clone(),
            sensor_id: sensor_id.clone(),
            pocket_machine_mm,
            pickup_nozzle_z_mm: None,
            pickup_controller_z_mm: None,
            open_nozzle_raw_values,
            pickup_samples,
            held_raw_values: Vec::new(),
            held_median_raw_value: None,
            vacuum_acquired: false,
            vacuum_held_after_transfer: false,
            inspection: None,
            alignment: None,
            rotation_captures: Vec::new(),
            disposition: StripFeederPickupDisposition::NotReleased,
            release_surface_machine_mm: None,
            release_raw_values: Vec::new(),
            released: true,
            nozzle_release_verification: None,
            return_verification: None,
            passed: false,
            artifact_names,
            findings,
        });
    };
    let vacuum_acquired =
        vacuum_value_is_acquired(&prepared.vacuum_characterization, contact.median_raw_value);
    if !vacuum_acquired {
        findings.push(
            "pickup signal crossed the coarse delta gate but not the calibrated acquire threshold"
                .into(),
        );
    }
    let inspection_phase = async {
        move_vertical_at_current_xy(
            state,
            prepared.lease_id,
            level_target.z_mm,
            prepared.carried_z_feed_mm_per_min,
        )
        .await?;
        execute_pickup_xy_transit(
            state,
            prepared,
            JogTarget {
                x_mm: bottom_pose.x_mm,
                y_mm: bottom_pose.y_mm,
                z_mm: bottom_pose.z_mm,
                rotation_deg: None,
            },
            prepared.carried_xy_feed_mm_per_min,
        )
        .await?;
        let held_raw_values = collect_sensor_values(
            state,
            prepared.lease_id,
            sensor_id,
            pickup_profile.held_sample_count,
        )
        .await?;
        let held_median_raw_value = median_raw(&held_raw_values);
        let vacuum_held_after_transfer = held_median_raw_value.is_some_and(|value| {
            vacuum_value_is_acquired(&prepared.vacuum_characterization, value)
        });
        let held = capture_bottom_mean_with_lights(
            state,
            prepared.lease_id,
            &camera_profile,
            &camera_path,
            pickup_profile.inspection_sample_count,
        )
        .await?;
        persist_transfer_gray_artifact(state, prepared, HELD_PART_ARTIFACT, &held)?;
        let mut initial_inspection = inspect_held_part_difference_with_orientation(
            &bare,
            &held,
            [bottom.frame_center_x_px, bottom.frame_center_y_px],
            prepared.head_reference.bottom_camera_mapping,
            pickup_profile.maximum_part_offset_mm,
            pickup_profile.minimum_part_size_mm,
            pickup_profile.maximum_part_size_mm,
            prepared.part_orientation,
            HELD_PART_INITIAL_INSPECTION_ARTIFACT,
        )
        .map_err(|error| error.to_string())?;
        apply_expected_held_part_size_gate(
            &mut initial_inspection.report,
            prepared.expected_part_size_mm,
            prepared.expected_part_size_source,
        );
        apply_registered_orientation_fallback(
            &mut initial_inspection.report,
            prepared.part_orientation,
            prepared.source_rotation_deg,
            prepared.expected_part_size_mm,
            pickup_profile,
        );
        persist_transfer_rgb_artifact(
            state,
            prepared,
            HELD_PART_INITIAL_INSPECTION_ARTIFACT,
            &initial_inspection.preview,
        )?;
        if let Some(shadow) = analyze_and_persist_held_part_shadow(
            state,
            prepared,
            &bare,
            &held,
            &initial_inspection,
            [bottom.frame_center_x_px, bottom.frame_center_y_px],
            HELD_PART_INITIAL_INSPECTION_ARTIFACT,
            HeldPartControlPolicy::ShadowOnly,
        )
        .await
        {
            artifact_names.extend([shadow.report_artifact_name, shadow.preview_artifact_name]);
        }
        let motion_permitted = vacuum_held_after_transfer && initial_inspection.report.passed;
        let rotation_reference_captured = if motion_permitted {
            state
                .machine
                .calibration_rotation_reference(prepared.lease_id, prepared.run.nozzle_id.clone())
                .await
                .map_err(|error| error.to_string())?;
            true
        } else {
            false
        };
        let rotation_captures = if motion_permitted {
            capture_held_part_rotation_sweep(
                state,
                prepared,
                &bare_rotation_captures,
                &camera_profile,
                &camera_path,
                sensor_id,
                initial_inspection
                    .report
                    .width_mm
                    .zip(initial_inspection.report.length_mm)
                    .map(|(width, length)| [width, length]),
            )
            .await?
        } else {
            Vec::new()
        };
        for capture in &rotation_captures {
            artifact_names.extend([
                capture.held_artifact_name.clone(),
                capture.inspection_artifact_name.clone(),
            ]);
            if let Some(shadow) = &capture.shadow {
                artifact_names.extend([
                    shadow.report_artifact_name.clone(),
                    shadow.preview_artifact_name.clone(),
                ]);
            }
        }
        let target_rotation_deg = prepared.registration.part_rotation_deg.unwrap_or(0.0);
        let alignment_result = align_held_part(
            state,
            prepared,
            &bare,
            initial_inspection,
            bottom_pose,
            &camera_profile,
            &camera_path,
            target_rotation_deg,
            motion_permitted,
            None,
        )
        .await;
        let rotation_restore = if rotation_reference_captured {
            state
                .machine
                .calibration_rotate_nozzle(prepared.lease_id, prepared.run.nozzle_id.clone(), 0.0)
                .await
                .map(|_| ())
                .map_err(|error| error.to_string())
        } else {
            Ok(())
        };
        let (inspection, alignment) = match (alignment_result, rotation_restore) {
            (Ok(result), Ok(())) => result,
            (Err(error), Ok(())) => return Err(error),
            (Ok(_), Err(error)) => {
                return Err(format!("failed to restore pickup rotation: {error}"));
            }
            (Err(error), Err(restore_error)) => {
                return Err(format!(
                    "{error}; pickup rotation restore also failed: {restore_error}"
                ));
            }
        };
        Ok::<_, String>((
            held_raw_values,
            held_median_raw_value,
            vacuum_held_after_transfer,
            inspection,
            alignment,
            rotation_captures,
        ))
    }
    .await;
    let (
        held_raw_values,
        held_median_raw_value,
        vacuum_held_after_transfer,
        inspection,
        alignment,
        rotation_captures,
    ) = match inspection_phase {
        Ok(result) => result,
        Err(error) => {
            let release_cleanup = release_pickup_part(
                state,
                prepared,
                sensor_id,
                [pickup_head_x_mm, pickup_head_y_mm],
                current_tip_offset,
                contact.controller_z_mm,
                false,
            )
            .await;
            let restore_cleanup = lift_and_restore_after_pickup(state, prepared.lease_id).await;
            let cleanup = release_cleanup.map(|_| ()).and(restore_cleanup);
            return Err(match cleanup {
                Ok(()) => format!("{error}; the part was returned to its pocket"),
                Err(cleanup_error) => {
                    format!("{error}; pickup cleanup also failed: {cleanup_error}")
                }
            });
        }
    };
    artifact_names.push(HELD_PART_ARTIFACT.into());
    for artifact_name in &alignment.artifact_names {
        if !artifact_names.contains(artifact_name) {
            artifact_names.push(artifact_name.clone());
        }
    }
    if !vacuum_held_after_transfer {
        findings.push("vacuum did not remain above the calibrated hold threshold".into());
    }
    if !rotation_captures.is_empty() {
        findings.push(format!(
            "captured {} same-angle bare-nozzle and held-part rotation pairs",
            rotation_captures.len()
        ));
    }
    findings.extend(inspection.report.findings.clone());
    findings.extend(alignment.findings.clone());

    // A coarse contact transition can hold a part even when a later signal or
    // image gate rejects it. Every contact path returns to the source pocket.
    let verified_release = {
        // Return to the exact pickup head pose. The measured part-to-nozzle
        // offset must not be applied here because it existed at pickup time.
        let release_reference = release_reference_inspection(&alignment, &inspection.report);
        release_and_verify_nozzle_clear(
            state,
            prepared,
            sensor_id,
            [pickup_head_x_mm, pickup_head_y_mm],
            current_tip_offset,
            contact.controller_z_mm,
            &bare,
            release_reference,
            bottom_pose,
            &camera_profile,
            &camera_path,
        )
        .await?
    };
    for artifact_name in &verified_release.verification.artifact_names {
        if !artifact_names.contains(artifact_name) {
            artifact_names.push(artifact_name.clone());
        }
    }
    findings.extend(verified_release.verification.findings.clone());
    let return_verification = if verified_release.disposition
        == StripFeederPickupDisposition::ReturnedToPocket
        && verified_release.released
    {
        let (source_after, source_after_pose) = capture_top_pocket_mean(
            state,
            prepared,
            pocket_machine_mm,
            pickup_profile.inspection_sample_count,
        )
        .await?;
        persist_transfer_gray_artifact(
            state,
            prepared,
            SOURCE_POCKET_AFTER_ARTIFACT,
            &source_after,
        )?;
        let registration = prepared.registration.clone();
        let camera_model = prepared.top_camera_model.clone();
        let verification = tokio::task::spawn_blocking(move || {
            inspect_strip_feeder_pocket_return(
                &source_before,
                source_before_pose,
                &source_after,
                source_after_pose,
                &camera_model,
                &registration,
                pocket_machine_mm,
                POCKET_RETURN_INSPECTION_ARTIFACT,
            )
        })
        .await
        .map_err(|error| error.to_string())?
        .map_err(|error| error.to_string())?;
        persist_transfer_rgb_artifact(
            state,
            prepared,
            POCKET_RETURN_INSPECTION_ARTIFACT,
            &verification.preview,
        )?;
        artifact_names.push(SOURCE_POCKET_AFTER_ARTIFACT.into());
        artifact_names.push(POCKET_RETURN_INSPECTION_ARTIFACT.into());
        Some(verification.report)
    } else {
        None
    };
    restore_level_visual_home(state, prepared.lease_id, None).await?;
    if !verified_release.released {
        findings.push("post-release bottom vision did not confirm a clear nozzle".into());
    }
    if let Some(verification) = &return_verification {
        findings.extend(verification.findings.clone());
        if verified_release.verification.nozzle_clear && !verification.passed {
            findings.push(
                "the nozzle is clear, but top vision did not find the part in its source pocket"
                    .into(),
            );
        }
    }
    let passed = vacuum_acquired
        && vacuum_held_after_transfer
        && alignment.passed
        && verified_release.released
        && verified_release.verification.passed
        && verified_release.disposition == StripFeederPickupDisposition::ReturnedToPocket
        && return_verification
            .as_ref()
            .is_some_and(|verification| verification.passed);
    if passed {
        findings.push(
            "pickup, transfer, bottom inspection, release, and top return verification passed"
                .into(),
        );
    }
    Ok(StripFeederPickupQualificationReport {
        algorithm_version: STRIP_FEEDER_PICKUP_ALGORITHM.into(),
        clear_xy_feed_mm_per_min: prepared.clear_xy_feed_mm_per_min,
        carried_xy_feed_mm_per_min: prepared.carried_xy_feed_mm_per_min,
        clear_z_feed_mm_per_min: prepared.clear_z_feed_mm_per_min,
        carried_z_feed_mm_per_min: prepared.carried_z_feed_mm_per_min,
        precision_z_approach_mm: prepared.precision_z_approach_mm,
        nozzle_id: nozzle_id.clone(),
        tip_id: prepared.geometry.tip_id.clone(),
        sensor_id: sensor_id.clone(),
        pocket_machine_mm,
        pickup_nozzle_z_mm: Some(contact.nozzle_z_mm),
        pickup_controller_z_mm: Some(contact.controller_z_mm),
        open_nozzle_raw_values,
        pickup_samples,
        held_raw_values,
        held_median_raw_value,
        vacuum_acquired,
        vacuum_held_after_transfer,
        inspection: Some(inspection.report),
        alignment: Some(alignment),
        rotation_captures,
        disposition: verified_release.disposition,
        release_surface_machine_mm: verified_release.release_surface_machine_mm,
        release_raw_values: verified_release.release_raw_values,
        released: verified_release.released,
        nozzle_release_verification: Some(verified_release.verification),
        return_verification,
        passed,
        artifact_names,
        findings,
    })
}

struct VerifiedPickupRelease {
    disposition: StripFeederPickupDisposition,
    release_surface_machine_mm: Option<[f64; 2]>,
    release_raw_values: Vec<i64>,
    released: bool,
    verification: NozzleReleaseVerificationReport,
}

#[allow(clippy::too_many_arguments)]
async fn release_and_verify_nozzle_clear(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    sensor_id: &str,
    pickup_head_machine_mm: [f64; 2],
    current_tip_offset: CurrentTipOffset,
    pickup_controller_z_mm: f64,
    bare: &GrayFrame,
    held_part: &HeldPartInspectionReport,
    bottom_pose: Pose,
    camera_profile: &CameraProfile,
    camera_path: &str,
) -> Result<VerifiedPickupRelease, String> {
    let pickup_profile = state.profile.strip_feeder_pickup.as_ref().unwrap();
    let bottom = state.profile.bottom_vision.as_ref().unwrap();
    let mut observations = Vec::new();
    let mut artifact_names = Vec::new();
    let mut findings = Vec::new();
    let mut release_raw_values = Vec::new();
    let mut final_disposition = StripFeederPickupDisposition::NotReleased;
    let mut release_surface_machine_mm = None;
    let mut nozzle_clear = false;

    for attempt in 1..=MAXIMUM_RELEASE_ATTEMPTS {
        let (disposition, surface, raw_values, sensor_released) = release_pickup_part(
            state,
            prepared,
            sensor_id,
            pickup_head_machine_mm,
            current_tip_offset,
            pickup_controller_z_mm,
            false,
        )
        .await?;
        final_disposition = disposition;
        release_surface_machine_mm = surface;
        release_raw_values.extend(raw_values);

        execute_pickup_xy_transit(
            state,
            prepared,
            JogTarget {
                x_mm: bottom_pose.x_mm,
                y_mm: bottom_pose.y_mm,
                z_mm: bottom_pose.z_mm,
                rotation_deg: None,
            },
            prepared.clear_xy_feed_mm_per_min,
        )
        .await?;
        let post_release = capture_bottom_mean_with_lights(
            state,
            prepared.lease_id,
            camera_profile,
            camera_path,
            pickup_profile.inspection_sample_count,
        )
        .await?;
        let raw_artifact = if attempt == 1 {
            POST_RELEASE_NOZZLE_ARTIFACT.to_string()
        } else {
            format!("post-release-nozzle-attempt-{attempt}.png")
        };
        let inspection_artifact = if attempt == 1 {
            POST_RELEASE_NOZZLE_INSPECTION_ARTIFACT.to_string()
        } else {
            format!("post-release-nozzle-inspection-attempt-{attempt}.png")
        };
        persist_transfer_gray_artifact(state, prepared, &raw_artifact, &post_release)?;
        let inspection = inspect_held_part_difference(
            bare,
            &post_release,
            [bottom.frame_center_x_px, bottom.frame_center_y_px],
            prepared.head_reference.bottom_camera_mapping,
            pickup_profile.maximum_part_offset_mm,
            pickup_profile.minimum_part_size_mm,
            pickup_profile.maximum_part_size_mm,
            &inspection_artifact,
        )
        .map_err(|error| error.to_string())?;
        persist_transfer_rgb_artifact(state, prepared, &inspection_artifact, &inspection.preview)?;
        let release_shadow = analyze_and_persist_held_part_shadow(
            state,
            prepared,
            bare,
            &post_release,
            &inspection,
            [bottom.frame_center_x_px, bottom.frame_center_y_px],
            &inspection_artifact,
            HeldPartControlPolicy::ReleaseNozzleClear,
        )
        .await;
        if let Some(shadow) = release_shadow.as_ref() {
            artifact_names.extend([
                shadow.report_artifact_name.clone(),
                shadow.preview_artifact_name.clone(),
            ]);
        }
        artifact_names.push(raw_artifact);
        artifact_names.push(inspection_artifact);
        let model_confirmed_clear = release_shadow
            .as_ref()
            .is_some_and(|shadow| shadow.control_authorized);
        let part_detected =
            !model_confirmed_clear && post_release_matches_held_part(held_part, &inspection.report);
        if model_confirmed_clear && inspection.report.detected {
            findings.push(format!(
                "the held-part model overrode a deterministic false-positive release detection on attempt {attempt}"
            ));
        }
        if inspection.report.detected && !part_detected {
            findings.push(format!(
                "post-release difference from attempt {attempt} did not match the held component size and contrast"
            ));
        }
        observations.push(inspection.report);
        nozzle_clear = nozzle_release_attempt_passed(sensor_released, part_detected);
        if nozzle_clear {
            findings.push(format!(
                "bottom vision confirmed a clear nozzle after release attempt {attempt}"
            ));
            break;
        }
        if attempt < MAXIMUM_RELEASE_ATTEMPTS {
            findings.push(format!(
                "release attempt {attempt} did not confirm both vacuum-off state and a clear nozzle; retrying once"
            ));
        }
    }

    if !nozzle_clear {
        final_disposition = StripFeederPickupDisposition::NotReleased;
        findings
            .push("bounded release attempts ended without proof that the nozzle is clear".into());
    }
    let attempt_count = observations.len() as u32;
    Ok(VerifiedPickupRelease {
        disposition: final_disposition,
        release_surface_machine_mm,
        release_raw_values,
        released: nozzle_clear,
        verification: NozzleReleaseVerificationReport {
            algorithm_version: NOZZLE_RELEASE_VERIFICATION_ALGORITHM.into(),
            attempt_count,
            retry_performed: attempt_count > 1,
            nozzle_clear,
            passed: nozzle_clear,
            observations,
            artifact_names,
            findings,
        },
    })
}

fn nozzle_release_attempt_passed(sensor_released: bool, part_detected: bool) -> bool {
    sensor_released && !part_detected
}

fn post_release_matches_held_part(
    held: &HeldPartInspectionReport,
    observed: &HeldPartInspectionReport,
) -> bool {
    if !observed.detected {
        return false;
    }
    let size_matches = held
        .width_mm
        .zip(held.length_mm)
        .zip(observed.width_mm.zip(observed.length_mm))
        .is_some_and(
            |((held_width, held_length), (observed_width, observed_length))| {
                observed_width >= MINIMUM_RETAINED_PART_DIMENSION_RATIO * held_width
                    && observed_length >= MINIMUM_RETAINED_PART_DIMENSION_RATIO * held_length
            },
        );
    let pixel_ratio = if held.changed_pixel_count == 0 {
        0.0
    } else {
        f64::from(observed.changed_pixel_count) / f64::from(held.changed_pixel_count)
    };
    let luma_ratio = if held.mean_difference_luma <= 0.0 {
        0.0
    } else {
        observed.mean_difference_luma / held.mean_difference_luma
    };
    let polarity_matches = match (
        held_part_foreground_is_brighter(held),
        held_part_foreground_is_brighter(observed),
    ) {
        (Some(held), Some(observed)) => held == observed,
        _ => true,
    };
    size_matches
        && polarity_matches
        && (pixel_ratio >= MINIMUM_RETAINED_PART_PIXEL_RATIO
            || luma_ratio >= MINIMUM_RETAINED_PART_LUMA_RATIO)
}

fn release_reference_inspection<'a>(
    alignment: &'a HeldPartAlignmentReport,
    final_inspection: &'a HeldPartInspectionReport,
) -> &'a HeldPartInspectionReport {
    alignment
        .observations
        .first()
        .map(|observation| &observation.inspection)
        .unwrap_or(final_inspection)
}

fn held_part_foreground_is_brighter(report: &HeldPartInspectionReport) -> Option<bool> {
    if report
        .findings
        .iter()
        .any(|finding| finding.contains("foreground is brighter"))
    {
        Some(true)
    } else if report
        .findings
        .iter()
        .any(|finding| finding.contains("foreground is darker"))
    {
        Some(false)
    } else {
        None
    }
}

fn apply_expected_held_part_size_gate(
    report: &mut HeldPartInspectionReport,
    expected_size_mm: Option<[f64; 2]>,
    source: &str,
) {
    let Some(expected_size_mm) = expected_size_mm else {
        return;
    };
    let Some((observed_width_mm, observed_length_mm)) = report.width_mm.zip(report.length_mm)
    else {
        report.passed = false;
        report.findings.push(format!(
            "held-part dimensions are unavailable for comparison with the {source}"
        ));
        return;
    };
    let expected_width_mm = expected_size_mm[0].min(expected_size_mm[1]);
    let expected_length_mm = expected_size_mm[0].max(expected_size_mm[1]);
    if !expected_width_mm.is_finite() || !expected_length_mm.is_finite() || expected_width_mm <= 0.0
    {
        report.passed = false;
        report
            .findings
            .push(format!("the {source} has invalid part dimensions"));
        return;
    }
    let dimensions_match = held_part_dimensions_match_expected(report, expected_size_mm);
    if dimensions_match {
        report.findings.push(format!(
            "held-part dimensions match the {source} within the configured ratio bounds"
        ));
    } else {
        report.passed = false;
        report.findings.push(format!(
            "held-part size {observed_width_mm:.3} by {observed_length_mm:.3} mm does not match the {source} size {expected_width_mm:.3} by {expected_length_mm:.3} mm"
        ));
    }
}

fn held_part_dimensions_match_expected(
    report: &HeldPartInspectionReport,
    expected_size_mm: [f64; 2],
) -> bool {
    held_part_dimensions_match_expected_with_maximum(
        report,
        expected_size_mm,
        MAXIMUM_EXPECTED_PART_DIMENSION_RATIO,
    )
}

fn held_part_dimensions_match_expected_with_maximum(
    report: &HeldPartInspectionReport,
    expected_size_mm: [f64; 2],
    maximum_ratio: f64,
) -> bool {
    let expected_width_mm = expected_size_mm[0].min(expected_size_mm[1]);
    let expected_length_mm = expected_size_mm[0].max(expected_size_mm[1]);
    report
        .width_mm
        .zip(report.length_mm)
        .is_some_and(|(observed_width_mm, observed_length_mm)| {
            expected_width_mm.is_finite()
                && expected_length_mm.is_finite()
                && expected_width_mm > 0.0
                && [
                    observed_width_mm / expected_width_mm,
                    observed_length_mm / expected_length_mm,
                ]
                .into_iter()
                .all(|ratio| {
                    (MINIMUM_EXPECTED_PART_DIMENSION_RATIO..=maximum_ratio).contains(&ratio)
                })
        })
}

fn apply_rotated_retained_part_size_gate(
    report: &mut HeldPartInspectionReport,
    expected_size_mm: Option<[f64; 2]>,
) {
    let Some(expected_size_mm) = expected_size_mm else {
        return;
    };
    if held_part_dimensions_match_expected_with_maximum(
        report,
        expected_size_mm,
        MAXIMUM_ROTATED_RETAINED_PART_DIMENSION_RATIO,
    ) {
        report.findings.push(
            "post-rotation dimensions passed the retained-part bounds; nozzle-reference reflections can enlarge this outline"
                .into(),
        );
    } else {
        report.passed = false;
        report
            .findings
            .push("post-rotation dimensions do not match the initial held-part measurement".into());
    }
}

fn rotate_machine_vector(vector: [f64; 2], rotation_deg: f64) -> [f64; 2] {
    let radians = rotation_deg.to_radians();
    let cosine = radians.cos();
    let sine = radians.sin();
    [
        cosine * vector[0] - sine * vector[1],
        sine * vector[0] + cosine * vector[1],
    ]
}

fn apply_registered_orientation_fallback(
    report: &mut HeldPartInspectionReport,
    orientation: PartOrientation,
    source_rotation_deg: f64,
    expected_size_mm: Option<[f64; 2]>,
    pickup: &velocitypnp_domain::StripFeederPickupProfile,
) {
    let minimum_contrast_luma = match orientation {
        PartOrientation::BrighterEnd {
            minimum_contrast_luma,
            ..
        }
        | PartOrientation::DarkerEnd {
            minimum_contrast_luma,
            ..
        } => minimum_contrast_luma,
        PartOrientation::AxisSymmetric | PartOrientation::FeederReferenced => return,
    };
    if report.passed
        || report
            .orientation_contrast_luma
            .is_none_or(|contrast| contrast >= minimum_contrast_luma)
    {
        return;
    }
    let geometry_passed = report.detected
        && report
            .centering_correction_mm
            .is_some_and(|offset| offset.is_finite() && offset <= pickup.maximum_part_offset_mm)
        && report
            .width_mm
            .zip(report.length_mm)
            .is_some_and(|(width, length)| {
                width >= pickup.minimum_part_size_mm
                    && length >= width
                    && length <= pickup.maximum_part_size_mm
            })
        && expected_size_mm
            .is_none_or(|expected| held_part_dimensions_match_expected(report, expected))
        && report.confidence >= 0.35;
    let Some(axis_rotation_deg) = report.rotation_deg.filter(|_| geometry_passed) else {
        return;
    };
    report.orientation_rotation_deg = Some(unwrap_package_axis_deg(
        axis_rotation_deg,
        source_rotation_deg,
    ));
    report.passed = true;
    report.findings.push(
        "visible package-end contrast was ambiguous; the registered feeder phase resolved the directed orientation"
            .into(),
    );
}

async fn release_pickup_part(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    sensor_id: &str,
    pickup_head_machine_mm: [f64; 2],
    current_tip_offset: CurrentTipOffset,
    pickup_controller_z_mm: f64,
    prefer_fallback_drop: bool,
) -> Result<
    (
        StripFeederPickupDisposition,
        Option<[f64; 2]>,
        Vec<i64>,
        bool,
    ),
    String,
> {
    let pickup_profile = state.profile.strip_feeder_pickup.as_ref().unwrap();
    let vacuum_profile = state.profile.vacuum_calibration.as_ref().unwrap();
    let z_kinematics = state.profile.z_kinematics.as_ref().unwrap();
    let pocket_machine_mm = prepared.registration.selected_pocket_machine_mm.unwrap();
    let status = state.machine.status();
    let pose = status
        .pose
        .ok_or_else(|| "pickup release has no trusted machine pose".to_string())?;
    let return_level = JogTarget {
        x_mm: pickup_head_machine_mm[0],
        y_mm: pickup_head_machine_mm[1],
        z_mm: z_kinematics.level_controller_z_mm,
        rotation_deg: None,
    };
    let return_is_valid = state.profile.bounds.contains(Pose {
        x_mm: return_level.x_mm,
        y_mm: return_level.y_mm,
        z_mm: return_level.z_mm,
        rotation_deg: pose.rotation_deg,
    });
    let fallback = if let Some(drop_surface) = prepared.run.fallback_drop_surface_machine_mm {
        let drop_level = JogTarget {
            x_mm: drop_surface[0] - current_tip_offset.x_mm,
            y_mm: drop_surface[1] - current_tip_offset.y_mm,
            z_mm: z_kinematics.level_controller_z_mm,
            rotation_deg: None,
        };
        if !state.profile.bounds.contains(Pose {
            x_mm: drop_level.x_mm,
            y_mm: drop_level.y_mm,
            z_mm: drop_level.z_mm,
            rotation_deg: pose.rotation_deg,
        }) {
            return Err("pickup fallback drop target is outside bounds".into());
        }
        Some((
            drop_level,
            drop_surface,
            false,
            StripFeederPickupDisposition::DroppedAtFallback,
        ))
    } else {
        None
    };
    let (release_level, release_surface, release_at_pickup_z, success_disposition) =
        if prefer_fallback_drop {
            fallback.ok_or_else(|| "production pickup has no fallback drop target".to_string())?
        } else if return_is_valid {
            (
                return_level,
                pocket_machine_mm,
                true,
                StripFeederPickupDisposition::ReturnedToPocket,
            )
        } else if let Some(fallback) = fallback {
            fallback
        } else {
            return Err(
                "pickup return target is outside bounds and no fallback was supplied".into(),
            );
        };

    let release_result = async {
        if (pose.z_mm - z_kinematics.level_controller_z_mm).abs() > 1e-9 {
            move_vertical_at_current_xy(
                state,
                prepared.lease_id,
                z_kinematics.level_controller_z_mm,
                prepared.carried_z_feed_mm_per_min,
            )
            .await?;
        }
        execute_pickup_xy_transit(
            state,
            prepared,
            release_level,
            prepared.carried_xy_feed_mm_per_min,
        )
        .await?;
        if release_at_pickup_z {
            approach_z_with_slow_finish(
                state,
                prepared.lease_id,
                pickup_controller_z_mm,
                prepared.carried_z_feed_mm_per_min,
                vacuum_profile.z_approach_feed_mm_per_min,
                prepared.precision_z_approach_mm,
            )
            .await?;
        }
        state
            .machine
            .disable_actuator(sensor_id.into())
            .await
            .map_err(|error| error.to_string())?;
        tokio::time::sleep(Duration::from_millis(pickup_profile.release_settle_ms)).await;
        let release_raw_values = collect_sensor_values(
            state,
            prepared.lease_id,
            sensor_id,
            pickup_profile.release_sample_count,
        )
        .await?;
        let released = median_raw(&release_raw_values).is_some_and(|value| {
            vacuum_value_is_released(&prepared.vacuum_characterization, value)
        });
        if release_at_pickup_z {
            move_vertical_at_current_xy(
                state,
                prepared.lease_id,
                release_level.z_mm,
                prepared.clear_z_feed_mm_per_min,
            )
            .await?;
        }
        Ok::<_, String>((
            if released {
                success_disposition
            } else {
                StripFeederPickupDisposition::NotReleased
            },
            Some(release_surface),
            release_raw_values,
            released,
        ))
    }
    .await;
    if let Err(error) = release_result {
        let disable_error = state
            .machine
            .disable_actuator(sensor_id.into())
            .await
            .err()
            .map(|cleanup| cleanup.to_string());
        let lift_error = lift_and_restore_after_pickup(state, prepared.lease_id)
            .await
            .err();
        let cleanup = [disable_error, lift_error]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join("; ");
        return if cleanup.is_empty() {
            Err(error)
        } else {
            Err(format!("{error}; release cleanup also failed: {cleanup}"))
        };
    }
    release_result
}

#[allow(clippy::too_many_arguments)]
async fn align_held_part(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    bare: &GrayFrame,
    initial: HeldPartInspectionArtifacts,
    initial_head_pose: Pose,
    camera_profile: &CameraProfile,
    camera_path: &str,
    target_rotation_deg: f64,
    motion_permitted: bool,
    artifact_suffix: Option<&str>,
) -> Result<(HeldPartInspectionArtifacts, HeldPartAlignmentReport), String> {
    let pickup = state.profile.strip_feeder_pickup.as_ref().unwrap();
    let bottom = state.profile.bottom_vision.as_ref().unwrap();
    let mut current = initial;
    let initial_report = current.report.clone();
    let initial_size_mm = current
        .report
        .width_mm
        .zip(current.report.length_mm)
        .map(|(width, length)| [width, length]);
    let mut head_pose = initial_head_pose;
    let mut commanded_x_mm = 0.0;
    let mut commanded_y_mm = 0.0;
    let mut commanded_rotation_deg = 0.0;
    let aligned_artifact = suffixed_png_artifact(HELD_PART_ALIGNED_ARTIFACT, artifact_suffix);
    let inspection_artifact = suffixed_png_artifact(HELD_PART_INSPECTION_ARTIFACT, artifact_suffix);
    let mut artifact_names = vec![current.report.artifact_name.clone()];
    let mut observations = Vec::new();
    let mut findings = Vec::new();

    for iteration in 0..=pickup.alignment_max_iterations {
        observations.push(HeldPartAlignmentObservation {
            iteration,
            head_machine_mm: [head_pose.x_mm, head_pose.y_mm],
            nozzle_rotation_offset_deg: commanded_rotation_deg,
            inspection: current.report.clone(),
        });
        let center_residual = current.report.centering_correction_mm;
        let corrected_observation = iteration > 0;
        let visual_evidence_passed = if corrected_observation {
            initial_size_mm.is_some_and(|expected| {
                held_part_dimensions_match_expected_with_maximum(
                    &current.report,
                    expected,
                    MAXIMUM_ROTATED_RETAINED_PART_DIMENSION_RATIO,
                )
            }) && post_release_matches_held_part(&initial_report, &current.report)
        } else {
            current.report.passed
        };
        let resolved_rotation = if corrected_observation {
            resolved_held_part_rotation_deg(
                &initial_report,
                prepared.part_orientation,
                prepared.source_rotation_deg,
            )
            .map(|rotation| rotation + commanded_rotation_deg)
        } else {
            resolved_held_part_rotation_deg(
                &current.report,
                prepared.part_orientation,
                prepared.source_rotation_deg,
            )
        };
        let rotation_residual = resolved_rotation.map(|measured| {
            held_part_rotation_error_deg(measured, target_rotation_deg, prepared.part_orientation)
        });
        let passed = visual_evidence_passed
            && center_residual
                .is_some_and(|value| value <= pickup.alignment_translation_tolerance_mm)
            && rotation_residual
                .is_some_and(|value| value.abs() <= pickup.alignment_rotation_tolerance_deg);
        if passed
            || iteration == pickup.alignment_max_iterations
            || !current.report.passed
            || !motion_permitted
        {
            if passed {
                findings.push(
                    if corrected_observation {
                        "bottom vision verified retained part size and centering; the calibrated nozzle command resolved the rotation"
                    } else {
                        "bottom vision verified the held-part pose without correction"
                    }
                    .into(),
                );
            } else if !visual_evidence_passed {
                findings.push(
                    if corrected_observation {
                        "post-correction bottom vision did not confirm a retained part"
                    } else {
                        "initial held-part evidence did not permit alignment motion"
                    }
                    .into(),
                );
            } else if !motion_permitted {
                findings.push("vacuum evidence did not permit alignment motion".into());
            } else {
                findings.push("held-part alignment reached its bounded iteration limit".into());
            }
            if current.report.artifact_name != inspection_artifact {
                current.report.artifact_name = inspection_artifact.clone();
                persist_transfer_rgb_artifact(
                    state,
                    prepared,
                    &inspection_artifact,
                    &current.preview,
                )?;
            }
            if !artifact_names
                .iter()
                .any(|name| name == &inspection_artifact)
            {
                artifact_names.push(inspection_artifact.clone());
            }
            return Ok((
                current,
                HeldPartAlignmentReport {
                    algorithm_version: HELD_PART_ALIGNMENT_ALGORITHM.into(),
                    orientation: prepared.part_orientation,
                    source_rotation_deg: prepared.source_rotation_deg,
                    target_rotation_deg,
                    commanded_x_mm,
                    commanded_y_mm,
                    commanded_rotation_deg,
                    final_centering_residual_mm: center_residual,
                    final_rotation_residual_deg: rotation_residual,
                    final_resolved_rotation_deg: resolved_rotation,
                    passed,
                    observations,
                    artifact_names,
                    findings,
                },
            ));
        }

        let measured_correction_x_mm = current
            .report
            .centering_correction_x_mm
            .ok_or_else(|| "held-part alignment has no X correction".to_string())?;
        let measured_correction_y_mm = current
            .report
            .centering_correction_y_mm
            .ok_or_else(|| "held-part alignment has no Y correction".to_string())?;
        let rotation_correction_deg = -rotation_residual
            .ok_or_else(|| "held-part alignment has no rotation measurement".to_string())?;
        commanded_rotation_deg += rotation_correction_deg;
        if commanded_rotation_deg.abs() > pickup.alignment_max_rotation_correction_deg {
            return Err(format!(
                "held-part rotation correction {commanded_rotation_deg:.3} degrees exceeds the configured bound"
            ));
        }
        let [correction_x_mm, correction_y_mm] = rotate_machine_vector(
            [measured_correction_x_mm, measured_correction_y_mm],
            rotation_correction_deg,
        );
        state
            .machine
            .calibration_rotate_nozzle(
                prepared.lease_id,
                prepared.run.nozzle_id.clone(),
                commanded_rotation_deg,
            )
            .await
            .map_err(|error| error.to_string())?;
        head_pose = state
            .machine
            .jog(
                prepared.lease_id,
                JogTarget {
                    x_mm: head_pose.x_mm + correction_x_mm,
                    y_mm: head_pose.y_mm + correction_y_mm,
                    z_mm: head_pose.z_mm,
                    rotation_deg: None,
                },
                bottom.feed_mm_per_min,
            )
            .await
            .map_err(|error| error.to_string())?;
        commanded_x_mm += correction_x_mm;
        commanded_y_mm += correction_y_mm;
        let held = capture_bottom_mean_with_lights(
            state,
            prepared.lease_id,
            camera_profile,
            camera_path,
            pickup.inspection_sample_count,
        )
        .await?;
        persist_transfer_gray_artifact(state, prepared, &aligned_artifact, &held)?;
        if !artifact_names.iter().any(|name| name == &aligned_artifact) {
            artifact_names.push(aligned_artifact.clone());
        }
        current = inspect_held_part_difference_with_orientation(
            bare,
            &held,
            [bottom.frame_center_x_px, bottom.frame_center_y_px],
            prepared.head_reference.bottom_camera_mapping,
            pickup.maximum_part_offset_mm,
            pickup.minimum_part_size_mm,
            pickup.maximum_part_size_mm,
            prepared.part_orientation,
            &inspection_artifact,
        )
        .map_err(|error| error.to_string())?;
        apply_rotated_retained_part_size_gate(&mut current.report, initial_size_mm);
        persist_transfer_rgb_artifact(state, prepared, &inspection_artifact, &current.preview)?;
        if let Some(shadow) = analyze_and_persist_held_part_shadow(
            state,
            prepared,
            bare,
            &held,
            &current,
            [bottom.frame_center_x_px, bottom.frame_center_y_px],
            &inspection_artifact,
            HeldPartControlPolicy::ShadowOnly,
        )
        .await
        {
            for name in [shadow.report_artifact_name, shadow.preview_artifact_name] {
                if !artifact_names.contains(&name) {
                    artifact_names.push(name);
                }
            }
        }
    }
    Err("held-part alignment ended without a report".into())
}

fn suffixed_png_artifact(base: &str, suffix: Option<&str>) -> String {
    suffix.map_or_else(
        || base.to_string(),
        |suffix| {
            base.strip_suffix(".png").map_or_else(
                || format!("{base}-{suffix}"),
                |stem| format!("{stem}-{suffix}.png"),
            )
        },
    )
}

fn resolved_held_part_rotation_deg(
    inspection: &HeldPartInspectionReport,
    orientation: PartOrientation,
    expected_rotation_deg: f64,
) -> Option<f64> {
    match orientation {
        PartOrientation::AxisSymmetric => inspection.rotation_deg,
        PartOrientation::FeederReferenced => inspection
            .rotation_deg
            .map(|axis| unwrap_package_axis_deg(axis, expected_rotation_deg)),
        PartOrientation::BrighterEnd { .. } | PartOrientation::DarkerEnd { .. } => {
            inspection.orientation_rotation_deg
        }
    }
}

fn unwrap_package_axis_deg(axis_rotation_deg: f64, expected_rotation_deg: f64) -> f64 {
    let turns = ((expected_rotation_deg - axis_rotation_deg) / 180.0).round();
    axis_rotation_deg + 180.0 * turns
}

fn held_part_rotation_error_deg(
    measured_deg: f64,
    target_deg: f64,
    orientation: PartOrientation,
) -> f64 {
    let period = if orientation.is_directed() {
        360.0
    } else {
        180.0
    };
    let mut error = (measured_deg - target_deg).rem_euclid(period);
    if error > 0.5 * period {
        error -= period;
    }
    error
}

async fn capture_top_pocket_mean(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    pocket_machine_mm: [f64; 2],
    sample_count: u32,
) -> Result<(GrayFrame, Pose), String> {
    let target = Pose {
        x_mm: pocket_machine_mm[0],
        y_mm: pocket_machine_mm[1],
        z_mm: state.profile.safe_z_mm,
        rotation_deg: state
            .machine
            .status()
            .pose
            .map_or(0.0, |pose| pose.rotation_deg),
    };
    let measured_pose = execute_pickup_xy_transit(
        state,
        prepared,
        target.into(),
        prepared.clear_xy_feed_mm_per_min,
    )
    .await?;
    if prepared.top_camera_profile.lighting_enabled {
        state
            .machine
            .actuate(prepared.lease_id, "lights".into(), true)
            .await
            .map_err(|error| error.to_string())?;
    }
    let capture = capture_profiled_frames(
        state,
        &prepared.top_camera_profile,
        &prepared.top_camera_path,
        sample_count,
    )
    .await
    .map_err(|error| error.message)
    .and_then(|frames| mean_gray_frames(&frames));
    let lights_off = if prepared.top_camera_profile.lighting_enabled {
        state.machine.disable_actuator("lights".into()).await
    } else {
        Ok(())
    };
    match (capture, lights_off) {
        (Ok(frame), Ok(())) => Ok((frame, measured_pose)),
        (Err(error), Ok(())) => Err(error),
        (Ok(_), Err(error)) => Err(format!("top-camera light cleanup failed: {error}")),
        (Err(error), Err(cleanup_error)) => Err(format!(
            "{error}; top-camera light cleanup also failed: {cleanup_error}"
        )),
    }
}

async fn execute_pickup_xy_transit(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    target: JogTarget,
    feed_mm_per_min: f64,
) -> Result<Pose, String> {
    state
        .profile
        .transit_motion
        .validate(state.profile.maximum_feed_mm_per_min)
        .map_err(str::to_string)?;
    let current = state
        .machine
        .status()
        .pose
        .ok_or_else(|| "pickup transit has no trusted machine pose".to_string())?;
    let logical_target = target
        .resolve(current)
        .ok_or_else(|| "pickup transit target is invalid".to_string())?;
    if (current.z_mm - logical_target.z_mm).abs() > 1e-9
        || (current.rotation_deg - logical_target.rotation_deg).abs() > 1e-9
    {
        return Err("pickup XY transit requires level Z and fixed rotation".into());
    }
    let mut motion_state = prepared
        .motion_planner
        .initial_state(current)
        .map_err(|error| error.to_string())?;
    execute_job_motion(
        &state.machine,
        prepared.lease_id,
        &prepared.motion_planner,
        &mut motion_state,
        logical_target,
        feed_mm_per_min,
        MotionMode::Calibrated,
    )
    .await?;
    state
        .machine
        .status()
        .pose
        .ok_or_else(|| "pickup transit lost the machine pose".to_string())
}

async fn capture_bottom_mean_with_lights(
    state: &AppState,
    lease_id: Uuid,
    camera_profile: &CameraProfile,
    camera_path: &str,
    sample_count: u32,
) -> Result<GrayFrame, String> {
    if camera_profile.lighting_enabled {
        state
            .machine
            .actuate(lease_id, "lights".into(), true)
            .await
            .map_err(|error| error.to_string())?;
    }
    let capture = capture_profiled_frames(state, camera_profile, camera_path, sample_count)
        .await
        .map_err(|error| error.message)
        .and_then(|frames| mean_gray_frames(&frames));
    let lights_off = if camera_profile.lighting_enabled {
        state.machine.disable_actuator("lights".into()).await
    } else {
        Ok(())
    };
    match (capture, lights_off) {
        (Ok(frame), Ok(())) => Ok(frame),
        (Err(error), Ok(())) => Err(error),
        (Ok(_), Err(error)) => Err(format!("bottom-camera light cleanup failed: {error}")),
        (Err(error), Err(cleanup_error)) => Err(format!(
            "{error}; bottom-camera light cleanup also failed: {cleanup_error}"
        )),
    }
}

async fn lift_and_restore_after_pickup(state: &AppState, lease_id: Uuid) -> Result<(), String> {
    let status = state.machine.status();
    let pose = status
        .pose
        .ok_or_else(|| "pickup cleanup has no trusted pose".to_string())?;
    let z_kinematics = state.profile.z_kinematics.as_ref().unwrap();
    if (pose.z_mm - z_kinematics.level_controller_z_mm).abs() > 1e-9 {
        move_vertical_at_current_xy(
            state,
            lease_id,
            z_kinematics.level_controller_z_mm,
            state.profile.transit_motion.carried_z_feed_mm_per_min,
        )
        .await?;
    }
    restore_level_visual_home(state, lease_id, None).await
}

fn update_registration_after_pickup(
    state: &AppState,
    mut registration: StripFeederRegistration,
    qualification_id: Uuid,
    report: &StripFeederPickupQualificationReport,
) -> Result<(), String> {
    registration.latest_pickup_qualification_id = Some(qualification_id);
    registration.latest_pickup_sequence_qualification_ids =
        current_pickup_sequence_ids(state, &registration)?;
    registration.pickup_sequence_passed =
        registration.latest_pickup_sequence_qualification_ids.len() >= 3;
    registration.updated_at = Utc::now();
    registration.findings.retain(|finding| {
        !finding.contains("pickup qualification")
            && !finding.contains("pickup-return qualification")
            && !finding.contains("pickup Z, vacuum hold")
            && !finding.contains("guarded inspected placement")
            && !finding.contains("guarded board placement")
    });
    if let Some(inspection) = report
        .inspection
        .as_ref()
        .filter(|inspection| inspection.passed)
    {
        registration.measured_part_size_mm = inspection
            .width_mm
            .zip(inspection.length_mm)
            .map(|(width, length)| [width, length]);
        registration.measured_part_rotation_deg = report
            .alignment
            .as_ref()
            .and_then(|alignment| alignment.observations.first())
            .and_then(|observation| observation.inspection.rotation_deg)
            .or(inspection.rotation_deg);
        registration.measured_part_confidence = Some(inspection.confidence);
    }
    if report.passed {
        registration.pickup_z_mm = report.pickup_nozzle_z_mm;
        registration.selected_pocket_index = nearest_strip_feeder_pocket_index(
            &registration.pocket_centers_machine_mm,
            report.pocket_machine_mm,
        )
        .or(registration.selected_pocket_index);
        if registration.pickup_sequence_passed
            || registration.latest_placement_validation_id.is_some()
        {
            if activate_strip_feeder(state, &mut registration, report)? {
                registration.status = StripFeederRegistrationStatus::Ready;
                registration.findings.push(
                    if registration.pickup_sequence_passed {
                        "three successful pickup-return qualifications at distinct pockets passed"
                    } else {
                        "guarded board placement and top inspection remain current"
                    }
                    .into(),
                );
                registration.findings.push(
                    "pickup Z, vacuum hold, bottom inspection, nozzle release, and pocket return passed"
                        .into(),
                );
            } else {
                deactivate_strip_feeder(state, &mut registration)?;
                registration.status = StripFeederRegistrationStatus::LiveValidationRequired;
                registration.findings.push(
                    "pickup qualification passed; part identity and orientation are still required"
                        .into(),
                );
            }
        } else if activate_strip_feeder(state, &mut registration, report)? {
            registration.status = StripFeederRegistrationStatus::PlacementValidationRequired;
            registration.findings.push(
                "one pickup-return qualification passed; one guarded inspected placement is required"
                    .into(),
            );
        } else {
            deactivate_strip_feeder(state, &mut registration)?;
            registration.status = StripFeederRegistrationStatus::LiveValidationRequired;
            registration.findings.push(
                "pickup qualification passed; part identity and orientation are still required"
                    .into(),
            );
        }
    } else {
        deactivate_strip_feeder(state, &mut registration)?;
        registration.latest_placement_validation_id = None;
        registration.pickup_z_mm = None;
        registration.status = StripFeederRegistrationStatus::LiveValidationRequired;
        registration
            .findings
            .push("latest pickup qualification did not pass".into());
    }
    state
        .store
        .put_strip_feeder_registration(&registration)
        .map_err(|error| error.to_string())
}

fn activate_strip_feeder(
    state: &AppState,
    registration: &mut StripFeederRegistration,
    report: &StripFeederPickupQualificationReport,
) -> Result<bool, String> {
    let (Some(part_key), Some(part_rotation_deg), Some(pickup_z_mm)) = (
        registration.part_key.clone(),
        registration.part_rotation_deg,
        report.pickup_nozzle_z_mm,
    ) else {
        return Ok(false);
    };
    let feeder_id = registration.active_feeder_id.unwrap_or_else(Uuid::new_v4);
    let remaining = registration
        .pockets
        .iter()
        .filter(|pocket| {
            pocket.status == StripFeederPocketStatus::Available
                && pocket.occupancy == StripPocketOccupancy::Occupied
        })
        .count()
        .try_into()
        .ok();
    state
        .store
        .put_feeder(&Feeder::Strip {
            id: feeder_id,
            name: registration.name.clone(),
            part_key,
            first_pick: Pose {
                x_mm: report.pocket_machine_mm[0],
                y_mm: report.pocket_machine_mm[1],
                z_mm: pickup_z_mm,
                rotation_deg: part_rotation_deg,
            },
            tape_pitch_mm: registration.tape_pitch_mm,
            tape_width_mm: registration.tape_width_mm,
            tape_rotation_deg: registration.tape_rotation_deg,
            remaining,
        })
        .map_err(|error| error.to_string())?;
    registration.active_feeder_id = Some(feeder_id);
    Ok(true)
}

fn current_pickup_sequence_ids(
    state: &AppState,
    registration: &StripFeederRegistration,
) -> Result<Vec<Uuid>, String> {
    let mut runs = state
        .store
        .list_strip_feeder_pickup_qualifications()
        .map_err(|error| error.to_string())?
        .into_iter()
        .filter(|run| {
            run.registration_id == registration.id
                && !matches!(
                    run.status,
                    OperationStatus::Pending | OperationStatus::Running
                )
        })
        .collect::<Vec<_>>();
    runs.sort_by(|left, right| {
        right
            .updated_at
            .cmp(&left.updated_at)
            .then_with(|| right.created_at.cmp(&left.created_at))
            .then_with(|| right.id.cmp(&left.id))
    });
    runs.truncate(3);
    if runs.len() != 3 {
        return Ok(Vec::new());
    }
    let pocket_indexes = runs
        .iter()
        .map(|run| run.pocket_index)
        .collect::<BTreeSet<_>>();
    let nozzle_ids = runs
        .iter()
        .map(|run| run.nozzle_id.as_str())
        .collect::<BTreeSet<_>>();
    let all_passed = runs.iter().all(|run| {
        run.status == OperationStatus::Succeeded
            && run.calibration_id == registration.calibration_id
            && run.report.as_ref().is_some_and(|report| {
                report.algorithm_version == STRIP_FEEDER_PICKUP_ALGORITHM
                    && pickup_report_uses_current_transit(&state.profile, report)
                    && report.nozzle_id == run.nozzle_id
                    && report.passed
                    && report.disposition == StripFeederPickupDisposition::ReturnedToPocket
                    && report.released
                    && report
                        .nozzle_release_verification
                        .as_ref()
                        .is_some_and(|verification| verification.passed)
                    && report
                        .return_verification
                        .as_ref()
                        .is_some_and(|verification| verification.passed)
            })
    });
    if !all_passed || pocket_indexes.len() != 3 || nozzle_ids.len() != 1 {
        return Ok(Vec::new());
    }
    let mut ids = runs.into_iter().map(|run| run.id).collect::<Vec<_>>();
    ids.reverse();
    Ok(ids)
}

fn pickup_report_uses_current_transit(
    profile: &MachineProfile,
    report: &StripFeederPickupQualificationReport,
) -> bool {
    (report.clear_xy_feed_mm_per_min - profile.transit_motion.clear_xy_feed_mm_per_min).abs() < 1e-6
        && (report.carried_xy_feed_mm_per_min - profile.transit_motion.carried_xy_feed_mm_per_min)
            .abs()
            < 1e-6
        && (report.clear_z_feed_mm_per_min - profile.transit_motion.clear_z_feed_mm_per_min).abs()
            < 1e-6
        && (report.carried_z_feed_mm_per_min - profile.transit_motion.carried_z_feed_mm_per_min)
            .abs()
            < 1e-6
        && (report.precision_z_approach_mm - profile.transit_motion.precision_z_approach_mm).abs()
            < 1e-6
}

fn deactivate_strip_feeder(
    state: &AppState,
    registration: &mut StripFeederRegistration,
) -> Result<(), String> {
    if let Some(feeder_id) = registration.active_feeder_id.take() {
        state
            .store
            .delete_feeder(feeder_id)
            .map_err(|error| error.to_string())?;
    }
    Ok(())
}

fn invalidate_registration_after_pickup_error(
    state: &AppState,
    registration_id: Uuid,
    qualification_id: Uuid,
) -> Result<(), String> {
    let Some(mut registration) = state
        .store
        .get_strip_feeder_registration(registration_id)
        .map_err(|error| error.to_string())?
    else {
        return Ok(());
    };
    deactivate_strip_feeder(state, &mut registration)?;
    registration.latest_pickup_qualification_id = Some(qualification_id);
    registration.pickup_sequence_passed = false;
    registration
        .latest_pickup_sequence_qualification_ids
        .clear();
    registration.latest_placement_validation_id = None;
    registration.pickup_z_mm = None;
    registration.status = StripFeederRegistrationStatus::LiveValidationRequired;
    registration.updated_at = Utc::now();
    registration.findings.retain(|finding| {
        !finding.contains("pickup qualification")
            && !finding.contains("pickup-return qualifications")
            && !finding.contains("pickup Z, vacuum hold")
    });
    registration
        .findings
        .push("latest pickup qualification was interrupted".into());
    state
        .store
        .put_strip_feeder_registration(&registration)
        .map_err(|error| error.to_string())
}

fn nearest_strip_feeder_pocket_index(
    pocket_centers_machine_mm: &[[f64; 2]],
    point_machine_mm: [f64; 2],
) -> Option<u32> {
    point_machine_mm
        .iter()
        .all(|value| value.is_finite())
        .then_some(())?;
    pocket_centers_machine_mm
        .iter()
        .enumerate()
        .filter(|(_, center)| center.iter().all(|value| value.is_finite()))
        .min_by(|(_, first), (_, second)| {
            let first_distance =
                (first[0] - point_machine_mm[0]).powi(2) + (first[1] - point_machine_mm[1]).powi(2);
            let second_distance = (second[0] - point_machine_mm[0]).powi(2)
                + (second[1] - point_machine_mm[1]).powi(2);
            first_distance.total_cmp(&second_distance)
        })
        .and_then(|(index, _)| u32::try_from(index).ok())
}

fn planned_available_strip_feeder_pocket(
    registration: &StripFeederRegistration,
    planned_pick: Pose,
) -> Option<&StripFeederPocketState> {
    let maximum_distance_mm = 0.5 * registration.tape_pitch_mm;
    registration
        .pockets
        .iter()
        .filter(|pocket| {
            pocket.status == StripFeederPocketStatus::Available
                && pocket.occupancy == StripPocketOccupancy::Occupied
        })
        .filter_map(|pocket| {
            let center = pocket
                .measured_center_machine_mm
                .unwrap_or(pocket.nominal_center_machine_mm);
            let distance_mm = (center[0] - planned_pick.x_mm).hypot(center[1] - planned_pick.y_mm);
            (distance_mm <= maximum_distance_mm).then_some((distance_mm, pocket))
        })
        .min_by(|left, right| left.0.total_cmp(&right.0))
        .map(|(_, pocket)| pocket)
}

fn placement_available_strip_feeder_pocket(
    registration: &StripFeederRegistration,
    planned_pick: Pose,
    prefer_selected_pocket: bool,
) -> Option<&StripFeederPocketState> {
    let selected = prefer_selected_pocket
        .then_some(registration.selected_pocket_index)
        .flatten()
        .and_then(|selected_index| {
            registration.pockets.iter().find(|pocket| {
                pocket.pocket_index == selected_index
                    && pocket.status == StripFeederPocketStatus::Available
                    && pocket.occupancy == StripPocketOccupancy::Occupied
            })
        });
    selected
        .or_else(|| planned_available_strip_feeder_pocket(registration, planned_pick))
        .or_else(|| registration.next_available_pocket(None))
}

fn vacuum_value_is_acquired(
    characterization: &VacuumSensorCharacterizationReport,
    value: f64,
) -> bool {
    match characterization.signal_polarity {
        velocitypnp_domain::VacuumSignalPolarity::LowerIsMoreVacuum => {
            value <= characterization.acquire_threshold_raw_value
        }
        velocitypnp_domain::VacuumSignalPolarity::HigherIsMoreVacuum => {
            value >= characterization.acquire_threshold_raw_value
        }
    }
}

fn marginal_transfer_vacuum_is_separated(
    open: &VacuumStateStatistics,
    expected_polarity: VacuumSignalPolarity,
    minimum_signal_delta_counts: i64,
    minimum_distribution_gap_counts: i64,
    held_raw_values: &[i64],
) -> bool {
    let Some(held) = VacuumStateStatistics::from_raw(held_raw_values.to_vec()) else {
        return false;
    };
    let minimum_fused_delta_counts = ((minimum_signal_delta_counts + 1) / 2)
        .max(minimum_distribution_gap_counts)
        .max(1);
    calculate_vacuum_classification_thresholds(
        open,
        &held,
        minimum_fused_delta_counts,
        minimum_distribution_gap_counts,
    )
    .is_some_and(|thresholds| thresholds.passed && thresholds.signal_polarity == expected_polarity)
}

fn vacuum_value_is_released(
    characterization: &VacuumSensorCharacterizationReport,
    value: f64,
) -> bool {
    let off = &characterization.pump_off;
    let off_margin = (3.0 * off.standard_deviation_counts).max(2.0);
    let matches_pump_off_state =
        value >= off.p05_raw_value - off_margin && value <= off.p95_raw_value + off_margin;
    let crosses_release_threshold = match characterization.signal_polarity {
        velocitypnp_domain::VacuumSignalPolarity::LowerIsMoreVacuum => {
            value >= characterization.release_threshold_raw_value
        }
        velocitypnp_domain::VacuumSignalPolarity::HigherIsMoreVacuum => {
            value <= characterization.release_threshold_raw_value
        }
    };
    matches_pump_off_state || crosses_release_threshold
}

