fn mean_gray_frames(frames: &[GrayFrame]) -> Result<GrayFrame, String> {
    let first = frames
        .first()
        .ok_or_else(|| "camera returned no frames".to_string())?;
    if frames.iter().any(|frame| {
        frame.width != first.width
            || frame.height != first.height
            || frame.pixels.len() != first.pixels.len()
    }) {
        return Err("camera returned incompatible frames".into());
    }
    let mut sums = vec![0_u32; first.pixels.len()];
    for frame in frames {
        for (sum, value) in sums.iter_mut().zip(&frame.pixels) {
            *sum += u32::from(*value);
        }
    }
    Ok(GrayFrame {
        width: first.width,
        height: first.height,
        pixels: sums
            .into_iter()
            .map(|sum| (sum / frames.len() as u32) as u8)
            .collect(),
    })
}

fn ensure_no_active_strip_feeder_pickup_qualifications(state: &AppState) -> ApiResult<()> {
    let active = state
        .store
        .list_strip_feeder_pickup_qualifications()
        .map_err(ApiError::internal)?
        .into_iter()
        .any(|run| {
            matches!(
                run.status,
                OperationStatus::Pending | OperationStatus::Running
            )
        });
    if active {
        return Err(ApiError::bad_request(
            "a strip-feeder pickup qualification is already active",
        ));
    }
    Ok(())
}

fn sensor_id_for_nozzle(nozzle_id: &str) -> Option<&'static str> {
    match nozzle_id {
        "N1" => Some("vacuum_1"),
        "N2" => Some("vacuum_2"),
        _ => None,
    }
}

async fn get_strip_feeder_pickup_qualification(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<StripFeederPickupQualificationRun>> {
    state
        .store
        .get_strip_feeder_pickup_qualification(id)
        .map_err(ApiError::internal)?
        .map(Json)
        .ok_or_else(|| ApiError::not_found("strip feeder pickup qualification not found"))
}

async fn reanalyze_strip_feeder_pickup_return(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<StripFeederPickupQualificationRun>> {
    let mut run = state
        .store
        .get_strip_feeder_pickup_qualification(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("strip feeder pickup qualification not found"))?;
    if matches!(
        run.status,
        OperationStatus::Pending | OperationStatus::Running
    ) {
        return Err(ApiError::bad_request(
            "pickup return evidence is not complete",
        ));
    }
    let mut report = run
        .report
        .clone()
        .ok_or_else(|| ApiError::bad_request("pickup qualification has no retained report"))?;
    if report.disposition != StripFeederPickupDisposition::ReturnedToPocket || !report.released {
        return Err(ApiError::bad_request(
            "pickup qualification has no completed source-pocket return",
        ));
    }
    let prior_verification = report
        .return_verification
        .clone()
        .ok_or_else(|| ApiError::bad_request("pickup qualification has no return evidence"))?;
    let registration = state
        .store
        .get_strip_feeder_registration(run.registration_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("strip feeder registration not found"))?;
    if registration.latest_pickup_qualification_id != Some(run.id) {
        return Err(ApiError::bad_request(
            "only the latest pickup qualification can change pocket state",
        ));
    }
    let load_frame = |name: &str| -> ApiResult<GrayFrame> {
        let (media_type, data) = state
            .store
            .get_strip_feeder_pickup_artifact(id, name)
            .map_err(ApiError::internal)?
            .ok_or_else(|| ApiError::not_found(format!("pickup artifact {name} not found")))?;
        if media_type != "image/png" {
            return Err(ApiError::bad_request(format!(
                "pickup artifact {name} is not a PNG"
            )));
        }
        decode_gray_png(&data).map_err(ApiError::internal)
    };
    let before = load_frame(SOURCE_POCKET_BEFORE_ARTIFACT)?;
    let after = load_frame(SOURCE_POCKET_AFTER_ARTIFACT)?;
    let (_, camera_model) = load_workspace_camera_model(&state, run.calibration_id)?;
    let nominal = prior_verification
        .nominal_center_machine_mm
        .unwrap_or(report.pocket_machine_mm);
    let fallback_pose = Pose {
        x_mm: nominal[0],
        y_mm: nominal[1],
        z_mm: state.profile.safe_z_mm,
        rotation_deg: 0.0,
    };
    let before_pose = prior_verification
        .before_camera_pose
        .unwrap_or(fallback_pose);
    let after_pose = prior_verification
        .after_camera_pose
        .unwrap_or(fallback_pose);
    let artifact_name = prior_verification.artifact_name.clone();
    let verification = tokio::task::spawn_blocking(move || {
        inspect_strip_feeder_pocket_return(
            &before,
            before_pose,
            &after,
            after_pose,
            &camera_model,
            &registration,
            nominal,
            &artifact_name,
        )
    })
    .await
    .map_err(ApiError::internal)?
    .map_err(ApiError::internal)?;
    persist_pickup_rgb_artifact(
        &state,
        id,
        &verification.report.artifact_name,
        &verification.preview,
    )
    .map_err(ApiError::internal)?;

    report.findings.retain(|finding| {
        !prior_verification.findings.contains(finding)
            && !finding.contains("pickup, transfer, bottom inspection, release")
            && !finding.contains("retained return reanalysis")
    });
    report.findings.extend(verification.report.findings.clone());
    report.return_verification = Some(verification.report.clone());
    report.passed = report.vacuum_acquired
        && report.vacuum_held_after_transfer
        && report
            .inspection
            .as_ref()
            .is_some_and(|inspection| inspection.passed)
        && report
            .alignment
            .as_ref()
            .is_none_or(|alignment| alignment.passed)
        && report.released
        && report
            .nozzle_release_verification
            .as_ref()
            .is_some_and(|verification| verification.passed)
        && verification.report.passed;
    let message = if report.passed {
        report
            .findings
            .push("retained return reanalysis passed".into());
        "Retained source-pocket return reanalysis passed".to_string()
    } else {
        report
            .findings
            .push("retained return reanalysis rejected the release outcome".into());
        "Retained source-pocket return reanalysis failed".to_string()
    };
    run.status = if report.passed {
        OperationStatus::Succeeded
    } else {
        OperationStatus::Failed
    };
    run.report = Some(report.clone());
    run.message = Some(message.clone());
    run.updated_at = Utc::now();
    state
        .store
        .put_strip_feeder_pickup_qualification(&run)
        .map_err(ApiError::internal)?;
    let outcome = if verification.report.passed {
        StripFeederPocketOutcome::Returned
    } else {
        StripFeederPocketOutcome::ReleaseUncertain
    };
    let registration = state
        .store
        .reconcile_strip_feeder_pocket_qualification(run.registration_id, run.id, outcome)
        .map_err(ApiError::internal)?;
    update_registration_after_pickup(&state, registration, run.id, &report)
        .map_err(ApiError::internal)?;
    if let Some(mut operation) = state
        .store
        .get_operation(run.operation_id)
        .map_err(ApiError::internal)?
    {
        operation.status = run.status;
        operation.message = Some(message);
        operation.updated_at = Utc::now();
        state
            .store
            .put_operation(&operation)
            .map_err(ApiError::internal)?;
    }
    Ok(Json(run))
}

async fn get_strip_feeder_pickup_artifact(
    State(state): State<AppState>,
    Path((id, name)): Path<(Uuid, String)>,
) -> ApiResult<Response> {
    let (media_type, data) = state
        .store
        .get_strip_feeder_pickup_artifact(id, &name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("strip feeder pickup artifact not found"))?;
    Response::builder()
        .status(StatusCode::OK)
        .header(header::CONTENT_TYPE, media_type)
        .header(header::CACHE_CONTROL, "no-store")
        .body(axum::body::Body::from(data))
        .map_err(ApiError::internal)
}

#[derive(Debug, Deserialize)]
struct StartBoardRegistrationRequest {
    lease_id: Uuid,
    candidate_index: u32,
    board_id: Uuid,
    #[serde(default)]
    label: Option<String>,
    #[serde(default = "default_board_registration_sample_count")]
    sample_count: u32,
    confirmed_external_safety_checks: bool,
}

#[derive(Debug, Serialize)]
struct StartBoardRegistrationResponse {
    registration: BoardRegistrationRun,
    operation: Operation,
}

fn default_board_registration_sample_count() -> u32 {
    3
}

async fn start_board_registration(
    State(state): State<AppState>,
    Path(scan_id): Path<Uuid>,
    Json(body): Json<StartBoardRegistrationRequest>,
) -> ApiResult<(StatusCode, Json<StartBoardRegistrationResponse>)> {
    if !body.confirmed_external_safety_checks {
        return Err(ApiError::bad_request(
            "board registration requires confirmation that the PCB is fixed, both nozzles are level, the travel envelope is clear, and power isolation is reachable",
        ));
    }
    if !(3..=5).contains(&body.sample_count) {
        return Err(ApiError::bad_request(
            "board registration sample_count must be between 3 and 5",
        ));
    }
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed || status.pose.is_none() {
        return Err(ApiError::bad_request(
            "board registration requires a homed ready machine",
        ));
    }
    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(&state)?;
    ensure_no_active_board_registrations(&state)?;
    ensure_no_active_board_surface_measurements(&state)?;
    ensure_no_active_strip_feeder_holdouts(&state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(&state)?;
    let scan = state
        .store
        .get_workspace_scan(scan_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("workspace scan not found"))?;
    if scan.status != WorkspaceScanStatus::Succeeded
        || !state.profile.accepts_profile_id(&scan.profile_id)
    {
        return Err(ApiError::bad_request(
            "board registration requires a successful scan from the active machine profile",
        ));
    }
    if !status.simulated && status.calibration_revision != Some(scan.calibration_id) {
        return Err(ApiError::bad_request(format!(
            "board registration requires fine XYZ homing with calibration {}",
            scan.calibration_id,
        )));
    }
    let report = load_workspace_object_report(&state, &scan)?;
    let candidate = report
        .candidates
        .iter()
        .find(|candidate| candidate.candidate_index == body.candidate_index)
        .ok_or_else(|| ApiError::bad_request("workspace candidate was not found"))?;
    let design_match = candidate
        .design_matches
        .iter()
        .find(|design_match| design_match.board_id == body.board_id)
        .filter(|design_match| {
            design_match.registration_method
                == velocitypnp_domain::WorkspaceBoardRegistrationMethod::VisualOutline
        })
        .cloned()
        .ok_or_else(|| {
            ApiError::bad_request(
                "board registration requires a visual-outline match for the selected design",
            )
        })?;
    let seed_center_x_mm = design_match
        .center_x_mm
        .ok_or_else(|| ApiError::bad_request("board match has no visual center X"))?;
    let seed_center_y_mm = design_match
        .center_y_mm
        .ok_or_else(|| ApiError::bad_request("board match has no visual center Y"))?;
    let board = state
        .store
        .get_board(body.board_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("board design not found"))?;
    if board.outline_bounds.is_none() {
        return Err(ApiError::bad_request(
            "board registration requires usable Edge.Cuts bounds",
        ));
    }
    let fiducial_count = board
        .placements
        .iter()
        .filter(|placement| {
            placement.enabled && placement.fiducial && placement.side == BoardSide::Top
        })
        .count();
    if fiducial_count < 3 {
        return Err(ApiError::bad_request(
            "automatic board registration requires at least three enabled top-side fiducials",
        ));
    }
    let (_, camera_model) = load_workspace_camera_model(&state, scan.calibration_id)?;
    let camera_profile = stored_camera_profile(&state, CameraRole::TopCamera)?;
    let camera_path = camera_path_for_role(CameraRole::TopCamera)?;
    let visual = state
        .profile
        .visual_homing
        .as_ref()
        .cloned()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let operation = Operation::pending("vision.board_registration");
    let now = Utc::now();
    let registration = BoardRegistrationRun {
        id: Uuid::new_v4(),
        operation_id: operation.id,
        profile_id: scan.profile_id.clone(),
        calibration_id: scan.calibration_id,
        source_scan_id: scan.id,
        source_candidate_index: candidate.candidate_index,
        board_id: board.id,
        label: body.label.unwrap_or_else(|| board.name.clone()),
        side: BoardSide::Top,
        status: OperationStatus::Pending,
        created_at: now,
        updated_at: now,
        sample_count: body.sample_count,
        seed_center_x_mm,
        seed_center_y_mm,
        seed_rotation_deg: design_match.rotation_deg,
        hypotheses: Vec::new(),
        selected_rotation_deg: None,
        fit_residuals: None,
        design_to_machine: None,
        board_instance: None,
        latest_surface_measurement_id: None,
        passed: false,
        message: None,
    };
    state
        .machine
        .renew_lease(body.lease_id, 900)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    state
        .store
        .put_operation(&operation)
        .map_err(ApiError::internal)?;
    state
        .store
        .put_board_registration(&registration)
        .map_err(ApiError::internal)?;
    drop(admission_guard);
    let response = StartBoardRegistrationResponse {
        registration: registration.clone(),
        operation: operation.clone(),
    };
    let task_state = state.clone();
    spawn_prepared_operation(
        state,
        operation,
        execute_board_registration_task(
            task_state,
            registration,
            board,
            design_match,
            camera_model,
            camera_profile,
            camera_path,
            visual,
            body.lease_id,
        ),
    );
    Ok((StatusCode::ACCEPTED, Json(response)))
}

#[allow(clippy::too_many_arguments)]
async fn execute_board_registration_task(
    state: AppState,
    mut run: BoardRegistrationRun,
    board: BoardDesign,
    design_match: WorkspaceBoardDesignMatch,
    camera_model: PlanarCameraModel,
    camera_profile: CameraProfile,
    camera_path: String,
    visual: VisualHomingProfile,
    lease_id: Uuid,
) -> Result<Option<String>, String> {
    let task_started = Instant::now();
    let operation_id = run.operation_id;
    let simulated = state.machine.status().simulated;
    run.status = OperationStatus::Running;
    run.updated_at = Utc::now();
    state
        .store
        .put_board_registration(&run)
        .map_err(|error| error.to_string())?;
    let (result, camera_timing) = if simulated {
        (
            execute_board_registration(
                &state,
                &mut run,
                &board,
                &design_match,
                &camera_model,
                &camera_profile,
                &camera_path,
                &visual,
                lease_id,
            )
            .await,
            json!({}),
        )
    } else {
        let operation_state = state.clone();
        with_profiled_camera_reuse(
            &state,
            execute_board_registration(
                &operation_state,
                &mut run,
                &board,
                &design_match,
                &camera_model,
                &camera_profile,
                &camera_path,
                &visual,
                lease_id,
            ),
        )
        .await
    };
    record_camera_target_operation_timing(
        &state,
        operation_id,
        "board_registration",
        simulated,
        result.is_ok(),
        elapsed_ms(task_started),
        camera_timing,
    )
    .await;
    match result {
        Ok(message) => {
            run.status = OperationStatus::Succeeded;
            run.passed = true;
            run.message = Some(message.clone());
            run.updated_at = Utc::now();
            state
                .store
                .put_board_registration(&run)
                .map_err(|error| error.to_string())?;
            Ok(Some(message))
        }
        Err(message) => {
            run.status = OperationStatus::Failed;
            run.passed = false;
            run.message = Some(message.clone());
            run.updated_at = Utc::now();
            if let Err(error) = state.store.put_board_registration(&run) {
                tracing::error!(%error, registration_id = %run.id, "failed to persist rejected board registration");
            }
            Err(message)
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn execute_board_registration(
    state: &AppState,
    run: &mut BoardRegistrationRun,
    board: &BoardDesign,
    design_match: &WorkspaceBoardDesignMatch,
    camera_model: &PlanarCameraModel,
    camera_profile: &CameraProfile,
    camera_path: &str,
    visual: &VisualHomingProfile,
    lease_id: Uuid,
) -> Result<String, String> {
    let _motion_guard = state.workspace_scan_motion_lock.lock().await;
    execute_visual_home(
        state,
        VisualHomingRequest {
            lease_id,
            apply_offset: true,
            move_to_seed: true,
        },
    )
    .await
    .map_err(|error| {
        format!(
            "visual home before board registration failed: {}",
            error.message
        )
    })?;
    let mut motion =
        operation_motion_sequence(state, run.calibration_id, "board registration motion")?;
    if camera_profile.lighting_enabled {
        state
            .machine
            .actuate(lease_id, "lights".into(), true)
            .await
            .map_err(|error| error.to_string())?;
    }
    let result = measure_board_registration(
        state,
        run,
        board,
        design_match,
        camera_model,
        camera_profile,
        camera_path,
        visual,
        lease_id,
        &mut motion,
    )
    .await;
    let return_feed_mm_per_min = safe_level_xy_feed(
        &state.profile,
        Some(motion.state.logical_pose),
        visual.seed_pose,
        visual.feed_mm_per_min,
    );
    let return_result = execute_calibrated_motion(
        state,
        lease_id,
        &mut motion,
        visual.seed_pose,
        return_feed_mm_per_min,
    )
    .await;
    let lights_result = if camera_profile.lighting_enabled {
        state.machine.disable_actuator("lights".into()).await
    } else {
        Ok(())
    };
    if let Err(error) = return_result {
        return Err(format!("board registration return move failed: {error}"));
    }
    if let Err(error) = lights_result {
        return Err(format!("board registration light cleanup failed: {error}"));
    }
    result
}

#[allow(clippy::too_many_arguments)]
async fn measure_board_registration(
    state: &AppState,
    run: &mut BoardRegistrationRun,
    board: &BoardDesign,
    design_match: &WorkspaceBoardDesignMatch,
    camera_model: &PlanarCameraModel,
    camera_profile: &CameraProfile,
    camera_path: &str,
    visual: &VisualHomingProfile,
    lease_id: Uuid,
    motion: &mut CalibratedMotionSequence,
) -> Result<String, String> {
    let bounds = board
        .outline_bounds
        .ok_or_else(|| "board has no Edge.Cuts bounds".to_string())?;
    let mut fiducials = board
        .placements
        .iter()
        .filter(|placement| {
            placement.enabled && placement.fiducial && placement.side == BoardSide::Top
        })
        .collect::<Vec<_>>();
    fiducials.sort_by(|left, right| left.reference.cmp(&right.reference));
    let hypothesis_count = if design_match.orientation_ambiguous {
        4
    } else {
        1
    };
    for orientation_index in 0..hypothesis_count {
        let seed_rotation_deg =
            normalize_angle_deg(design_match.rotation_deg + 90.0 * f64::from(orientation_index));
        let seed_transform = velocitypnp_domain::top_side_board_transform(
            bounds,
            [run.seed_center_x_mm, run.seed_center_y_mm],
            seed_rotation_deg,
        );
        let mut hypothesis = BoardRegistrationHypothesis {
            orientation_index,
            seed_rotation_deg,
            observations: Vec::new(),
            rejection_reason: None,
        };
        for fiducial in &fiducials {
            match observe_board_fiducial(
                state,
                run.id,
                orientation_index,
                fiducial,
                seed_transform,
                camera_model,
                camera_profile,
                camera_path,
                visual,
                lease_id,
                run.sample_count,
                motion,
            )
            .await
            {
                Ok(observation) => hypothesis.observations.push(observation),
                Err(message) => {
                    hypothesis.rejection_reason = Some(message);
                    break;
                }
            }
        }
        if hypothesis.rejection_reason.is_none() {
            let design_points = hypothesis
                .observations
                .iter()
                .map(|item| (item.design_x_mm, item.design_y_mm))
                .collect::<Vec<_>>();
            let measured_points = hypothesis
                .observations
                .iter()
                .map(|item| (item.measured_x_mm, item.measured_y_mm))
                .collect::<Vec<_>>();
            let fit = fit_top_side_board_registration(bounds, &design_points, &measured_points)
                .ok_or_else(|| "board fiducials did not produce a rigid transform".to_string())?;
            let rotation_error = angle_difference_deg(fit.rotation_deg, seed_rotation_deg).abs();
            if fit.residuals.max_mm > BOARD_REGISTRATION_MAX_RESIDUAL_MM {
                hypothesis.rejection_reason = Some(format!(
                    "fiducial fit residual {:.3} mm exceeds {:.3} mm",
                    fit.residuals.max_mm, BOARD_REGISTRATION_MAX_RESIDUAL_MM,
                ));
            } else if rotation_error > BOARD_REGISTRATION_MAX_ROTATION_ERROR_DEG {
                hypothesis.rejection_reason = Some(format!(
                    "fitted rotation differs from the seed by {rotation_error:.3} degrees",
                ));
            } else {
                let board_instance = BoardInstance {
                    id: Uuid::new_v4(),
                    board_id: board.id,
                    label: run.label.clone(),
                    side: BoardSide::Top,
                    design_to_machine: Some(fit.design_to_machine),
                    surface_z_mm: None,
                    placement_surface_offset_mm: 0.0,
                };
                run.selected_rotation_deg = Some(fit.rotation_deg);
                run.fit_residuals = Some(fit.residuals);
                run.design_to_machine = Some(fit.design_to_machine);
                run.board_instance = Some(board_instance);
                run.hypotheses.push(hypothesis);
                run.updated_at = Utc::now();
                state
                    .store
                    .put_board_registration(run)
                    .map_err(|error| error.to_string())?;
                return Ok(format!(
                    "Registered {} from {} fiducials at {:.3} degrees with {:.3} mm maximum residual; board surface Z remains unmeasured",
                    board.name,
                    design_points.len(),
                    fit.rotation_deg,
                    fit.residuals.max_mm,
                ));
            }
        }
        run.hypotheses.push(hypothesis);
        run.updated_at = Utc::now();
        state
            .store
            .put_board_registration(run)
            .map_err(|error| error.to_string())?;
    }
    let reasons = run
        .hypotheses
        .iter()
        .filter_map(|hypothesis| hypothesis.rejection_reason.as_deref())
        .collect::<Vec<_>>()
        .join("; ");
    Err(format!(
        "no board orientation passed local fiducial verification: {reasons}"
    ))
}

#[allow(clippy::too_many_arguments)]
async fn observe_board_fiducial(
    state: &AppState,
    registration_id: Uuid,
    orientation_index: u32,
    fiducial: &velocitypnp_domain::Placement,
    seed_transform: velocitypnp_domain::Transform2d,
    camera_model: &PlanarCameraModel,
    camera_profile: &CameraProfile,
    camera_path: &str,
    visual: &VisualHomingProfile,
    lease_id: Uuid,
    sample_count: u32,
    motion: &mut CalibratedMotionSequence,
) -> Result<BoardRegistrationFiducialObservation, String> {
    let predicted = seed_transform.apply(fiducial.pose.x_mm, fiducial.pose.y_mm);
    let target = Pose {
        x_mm: predicted.0,
        y_mm: predicted.1,
        z_mm: state.profile.safe_z_mm,
        rotation_deg: 0.0,
    };
    if !state.profile.bounds.contains(target) {
        return Err(format!(
            "predicted {} position is outside machine bounds",
            fiducial.reference
        ));
    }
    state
        .machine
        .renew_lease(lease_id, 900)
        .await
        .map_err(|error| error.to_string())?;
    let measured_pose =
        jog_board_registration_target(state, lease_id, target, visual, motion).await?;
    let scale_mm_per_px = camera_model
        .local_mm_per_pixel(camera_model.center_x_px, camera_model.center_y_px)
        .ok_or_else(|| "top-camera model has no local center scale".to_string())?;
    let frames = capture_profiled_frames(state, camera_profile, camera_path, sample_count)
        .await
        .map_err(|error| error.message)?;
    let expected = [camera_model.center_x_px, camera_model.center_y_px];
    let search_radius_px = BOARD_REGISTRATION_SEARCH_RADIUS_MM / scale_mm_per_px;
    let expected_diameter_px = BOARD_REGISTRATION_FIDUCIAL_DIAMETER_MM / scale_mm_per_px;
    let diameter_tolerance_px = BOARD_REGISTRATION_FIDUCIAL_DIAMETER_TOLERANCE_MM / scale_mm_per_px;
    let detections = frames
        .iter()
        .filter_map(|frame| {
            detect_board_fiducial_near(
                frame,
                expected[0],
                expected[1],
                search_radius_px,
                expected_diameter_px,
                diameter_tolerance_px,
            )
        })
        .collect::<Vec<_>>();
    let required_detections = (2 * sample_count).div_ceil(3);
    let detection = (detections.len() >= required_detections as usize)
        .then(|| mean_fiducial_detection(&detections))
        .flatten();
    let artifact_name = format!(
        "hypothesis-{orientation_index}-{}.png",
        fiducial
            .reference
            .chars()
            .map(|character| {
                if character.is_ascii_alphanumeric() {
                    character.to_ascii_lowercase()
                } else {
                    '-'
                }
            })
            .collect::<String>(),
    );
    let evidence = render_board_fiducial_evidence(
        frames
            .last()
            .ok_or_else(|| "top camera returned no board-registration frames".to_string())?,
        expected,
        detection,
    );
    let encoded = encode_rgb_png(&evidence).map_err(|error| error.to_string())?;
    state
        .store
        .put_board_registration_artifact(registration_id, &artifact_name, "image/png", &encoded)
        .map_err(|error| error.to_string())?;
    let detection = detection.ok_or_else(|| {
        format!(
            "{} was detected in {} of {} frames",
            fiducial.reference,
            detections.len(),
            sample_count,
        )
    })?;
    let maximum_jitter_px = detections
        .iter()
        .map(|sample| (sample.x_px - detection.x_px).hypot(sample.y_px - detection.y_px))
        .fold(0.0_f64, f64::max);
    if maximum_jitter_px * scale_mm_per_px > BOARD_REGISTRATION_MAX_RESIDUAL_MM {
        return Err(format!(
            "{} center jitter {:.3} mm exceeds {:.3} mm",
            fiducial.reference,
            maximum_jitter_px * scale_mm_per_px,
            BOARD_REGISTRATION_MAX_RESIDUAL_MM,
        ));
    }
    let correction = camera_model
        .correction_at(detection.x_px, detection.y_px)
        .ok_or_else(|| {
            format!(
                "{} is outside the calibrated image region",
                fiducial.reference
            )
        })?;
    if correction[0].hypot(correction[1]) > BOARD_REGISTRATION_MAX_CORRECTION_MM {
        return Err(format!(
            "{} needs {:.3} mm correction, above the {:.3} mm seed bound",
            fiducial.reference,
            correction[0].hypot(correction[1]),
            BOARD_REGISTRATION_MAX_CORRECTION_MM,
        ));
    }
    Ok(BoardRegistrationFiducialObservation {
        reference: fiducial.reference.clone(),
        design_x_mm: fiducial.pose.x_mm,
        design_y_mm: fiducial.pose.y_mm,
        predicted_x_mm: predicted.0,
        predicted_y_mm: predicted.1,
        observed_x_px: detection.x_px,
        observed_y_px: detection.y_px,
        measured_x_mm: measured_pose.x_mm + correction[0],
        measured_y_mm: measured_pose.y_mm + correction[1],
        diameter_px: detection.diameter_px,
        confidence: detection.confidence,
        artifact_name,
    })
}

async fn jog_board_registration_target(
    state: &AppState,
    lease_id: Uuid,
    target: Pose,
    visual: &VisualHomingProfile,
    motion: &mut CalibratedMotionSequence,
) -> Result<Pose, String> {
    let approach = Pose {
        x_mm: target.x_mm - BOARD_REGISTRATION_APPROACH_MM,
        y_mm: target.y_mm - BOARD_REGISTRATION_APPROACH_MM,
        ..target
    };
    if state.profile.bounds.contains(approach) {
        let approach_target = JogTarget {
            x_mm: approach.x_mm,
            y_mm: approach.y_mm,
            z_mm: approach.z_mm,
            rotation_deg: None,
        };
        let approach_feed_mm_per_min = safe_level_xy_feed(
            &state.profile,
            Some(motion.state.logical_pose),
            approach_target,
            visual.feed_mm_per_min,
        );
        execute_calibrated_motion(
            state,
            lease_id,
            motion,
            approach_target,
            approach_feed_mm_per_min,
        )
        .await?;
    }
    execute_calibrated_motion(
        state,
        lease_id,
        motion,
        JogTarget {
            x_mm: target.x_mm,
            y_mm: target.y_mm,
            z_mm: target.z_mm,
            rotation_deg: None,
        },
        visual.feed_mm_per_min,
    )
    .await
    .map(|(pose, _)| pose)
}

fn normalize_angle_deg(angle_deg: f64) -> f64 {
    (angle_deg + 180.0).rem_euclid(360.0) - 180.0
}

fn angle_difference_deg(first_deg: f64, second_deg: f64) -> f64 {
    normalize_angle_deg(first_deg - second_deg)
}

async fn list_board_registrations(State(state): State<AppState>) -> ApiResult<Json<Value>> {
    Ok(Json(json!({
        "registrations": state
            .store
            .list_board_registrations()
            .map_err(ApiError::internal)?,
    })))
}

async fn get_board_registration(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<BoardRegistrationRun>> {
    state
        .store
        .get_board_registration(id)
        .map_err(ApiError::internal)?
        .map(Json)
        .ok_or_else(|| ApiError::not_found("board registration not found"))
}

async fn get_board_registration_artifact(
    State(state): State<AppState>,
    Path((id, name)): Path<(Uuid, String)>,
) -> ApiResult<Response> {
    let (media_type, data) = state
        .store
        .get_board_registration_artifact(id, &name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("board registration artifact not found"))?;
    Response::builder()
        .status(StatusCode::OK)
        .header(header::CONTENT_TYPE, media_type)
        .header(header::CACHE_CONTROL, "no-store")
        .body(axum::body::Body::from(data))
        .map_err(ApiError::internal)
}

#[derive(Debug, Deserialize)]
struct StartBoardSurfaceMeasurementRequest {
    lease_id: Uuid,
    #[serde(default = "default_board_surface_nozzle")]
    nozzle_id: String,
    #[serde(default = "default_board_registration_sample_count")]
    sample_count: u32,
    confirmed_external_safety_checks: bool,
}

#[derive(Debug, Serialize)]
struct StartBoardSurfaceMeasurementResponse {
    measurement: BoardSurfaceMeasurementRun,
    operation: Operation,
}

fn default_board_surface_nozzle() -> String {
    "N1".into()
}

async fn start_board_surface_measurement(
    State(state): State<AppState>,
    Path(registration_id): Path<Uuid>,
    Json(body): Json<StartBoardSurfaceMeasurementRequest>,
) -> ApiResult<(StatusCode, Json<StartBoardSurfaceMeasurementResponse>)> {
    if !body.confirmed_external_safety_checks {
        return Err(ApiError::bad_request(
            "board surface measurement requires confirmation that the PCB is fixed, its fiducials are visible, both nozzles are level, the travel envelope is clear, and power isolation is reachable",
        ));
    }
    if !(3..=5).contains(&body.sample_count) {
        return Err(ApiError::bad_request(
            "board surface sample_count must be between 3 and 5",
        ));
    }
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed || status.pose.is_none() {
        return Err(ApiError::bad_request(
            "board surface measurement requires a homed ready machine",
        ));
    }
    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(&state)?;
    ensure_no_active_board_registrations(&state)?;
    ensure_no_active_board_surface_measurements(&state)?;
    ensure_no_active_strip_feeder_holdouts(&state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(&state)?;
    let registration = state
        .store
        .get_board_registration(registration_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("board registration not found"))?;
    if registration.status != OperationStatus::Succeeded
        || !registration.passed
        || registration.design_to_machine.is_none()
        || registration.board_instance.is_none()
    {
        return Err(ApiError::bad_request(
            "board surface measurement requires a passing board registration",
        ));
    }
    if !state.profile.accepts_profile_id(&registration.profile_id) {
        return Err(ApiError::bad_request(
            "board registration does not match the active machine profile",
        ));
    }
    if !status.simulated && status.calibration_revision != Some(registration.calibration_id) {
        return Err(ApiError::bad_request(format!(
            "board surface measurement requires fine XYZ homing with calibration {}",
            registration.calibration_id,
        )));
    }
    let board = state
        .store
        .get_board(registration.board_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("board design not found"))?;
    let fiducial_count = board
        .placements
        .iter()
        .filter(|placement| {
            placement.enabled && placement.fiducial && placement.side == BoardSide::Top
        })
        .count();
    if fiducial_count < 3 {
        return Err(ApiError::bad_request(
            "board surface measurement requires at least three top fiducials",
        ));
    }
    let (snapshot, top_camera_model) =
        load_workspace_camera_model(&state, registration.calibration_id)?;
    let (working_camera_model, _, installed_camera_model, _) = select_workspace_surface_models(
        &state,
        &snapshot,
        top_camera_model,
        Some(WorkspaceRegionPreset::InstalledPlates),
        WorkspaceScanMode::Precision,
    )?;
    let installed_camera_model = installed_camera_model.ok_or_else(|| {
        ApiError::bad_request("board surface measurement has no installed-plate camera model")
    })?;
    let installed_geometry = state
        .profile
        .installed_geometry_calibration
        .as_ref()
        .ok_or_else(|| {
            ApiError::bad_request("active profile does not define installed plate geometry")
        })?;
    let plate_depth_mm = installed_geometry
        .installed_plate_depth_below_working_plane_mm
        .ok_or_else(|| {
            ApiError::bad_request(
                "active profile does not define installed plate depth below the working plane",
            )
        })?;
    let contact_artifact = CalibrationArtifactId::vacuum_contact(&body.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("unknown surface-reference nozzle"))?;
    if !crate::calibration_artifacts::artifact_tree_is_current(&state, &snapshot, contact_artifact)
    {
        return Err(ApiError::bad_request(
            "board surface measurement requires a current vacuum-contact reference",
        ));
    }
    let contact: VacuumProbeReport = serde_json::from_value(
        crate::calibration_artifacts::artifact_result_value(&snapshot, contact_artifact)
            .map_err(ApiError::bad_request)?,
    )
    .map_err(|_| ApiError::bad_request("stored vacuum contact is invalid"))?;
    let reference_contact_nozzle_z_mm = contact
        .contact_nozzle_z_mm
        .filter(|_| contact.passed && contact.nozzle_id == body.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("stored vacuum contact did not pass"))?;
    let camera_profile = stored_camera_profile(&state, CameraRole::TopCamera)?;
    let camera_path = camera_path_for_role(CameraRole::TopCamera)?;
    let visual = state
        .profile
        .visual_homing
        .as_ref()
        .cloned()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let operation = Operation::pending("vision.board_surface_measurement");
    let now = Utc::now();
    let measurement = BoardSurfaceMeasurementRun {
        id: Uuid::new_v4(),
        operation_id: operation.id,
        registration_id,
        profile_id: registration.profile_id.clone(),
        calibration_id: registration.calibration_id,
        nozzle_id: body.nozzle_id,
        status: OperationStatus::Pending,
        created_at: now,
        updated_at: now,
        sample_count: body.sample_count,
        report: None,
        message: None,
    };
    state
        .machine
        .renew_lease(body.lease_id, 900)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    state
        .store
        .put_operation(&operation)
        .map_err(ApiError::internal)?;
    state
        .store
        .put_board_surface_measurement(&measurement)
        .map_err(ApiError::internal)?;
    drop(admission_guard);
    let response = StartBoardSurfaceMeasurementResponse {
        measurement: measurement.clone(),
        operation: operation.clone(),
    };
    let task_state = state.clone();
    spawn_prepared_operation(
        state,
        operation,
        execute_board_surface_measurement_task(
            task_state,
            measurement,
            registration,
            board,
            working_camera_model,
            installed_camera_model,
            camera_profile,
            camera_path,
            visual,
            reference_contact_nozzle_z_mm,
            plate_depth_mm,
            body.lease_id,
        ),
    );
    Ok((StatusCode::ACCEPTED, Json(response)))
}

#[allow(clippy::too_many_arguments)]
async fn execute_board_surface_measurement_task(
    state: AppState,
    mut run: BoardSurfaceMeasurementRun,
    mut registration: BoardRegistrationRun,
    board: BoardDesign,
    working_camera_model: PlanarCameraModel,
    installed_camera_model: PlanarCameraModel,
    camera_profile: CameraProfile,
    camera_path: String,
    visual: VisualHomingProfile,
    reference_contact_nozzle_z_mm: f64,
    plate_depth_mm: f64,
    lease_id: Uuid,
) -> Result<Option<String>, String> {
    let task_started = Instant::now();
    let operation_id = run.operation_id;
    let simulated = state.machine.status().simulated;
    run.status = OperationStatus::Running;
    run.updated_at = Utc::now();
    state
        .store
        .put_board_surface_measurement(&run)
        .map_err(|error| error.to_string())?;
    let (result, camera_timing) = if simulated {
        (
            execute_board_surface_measurement(
                &state,
                &run,
                &registration,
                &board,
                &working_camera_model,
                &installed_camera_model,
                &camera_profile,
                &camera_path,
                &visual,
                reference_contact_nozzle_z_mm,
                plate_depth_mm,
                lease_id,
            )
            .await,
            json!({}),
        )
    } else {
        let operation_state = state.clone();
        with_profiled_camera_reuse(
            &state,
            execute_board_surface_measurement(
                &operation_state,
                &run,
                &registration,
                &board,
                &working_camera_model,
                &installed_camera_model,
                &camera_profile,
                &camera_path,
                &visual,
                reference_contact_nozzle_z_mm,
                plate_depth_mm,
                lease_id,
            ),
        )
        .await
    };
    record_camera_target_operation_timing(
        &state,
        operation_id,
        "board_surface_measurement",
        simulated,
        result.is_ok(),
        elapsed_ms(task_started),
        camera_timing,
    )
    .await;
    match result {
        Ok(report) => {
            if !report.passed {
                let message = format!(
                    "board surface was rejected: fraction {:.3}, p95 spread {:.3}, residual {:.3} mm, uncertainty {:.3} mm",
                    report.median_surface_fraction,
                    report.surface_fraction_p95_deviation,
                    report.fit_residuals.p95_mm,
                    report.uncertainty_mm,
                );
                run.report = Some(report);
                run.status = OperationStatus::Failed;
                run.message = Some(message.clone());
                run.updated_at = Utc::now();
                state
                    .store
                    .put_board_surface_measurement(&run)
                    .map_err(|error| error.to_string())?;
                return Err(message);
            }
            let message = format!(
                "Measured board surface Z {:.3} mm without contact; uncertainty {:.3} mm",
                report.surface_z_mm, report.uncertainty_mm,
            );
            let board_instance = registration
                .board_instance
                .as_mut()
                .ok_or_else(|| "board registration lost its board instance".to_string())?;
            board_instance.surface_z_mm = Some(report.surface_z_mm);
            registration.latest_surface_measurement_id = Some(run.id);
            registration.updated_at = Utc::now();
            state
                .store
                .put_board_registration(&registration)
                .map_err(|error| error.to_string())?;
            run.report = Some(report);
            run.status = OperationStatus::Succeeded;
            run.message = Some(message.clone());
            run.updated_at = Utc::now();
            state
                .store
                .put_board_surface_measurement(&run)
                .map_err(|error| error.to_string())?;
            Ok(Some(message))
        }
        Err(message) => {
            run.status = OperationStatus::Failed;
            run.message = Some(message.clone());
            run.updated_at = Utc::now();
            if let Err(error) = state.store.put_board_surface_measurement(&run) {
                tracing::error!(%error, measurement_id = %run.id, "failed to persist rejected board surface measurement");
            }
            Err(message)
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn execute_board_surface_measurement(
    state: &AppState,
    run: &BoardSurfaceMeasurementRun,
    registration: &BoardRegistrationRun,
    board: &BoardDesign,
    working_camera_model: &PlanarCameraModel,
    installed_camera_model: &PlanarCameraModel,
    camera_profile: &CameraProfile,
    camera_path: &str,
    visual: &VisualHomingProfile,
    reference_contact_nozzle_z_mm: f64,
    plate_depth_mm: f64,
    lease_id: Uuid,
) -> Result<BoardSurfaceMeasurementReport, String> {
    let _motion_guard = state.workspace_scan_motion_lock.lock().await;
    execute_visual_home(
        state,
        VisualHomingRequest {
            lease_id,
            apply_offset: true,
            move_to_seed: true,
        },
    )
    .await
    .map_err(|error| {
        format!(
            "visual home before board surface measurement failed: {}",
            error.message
        )
    })?;
    let mut motion = operation_motion_sequence(
        state,
        run.calibration_id,
        "board surface measurement motion",
    )?;
    if camera_profile.lighting_enabled {
        state
            .machine
            .actuate(lease_id, "lights".into(), true)
            .await
            .map_err(|error| error.to_string())?;
    }
    let result = measure_board_surface(
        state,
        run,
        registration,
        board,
        working_camera_model,
        installed_camera_model,
        camera_profile,
        camera_path,
        visual,
        reference_contact_nozzle_z_mm,
        plate_depth_mm,
        lease_id,
        &mut motion,
    )
    .await;
    let return_feed_mm_per_min = safe_level_xy_feed(
        &state.profile,
        Some(motion.state.logical_pose),
        visual.seed_pose,
        visual.feed_mm_per_min,
    );
    let return_result = execute_calibrated_motion(
        state,
        lease_id,
        &mut motion,
        visual.seed_pose,
        return_feed_mm_per_min,
    )
    .await;
    let lights_result = if camera_profile.lighting_enabled {
        state.machine.disable_actuator("lights".into()).await
    } else {
        Ok(())
    };
    if let Err(error) = return_result {
        return Err(format!("board surface return move failed: {error}"));
    }
    if let Err(error) = lights_result {
        return Err(format!("board surface light cleanup failed: {error}"));
    }
    result
}

#[allow(clippy::too_many_arguments)]
async fn measure_board_surface(
    state: &AppState,
    run: &BoardSurfaceMeasurementRun,
    registration: &BoardRegistrationRun,
    board: &BoardDesign,
    working_camera_model: &PlanarCameraModel,
    installed_camera_model: &PlanarCameraModel,
    camera_profile: &CameraProfile,
    camera_path: &str,
    visual: &VisualHomingProfile,
    reference_contact_nozzle_z_mm: f64,
    plate_depth_mm: f64,
    lease_id: Uuid,
    motion: &mut CalibratedMotionSequence,
) -> Result<BoardSurfaceMeasurementReport, String> {
    let transform = registration
        .design_to_machine
        .ok_or_else(|| "board registration has no machine transform".to_string())?;
    let view_offsets = board_surface_view_offsets(working_camera_model)
        .ok_or_else(|| "top-camera model cannot plan board surface views".to_string())?;
    let mut fiducials = board
        .placements
        .iter()
        .filter(|placement| {
            placement.enabled && placement.fiducial && placement.side == BoardSide::Top
        })
        .collect::<Vec<_>>();
    fiducials.sort_by(|left, right| left.reference.cmp(&right.reference));
    let mut views = Vec::new();
    let mut observations = Vec::new();
    for fiducial in fiducials.into_iter().take(3) {
        let feature_machine = transform.apply(fiducial.pose.x_mm, fiducial.pose.y_mm);
        let mut feature_views = Vec::new();
        for (view_index, offset) in view_offsets.iter().enumerate() {
            let target = Pose {
                x_mm: feature_machine.0 + offset[0],
                y_mm: feature_machine.1 + offset[1],
                z_mm: state.profile.safe_z_mm,
                rotation_deg: 0.0,
            };
            if !state.profile.bounds.contains(target) {
                return Err(format!(
                    "surface view {} for {} is outside machine bounds",
                    view_index, fiducial.reference,
                ));
            }
            let expected_correction = [-offset[0], -offset[1]];
            let expected_pixel =
                invert_planar_camera_correction(working_camera_model, expected_correction)
                    .ok_or_else(|| {
                        format!(
                            "surface view {} for {} is outside the camera model",
                            view_index, fiducial.reference,
                        )
                    })?;
            state
                .machine
                .renew_lease(lease_id, 900)
                .await
                .map_err(|error| error.to_string())?;
            let measured_pose =
                jog_board_registration_target(state, lease_id, target, visual, motion).await?;
            let scale_mm_per_px = working_camera_model
                .local_mm_per_pixel(expected_pixel[0], expected_pixel[1])
                .ok_or_else(|| "top-camera model has no local surface-view scale".to_string())?;
            let frames =
                capture_profiled_frames(state, camera_profile, camera_path, run.sample_count)
                    .await
                    .map_err(|error| error.message)?;
            let detections = frames
                .iter()
                .filter_map(|frame| {
                    detect_board_fiducial_near(
                        frame,
                        expected_pixel[0],
                        expected_pixel[1],
                        1.5 / scale_mm_per_px,
                        BOARD_REGISTRATION_FIDUCIAL_DIAMETER_MM / scale_mm_per_px,
                        BOARD_REGISTRATION_FIDUCIAL_DIAMETER_TOLERANCE_MM / scale_mm_per_px,
                    )
                })
                .collect::<Vec<_>>();
            let required_detections = (2 * run.sample_count).div_ceil(3);
            let detection = (detections.len() >= required_detections as usize)
                .then(|| mean_fiducial_detection(&detections))
                .flatten();
            let artifact_name = format!(
                "surface-{}-view-{view_index}.png",
                safe_artifact_component(&fiducial.reference),
            );
            let evidence = render_board_fiducial_evidence(
                frames
                    .last()
                    .ok_or_else(|| "top camera returned no surface frames".to_string())?,
                expected_pixel,
                detection,
            );
            let encoded = encode_rgb_png(&evidence).map_err(|error| error.to_string())?;
            state
                .store
                .put_board_surface_measurement_artifact(
                    run.id,
                    &artifact_name,
                    "image/png",
                    &encoded,
                )
                .map_err(|error| error.to_string())?;
            let detection = detection.ok_or_else(|| {
                format!(
                    "{} surface view {} was detected in {} of {} frames",
                    fiducial.reference,
                    view_index,
                    detections.len(),
                    run.sample_count,
                )
            })?;
            let maximum_jitter_mm = detections
                .iter()
                .map(|sample| {
                    (sample.x_px - detection.x_px).hypot(sample.y_px - detection.y_px)
                        * scale_mm_per_px
                })
                .fold(0.0_f64, f64::max);
            if maximum_jitter_mm > BOARD_REGISTRATION_MAX_RESIDUAL_MM {
                return Err(format!(
                    "{} surface-view jitter {:.3} mm exceeds {:.3} mm",
                    fiducial.reference, maximum_jitter_mm, BOARD_REGISTRATION_MAX_RESIDUAL_MM,
                ));
            }
            let view = BoardSurfaceFiducialView {
                reference: fiducial.reference.clone(),
                view_index: view_index as u32,
                camera_pose: measured_pose,
                observed_x_px: detection.x_px,
                observed_y_px: detection.y_px,
                diameter_px: detection.diameter_px,
                confidence: detection.confidence,
                artifact_name,
            };
            views.push(view.clone());
            feature_views.push(view);
        }
        for fixed_index in 0..feature_views.len() {
            for moving_index in (fixed_index + 1)..feature_views.len() {
                let fixed = &feature_views[fixed_index];
                let moving = &feature_views[moving_index];
                let observation = measure_known_feature_surface_fraction(
                    fixed.camera_pose,
                    [fixed.observed_x_px, fixed.observed_y_px],
                    moving.camera_pose,
                    [moving.observed_x_px, moving.observed_y_px],
                    working_camera_model,
                    installed_camera_model,
                )
                .ok_or_else(|| {
                    format!(
                        "{} views {} and {} did not produce a valid parallax estimate",
                        fiducial.reference, fixed.view_index, moving.view_index,
                    )
                })?;
                observations.push(BoardSurfaceParallaxObservation {
                    reference: fiducial.reference.clone(),
                    fixed_view_index: fixed.view_index,
                    moving_view_index: moving.view_index,
                    surface_fraction: observation.surface_fraction,
                    residual_mm: observation.residual_mm,
                    parallax_signal_mm: observation.parallax_signal_mm,
                });
            }
        }
    }
    if observations.len() < 6 {
        return Err("board surface measurement produced fewer than six estimates".into());
    }
    let mut fractions = observations
        .iter()
        .map(|observation| observation.surface_fraction)
        .collect::<Vec<_>>();
    fractions.sort_by(f64::total_cmp);
    let median_fraction = percentile_sorted(&fractions, 0.5)
        .ok_or_else(|| "board surface fraction is unavailable".to_string())?;
    let mut deviations = fractions
        .iter()
        .map(|fraction| (fraction - median_fraction).abs())
        .collect::<Vec<_>>();
    deviations.sort_by(f64::total_cmp);
    let p95_deviation = percentile_sorted(&deviations, 0.95)
        .ok_or_else(|| "board surface spread is unavailable".to_string())?;
    let fit_residuals = summarize_residuals(
        observations
            .iter()
            .map(|observation| observation.residual_mm),
    )
    .ok_or_else(|| "board surface residuals are invalid".to_string())?;
    let mut fractional_fit_uncertainties = observations
        .iter()
        .map(|observation| observation.residual_mm / observation.parallax_signal_mm)
        .collect::<Vec<_>>();
    fractional_fit_uncertainties.sort_by(f64::total_cmp);
    let fit_fraction_uncertainty = percentile_sorted(&fractional_fit_uncertainties, 0.95)
        .ok_or_else(|| "board surface fit uncertainty is unavailable".to_string())?;
    let uncertainty_mm = (plate_depth_mm * p95_deviation.max(fit_fraction_uncertainty)).hypot(0.10);
    let surface_z_mm = reference_contact_nozzle_z_mm - plate_depth_mm * median_fraction;
    let passed = (MIN_WORKSPACE_SURFACE_FRACTION..=0.90).contains(&median_fraction)
        && p95_deviation <= BOARD_SURFACE_MAX_FRACTION_P95_DEVIATION
        && fit_residuals.p95_mm <= BOARD_REGISTRATION_MAX_RESIDUAL_MM
        && uncertainty_mm <= BOARD_SURFACE_MAX_UNCERTAINTY_MM;
    let findings = vec![
        format!(
            "{} fiducial views produced {} pair estimates",
            views.len(),
            observations.len(),
        ),
        "All views were captured at safe Z; no board contact was made".into(),
    ];
    let report = BoardSurfaceMeasurementReport {
        algorithm_version: BOARD_SURFACE_MEASUREMENT_ALGORITHM.into(),
        nozzle_id: run.nozzle_id.clone(),
        reference_contact_nozzle_z_mm,
        installed_plate_depth_below_working_plane_mm: plate_depth_mm,
        median_surface_fraction: median_fraction,
        surface_fraction_p95_deviation: p95_deviation,
        surface_z_mm,
        uncertainty_mm,
        fit_residuals,
        views,
        observations,
        passed,
        findings,
    };
    let encoded = serde_json::to_vec_pretty(&report).map_err(|error| error.to_string())?;
    state
        .store
        .put_board_surface_measurement_artifact(run.id, "report.json", "application/json", &encoded)
        .map_err(|error| error.to_string())?;
    Ok(report)
}

fn invert_planar_camera_correction(
    model: &PlanarCameraModel,
    target_correction_mm: [f64; 2],
) -> Option<[f64; 2]> {
    let mut pixel = [model.center_x_px, model.center_y_px];
    for _ in 0..10 {
        let correction = model.correction_at(pixel[0], pixel[1])?;
        let error = [
            correction[0] - target_correction_mm[0],
            correction[1] - target_correction_mm[1],
        ];
        if error[0].hypot(error[1]) < 1e-6 {
            return Some(pixel);
        }
        let correction_x = model.correction_at(pixel[0] + 1.0, pixel[1])?;
        let correction_y = model.correction_at(pixel[0], pixel[1] + 1.0)?;
        let jacobian = [
            [
                correction_x[0] - correction[0],
                correction_y[0] - correction[0],
            ],
            [
                correction_x[1] - correction[1],
                correction_y[1] - correction[1],
            ],
        ];
        let determinant = jacobian[0][0] * jacobian[1][1] - jacobian[0][1] * jacobian[1][0];
        if determinant.abs() < 1e-12 {
            return None;
        }
        pixel[0] -= (jacobian[1][1] * error[0] - jacobian[0][1] * error[1]) / determinant;
        pixel[1] -= (-jacobian[1][0] * error[0] + jacobian[0][0] * error[1]) / determinant;
    }
    let correction = model.correction_at(pixel[0], pixel[1])?;
    (correction[0] - target_correction_mm[0])
        .hypot(correction[1] - target_correction_mm[1])
        .lt(&1e-4)
        .then_some(pixel)
}

fn board_surface_view_offsets(model: &PlanarCameraModel) -> Option<[[f64; 2]; 3]> {
    let x_probe = [
        model.center_x_px
            + BOARD_SURFACE_APERTURE_FRACTION * (model.supported_max_x_px - model.center_x_px),
        model.center_y_px,
    ];
    let y_probe = [
        model.center_x_px,
        model.center_y_px
            + BOARD_SURFACE_APERTURE_FRACTION * (model.supported_min_y_px - model.center_y_px),
    ];
    let x_correction = model.correction_at(x_probe[0], x_probe[1])?;
    let y_correction = model.correction_at(y_probe[0], y_probe[1])?;
    if x_correction[0].hypot(x_correction[1]) < 1.0 || y_correction[0].hypot(y_correction[1]) < 1.0
    {
        return None;
    }
    Some([
        [0.0, 0.0],
        [-x_correction[0], -x_correction[1]],
        [-y_correction[0], -y_correction[1]],
    ])
}

fn safe_artifact_component(value: &str) -> String {
    value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect()
}

fn percentile_sorted(values: &[f64], fraction: f64) -> Option<f64> {
    if values.is_empty() || !(0.0..=1.0).contains(&fraction) {
        return None;
    }
    let index = ((values.len() - 1) as f64 * fraction).ceil() as usize;
    values.get(index).copied()
}

async fn list_board_surface_measurements(State(state): State<AppState>) -> ApiResult<Json<Value>> {
    Ok(Json(json!({
        "measurements": state
            .store
            .list_board_surface_measurements()
            .map_err(ApiError::internal)?,
    })))
}

