fn default_camera_sample_count() -> u32 {
    30
}

async fn camera_reproducibility(
    State(state): State<AppState>,
    Path(role): Path<String>,
    Json(body): Json<CameraReproducibilityRequest>,
) -> ApiResult<Json<Value>> {
    let role = parse_camera_role(&role)?;
    if !(1..=120).contains(&body.sample_count) {
        return Err(ApiError::bad_request(
            "camera sample_count must be between 1 and 120",
        ));
    }
    if body.settle_frames.is_some_and(|frames| frames > 120) {
        return Err(ApiError::bad_request(
            "camera settle_frames must not exceed 120",
        ));
    }
    if body
        .frames_per_second
        .is_some_and(|frames_per_second| !(1..=240).contains(&frames_per_second))
    {
        return Err(ApiError::bad_request(
            "camera frames_per_second must be between 1 and 240",
        ));
    }
    let sample_count = body.sample_count;
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed {
        return Err(ApiError::bad_request(
            "camera reproducibility requires a homed ready machine",
        ));
    }
    let profile = stored_camera_profile(&state, role)?;
    let mut tested_profile = profile.clone();
    if let Some(pixel_format) = body.pixel_format {
        tested_profile.pixel_format = pixel_format;
    }
    if let Some(frames_per_second) = body.frames_per_second {
        tested_profile.frames_per_second = frames_per_second;
    }
    tested_profile
        .validate()
        .map_err(|message| ApiError::bad_request(message.to_string()))?;

    if profile.lighting_enabled {
        state
            .machine
            .actuate(body.lease_id, "lights".into(), true)
            .await
            .map_err(|error| ApiError::bad_request(error.to_string()))?;
    }
    let capture = capture_camera_reproducibility_report_with_profile(
        &state,
        role,
        sample_count,
        body.settle_frames,
        tested_profile.clone(),
    )
    .await;
    let lights_off = if profile.lighting_enabled {
        state.machine.disable_actuator("lights".into()).await
    } else {
        Ok(())
    };
    if let Err(error) = lights_off {
        return Err(ApiError::internal(error));
    }
    let (controls, report) = capture?;
    Ok(Json(json!({
        "role": role,
        "profile": tested_profile,
        "temporary_capture_override": tested_profile != profile,
        "controls": controls,
        "discarded_settle_frames": body.settle_frames.unwrap_or(tested_profile.settle_frames),
        "report": report,
    })))
}

async fn capture_camera_reproducibility_report(
    state: &AppState,
    role: CameraRole,
    sample_count: u32,
) -> ApiResult<(Value, CameraReproducibilityReport)> {
    capture_camera_reproducibility_report_with_settle(state, role, sample_count, None).await
}

async fn capture_camera_reproducibility_report_with_settle(
    state: &AppState,
    role: CameraRole,
    sample_count: u32,
    settle_frames: Option<u32>,
) -> ApiResult<(Value, CameraReproducibilityReport)> {
    let profile = stored_camera_profile(state, role)?;
    capture_camera_reproducibility_report_with_profile(
        state,
        role,
        sample_count,
        settle_frames,
        profile,
    )
    .await
}

async fn capture_camera_reproducibility_report_with_profile(
    state: &AppState,
    role: CameraRole,
    sample_count: u32,
    settle_frames: Option<u32>,
    profile: CameraProfile,
) -> ApiResult<(Value, CameraReproducibilityReport)> {
    let device_path = camera_path_for_role(role)?;
    let mut config = camera_capture_config(&profile, device_path);
    if let Some(settle_frames) = settle_frames {
        config.settle_frames = settle_frames;
    }
    let updates = profile_control_updates(&profile);
    let thresholds = profile.thresholds.clone();
    let _capture_guard = state.camera_capture_lock.lock().await;
    tokio::task::spawn_blocking(move || {
        let controls = serde_json::to_value(apply_camera_controls(&config.device, &updates)?)?;
        let mut failures = 0;
        let mut samples = Vec::with_capacity(sample_count as usize);
        match capture_gray_frames(&config, sample_count) {
            Ok(captures) => {
                for capture in captures {
                    match camera_sample_metrics(&capture.frame, role) {
                        Some(metrics) => samples.push(metrics),
                        None => failures += 1,
                    }
                }
            }
            Err(_) => failures = sample_count,
        }
        let report = summarize_camera_reproducibility(sample_count, failures, samples, &thresholds);
        anyhow::Ok((controls, report))
    })
    .await
    .map_err(ApiError::internal)?
    .map_err(ApiError::internal)
}

fn parse_camera_role(role: &str) -> ApiResult<CameraRole> {
    CameraRole::try_from(role).map_err(ApiError::bad_request)
}

fn stored_camera_profile(state: &AppState, role: CameraRole) -> ApiResult<CameraProfile> {
    for profile_id in std::iter::once(&state.profile.id).chain(&state.profile.legacy_profile_ids) {
        if let Some(profile) = state
            .store
            .get_camera_profile(profile_id, role)
            .map_err(ApiError::internal)?
        {
            return Ok(profile);
        }
    }
    Ok(CameraProfile::initial_lumenpnp(
        state.profile.id.clone(),
        role,
    ))
}

fn profile_control_updates(profile: &CameraProfile) -> Vec<CameraControlUpdate> {
    profile
        .controls
        .iter()
        .map(|control| CameraControlUpdate {
            id: control.id,
            value: match control.value {
                CameraProfileControlValue::Integer(value) => CameraControlValue::Integer(value),
                CameraProfileControlValue::Boolean(value) => CameraControlValue::Boolean(value),
            },
        })
        .collect()
}

fn camera_capture_config(profile: &CameraProfile, device_path: String) -> V4l2CaptureConfig {
    let mut config = V4l2CaptureConfig::lumenpnp(device_path);
    config.width = profile.width;
    config.height = profile.height;
    config.pixel_format = profile.pixel_format;
    config.frames_per_second = profile.frames_per_second;
    config.settle_frames = profile.settle_frames;
    config
}

fn camera_frame_period(profile: &CameraProfile) -> Duration {
    Duration::from_secs_f64(1.0 / f64::from(profile.frames_per_second))
}

fn camera_end_of_frame_guard(profile: &CameraProfile) -> Duration {
    let manual_exposure = profile.controls.iter().any(|control| {
        control.id == CAMERA_EXPOSURE_AUTO_CONTROL_ID
            && control.value == CameraProfileControlValue::Integer(CAMERA_MANUAL_EXPOSURE_MODE)
    });
    let exposure = profile.controls.iter().find_map(|control| {
        if control.id != CAMERA_EXPOSURE_ABSOLUTE_CONTROL_ID {
            return None;
        }
        match control.value {
            CameraProfileControlValue::Integer(value) if value > 0 => u64::try_from(value)
                .ok()?
                .checked_mul(100)
                .map(Duration::from_micros),
            _ => None,
        }
    });
    if manual_exposure {
        exposure.unwrap_or_else(|| camera_frame_period(profile))
    } else {
        camera_frame_period(profile)
    }
}

fn camera_freshness_boundary(
    profile: &CameraProfile,
    exposure_started_after: Duration,
) -> CaptureFreshnessBoundary {
    let end_of_frame_exposure = camera_end_of_frame_guard(profile);
    CaptureFreshnessBoundary {
        exposure_started_after,
        end_of_frame_exposure,
        unknown_source_guard: camera_frame_period(profile).max(end_of_frame_exposure),
    }
}

fn camera_path_for_role(role: CameraRole) -> ApiResult<String> {
    let device = discover_linux_devices()
        .map_err(ApiError::internal)?
        .into_iter()
        .find(|device| {
            device.capture_capable == Some(true)
                && device.suggested_role.as_deref() == Some(role.as_str())
        })
        .ok_or_else(|| ApiError::not_found(format!("{} is not attached", role.as_str())))?;
    Ok(device.stable_path.unwrap_or(device.path))
}

