async fn import_openpnp_config(mut multipart: Multipart) -> ApiResult<Json<Value>> {
    let mut machine = None;
    let mut parts = None;
    while let Some(field) = multipart
        .next_field()
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?
    {
        let name = field.name().unwrap_or_default().to_string();
        let text = field
            .text()
            .await
            .map_err(|error| ApiError::bad_request(error.to_string()))?;
        match name.as_str() {
            "machine" => machine = Some(text),
            "parts" => parts = Some(text),
            _ => {}
        }
    }
    let machine =
        machine.ok_or_else(|| ApiError::bad_request("multipart field 'machine' is required"))?;
    let imported = import_openpnp(&machine, parts.as_deref())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    Ok(Json(json!({"import": imported})))
}

async fn put_feeder(
    State(state): State<AppState>,
    Json(feeder): Json<Feeder>,
) -> ApiResult<(StatusCode, Json<Feeder>)> {
    validate_feeder(&feeder)?;
    state
        .store
        .put_feeder(&feeder)
        .map_err(ApiError::internal)?;
    Ok((StatusCode::CREATED, Json(feeder)))
}

async fn put_part(
    State(state): State<AppState>,
    Json(part): Json<Part>,
) -> ApiResult<(StatusCode, Json<Part>)> {
    let existing = state.store.get_part(part.id).map_err(ApiError::internal)?;
    if part.key.trim().is_empty()
        || part.package.trim().is_empty()
        || part
            .height_mm
            .is_some_and(|value| !value.is_finite() || value <= 0.0)
        || part
            .body_width_mm
            .is_some_and(|value| !value.is_finite() || value <= 0.0)
        || part
            .body_length_mm
            .is_some_and(|value| !value.is_finite() || value <= 0.0)
        || part
            .placement_seating_offset_mm
            .is_some_and(|value| !value.is_finite() || !(-0.25..=0.5).contains(&value))
        || part
            .placement_release
            .is_some_and(|schedule| schedule.validate().is_err())
        || part
            .resolved_orientation()
            .is_none_or(|orientation| orientation.validate().is_err())
        || (part.orientation.is_none() && existing.is_none())
    {
        return Err(ApiError::bad_request(
            "part key, package, geometry, release schedule, and orientation must be valid",
        ));
    }
    state.store.put_part(&part).map_err(ApiError::internal)?;
    Ok((StatusCode::CREATED, Json(part)))
}

