fn validate_feeder(feeder: &Feeder) -> ApiResult<()> {
    match feeder {
        Feeder::Strip {
            tape_pitch_mm,
            tape_width_mm,
            first_pick,
            ..
        } => {
            if *tape_pitch_mm <= 0.0 || *tape_width_mm <= 0.0 || !first_pick.finite() {
                return Err(ApiError::bad_request(
                    "strip feeder dimensions and pose must be valid",
                ));
            }
        }
        Feeder::Drag {
            feed_distance_mm,
            pick,
            ..
        } => {
            if *feed_distance_mm <= 0.0 || !pick.finite() {
                return Err(ApiError::bad_request(
                    "drag feeder distance and pose must be valid",
                ));
            }
        }
        Feeder::Photon {
            hardware_uuid,
            part_pitch_mm,
            ..
        } => {
            if hardware_uuid.is_empty() || *part_pitch_mm <= 0.0 {
                return Err(ApiError::bad_request("Photon UUID and pitch are required"));
            }
        }
    }
    Ok(())
}

async fn put_job(
    State(state): State<AppState>,
    Json(job): Json<Job>,
) -> ApiResult<(StatusCode, Json<Job>)> {
    if job.boards.is_empty() {
        return Err(ApiError::bad_request(
            "a job must contain at least one board instance",
        ));
    }
    if job
        .placement_references
        .iter()
        .any(|reference| reference.trim().is_empty())
    {
        return Err(ApiError::bad_request(
            "job placement references cannot be empty",
        ));
    }
    if job
        .placement_seating_offset_mm
        .is_some_and(|offset| !offset.is_finite() || !(-0.25..=0.5).contains(&offset))
    {
        return Err(ApiError::bad_request(
            "job placement seating offset must be from -0.25 to +0.50 mm",
        ));
    }
    if job
        .placement_release
        .is_some_and(|schedule| schedule.validate().is_err())
    {
        return Err(ApiError::bad_request(
            "job placement release schedule is invalid",
        ));
    }
    for instance in &job.boards {
        if !instance.placement_surface_offset_mm.is_finite()
            || !(0.0..=5.0).contains(&instance.placement_surface_offset_mm)
        {
            return Err(ApiError::bad_request(
                "board placement surface offset must be from 0 to 5 mm",
            ));
        }
        if state
            .store
            .get_board(instance.board_id)
            .map_err(ApiError::internal)?
            .is_none()
        {
            return Err(ApiError::bad_request(format!(
                "board {} does not exist",
                instance.board_id
            )));
        }
    }
    state.store.put_job(&job).map_err(ApiError::internal)?;
    Ok((StatusCode::CREATED, Json(job)))
}

