async fn get_job_plan(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<Value>> {
    let job = state
        .store
        .get_job(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("job not found"))?;
    let boards = state
        .store
        .list_boards()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|board| (board.id, board))
        .collect::<HashMap<_, _>>();
    let feeders = state.store.list_feeders().map_err(ApiError::internal)?;
    let parts = state
        .store
        .list_parts()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|part| (part.key.clone(), part))
        .collect::<HashMap<_, _>>();
    Ok(Json(json!({
        "plan": plan_job(&job, &boards, &feeders, &parts, &state.profile)
    })))
}

#[derive(Deserialize)]
struct SimulateJobRequest {
    lease_id: Uuid,
    /// Omit this only when deliberately testing raw controller motion.
    calibration_id: Option<Uuid>,
}

async fn simulate_job(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    Json(body): Json<SimulateJobRequest>,
) -> ApiResult<(StatusCode, Json<Operation>)> {
    if !state.machine.status().simulated {
        return Err(ApiError::bad_request(
            "this endpoint is simulator-only; physical job execution remains calibration-gated",
        ));
    }
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed || status.pose.is_none() {
        return Err(ApiError::bad_request(
            "job simulation requires a homed ready simulator",
        ));
    }
    let job = state
        .store
        .get_job(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("job not found"))?;
    let boards = state
        .store
        .list_boards()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|board| (board.id, board))
        .collect::<HashMap<_, _>>();
    let feeders = state.store.list_feeders().map_err(ApiError::internal)?;
    let parts = state
        .store
        .list_parts()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|part| (part.key.clone(), part))
        .collect::<HashMap<_, _>>();
    let plan = plan_job(&job, &boards, &feeders, &parts, &state.profile);
    if !plan.report.ready {
        return Err(ApiError::bad_request(format!(
            "job preflight failed: {}",
            plan.report.errors.join("; ")
        )));
    }
    let motion_calibration = body
        .calibration_id
        .map(|id| load_job_motion_calibration(&state, id))
        .transpose()?;
    let motion_mode = if motion_calibration.is_some() {
        MotionMode::Calibrated
    } else {
        MotionMode::Raw
    };
    let motion_planner = MotionPlanner::new(state.profile.bounds, motion_calibration);
    let machine = state.machine.clone();
    spawn_operation(state, "job.simulate", async move {
        let controller_pose = machine
            .status()
            .pose
            .ok_or_else(|| "job simulation lost the controller pose".to_string())?;
        let mut motion_state = motion_planner
            .initial_state(controller_pose)
            .map_err(|error| error.to_string())?;
        let mut corrected_moves = 0_u32;
        for step in &plan.steps {
            let pick_safe = Pose {
                z_mm: step.safe_z_mm,
                ..step.feeder_pick
            };
            let place_safe = Pose {
                z_mm: step.safe_z_mm,
                ..step.board_place
            };
            corrected_moves += execute_job_motion(
                &machine,
                body.lease_id,
                &motion_planner,
                &mut motion_state,
                pick_safe,
                300.0,
                motion_mode,
            )
            .await?
            .correction
            .applied() as u32;
            corrected_moves += execute_job_motion(
                &machine,
                body.lease_id,
                &motion_planner,
                &mut motion_state,
                step.feeder_pick,
                120.0,
                motion_mode,
            )
            .await?
            .correction
            .applied() as u32;
            machine
                .actuate(body.lease_id, "vacuum_1".into(), true)
                .await
                .map_err(|error| error.to_string())?;
            corrected_moves += execute_job_motion(
                &machine,
                body.lease_id,
                &motion_planner,
                &mut motion_state,
                pick_safe,
                120.0,
                motion_mode,
            )
            .await?
            .correction
            .applied() as u32;
            corrected_moves += execute_job_motion(
                &machine,
                body.lease_id,
                &motion_planner,
                &mut motion_state,
                place_safe,
                300.0,
                motion_mode,
            )
            .await?
            .correction
            .applied() as u32;
            corrected_moves += execute_job_motion(
                &machine,
                body.lease_id,
                &motion_planner,
                &mut motion_state,
                step.board_place,
                120.0,
                motion_mode,
            )
            .await?
            .correction
            .applied() as u32;
            machine
                .actuate(body.lease_id, "vacuum_1".into(), false)
                .await
                .map_err(|error| error.to_string())?;
            corrected_moves += execute_job_motion(
                &machine,
                body.lease_id,
                &motion_planner,
                &mut motion_state,
                place_safe,
                120.0,
                motion_mode,
            )
            .await?
            .correction
            .applied() as u32;
        }
        Ok(Some(format!(
            "Simulated {} conservative placement cycles in {motion_mode:?} mode; \
             {corrected_moves} moves used local direction compensation",
            plan.steps.len(),
        )))
    })
}

#[derive(Debug, Deserialize)]
struct StartJobExecutionRequest {
    lease_id: Uuid,
    calibration_id: Uuid,
    confirmed_external_safety_checks: bool,
}

#[derive(Debug, Deserialize)]
struct ResumeJobExecutionRequest {
    lease_id: Uuid,
    confirmed_external_safety_checks: bool,
}

#[derive(Debug, Serialize)]
struct StartJobExecutionResponse {
    execution: JobExecutionRun,
    operation: Operation,
}

#[derive(Debug, Serialize)]
struct JobExecutionList {
    executions: Vec<JobExecutionRun>,
}

#[derive(Debug, Clone, Copy, Deserialize)]
#[serde(rename_all = "snake_case")]
enum JobExecutionResolution {
    Retry,
    Skip,
}

#[derive(Debug, Deserialize)]
struct ResolveJobExecutionStepRequest {
    action: JobExecutionResolution,
    #[serde(default)]
    note: Option<String>,
}

fn validate_job_execution_machine(
    state: &AppState,
    lease_id: Uuid,
    calibration_id: Uuid,
    safety_confirmed: bool,
) -> ApiResult<bool> {
    if !safety_confirmed {
        return Err(ApiError::bad_request(
            "job execution requires confirmation that the PCB and feeders are fixed, both nozzles are level, the travel envelope is clear, and power isolation is reachable",
        ));
    }
    let status = state.machine.status();
    status
        .assert_lease(lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed || status.pose.is_none() {
        return Err(ApiError::bad_request(
            "job execution requires a homed ready machine",
        ));
    }
    if !status.simulated && status.calibration_revision != Some(calibration_id) {
        return Err(ApiError::bad_request(format!(
            "physical job execution requires fine XYZ homing with calibration {calibration_id}"
        )));
    }
    Ok(status.simulated)
}

fn latest_board_population_state(
    state: &AppState,
    job: &Job,
    calibration_id: Uuid,
) -> ApiResult<HashMap<(Uuid, String), (chrono::DateTime<Utc>, BoardPlacementScanObservation)>> {
    let mut latest =
        HashMap::<(Uuid, String), (chrono::DateTime<Utc>, BoardPlacementScanObservation)>::new();
    for report in state
        .store
        .list_board_population_refreshes()
        .map_err(ApiError::internal)?
    {
        if report.algorithm_version != BOARD_POPULATION_REFRESH_ALGORITHM
            || report.job_id != job.id
            || report.calibration_id != calibration_id
            || !state.profile.accepts_profile_id(&report.profile_id)
        {
            continue;
        }
        let current = job.boards.iter().find(|instance| {
            instance.id == report.board_instance_id
                && instance.board_id == report.board_design_id
                && instance.design_to_machine == Some(report.design_to_machine)
        });
        if current.is_none() {
            continue;
        }
        for observation in report.observations {
            let key = (
                report.board_instance_id,
                observation.placement_reference.clone(),
            );
            if latest
                .get(&key)
                .is_none_or(|(created_at, _)| report.created_at > *created_at)
            {
                latest.insert(key, (report.created_at, observation));
            }
        }
    }
    for run in state
        .store
        .list_placement_executions()
        .map_err(ApiError::internal)?
        .into_iter()
        .filter(|run| run.job_id == job.id)
    {
        let Some(report) = run.report.as_ref().filter(|report| !report.simulated) else {
            continue;
        };
        latest.retain(|(board_instance_id, reference), (created_at, _)| {
            let same_target = reference == &report.placement_reference
                && report
                    .board_instance_id
                    .is_none_or(|id| id == *board_instance_id);
            !same_target || run.updated_at <= *created_at
        });
    }
    Ok(latest)
}

async fn start_job_execution(
    State(state): State<AppState>,
    Path(job_id): Path<Uuid>,
    Json(body): Json<StartJobExecutionRequest>,
) -> ApiResult<(StatusCode, Json<StartJobExecutionResponse>)> {
    let simulated = validate_job_execution_machine(
        &state,
        body.lease_id,
        body.calibration_id,
        body.confirmed_external_safety_checks,
    )?;
    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(&state)?;
    ensure_no_active_board_registrations(&state)?;
    ensure_no_active_board_surface_measurements(&state)?;
    ensure_no_active_strip_feeder_holdouts(&state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(&state)?;
    ensure_no_active_placement_executions(&state)?;
    ensure_no_active_job_executions(&state)?;
    let job = state
        .store
        .get_job(job_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("job not found"))?;
    let boards = state
        .store
        .list_boards()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|board| (board.id, board))
        .collect::<HashMap<_, _>>();
    let feeders = state.store.list_feeders().map_err(ApiError::internal)?;
    let parts = state
        .store
        .list_parts()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|part| (part.key.clone(), part))
        .collect::<HashMap<_, _>>();
    let plan = plan_job(&job, &boards, &feeders, &parts, &state.profile);
    if !plan.report.ready {
        return Err(ApiError::bad_request(format!(
            "job-execution preflight failed: {}",
            plan.report.errors.join("; ")
        )));
    }
    if plan.steps.is_empty() {
        return Err(ApiError::bad_request("job plan has no placement steps"));
    }
    let population = latest_board_population_state(&state, &job, body.calibration_id)?;
    let review_references = plan
        .steps
        .iter()
        .filter_map(|step| {
            population
                .get(&(step.board_instance_id, step.placement_reference.clone()))
                .filter(|(_, observation)| {
                    observation.review_required
                        || observation.occupancy == BoardPlacementOccupancy::Uncertain
                })
                .map(|_| step.placement_reference.clone())
        })
        .collect::<Vec<_>>();
    if !review_references.is_empty() {
        return Err(ApiError::bad_request(format!(
            "job execution requires board-population review for {}",
            review_references.join(", "),
        )));
    }
    let populated = plan
        .steps
        .iter()
        .filter(|step| {
            population
                .get(&(step.board_instance_id, step.placement_reference.clone()))
                .is_some_and(|(_, observation)| {
                    observation.occupancy == BoardPlacementOccupancy::Populated
                        && !observation.review_required
                })
        })
        .count();
    let operation = Operation::pending(if simulated {
        "job.execution.simulate"
    } else {
        "job.execution.physical"
    });
    let now = Utc::now();
    let run = JobExecutionRun {
        id: Uuid::new_v4(),
        operation_id: operation.id,
        job_id,
        calibration_id: body.calibration_id,
        simulated,
        status: JobExecutionStatus::Pending,
        created_at: now,
        updated_at: now,
        steps: plan
            .steps
            .iter()
            .enumerate()
            .map(|(step_index, step)| {
                let already_populated = population
                    .get(&(step.board_instance_id, step.placement_reference.clone()))
                    .is_some_and(|(_, observation)| {
                        observation.occupancy == BoardPlacementOccupancy::Populated
                            && !observation.review_required
                    });
                JobExecutionStep {
                    step_index: step_index as u32,
                    placement_reference: step.placement_reference.clone(),
                    status: if already_populated {
                        JobExecutionStepStatus::Skipped
                    } else {
                        JobExecutionStepStatus::Pending
                    },
                    execution_id: None,
                    attempt_execution_ids: Vec::new(),
                    outcome_disposition: None,
                    board_contacted: false,
                    message: already_populated
                        .then(|| "board rescan found this placement populated".into()),
                }
            })
            .collect(),
        current_step_index: None,
        pause_requested: false,
        cancel_requested: false,
        message: Some(format!(
            "{} placement steps are ready; {populated} already populated",
            plan.steps.len() - populated,
        )),
    };
    state
        .machine
        .renew_lease(body.lease_id, 900)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    state
        .store
        .put_operation(&operation)
        .and_then(|_| state.store.put_job_execution(&run))
        .map_err(ApiError::internal)?;
    drop(admission_guard);
    let response = StartJobExecutionResponse {
        execution: run.clone(),
        operation: operation.clone(),
    };
    let task_state = state.clone();
    spawn_prepared_operation(
        state,
        operation,
        execute_job_execution_task(task_state, run.id, body.lease_id),
    );
    Ok((StatusCode::ACCEPTED, Json(response)))
}

async fn execute_job_execution_task(
    state: AppState,
    job_execution_id: Uuid,
    lease_id: Uuid,
) -> Result<Option<String>, String> {
    let run = state
        .store
        .get_job_execution(job_execution_id)
        .map_err(|error| error.to_string())?
        .ok_or_else(|| "job execution disappeared".to_string())?;
    if run.simulated {
        return execute_job_execution_loop(state, job_execution_id, lease_id).await;
    }

    let task_started = Instant::now();
    let task_state = state.clone();
    let (result, camera_timing) = with_profiled_camera_reuse(
        &state,
        execute_job_execution_loop(task_state, job_execution_id, lease_id),
    )
    .await;
    if let Err(error) = state
        .machine
        .record_operation_event(
            "operation.job_execution_timing".into(),
            json!({
                "job_execution_id": job_execution_id,
                "task_result_ok": result.is_ok(),
                "total_elapsed_ms": elapsed_ms(task_started),
                "cameras": camera_timing,
            }),
        )
        .await
    {
        tracing::warn!(
            %error,
            %job_execution_id,
            "failed to record job execution timing",
        );
    }
    result
}

async fn execute_job_execution_loop(
    state: AppState,
    job_execution_id: Uuid,
    lease_id: Uuid,
) -> Result<Option<String>, String> {
    loop {
        let mut run = state
            .store
            .get_job_execution(job_execution_id)
            .map_err(|error| error.to_string())?
            .ok_or_else(|| "job execution disappeared".to_string())?;
        if run.cancel_requested {
            run.status = JobExecutionStatus::Cancelled;
            run.current_step_index = None;
            run.message = Some("job execution cancelled between placements".into());
            run.updated_at = Utc::now();
            state
                .store
                .put_job_execution(&run)
                .map_err(|error| error.to_string())?;
            return Ok(run.message);
        }
        if run.pause_requested {
            run.status = JobExecutionStatus::Paused;
            run.current_step_index = None;
            run.pause_requested = false;
            run.message = Some("job execution paused between placements".into());
            run.updated_at = Utc::now();
            state
                .store
                .put_job_execution(&run)
                .map_err(|error| error.to_string())?;
            return Ok(run.message);
        }
        let Some(step_position) = run
            .steps
            .iter()
            .position(|step| step.status == JobExecutionStepStatus::Pending)
        else {
            let skipped_count = run
                .steps
                .iter()
                .filter(|step| step.status == JobExecutionStepStatus::Skipped)
                .count();
            run.status = if skipped_count == 0 {
                JobExecutionStatus::Succeeded
            } else {
                JobExecutionStatus::CompletedWithSkips
            };
            run.current_step_index = None;
            run.message = Some(format!(
                "job execution completed {} placements with {} skipped",
                run.steps
                    .iter()
                    .filter(|step| step.status == JobExecutionStepStatus::Succeeded)
                    .count(),
                skipped_count,
            ));
            run.updated_at = Utc::now();
            state
                .store
                .put_job_execution(&run)
                .map_err(|error| error.to_string())?;
            return Ok(run.message);
        };
        let step_index = run.steps[step_position].step_index;
        run.status = JobExecutionStatus::Running;
        run.current_step_index = Some(step_index);
        run.steps[step_position].status = JobExecutionStepStatus::Running;
        run.steps[step_position].message = Some("preparing production placement".into());
        run.updated_at = Utc::now();
        state
            .store
            .put_job_execution(&run)
            .map_err(|error| error.to_string())?;

        let prepared = prepare_guarded_placement_execution(
            &state,
            run.job_id,
            StartGuardedPlacementExecutionRequest {
                lease_id,
                calibration_id: run.calibration_id,
                step_index,
                confirmed_external_safety_checks: true,
            },
            Some(run.steps[step_position].placement_reference.as_str()),
            None,
            None,
        )
        .await;
        let prepared = match prepared {
            Ok(prepared) => prepared,
            Err(error) => {
                stop_job_execution_for_attention(
                    &state,
                    &mut run,
                    step_position,
                    error.message,
                    false,
                    None,
                )?;
                return Ok(run.message);
            }
        };
        let child_execution_id = prepared.run.id;
        run.steps[step_position].execution_id = Some(child_execution_id);
        run.steps[step_position]
            .attempt_execution_ids
            .push(child_execution_id);
        run.steps[step_position].message = Some("production placement is running".into());
        run.updated_at = Utc::now();
        state
            .store
            .put_job_execution(&run)
            .map_err(|error| error.to_string())?;

        let mut child_operation = prepared.operation;
        child_operation.status = OperationStatus::Running;
        child_operation.updated_at = Utc::now();
        state
            .store
            .put_operation(&child_operation)
            .map_err(|error| error.to_string())?;
        let child_result = execute_guarded_placement_task(
            state.clone(),
            prepared.run,
            prepared.step,
            prepared.lease_id,
            prepared.motion_planner,
            prepared.physical,
            true,
        )
        .await;
        match &child_result {
            Ok(message) => {
                child_operation.status = OperationStatus::Succeeded;
                child_operation.message = message.clone();
            }
            Err(message) => {
                child_operation.status = OperationStatus::Failed;
                child_operation.message = Some(message.clone());
            }
        }
        child_operation.updated_at = Utc::now();
        state
            .store
            .put_operation(&child_operation)
            .map_err(|error| error.to_string())?;
        let child = state
            .store
            .get_placement_execution(child_execution_id)
            .map_err(|error| error.to_string())?
            .ok_or_else(|| "production placement result disappeared".to_string())?;
        run = state
            .store
            .get_job_execution(job_execution_id)
            .map_err(|error| error.to_string())?
            .ok_or_else(|| "job execution disappeared".to_string())?;
        let step_position = run
            .steps
            .iter()
            .position(|step| step.step_index == step_index)
            .ok_or_else(|| "running job step disappeared".to_string())?;
        let board_contacted = child.report.as_ref().is_some_and(|report| {
            report
                .stages
                .iter()
                .any(|stage| stage.stage == PlacementExecutionStage::Placement && stage.passed)
        });
        let outcome = state
            .store
            .get_placement_outcome(child_execution_id)
            .map_err(|error| error.to_string())?;
        run.steps[step_position].board_contacted = board_contacted;
        run.steps[step_position].outcome_disposition = outcome
            .as_ref()
            .map(PlacementOutcomeRecord::effective_disposition);
        if child.status == OperationStatus::Succeeded {
            run.steps[step_position].status = JobExecutionStepStatus::Succeeded;
            run.steps[step_position].message = child.message;
            run.current_step_index = None;
            run.updated_at = Utc::now();
            state
                .store
                .put_job_execution(&run)
                .map_err(|error| error.to_string())?;
            continue;
        }
        stop_job_execution_for_attention(
            &state,
            &mut run,
            step_position,
            child
                .message
                .unwrap_or_else(|| "production placement failed".into()),
            board_contacted,
            outcome.map(|outcome| outcome.effective_disposition()),
        )?;
        return Ok(run.message);
    }
}

fn stop_job_execution_for_attention(
    state: &AppState,
    run: &mut JobExecutionRun,
    step_position: usize,
    message: String,
    board_contacted: bool,
    outcome: Option<PlacementOutcomeDisposition>,
) -> Result<(), String> {
    run.status = JobExecutionStatus::NeedsAttention;
    run.current_step_index = Some(run.steps[step_position].step_index);
    run.steps[step_position].status = JobExecutionStepStatus::NeedsAttention;
    run.steps[step_position].board_contacted = board_contacted;
    run.steps[step_position].outcome_disposition = outcome;
    run.steps[step_position].message = Some(message.clone());
    run.message = Some(format!(
        "placement {} needs attention: {message}",
        run.steps[step_position].placement_reference
    ));
    run.updated_at = Utc::now();
    state
        .store
        .put_job_execution(run)
        .map_err(|error| error.to_string())
}

async fn list_job_executions(State(state): State<AppState>) -> ApiResult<Json<JobExecutionList>> {
    Ok(Json(JobExecutionList {
        executions: state
            .store
            .list_job_executions()
            .map_err(ApiError::internal)?,
    }))
}

async fn get_job_execution(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<JobExecutionRun>> {
    state
        .store
        .get_job_execution(id)
        .map_err(ApiError::internal)?
        .map(Json)
        .ok_or_else(|| ApiError::not_found("job execution not found"))
}

async fn pause_job_execution(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<JobExecutionRun>> {
    let mut run = state
        .store
        .get_job_execution(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("job execution not found"))?;
    match run.status {
        JobExecutionStatus::Pending | JobExecutionStatus::Running => {
            run.pause_requested = true;
            run.message = Some("pause requested; the current placement will finish".into());
        }
        JobExecutionStatus::Paused => {}
        _ => return Err(ApiError::bad_request("job execution cannot be paused")),
    }
    run.updated_at = Utc::now();
    state
        .store
        .put_job_execution(&run)
        .map_err(ApiError::internal)?;
    Ok(Json(run))
}

async fn cancel_job_execution(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<JobExecutionRun>> {
    let mut run = state
        .store
        .get_job_execution(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("job execution not found"))?;
    match run.status {
        JobExecutionStatus::Pending | JobExecutionStatus::Running => {
            run.cancel_requested = true;
            run.message = Some("cancel requested; the current placement will finish".into());
        }
        JobExecutionStatus::Paused | JobExecutionStatus::NeedsAttention => {
            run.status = JobExecutionStatus::Cancelled;
            run.cancel_requested = true;
            run.current_step_index = None;
            run.message = Some("job execution cancelled".into());
        }
        JobExecutionStatus::Cancelled => {}
        JobExecutionStatus::Succeeded | JobExecutionStatus::CompletedWithSkips => {
            return Err(ApiError::bad_request(
                "completed job execution cannot be cancelled",
            ));
        }
    }
    run.updated_at = Utc::now();
    state
        .store
        .put_job_execution(&run)
        .map_err(ApiError::internal)?;
    Ok(Json(run))
}

async fn resolve_job_execution_step(
    State(state): State<AppState>,
    Path((id, step_index)): Path<(Uuid, u32)>,
    Json(body): Json<ResolveJobExecutionStepRequest>,
) -> ApiResult<Json<JobExecutionRun>> {
    let mut run = state
        .store
        .get_job_execution(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("job execution not found"))?;
    if run.status != JobExecutionStatus::NeedsAttention {
        return Err(ApiError::bad_request(
            "job execution does not have an unresolved placement",
        ));
    }
    let step = run
        .steps
        .iter_mut()
        .find(|step| step.step_index == step_index)
        .filter(|step| step.status == JobExecutionStepStatus::NeedsAttention)
        .ok_or_else(|| ApiError::bad_request("job step does not need attention"))?;
    let note = body
        .note
        .map(|note| note.trim().to_string())
        .filter(|note| !note.is_empty());
    match body.action {
        JobExecutionResolution::Retry => {
            if step.board_contacted {
                return Err(ApiError::bad_request(
                    "a placement that reached board contact cannot use ordinary retry",
                ));
            }
            step.status = JobExecutionStepStatus::Pending;
            step.execution_id = None;
            step.outcome_disposition = None;
            step.message = Some(note.unwrap_or_else(|| "operator approved retry".into()));
        }
        JobExecutionResolution::Skip => {
            let Some(note) = note else {
                return Err(ApiError::bad_request(
                    "skipping a placement requires an operator note",
                ));
            };
            step.status = JobExecutionStepStatus::Skipped;
            step.message = Some(note);
        }
    }
    run.status = JobExecutionStatus::Paused;
    run.current_step_index = None;
    run.message = Some("placement recovery recorded; resume when the machine is ready".into());
    run.updated_at = Utc::now();
    state
        .store
        .put_job_execution(&run)
        .map_err(ApiError::internal)?;
    Ok(Json(run))
}

async fn resume_job_execution(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    Json(body): Json<ResumeJobExecutionRequest>,
) -> ApiResult<(StatusCode, Json<StartJobExecutionResponse>)> {
    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(&state)?;
    ensure_no_active_board_registrations(&state)?;
    ensure_no_active_board_surface_measurements(&state)?;
    ensure_no_active_strip_feeder_holdouts(&state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(&state)?;
    ensure_no_active_placement_executions(&state)?;
    let mut run = state
        .store
        .get_job_execution(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("job execution not found"))?;
    if run.status != JobExecutionStatus::Paused {
        return Err(ApiError::bad_request(
            "only a paused job execution can resume",
        ));
    }
    if run
        .steps
        .iter()
        .any(|step| step.status == JobExecutionStepStatus::NeedsAttention)
    {
        return Err(ApiError::bad_request(
            "resolve the placement that needs attention before resume",
        ));
    }
    validate_job_execution_machine(
        &state,
        body.lease_id,
        run.calibration_id,
        body.confirmed_external_safety_checks,
    )?;
    let operation = Operation::pending(if run.simulated {
        "job.execution.resume_simulation"
    } else {
        "job.execution.resume_physical"
    });
    run.operation_id = operation.id;
    run.status = JobExecutionStatus::Pending;
    run.pause_requested = false;
    run.cancel_requested = false;
    run.message = Some("job execution resume queued".into());
    run.updated_at = Utc::now();
    state
        .machine
        .renew_lease(body.lease_id, 900)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    state
        .store
        .put_operation(&operation)
        .and_then(|_| state.store.put_job_execution(&run))
        .map_err(ApiError::internal)?;
    drop(admission_guard);
    let response = StartJobExecutionResponse {
        execution: run.clone(),
        operation: operation.clone(),
    };
    let task_state = state.clone();
    spawn_prepared_operation(
        state,
        operation,
        execute_job_execution_task(task_state, run.id, body.lease_id),
    );
    Ok((StatusCode::ACCEPTED, Json(response)))
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct StartGuardedPlacementExecutionRequest {
    lease_id: Uuid,
    calibration_id: Uuid,
    #[serde(default)]
    step_index: u32,
    confirmed_external_safety_checks: bool,
}

#[derive(Debug, Serialize)]
struct StartGuardedPlacementExecutionResponse {
    execution: PlacementExecutionRun,
    operation: Operation,
}

struct PreparedGuardedPlacementExecution {
    lease_id: Uuid,
    operation: Operation,
    run: PlacementExecutionRun,
    step: PlanStep,
    motion_planner: MotionPlanner,
    physical: Option<PreparedStripFeederPickup>,
}

#[derive(Debug, Deserialize)]
struct StartRetainedPartRecoveryRequest {
    lease_id: Uuid,
    confirmed_external_safety_checks: bool,
    confirmed_part_is_attached: bool,
    confirmed_target_is_empty: bool,
    #[serde(default)]
    placement_seating_offset_mm: Option<f64>,
    #[serde(default)]
    target_placement_reference: Option<String>,
}

struct PreparedRetainedPartRecovery {
    lease_id: Uuid,
    operation: Operation,
    run: PlacementExecutionRun,
    source_run: PlacementExecutionRun,
    source_report: PlacementExecutionReport,
    step: PlanStep,
    motion_planner: MotionPlanner,
    physical: PreparedStripFeederPickup,
    bare: GrayFrame,
}

async fn start_guarded_placement_execution(
    State(state): State<AppState>,
    Path(job_id): Path<Uuid>,
    Json(body): Json<StartGuardedPlacementExecutionRequest>,
) -> ApiResult<(StatusCode, Json<StartGuardedPlacementExecutionResponse>)> {
    ensure_no_active_job_executions(&state)?;
    let prepared =
        prepare_guarded_placement_execution(&state, job_id, body, None, None, None).await?;
    let response = StartGuardedPlacementExecutionResponse {
        execution: prepared.run.clone(),
        operation: prepared.operation.clone(),
    };
    let task_state = state.clone();
    spawn_prepared_operation(
        state,
        prepared.operation,
        execute_guarded_placement_task(
            task_state,
            prepared.run,
            prepared.step,
            prepared.lease_id,
            prepared.motion_planner,
            prepared.physical,
            true,
        ),
    );
    Ok((StatusCode::ACCEPTED, Json(response)))
}

async fn start_retained_part_recovery(
    State(state): State<AppState>,
    Path(source_execution_id): Path<Uuid>,
    Json(body): Json<StartRetainedPartRecoveryRequest>,
) -> ApiResult<(StatusCode, Json<StartGuardedPlacementExecutionResponse>)> {
    let prepared = prepare_retained_part_recovery(&state, source_execution_id, body).await?;
    let response = StartGuardedPlacementExecutionResponse {
        execution: prepared.run.clone(),
        operation: prepared.operation.clone(),
    };
    let task_state = state.clone();
    spawn_prepared_operation(
        state,
        prepared.operation.clone(),
        execute_retained_part_recovery_task(task_state, prepared),
    );
    Ok((StatusCode::ACCEPTED, Json(response)))
}

async fn prepare_retained_part_recovery(
    state: &AppState,
    source_execution_id: Uuid,
    body: StartRetainedPartRecoveryRequest,
) -> ApiResult<PreparedRetainedPartRecovery> {
    if !body.confirmed_external_safety_checks
        || !body.confirmed_part_is_attached
        || !body.confirmed_target_is_empty
    {
        return Err(ApiError::bad_request(
            "retained-part recovery requires confirmation that the part is attached, the original target is empty, the PCB is fixed, both nozzles are level, the travel envelope is clear, and power isolation is reachable",
        ));
    }
    let source_run = state
        .store
        .get_placement_execution(source_execution_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("source placement execution not found"))?;
    let source_report = source_run
        .report
        .as_ref()
        .filter(|report| !report.simulated)
        .cloned()
        .ok_or_else(|| ApiError::bad_request("source placement has no physical report"))?;
    if !source_report
        .stages
        .iter()
        .any(|stage| stage.stage == PlacementExecutionStage::Placement && stage.passed)
        || source_report
            .top_inspection
            .as_ref()
            .is_some_and(|inspection| inspection.passed)
    {
        return Err(ApiError::bad_request(
            "retained-part recovery requires prior board contact without a passed top inspection",
        ));
    }
    let source_pickup = source_report
        .pickup_report
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("source placement has no held-part evidence"))?;
    if source_pickup.inspection.is_none()
        || source_pickup
            .alignment
            .as_ref()
            .is_none_or(|alignment| !alignment.passed)
    {
        return Err(ApiError::bad_request(
            "source placement has no passed bottom-camera alignment",
        ));
    }
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.simulated
        || status.state != MachineState::Ready
        || !status.homed
        || status.pose.is_none()
    {
        return Err(ApiError::bad_request(
            "retained-part recovery requires a homed ready physical machine",
        ));
    }
    if status.calibration_revision != Some(source_run.calibration_id) {
        return Err(ApiError::bad_request(format!(
            "retained-part recovery requires fine XYZ homing with calibration {}",
            source_run.calibration_id,
        )));
    }

    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(state)?;
    ensure_no_active_board_registrations(state)?;
    ensure_no_active_board_surface_measurements(state)?;
    ensure_no_active_strip_feeder_holdouts(state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(state)?;
    ensure_no_active_placement_executions(state)?;
    if state
        .store
        .list_calibration_runs()
        .map_err(ApiError::internal)?
        .iter()
        .any(|run| {
            matches!(
                run.status,
                CalibrationRunStatus::Pending | CalibrationRunStatus::Running
            )
        })
    {
        return Err(ApiError::bad_request(
            "retained-part recovery cannot start during an active calibration run",
        ));
    }
    let job_motion_is_active = state
        .store
        .list_job_executions()
        .map_err(ApiError::internal)?
        .into_iter()
        .any(|run| {
            matches!(
                run.status,
                JobExecutionStatus::Pending | JobExecutionStatus::Running
            )
        });
    if job_motion_is_active {
        return Err(ApiError::bad_request(
            "retained-part recovery cannot run during active job motion",
        ));
    }

    let job = state
        .store
        .get_job(source_run.job_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("source placement job not found"))?;
    let boards = state
        .store
        .list_boards()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|board| (board.id, board))
        .collect::<HashMap<_, _>>();
    let feeders = state.store.list_feeders().map_err(ApiError::internal)?;
    let parts = state
        .store
        .list_parts()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|part| (part.key.clone(), part))
        .collect::<HashMap<_, _>>();
    let plan = plan_job(&job, &boards, &feeders, &parts, &state.profile);
    if !plan.report.ready {
        return Err(ApiError::bad_request(format!(
            "retained-part recovery preflight failed: {}",
            plan.report.errors.join("; ")
        )));
    }
    let source_step = plan
        .steps
        .get(source_run.step_index as usize)
        .cloned()
        .filter(|step| step.placement_reference == source_report.placement_reference)
        .ok_or_else(|| {
            ApiError::bad_request(
                "job plan changed after the source placement; recovery needs operator review",
            )
        })?;
    if source_step.nozzle_id != source_report.nozzle_id
        || source_step.part_key != source_report.part_key
        || source_step.board_instance_id
            != source_report
                .board_instance_id
                .unwrap_or(source_step.board_instance_id)
    {
        return Err(ApiError::bad_request(
            "source placement does not match the current job target",
        ));
    }
    let (target_step_index, mut step) = if let Some(target_reference) = body
        .target_placement_reference
        .as_deref()
        .filter(|reference| !reference.trim().is_empty())
    {
        plan.steps
            .iter()
            .enumerate()
            .find(|(_, step)| step.placement_reference == target_reference)
            .map(|(index, step)| (index as u32, step.clone()))
            .ok_or_else(|| ApiError::bad_request("recovery target is not in the current job"))?
    } else {
        (source_run.step_index, source_step.clone())
    };
    if step.part_key != source_step.part_key
        || step.nozzle_id != source_step.nozzle_id
        || step.feeder_id != source_step.feeder_id
        || step.board_instance_id != source_step.board_instance_id
    {
        return Err(ApiError::bad_request(
            "recovery target must use the same part, nozzle, feeder, and board",
        ));
    }
    if let Some(offset_mm) = body.placement_seating_offset_mm {
        if !offset_mm.is_finite()
            || !(MINIMUM_RETAINED_PART_RECOVERY_SEATING_OFFSET_MM..=0.5).contains(&offset_mm)
        {
            return Err(ApiError::bad_request(
                "retained-part recovery seating offset must be from -0.50 to +0.50 mm",
            ));
        }
        step.board_place.z_mm += offset_mm - step.placement_seating_offset_mm;
        step.placement_seating_offset_mm = offset_mm;
        let mut release_offsets = vec![offset_mm];
        release_offsets.extend(
            step.placement_release_seating_offsets_mm
                .iter()
                .copied()
                .filter(|candidate| *candidate < offset_mm - 1e-9),
        );
        release_offsets.dedup_by(|left, right| (*left - *right).abs() <= 1e-9);
        step.placement_release_seating_offsets_mm = release_offsets;
        if !state.profile.bounds.contains(step.board_place) {
            return Err(ApiError::bad_request(
                "retained-part recovery seating override is outside machine bounds",
            ));
        }
    }
    validate_guarded_board_surface(state, &step, source_run.calibration_id)?;
    let registration = state
        .store
        .list_strip_feeder_registrations()
        .map_err(ApiError::internal)?
        .into_iter()
        .find(|registration| registration.active_feeder_id == Some(step.feeder_id))
        .ok_or_else(|| ApiError::bad_request("source feeder registration is missing"))?;
    if registration.calibration_id != source_run.calibration_id {
        return Err(ApiError::bad_request(
            "source feeder calibration does not match the recovery calibration",
        ));
    }
    let (media_type, bare_data) = state
        .store
        .get_placement_execution_artifact(source_execution_id, BARE_NOZZLE_ARTIFACT)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::bad_request("source placement has no bare-nozzle image"))?;
    if media_type != "image/png" {
        return Err(ApiError::bad_request(
            "source bare-nozzle artifact is not a PNG",
        ));
    }
    let bare = decode_gray_png(&bare_data).map_err(ApiError::internal)?;
    let operation = Operation::pending("job.retained_part_recovery.physical");
    let now = Utc::now();
    let run = PlacementExecutionRun {
        id: Uuid::new_v4(),
        operation_id: operation.id,
        job_id: source_run.job_id,
        step_index: target_step_index,
        calibration_id: source_run.calibration_id,
        status: OperationStatus::Pending,
        created_at: now,
        updated_at: now,
        report: None,
        message: None,
    };
    let physical = prepare_retained_part_physical_context(
        state,
        &run,
        registration,
        &step,
        body.lease_id,
        &source_report,
    )?;
    let motion_calibration = load_job_motion_calibration(state, source_run.calibration_id)?;
    let motion_planner = MotionPlanner::new(state.profile.bounds, Some(motion_calibration));
    state
        .machine
        .renew_lease(body.lease_id, 900)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    state
        .store
        .put_operation(&operation)
        .and_then(|_| state.store.put_placement_execution(&run))
        .map_err(ApiError::internal)?;
    drop(admission_guard);
    Ok(PreparedRetainedPartRecovery {
        lease_id: body.lease_id,
        operation,
        run,
        source_run,
        source_report,
        step,
        motion_planner,
        physical,
        bare,
    })
}

fn prepare_retained_part_physical_context(
    state: &AppState,
    placement_run: &PlacementExecutionRun,
    mut registration: StripFeederRegistration,
    step: &PlanStep,
    lease_id: Uuid,
    source_report: &PlacementExecutionReport,
) -> ApiResult<PreparedStripFeederPickup> {
    let pickup_profile = state.profile.strip_feeder_pickup.as_ref().ok_or_else(|| {
        ApiError::bad_request("active profile does not define strip-feeder pickup")
    })?;
    pickup_profile.validate().map_err(ApiError::bad_request)?;
    state
        .profile
        .transit_motion
        .validate(state.profile.maximum_feed_mm_per_min)
        .map_err(ApiError::bad_request)?;
    let source_pickup = source_report
        .pickup_report
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("source placement has no pickup report"))?;
    let pocket_index = source_report
        .pocket_index
        .ok_or_else(|| ApiError::bad_request("source placement has no pocket index"))?;
    registration.selected_pocket_index = Some(pocket_index);
    registration.selected_pocket_machine_mm = Some(source_pickup.pocket_machine_mm);

    let bottom = state
        .profile
        .bottom_vision
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define bottom vision"))?;
    let nozzle = bottom
        .nozzles
        .iter()
        .find(|nozzle| nozzle.nozzle_id == step.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("recovery placement nozzle is unknown"))?;
    let (mut snapshot, top_camera_model) =
        load_workspace_camera_model(state, placement_run.calibration_id)?;
    let artifacts_changed =
        crate::calibration_artifacts::reconcile_snapshot_artifacts(state, &mut snapshot)
            .map_err(ApiError::bad_request)?;
    let runtime_artifact = CalibrationArtifactId::runtime_tip_transform(&step.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("recovery placement nozzle is unknown"))?;
    let contact_artifact = CalibrationArtifactId::vacuum_contact(&step.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("recovery placement nozzle is unknown"))?;
    let characterization_artifact = CalibrationArtifactId::vacuum_characterization(&step.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("recovery placement nozzle is unknown"))?;
    for (artifact, message) in [
        (runtime_artifact, "current runtime tip transform"),
        (contact_artifact, "current reference contact"),
        (characterization_artifact, "current vacuum characterization"),
    ] {
        if !crate::calibration_artifacts::artifact_tree_is_current(state, &snapshot, artifact) {
            return Err(ApiError::bad_request(format!(
                "retained-part recovery requires a {message}"
            )));
        }
    }
    let reference_contact: VacuumProbeReport = serde_json::from_value(
        crate::calibration_artifacts::artifact_result_value(&snapshot, contact_artifact)
            .map_err(ApiError::bad_request)?,
    )
    .map_err(|_| ApiError::bad_request("stored recovery contact is invalid"))?;
    let vacuum_characterization: VacuumSensorCharacterizationReport = serde_json::from_value(
        crate::calibration_artifacts::artifact_result_value(&snapshot, characterization_artifact)
            .map_err(ApiError::bad_request)?,
    )
    .map_err(|_| ApiError::bad_request("stored recovery vacuum reference is invalid"))?;
    if !reference_contact.passed
        || reference_contact.contact_nozzle_z_mm.is_none()
        || !vacuum_characterization.passed
        || !vacuum_characterization.reference_seal_validated
    {
        return Err(ApiError::bad_request(
            "retained-part recovery requires passing contact and vacuum references",
        ));
    }
    let geometry = calibrated_nozzle_geometry(&snapshot, &step.nozzle_id)?;
    if geometry.tip_id != nozzle.expected_tip_id {
        return Err(ApiError::bad_request(
            "recovery placement tip does not match the calibrated nozzle",
        ));
    }
    let visual = state
        .profile
        .visual_homing
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let head_reference = calibrated_head_reference(&snapshot, visual.pixel_error_to_machine_mm)?;
    let height_model = calibrated_nozzle_height_model(&snapshot, &step.nozzle_id)?;
    let placement_transfer_correction_mm =
        calibrated_placement_transfer_correction(state, &snapshot, &step.nozzle_id)?;
    let height_model_has_working_plane_transfer = height_model
        .as_ref()
        .is_some_and(|model| has_calibrated_working_plane_transfer(&snapshot, model));
    if !height_model_has_working_plane_transfer
        || height_model.as_ref().is_none_or(|model| {
            !placement_release_offsets(step).iter().all(|offset_mm| {
                let nozzle_z_mm = placement_release_nozzle_z_mm(step, *offset_mm);
                model.tip_offset_correction_at(nozzle_z_mm).is_some()
                    && state
                        .profile
                        .z_kinematics
                        .as_ref()
                        .and_then(|kinematics| {
                            kinematics.controller_z(&step.nozzle_id, nozzle_z_mm)
                        })
                        .is_some()
            })
        })
    {
        return Err(ApiError::bad_request(
            "retained-part recovery needs valid height and controller models for every release Z",
        ));
    }
    if artifacts_changed {
        state
            .store
            .put_calibration(&snapshot)
            .map_err(ApiError::internal)?;
    }
    let top_camera_profile = stored_camera_profile(state, CameraRole::TopCamera)?;
    let top_camera_path = camera_path_for_role(CameraRole::TopCamera)?;
    let motion_calibration = load_job_motion_calibration(state, placement_run.calibration_id)?;
    let synthetic_pickup_run = StripFeederPickupQualificationRun {
        id: placement_run.id,
        operation_id: placement_run.operation_id,
        registration_id: registration.id,
        profile_id: registration.profile_id.clone(),
        calibration_id: placement_run.calibration_id,
        status: OperationStatus::Pending,
        created_at: placement_run.created_at,
        updated_at: placement_run.updated_at,
        nozzle_id: step.nozzle_id.clone(),
        pocket_index,
        fallback_drop_surface_machine_mm: None,
        rotation_capture_offsets_deg: Vec::new(),
        requested_cycle_count: 1,
        benchmark_cycles: Vec::new(),
        report: None,
        message: None,
    };
    Ok(PreparedStripFeederPickup {
        run: synthetic_pickup_run,
        registration,
        lease_id,
        geometry,
        head_reference,
        height_model,
        height_model_has_working_plane_transfer,
        placement_transfer_correction_mm,
        calibration_pickup_retry_offsets_mm: Vec::new(),
        calibration_pickup_seating_depth_mm: 0.0,
        expected_part_size_mm: Some([step.body_width_mm, step.body_length_mm]),
        expected_part_size_source: "part definition",
        reference_contact,
        vacuum_characterization,
        top_camera_model,
        top_camera_profile,
        top_camera_path,
        part_orientation: step.part_orientation,
        source_rotation_deg: step.feeder_part_rotation_deg,
        rotation_capture_offsets_deg: Vec::new(),
        artifact_target: TransferArtifactTarget::PlacementExecution(placement_run.id),
        motion_planner: MotionPlanner::new(state.profile.bounds, Some(motion_calibration)),
        clear_xy_feed_mm_per_min: state.profile.transit_motion.clear_xy_feed_mm_per_min,
        carried_xy_feed_mm_per_min: state.profile.transit_motion.carried_xy_feed_mm_per_min,
        clear_z_feed_mm_per_min: state.profile.transit_motion.clear_z_feed_mm_per_min,
        carried_z_feed_mm_per_min: state.profile.transit_motion.carried_z_feed_mm_per_min,
        precision_z_approach_mm: state.profile.transit_motion.precision_z_approach_mm,
    })
}

async fn prepare_guarded_placement_execution(
    state: &AppState,
    job_id: Uuid,
    body: StartGuardedPlacementExecutionRequest,
    expected_placement_reference: Option<&str>,
    provisional_placement_transfer_correction_mm: Option<[f64; 2]>,
    preferred_feeder_registration_id: Option<Uuid>,
) -> ApiResult<PreparedGuardedPlacementExecution> {
    if !body.confirmed_external_safety_checks {
        return Err(ApiError::bad_request(
            "single placement requires confirmation that the PCB and feeders are fixed, both nozzles are level, the travel envelope is clear, and power isolation is reachable",
        ));
    }
    let status = state.machine.status();
    status
        .assert_lease(body.lease_id, Utc::now())
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    if status.state != MachineState::Ready || !status.homed || status.pose.is_none() {
        return Err(ApiError::bad_request(
            "single placement requires a homed ready machine",
        ));
    }
    if !status.simulated && status.calibration_revision != Some(body.calibration_id) {
        return Err(ApiError::bad_request(format!(
            "physical single placement requires fine XYZ homing with calibration {}",
            body.calibration_id,
        )));
    }
    let admission_guard = state.workspace_scan_admission_lock.lock().await;
    ensure_no_active_workspace_scans(state)?;
    ensure_no_active_board_registrations(state)?;
    ensure_no_active_board_surface_measurements(state)?;
    ensure_no_active_strip_feeder_holdouts(state)?;
    ensure_no_active_strip_feeder_pickup_qualifications(state)?;
    ensure_no_active_placement_executions(state)?;
    if provisional_placement_transfer_correction_mm.is_none()
        && state
            .store
            .list_calibration_runs()
            .map_err(ApiError::internal)?
            .iter()
            .any(|run| {
                matches!(
                    run.status,
                    CalibrationRunStatus::Pending | CalibrationRunStatus::Running
                )
            })
    {
        return Err(ApiError::bad_request(
            "production placement cannot start during an active calibration run",
        ));
    }
    let job = state
        .store
        .get_job(job_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("job not found"))?;
    let boards = state
        .store
        .list_boards()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|board| (board.id, board))
        .collect::<HashMap<_, _>>();
    let feeders = state.store.list_feeders().map_err(ApiError::internal)?;
    let parts = state
        .store
        .list_parts()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|part| (part.key.clone(), part))
        .collect::<HashMap<_, _>>();
    let plan = plan_job(&job, &boards, &feeders, &parts, &state.profile);
    if !plan.report.ready {
        return Err(ApiError::bad_request(format!(
            "single-placement preflight failed: {}",
            plan.report.errors.join("; ")
        )));
    }
    let step = plan
        .steps
        .get(body.step_index as usize)
        .cloned()
        .ok_or_else(|| ApiError::bad_request("placement step index is outside the job plan"))?;
    if expected_placement_reference
        .is_some_and(|expected| expected != step.placement_reference.as_str())
    {
        return Err(ApiError::bad_request(
            "job plan order changed after execution started; operator review is required",
        ));
    }
    let board_population = latest_board_population_state(state, &job, body.calibration_id)?;
    let board_observation =
        board_population.get(&(step.board_instance_id, step.placement_reference.clone()));
    if board_observation.is_some_and(|(_, observation)| {
        observation.review_required || observation.occupancy == BoardPlacementOccupancy::Uncertain
    }) {
        return Err(ApiError::bad_request(
            "placement target has uncertain board-rescan population",
        ));
    }
    if board_observation
        .is_some_and(|(_, observation)| observation.occupancy == BoardPlacementOccupancy::Populated)
    {
        return Err(ApiError::bad_request(
            "placement target is populated in the latest board rescan",
        ));
    }
    let feeder_registration = validate_production_strip_feeder_with_preference(
        state,
        &step,
        body.calibration_id,
        preferred_feeder_registration_id,
    )?;
    if !status.simulated {
        if feeder_registration.calibration_id != body.calibration_id {
            return Err(ApiError::bad_request(
                "physical placement feeder calibration does not match the fine-home revision",
            ));
        }
        validate_guarded_board_surface(state, &step, body.calibration_id)?;
        if board_observation
            .is_none_or(|(_, observation)| observation.occupancy != BoardPlacementOccupancy::Empty)
        {
            validate_guarded_board_target_unused(state, &step)?;
        }
    }
    let motion_calibration = load_job_motion_calibration(state, body.calibration_id)?;
    let motion_planner = MotionPlanner::new(state.profile.bounds, Some(motion_calibration));
    let operation = Operation::pending(if status.simulated {
        "job.single_placement.simulate"
    } else {
        "job.single_placement.physical"
    });
    let now = Utc::now();
    let run = PlacementExecutionRun {
        id: Uuid::new_v4(),
        operation_id: operation.id,
        job_id,
        step_index: body.step_index,
        calibration_id: body.calibration_id,
        status: OperationStatus::Pending,
        created_at: now,
        updated_at: now,
        report: None,
        message: None,
    };
    state
        .machine
        .renew_lease(body.lease_id, 900)
        .await
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    let physical = if status.simulated {
        None
    } else {
        Some(prepare_physical_placement_pickup(
            state,
            &run,
            feeder_registration,
            &step,
            body.lease_id,
            provisional_placement_transfer_correction_mm,
        )?)
    };
    let store_result = state
        .store
        .put_operation(&operation)
        .and_then(|_| state.store.put_placement_execution(&run));
    if let Err(error) = store_result {
        if let Some(prepared) = &physical {
            let _ = state.store.settle_strip_feeder_pocket(
                prepared.registration.id,
                run.id,
                StripFeederPocketOutcome::RetryableFailure,
                false,
            );
        }
        return Err(ApiError::internal(error));
    }
    drop(admission_guard);
    Ok(PreparedGuardedPlacementExecution {
        lease_id: body.lease_id,
        operation,
        run,
        step,
        motion_planner,
        physical,
    })
}

fn validate_guarded_board_surface(
    state: &AppState,
    step: &PlanStep,
    calibration_id: Uuid,
) -> ApiResult<()> {
    let registration = state
        .store
        .list_board_registrations()
        .map_err(ApiError::internal)?
        .into_iter()
        .find(|registration| {
            registration
                .board_instance
                .as_ref()
                .is_some_and(|board| board.id == step.board_instance_id)
        })
        .ok_or_else(|| {
            ApiError::bad_request("placement board has no persistent visual registration")
        })?;
    let measurement_id = registration.latest_surface_measurement_id.ok_or_else(|| {
        ApiError::bad_request("placement board has no current surface measurement")
    })?;
    let measurement = state
        .store
        .get_board_surface_measurement(measurement_id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::bad_request("board surface measurement is missing"))?;
    let report = measurement
        .report
        .as_ref()
        .filter(|report| report.passed)
        .ok_or_else(|| ApiError::bad_request("board surface measurement did not pass"))?;
    let registered_surface_z_mm = registration
        .board_instance
        .as_ref()
        .and_then(|board| board.surface_z_mm);
    if measurement.status != OperationStatus::Succeeded
        || measurement.calibration_id != calibration_id
        || measurement.nozzle_id != step.nozzle_id
        || registered_surface_z_mm != Some(report.surface_z_mm)
    {
        return Err(ApiError::bad_request(
            "placement board surface is not current for the planned calibration and nozzle",
        ));
    }
    Ok(())
}

fn validate_guarded_board_target_unused(state: &AppState, step: &PlanStep) -> ApiResult<()> {
    let jobs = state
        .store
        .list_jobs()
        .map_err(ApiError::internal)?
        .into_iter()
        .map(|job| (job.id, job))
        .collect::<HashMap<_, _>>();
    let prior = state
        .store
        .list_placement_executions()
        .map_err(ApiError::internal)?
        .into_iter()
        .find(|run| {
            let Some(report) = run.report.as_ref().filter(|report| !report.simulated) else {
                return false;
            };
            if report.placement_reference != step.placement_reference
                || !report
                    .stages
                    .iter()
                    .any(|stage| stage.stage == PlacementExecutionStage::Placement && stage.passed)
            {
                return false;
            }
            if report.board_instance_id == Some(step.board_instance_id) {
                return true;
            }
            report.board_instance_id.is_none()
                && jobs.get(&run.job_id).is_some_and(|job| {
                    job.boards
                        .iter()
                        .any(|board| board.id == step.board_instance_id)
                })
        });
    if let Some(prior) = prior {
        return Err(ApiError::bad_request(format!(
            "placement target {} has prior physical board contact in execution {}; ordinary placement will not reuse this target",
            step.placement_reference, prior.id,
        )));
    }
    Ok(())
}

fn production_reject_drop_surface_machine_mm(profile: &MachineProfile) -> ApiResult<[f64; 2]> {
    const NEGATIVE_Y_CLEARANCE_MM: f64 = 20.0;

    let visual = profile
        .visual_homing
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let installed = profile
        .installed_geometry_calibration
        .as_ref()
        .ok_or_else(|| {
            ApiError::bad_request("active profile does not define installed plate geometry")
        })?;
    let staging = installed
        .plates
        .iter()
        .find(|plate| plate.role == velocitypnp_domain::InstalledPlateRole::Staging)
        .ok_or_else(|| ApiError::bad_request("active profile has no staging plate"))?;
    if staging.column_count == 0 || staging.row_count == 0 {
        return Err(ApiError::bad_request("staging plate grid is empty"));
    }
    let mut min_x = f64::INFINITY;
    let mut max_x = f64::NEG_INFINITY;
    let mut min_y = f64::INFINITY;
    for column in [-1.0, f64::from(staging.column_count)] {
        for row in [-1.0, f64::from(staging.row_count)] {
            let x = visual.fiducial_x_mm
                + staging.origin_offset_x_mm
                + column * staging.column_step_x_mm
                + row * staging.row_step_x_mm;
            let y = visual.fiducial_y_mm
                + staging.origin_offset_y_mm
                + column * staging.column_step_y_mm
                + row * staging.row_step_y_mm;
            min_x = min_x.min(x);
            max_x = max_x.max(x);
            min_y = min_y.min(y);
        }
    }
    let drop_surface = [0.5 * (min_x + max_x), min_y - NEGATIVE_Y_CLEARANCE_MM];
    if !drop_surface.into_iter().all(f64::is_finite) {
        return Err(ApiError::bad_request(
            "production reject drop location is invalid",
        ));
    }
    Ok(drop_surface)
}

fn prepare_physical_placement_pickup(
    state: &AppState,
    placement_run: &PlacementExecutionRun,
    registration: StripFeederRegistration,
    step: &PlanStep,
    lease_id: Uuid,
    provisional_placement_transfer_correction_mm: Option<[f64; 2]>,
) -> ApiResult<PreparedStripFeederPickup> {
    let pickup_profile = state.profile.strip_feeder_pickup.as_ref().ok_or_else(|| {
        ApiError::bad_request("active profile does not define strip-feeder pickup")
    })?;
    pickup_profile.validate().map_err(ApiError::bad_request)?;
    state
        .profile
        .transit_motion
        .validate(state.profile.maximum_feed_mm_per_min)
        .map_err(ApiError::bad_request)?;
    let selected_pocket = placement_available_strip_feeder_pocket(
        &registration,
        step.feeder_pick,
        registration.active_feeder_id == Some(step.feeder_id),
    )
    .ok_or_else(|| ApiError::bad_request("strip feeder has no available occupied pocket"))?;
    let selected_pocket_index = selected_pocket.pocket_index;
    let nominal_center = selected_pocket.nominal_center_machine_mm;
    let latest_holdout = registration
        .latest_live_holdout_id
        .and_then(|id| state.store.get_strip_feeder_live_holdout(id).ok().flatten())
        .filter(|holdout| {
            holdout.status == OperationStatus::Succeeded
                && holdout.calibration_id == registration.calibration_id
        })
        .ok_or_else(|| ApiError::bad_request("placement feeder has no current live holdout"))?;
    let holdout = latest_holdout
        .report
        .as_ref()
        .filter(|report| report.passed)
        .ok_or_else(|| ApiError::bad_request("placement feeder live holdout did not pass"))?;
    let pocket_machine_mm = [
        nominal_center[0] + holdout.correction_x_mm,
        nominal_center[1] + holdout.correction_y_mm,
    ];
    let bottom = state
        .profile
        .bottom_vision
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define bottom vision"))?;
    let nozzle = bottom
        .nozzles
        .iter()
        .find(|nozzle| nozzle.nozzle_id == step.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("planned placement nozzle is unknown"))?;
    let (mut snapshot, top_camera_model) =
        load_workspace_camera_model(state, registration.calibration_id)?;
    let artifacts_changed =
        crate::calibration_artifacts::reconcile_snapshot_artifacts(state, &mut snapshot)
            .map_err(ApiError::bad_request)?;
    let runtime_artifact = CalibrationArtifactId::runtime_tip_transform(&step.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("planned placement nozzle is unknown"))?;
    let contact_artifact = CalibrationArtifactId::vacuum_contact(&step.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("planned placement nozzle is unknown"))?;
    let characterization_artifact = CalibrationArtifactId::vacuum_characterization(&step.nozzle_id)
        .ok_or_else(|| ApiError::bad_request("planned placement nozzle is unknown"))?;
    for (artifact, message) in [
        (runtime_artifact, "current runtime tip transform"),
        (contact_artifact, "current reference contact"),
        (characterization_artifact, "current vacuum characterization"),
    ] {
        if !crate::calibration_artifacts::artifact_tree_is_current(state, &snapshot, artifact) {
            return Err(ApiError::bad_request(format!(
                "physical placement requires a {message}"
            )));
        }
    }
    let reference_contact: VacuumProbeReport = serde_json::from_value(
        crate::calibration_artifacts::artifact_result_value(&snapshot, contact_artifact)
            .map_err(ApiError::bad_request)?,
    )
    .map_err(|_| ApiError::bad_request("stored placement contact is invalid"))?;
    let vacuum_characterization: VacuumSensorCharacterizationReport = serde_json::from_value(
        crate::calibration_artifacts::artifact_result_value(&snapshot, characterization_artifact)
            .map_err(ApiError::bad_request)?,
    )
    .map_err(|_| ApiError::bad_request("stored placement vacuum reference is invalid"))?;
    if !reference_contact.passed
        || reference_contact.contact_nozzle_z_mm.is_none()
        || !vacuum_characterization.passed
        || !vacuum_characterization.reference_seal_validated
    {
        return Err(ApiError::bad_request(
            "physical placement requires passing contact and vacuum references",
        ));
    }
    let geometry = calibrated_nozzle_geometry(&snapshot, &step.nozzle_id)?;
    if geometry.tip_id != nozzle.expected_tip_id {
        return Err(ApiError::bad_request(
            "planned placement tip does not match the calibrated nozzle",
        ));
    }
    let visual = state
        .profile
        .visual_homing
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("active profile does not define visual homing"))?;
    let head_reference = calibrated_head_reference(&snapshot, visual.pixel_error_to_machine_mm)?;
    let height_model = calibrated_nozzle_height_model(&snapshot, &step.nozzle_id)?;
    let calibration_pickup_retry_offsets_mm =
        if provisional_placement_transfer_correction_mm.is_some() {
            state
                .profile
                .placement_transfer_calibration
                .as_ref()
                .map_or_else(Vec::new, |profile| profile.pickup_retry_offsets_mm.clone())
        } else {
            Vec::new()
        };
    let calibration_pickup_seating_depth_mm =
        if provisional_placement_transfer_correction_mm.is_some() {
            state
                .profile
                .placement_transfer_calibration
                .as_ref()
                .map_or(0.0, |profile| profile.pickup_seating_depth_mm)
        } else {
            0.0
        };
    let placement_transfer_correction_mm = match provisional_placement_transfer_correction_mm {
        Some(correction) => correction,
        None => calibrated_placement_transfer_correction(state, &snapshot, &step.nozzle_id)?,
    };
    if !placement_transfer_correction_mm
        .iter()
        .all(|value| value.is_finite())
    {
        return Err(ApiError::bad_request(
            "placement-transfer correction is not finite",
        ));
    }
    let height_model_has_working_plane_transfer = height_model
        .as_ref()
        .is_some_and(|model| has_calibrated_working_plane_transfer(&snapshot, model));
    if !height_model_has_working_plane_transfer
        || height_model.as_ref().is_none_or(|model| {
            !placement_release_offsets(step).iter().all(|offset_mm| {
                let nozzle_z_mm = placement_release_nozzle_z_mm(step, *offset_mm);
                model.tip_offset_correction_at(nozzle_z_mm).is_some()
                    && state
                        .profile
                        .z_kinematics
                        .as_ref()
                        .and_then(|kinematics| {
                            kinematics.controller_z(&step.nozzle_id, nozzle_z_mm)
                        })
                        .is_some()
            })
        })
    {
        return Err(ApiError::bad_request(
            "physical placement needs valid height and controller models for every release Z",
        ));
    }
    if artifacts_changed {
        state
            .store
            .put_calibration(&snapshot)
            .map_err(ApiError::internal)?;
    }
    let top_camera_profile = stored_camera_profile(state, CameraRole::TopCamera)?;
    let top_camera_path = camera_path_for_role(CameraRole::TopCamera)?;
    let motion_calibration = load_job_motion_calibration(state, registration.calibration_id)?;
    let synthetic_pickup_run = StripFeederPickupQualificationRun {
        id: placement_run.id,
        operation_id: placement_run.operation_id,
        registration_id: registration.id,
        profile_id: registration.profile_id.clone(),
        calibration_id: registration.calibration_id,
        status: OperationStatus::Pending,
        created_at: placement_run.created_at,
        updated_at: placement_run.updated_at,
        nozzle_id: step.nozzle_id.clone(),
        pocket_index: selected_pocket_index,
        fallback_drop_surface_machine_mm: Some(production_reject_drop_surface_machine_mm(
            &state.profile,
        )?),
        rotation_capture_offsets_deg: Vec::new(),
        requested_cycle_count: 1,
        benchmark_cycles: Vec::new(),
        report: None,
        message: None,
    };
    let mut registration = state
        .store
        .reserve_strip_feeder_pocket(
            registration.id,
            placement_run.id,
            Some(selected_pocket_index),
        )
        .map_err(|error| ApiError::bad_request(error.to_string()))?;
    registration.selected_pocket_machine_mm = Some(pocket_machine_mm);
    if let Err(error) = state.store.put_strip_feeder_registration(&registration) {
        let _ = state.store.settle_strip_feeder_pocket(
            registration.id,
            placement_run.id,
            StripFeederPocketOutcome::RetryableFailure,
            false,
        );
        return Err(ApiError::internal(error));
    }
    Ok(PreparedStripFeederPickup {
        run: synthetic_pickup_run,
        registration,
        lease_id,
        geometry,
        head_reference,
        height_model,
        height_model_has_working_plane_transfer,
        placement_transfer_correction_mm,
        calibration_pickup_retry_offsets_mm,
        calibration_pickup_seating_depth_mm,
        expected_part_size_mm: Some([step.body_width_mm, step.body_length_mm]),
        expected_part_size_source: "part definition",
        reference_contact,
        vacuum_characterization,
        top_camera_model,
        top_camera_profile,
        top_camera_path,
        part_orientation: step.part_orientation,
        source_rotation_deg: step.feeder_part_rotation_deg,
        rotation_capture_offsets_deg: Vec::new(),
        artifact_target: TransferArtifactTarget::PlacementExecution(placement_run.id),
        motion_planner: MotionPlanner::new(state.profile.bounds, Some(motion_calibration)),
        clear_xy_feed_mm_per_min: state.profile.transit_motion.clear_xy_feed_mm_per_min,
        carried_xy_feed_mm_per_min: state.profile.transit_motion.carried_xy_feed_mm_per_min,
        clear_z_feed_mm_per_min: state.profile.transit_motion.clear_z_feed_mm_per_min,
        carried_z_feed_mm_per_min: state.profile.transit_motion.carried_z_feed_mm_per_min,
        precision_z_approach_mm: state.profile.transit_motion.precision_z_approach_mm,
    })
}

#[cfg(test)]
fn validate_production_strip_feeder(
    state: &AppState,
    step: &PlanStep,
    calibration_id: Uuid,
) -> ApiResult<StripFeederRegistration> {
    validate_production_strip_feeder_with_preference(state, step, calibration_id, None)
}

fn validate_production_strip_feeder_with_preference(
    state: &AppState,
    step: &PlanStep,
    calibration_id: Uuid,
    preferred_registration_id: Option<Uuid>,
) -> ApiResult<StripFeederRegistration> {
    let feeder = state
        .store
        .list_feeders()
        .map_err(ApiError::internal)?
        .into_iter()
        .find(|feeder| feeder.id() == step.feeder_id)
        .ok_or_else(|| ApiError::bad_request("placement feeder is missing"))?;
    if !matches!(feeder, Feeder::Strip { .. }) {
        return Err(ApiError::bad_request(
            "physical placement currently supports strip feeders only",
        ));
    }
    let registrations = state
        .store
        .list_strip_feeder_registrations()
        .map_err(ApiError::internal)?;
    let registration = preferred_registration_id
        .and_then(|id| {
            registrations
                .iter()
                .find(|registration| {
                    registration.id == id
                        && registration.calibration_id == calibration_id
                        && registration.part_key.as_deref() == Some(step.part_key.as_str())
                        && registration.status != StripFeederRegistrationStatus::VisionDraft
                })
                .cloned()
        })
        .or_else(|| {
            preferred_registration_id.is_none().then(|| {
                registrations
                    .iter()
                    .find(|registration| {
                        registration.calibration_id == calibration_id
                            && registration.active_feeder_id == Some(step.feeder_id)
                    })
                    .cloned()
            })?
        })
        .or_else(|| {
            preferred_registration_id.is_none().then(|| {
                registrations
                    .iter()
                    .filter(|registration| {
                        registration.calibration_id == calibration_id
                            && registration.part_key.as_deref() == Some(step.part_key.as_str())
                            && registration.status != StripFeederRegistrationStatus::VisionDraft
                    })
                    .filter_map(|registration| {
                        let maximum_distance_mm = 0.5 * registration.tape_pitch_mm;
                        let distance_mm = registration
                            .pockets
                            .iter()
                            .filter(|pocket| {
                                pocket.status == StripFeederPocketStatus::Available
                                    && pocket.occupancy == StripPocketOccupancy::Occupied
                            })
                            .map(|pocket| {
                                let center = pocket
                                    .measured_center_machine_mm
                                    .unwrap_or(pocket.nominal_center_machine_mm);
                                (center[0] - step.feeder_pick.x_mm)
                                    .hypot(center[1] - step.feeder_pick.y_mm)
                            })
                            .min_by(f64::total_cmp)?;
                        (distance_mm <= maximum_distance_mm)
                            .then_some((distance_mm, registration.clone()))
                    })
                    .min_by(|left, right| left.0.total_cmp(&right.0))
                    .map(|(_, registration)| registration)
            })?
        })
        .ok_or_else(|| {
            ApiError::bad_request("placement feeder has no current vision registration")
        })?;
    let (orientation, source_rotation_deg) = registration_part_orientation(state, &registration)?;
    if orientation != step.part_orientation
        || held_part_rotation_error_deg(
            source_rotation_deg,
            step.feeder_part_rotation_deg,
            PartOrientation::FeederReferenced,
        )
        .abs()
            > 0.01
    {
        return Err(ApiError::bad_request(
            "placement feeder part orientation does not match the job",
        ));
    }
    let holdout = registration
        .latest_live_holdout_id
        .and_then(|id| state.store.get_strip_feeder_live_holdout(id).ok().flatten())
        .filter(|holdout| {
            holdout.status == OperationStatus::Succeeded
                && holdout.calibration_id == calibration_id
                && holdout.report.as_ref().is_some_and(|report| report.passed)
        });
    if holdout.is_none() {
        return Err(ApiError::bad_request(
            "placement feeder has no current live pocket position",
        ));
    }
    if !registration.pockets.iter().any(|pocket| {
        pocket.status == StripFeederPocketStatus::Available
            && pocket.occupancy == StripPocketOccupancy::Occupied
    }) {
        return Err(ApiError::bad_request(
            "strip feeder has no available occupied pocket",
        ));
    }
    Ok(registration)
}

#[cfg(test)]
fn placement_validation_is_current(
    state: &AppState,
    registration: &StripFeederRegistration,
    step: &PlanStep,
    execution_id: Uuid,
) -> Result<bool, String> {
    let Some(execution) = state
        .store
        .get_placement_execution(execution_id)
        .map_err(|error| error.to_string())?
    else {
        return Ok(false);
    };
    let Some(report) = execution.report else {
        return Ok(false);
    };
    Ok(execution.status == OperationStatus::Succeeded
        && execution.calibration_id == registration.calibration_id
        && report.passed
        && !report.simulated
        && registration.active_feeder_id == Some(step.feeder_id)
        && registration.part_key.as_deref() == Some(step.part_key.as_str())
        && report.feeder_id == step.feeder_id
        && report.part_key == step.part_key
        && report.nozzle_id == step.nozzle_id
        && report.part_orientation == step.part_orientation
        && held_part_rotation_error_deg(
            report.feeder_part_rotation_deg,
            step.feeder_part_rotation_deg,
            PartOrientation::FeederReferenced,
        )
        .abs()
            <= 0.01
        && report.pickup_report.as_ref().is_some_and(|pickup| {
            pickup.passed
                && pickup.released
                && pickup.disposition == StripFeederPickupDisposition::PlacedOnBoard
                && pickup
                    .nozzle_release_verification
                    .as_ref()
                    .is_some_and(|verification| verification.passed)
        })
        && report
            .top_inspection
            .as_ref()
            .is_some_and(|inspection| inspection.passed))
}

fn promote_strip_feeder_after_placement(
    state: &AppState,
    registration_id: Uuid,
    execution_id: Uuid,
    report: &PlacementExecutionReport,
) -> Result<(), String> {
    if !report.passed
        || report.simulated
        || !report.pickup_report.as_ref().is_some_and(|pickup| {
            pickup.passed
                && pickup.released
                && pickup.disposition == StripFeederPickupDisposition::PlacedOnBoard
                && pickup
                    .nozzle_release_verification
                    .as_ref()
                    .is_some_and(|verification| verification.passed)
        })
        || !report
            .top_inspection
            .as_ref()
            .is_some_and(|inspection| inspection.passed)
    {
        return Err("feeder promotion requires a passed physical placement".into());
    }
    let mut registration = state
        .store
        .get_strip_feeder_registration(registration_id)
        .map_err(|error| error.to_string())?
        .ok_or_else(|| "placement feeder registration disappeared".to_string())?;
    if registration.status != StripFeederRegistrationStatus::PlacementValidationRequired {
        return Ok(());
    }
    if registration.active_feeder_id != Some(report.feeder_id) {
        return Err("placement evidence does not match the provisional feeder".into());
    }
    if registration.part_key.as_deref() != Some(report.part_key.as_str()) {
        return Err("placement part does not match the provisional feeder".into());
    }
    registration.status = StripFeederRegistrationStatus::Ready;
    registration.latest_placement_validation_id = Some(execution_id);
    registration.updated_at = Utc::now();
    registration.findings.retain(|finding| {
        !finding.contains("guarded inspected placement")
            && !finding.contains("guarded board placement")
    });
    registration
        .findings
        .push("guarded board placement and top inspection passed".into());
    state
        .store
        .put_strip_feeder_registration(&registration)
        .map_err(|error| error.to_string())
}

async fn execute_retained_part_recovery_task(
    state: AppState,
    prepared: PreparedRetainedPartRecovery,
) -> Result<Option<String>, String> {
    let _motion_guard = state.workspace_scan_motion_lock.lock().await;
    let PreparedRetainedPartRecovery {
        lease_id,
        operation: _,
        mut run,
        source_run,
        source_report,
        step,
        motion_planner,
        physical,
        bare,
    } = prepared;
    run.status = OperationStatus::Running;
    run.updated_at = Utc::now();
    let mut report = PlacementExecutionReport {
        algorithm_version: RETAINED_PART_RECOVERY_ALGORITHM.into(),
        simulated: false,
        board_instance_id: Some(step.board_instance_id),
        placement_reference: step.placement_reference.clone(),
        part_key: step.part_key.clone(),
        feeder_id: step.feeder_id,
        feeder_registration_id: source_report.feeder_registration_id,
        nozzle_id: step.nozzle_id.clone(),
        part_orientation: step.part_orientation,
        feeder_part_rotation_deg: step.feeder_part_rotation_deg,
        feeder_pick: source_report.feeder_pick,
        board_place: step.board_place,
        part_height_mm: step.part_height_mm,
        placement_surface_offset_mm: step.placement_surface_offset_mm,
        placement_seating_offset_mm: step.placement_seating_offset_mm,
        placement_release_seating_offsets_mm: step
            .placement_release_seating_offsets_mm
            .clone(),
        successful_placement_seating_offset_mm: None,
        placement_release_attempts: Vec::new(),
        pocket_index: source_report.pocket_index,
        pickup_open_nozzle_raw_values: Vec::new(),
        pickup_search_samples: Vec::new(),
        pickup_attempts: Vec::new(),
        source_pose_inspection: None,
        pickup_report: None,
        board_target_registration: None,
        top_inspection: None,
        top_inspection_comparison: None,
        artifact_names: Vec::new(),
        corrected_move_count: 0,
        passed: false,
        stages: vec![PlacementExecutionStageReport {
            stage: PlacementExecutionStage::Preflight,
            passed: true,
            message: format!(
                "source execution {} and an empty {} target were confirmed for retained-part recovery",
                source_run.id, step.placement_reference,
            ),
        }],
        findings: vec![format!(
            "recovery continued the part retained by source execution {} without consuming another feeder pocket",
            source_run.id,
        )],
    };
    if (step.placement_seating_offset_mm - source_report.placement_seating_offset_mm).abs() > 1e-9 {
        report.findings.push(format!(
            "recovery overrode the source seating offset from {:+.3} to {:+.3} mm",
            source_report.placement_seating_offset_mm, step.placement_seating_offset_mm,
        ));
    }
    if step.placement_reference != source_report.placement_reference {
        report.findings.push(format!(
            "recovery redirected the retained part from {} to the confirmed empty {} target",
            source_report.placement_reference, step.placement_reference,
        ));
    }
    run.report = Some(report.clone());
    state
        .store
        .put_placement_execution(&run)
        .map_err(|error| error.to_string())?;
    let (result, _camera_timing) = with_profiled_camera_reuse(
        &state,
        execute_physical_retained_part_recovery(
            &state,
            &run,
            &step,
            lease_id,
            &motion_planner,
            &physical,
            &bare,
            &source_report,
            &mut report,
        ),
    )
    .await;
    match result {
        Ok(()) => {
            report.passed = true;
            report.stages.push(PlacementExecutionStageReport {
                stage: PlacementExecutionStage::Complete,
                passed: true,
                message: "retained part was placed and inspected without another pickup".into(),
            });
            run.status = OperationStatus::Succeeded;
            run.message = Some(format!(
                "Recovered retained part onto {}",
                step.placement_reference
            ));
        }
        Err(error) => {
            if failed_recovery_requires_vacuum_hold(&report) {
                report.findings.push(
                    "retained-part recovery stopped with possible held-part evidence; vacuum remains on for operator recovery"
                        .into(),
                );
            } else {
                let _ = state
                    .machine
                    .disable_actuator(physical.vacuum_characterization.sensor_id.clone())
                    .await;
            }
            report.findings.push(error.clone());
            run.status = OperationStatus::Failed;
            run.message = Some(error);
        }
    }
    run.report = Some(report);
    run.updated_at = Utc::now();
    state
        .store
        .put_placement_execution(&run)
        .map_err(|error| error.to_string())?;
    persist_automatic_placement_outcome(&state, &run).map_err(|error| error.to_string())?;
    record_retained_part_recovery_attempt(&state, source_run.id, &run)?;
    if run.status == OperationStatus::Succeeded {
        Ok(run.message)
    } else {
        Err(run
            .message
            .clone()
            .unwrap_or_else(|| "retained-part recovery failed".into()))
    }
}

fn failed_recovery_requires_vacuum_hold(report: &PlacementExecutionReport) -> bool {
    report
        .placement_release_attempts
        .last()
        .is_none_or(|attempt| {
            !attempt.nozzle_clear
                && (attempt.vacuum_reacquired == Some(true)
                    || (attempt.vacuum_reacquired.is_none() && !attempt.sensor_released))
        })
}

#[allow(clippy::too_many_arguments)]
async fn execute_physical_retained_part_recovery(
    state: &AppState,
    run: &PlacementExecutionRun,
    step: &PlanStep,
    lease_id: Uuid,
    planner: &MotionPlanner,
    prepared: &PreparedStripFeederPickup,
    bare: &GrayFrame,
    source_report: &PlacementExecutionReport,
    report: &mut PlacementExecutionReport,
) -> Result<(), String> {
    let pickup = state.profile.strip_feeder_pickup.as_ref().unwrap();
    let vacuum = state.profile.vacuum_calibration.as_ref().unwrap();
    let bottom = state.profile.bottom_vision.as_ref().unwrap();
    let z_kinematics = state.profile.z_kinematics.as_ref().unwrap();
    let sensor_id = prepared.vacuum_characterization.sensor_id.as_str();
    let camera_profile =
        stored_camera_profile(state, CameraRole::BottomCamera).map_err(|error| error.message)?;
    let camera_path =
        camera_path_for_role(CameraRole::BottomCamera).map_err(|error| error.message)?;
    let nozzle = bottom
        .nozzles
        .iter()
        .find(|nozzle| nozzle.nozzle_id == step.nozzle_id)
        .ok_or_else(|| "retained-part nozzle is not in the bottom-vision profile".to_string())?;
    state
        .machine
        .actuate(lease_id, sensor_id.into(), true)
        .await
        .map_err(|error| error.to_string())?;
    tokio::time::sleep(Duration::from_millis(vacuum.vacuum_settle_ms)).await;

    execute_visual_home(
        state,
        VisualHomingRequest {
            lease_id,
            apply_offset: true,
            move_to_seed: true,
        },
    )
    .await
    .map_err(|error| error.message)?;
    let (board_before, _) = capture_top_pocket_mean(
        state,
        prepared,
        [step.board_place.x_mm, step.board_place.y_mm],
        pickup.inspection_sample_count,
    )
    .await?;
    persist_placement_gray_artifact(
        state,
        run.id,
        BOARD_PLACEMENT_BEFORE_ARTIFACT,
        &board_before,
    )?;
    let top_mapping = local_planar_camera_mapping(
        &prepared.top_camera_model,
        prepared.top_camera_model.center_x_px,
        prepared.top_camera_model.center_y_px,
    )
    .ok_or_else(|| "top-camera recovery mapping is invalid".to_string())?;
    let target_registration = register_two_terminal_placement_target(
        &board_before,
        [
            prepared.top_camera_model.center_x_px,
            prepared.top_camera_model.center_y_px,
        ],
        top_mapping,
        step.body_width_mm,
        step.body_length_mm,
        step.board_place.rotation_deg,
        BOARD_TARGET_REGISTRATION_ARTIFACT,
    )
    .map_err(|error| error.to_string())?;
    persist_placement_rgb_artifact(
        state,
        run.id,
        BOARD_TARGET_REGISTRATION_ARTIFACT,
        &target_registration.preview,
    )?;
    let target_report = target_registration.report;
    report.artifact_names.extend([
        BOARD_PLACEMENT_BEFORE_ARTIFACT.into(),
        BOARD_TARGET_REGISTRATION_ARTIFACT.into(),
    ]);
    report.board_target_registration = Some(target_report.clone());
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::BoardTargetRegistration,
        passed: target_report.passed,
        message: target_report.findings[0].clone(),
    });
    persist_placement_progress(state, run, report)?;
    if !target_report.passed {
        return Err("top vision did not register the empty recovery target".into());
    }
    let local_target_correction_mm = [
        target_report
            .correction_x_mm
            .ok_or_else(|| "recovery target has no X correction".to_string())?,
        target_report
            .correction_y_mm
            .ok_or_else(|| "recovery target has no Y correction".to_string())?,
    ];

    persist_placement_gray_artifact(state, run.id, BARE_NOZZLE_ARTIFACT, bare)?;
    let controller_angle_deg = state
        .machine
        .calibration_rotation_reference(lease_id, step.nozzle_id.clone())
        .await
        .map_err(|error| error.to_string())?;
    state
        .machine
        .calibration_rotate_nozzle(lease_id, step.nozzle_id.clone(), 0.0)
        .await
        .map_err(|error| format!("retained-part rotation reset failed: {error}"))?;
    report.findings.push(
        "restored the nozzle rotation reference before measuring the retained-part pose".into(),
    );
    let [runout_x_mm, runout_y_mm] = prepared
        .geometry
        .runout_correction_at(controller_angle_deg)
        .ok_or_else(|| "retained-part runout correction is invalid".to_string())?;
    let current_tip_offset = CurrentTipOffset {
        x_mm: prepared.geometry.head_offset_x_mm - runout_x_mm,
        y_mm: prepared.geometry.head_offset_y_mm - runout_y_mm,
    };
    let bottom_pose = execute_pickup_xy_transit(
        state,
        prepared,
        bottom.nozzle_target(nozzle),
        prepared.carried_xy_feed_mm_per_min,
    )
    .await?;
    let held = capture_bottom_mean_with_lights(
        state,
        lease_id,
        &camera_profile,
        &camera_path,
        pickup.inspection_sample_count,
    )
    .await?;
    persist_placement_gray_artifact(state, run.id, HELD_PART_ARTIFACT, &held)?;
    let mut initial = inspect_held_part_difference_with_orientation(
        bare,
        &held,
        [bottom.frame_center_x_px, bottom.frame_center_y_px],
        prepared.head_reference.bottom_camera_mapping,
        pickup.maximum_part_offset_mm,
        pickup.minimum_part_size_mm,
        pickup.maximum_part_size_mm,
        prepared.part_orientation,
        HELD_PART_INITIAL_INSPECTION_ARTIFACT,
    )
    .map_err(|error| error.to_string())?;
    apply_expected_held_part_size_gate(
        &mut initial.report,
        prepared.expected_part_size_mm,
        prepared.expected_part_size_source,
    );
    apply_registered_orientation_fallback(
        &mut initial.report,
        prepared.part_orientation,
        prepared.source_rotation_deg,
        prepared.expected_part_size_mm,
        pickup,
    );
    persist_placement_rgb_artifact(
        state,
        run.id,
        HELD_PART_INITIAL_INSPECTION_ARTIFACT,
        &initial.preview,
    )?;
    if let Some(shadow) = analyze_and_persist_held_part_shadow(
        state,
        prepared,
        bare,
        &held,
        &initial,
        [bottom.frame_center_x_px, bottom.frame_center_y_px],
        HELD_PART_INITIAL_INSPECTION_ARTIFACT,
        HeldPartControlPolicy::ShadowOnly,
    )
    .await
    {
        report
            .artifact_names
            .extend([shadow.report_artifact_name, shadow.preview_artifact_name]);
    }
    if !initial.report.passed {
        return Err("bottom vision did not confirm the retained resistor".into());
    }
    let (_, alignment) = align_held_part(
        state,
        prepared,
        bare,
        initial,
        bottom_pose,
        &camera_profile,
        &camera_path,
        step.board_place.rotation_deg,
        true,
        None,
    )
    .await?;
    if !alignment.passed {
        return Err("bottom vision did not align the retained resistor".into());
    }
    let inspection = alignment
        .observations
        .last()
        .map(|observation| observation.inspection.clone())
        .ok_or_else(|| "retained-part alignment has no inspection".to_string())?;
    let held_raw_values =
        collect_sensor_values(state, lease_id, sensor_id, pickup.held_sample_count).await?;
    let held_median_raw_value = median_raw(&held_raw_values);
    let source_pickup = source_report
        .pickup_report
        .as_ref()
        .ok_or_else(|| "source placement lost its pickup report".to_string())?;
    let contact = source_pickup
        .pickup_controller_z_mm
        .and_then(|controller_z_mm| {
            source_pickup
                .pickup_samples
                .iter()
                .min_by(|left, right| {
                    (left.controller_z_mm - controller_z_mm)
                        .abs()
                        .total_cmp(&(right.controller_z_mm - controller_z_mm).abs())
                })
                .cloned()
        })
        .ok_or_else(|| "source placement has no pickup contact sample".to_string())?;
    let mut artifact_names = vec![
        BARE_NOZZLE_ARTIFACT.into(),
        HELD_PART_ARTIFACT.into(),
        HELD_PART_INITIAL_INSPECTION_ARTIFACT.into(),
    ];
    for name in &alignment.artifact_names {
        if !artifact_names.contains(name) {
            artifact_names.push(name.clone());
        }
    }
    let acquired = AcquiredPlacementPart {
        current_tip_offset,
        bottom_pose,
        bare: bare.clone(),
        pickup_center_machine_mm: source_pickup.pocket_machine_mm,
        pickup_head_machine_mm: [
            source_report.feeder_pick.x_mm,
            source_report.feeder_pick.y_mm,
        ],
        contact,
        open_nozzle_raw_values: source_pickup.open_nozzle_raw_values.clone(),
        pickup_samples: source_pickup.pickup_samples.clone(),
        held_raw_values,
        held_median_raw_value,
        inspection,
        alignment,
        artifact_names,
    };
    report.pickup_open_nozzle_raw_values = acquired.open_nozzle_raw_values.clone();
    report.pickup_search_samples = acquired.pickup_samples.clone();
    report
        .artifact_names
        .extend(acquired.artifact_names.clone());
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::Pickup,
        passed: true,
        message: "bottom vision confirmed the previously acquired resistor remained on N1".into(),
    });
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::BottomInspection,
        passed: true,
        message: format!(
            "bottom vision re-aligned the retained resistor to {:.3} degrees with {:.3} mm residual",
            step.board_place.rotation_deg,
            acquired
                .alignment
                .final_centering_residual_mm
                .unwrap_or_default(),
        ),
    });
    persist_placement_progress(state, run, report)?;

    let height_correction = placement_height_correction(prepared, step.board_place.z_mm)?;
    let [place_head_x_mm, place_head_y_mm] = resolved_physical_place_head_xy(
        [step.board_place.x_mm, step.board_place.y_mm],
        local_target_correction_mm,
        acquired.current_tip_offset,
        height_correction,
        &acquired.alignment,
    )?;
    let place_controller_z_mm = z_kinematics
        .controller_z(&step.nozzle_id, step.board_place.z_mm)
        .ok_or_else(|| "recovery placement Z is outside controller bounds".to_string())?;
    let current_pose = state
        .machine
        .status()
        .pose
        .ok_or_else(|| "retained-part recovery lost the controller pose".to_string())?;
    let mut motion_state = planner
        .initial_state(current_pose)
        .map_err(|error| error.to_string())?;
    let place_level = Pose {
        x_mm: place_head_x_mm,
        y_mm: place_head_y_mm,
        z_mm: z_kinematics.level_controller_z_mm,
        rotation_deg: current_pose.rotation_deg,
    };
    let place_contact = Pose {
        z_mm: place_controller_z_mm,
        ..place_level
    };
    let planned = execute_job_motion(
        &state.machine,
        lease_id,
        planner,
        &mut motion_state,
        place_level,
        prepared.carried_xy_feed_mm_per_min,
        MotionMode::Calibrated,
    )
    .await?;
    report.corrected_move_count += u32::from(planned.correction.applied());
    approach_z_with_slow_finish(
        state,
        lease_id,
        place_contact.z_mm,
        prepared.carried_z_feed_mm_per_min,
        vacuum.z_approach_feed_mm_per_min,
        prepared.precision_z_approach_mm,
    )
    .await?;
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::PlaceApproach,
        passed: true,
        message: format!(
            "moved the retained resistor above the registered target at X{:+.3} Y{:+.3} mm",
            local_target_correction_mm[0], local_target_correction_mm[1],
        ),
    });
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::Placement,
        passed: true,
        message: format!(
            "reached recovery contact Z{:.3} with seating offset {:+.3} mm",
            step.board_place.z_mm, step.placement_seating_offset_mm,
        ),
    });
    persist_placement_progress(state, run, report)?;

    let board_release = release_part_at_board_and_verify(
        state,
        run.id,
        step,
        lease_id,
        planner,
        place_level,
        place_contact,
        local_target_correction_mm,
        prepared,
        &acquired,
    )
    .await;
    let board_release = match board_release {
        Ok(board_release) => board_release,
        Err(error) => {
            if let Err(capture_error) = capture_post_contact_board_frame(
                state,
                run,
                step,
                prepared,
                pickup.inspection_sample_count,
                report,
            )
            .await
            {
                report.findings.push(format!(
                    "top-camera post-contact evidence capture failed: {capture_error}"
                ));
                let _ = persist_placement_progress(state, run, report);
            }
            return Err(error);
        }
    };
    let VerifiedBoardRelease {
        release_raw_values,
        verification: release_verification,
        corrected_move_count,
        sensor_released: _,
        successful_seating_offset_mm,
        attempts,
        retained_part_secured: _,
    } = board_release;
    report.corrected_move_count += corrected_move_count;
    report.successful_placement_seating_offset_mm = successful_seating_offset_mm;
    report.placement_release_attempts = attempts;
    let nozzle_clear = release_verification.nozzle_clear;
    report
        .artifact_names
        .extend(release_verification.artifact_names.clone());
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::Release,
        passed: nozzle_clear,
        message: release_verification
            .findings
            .first()
            .cloned()
            .unwrap_or_else(|| "release verification produced no finding".into()),
    });
    let mut pickup_report = build_placement_pickup_report(
        prepared,
        &acquired,
        [
            step.board_place.x_mm + local_target_correction_mm[0],
            step.board_place.y_mm + local_target_correction_mm[1],
        ],
        release_raw_values,
        release_verification,
        nozzle_clear,
    );
    pickup_report.algorithm_version = RETAINED_PART_RECOVERY_ALGORITHM.into();
    pickup_report.vacuum_held_after_transfer = acquired
        .held_median_raw_value
        .is_some_and(|value| vacuum_value_is_acquired(&prepared.vacuum_characterization, value));
    pickup_report.findings = vec![
        "bottom vision recovered a previously acquired part without another feeder pickup".into(),
    ];
    report.pickup_report = Some(pickup_report);
    persist_placement_progress(state, run, report)?;
    let board_after = capture_post_contact_board_frame(
        state,
        run,
        step,
        prepared,
        pickup.inspection_sample_count,
        report,
    )
    .await?;
    if !nozzle_clear {
        return Err("retained resistor did not release after the bounded recovery attempts".into());
    }
    let placement_center_tolerance_mm = (0.5 * step.body_width_mm)
        .max(0.25)
        .min(pickup.maximum_part_offset_mm);
    let top_inspection = inspect_placed_part_with_orientation(
        &board_before,
        &board_after,
        [
            prepared.top_camera_model.center_x_px,
            prepared.top_camera_model.center_y_px,
        ],
        top_mapping,
        step.body_width_mm,
        step.body_length_mm,
        step.board_place.rotation_deg,
        placement_center_tolerance_mm,
        MAX_PLACED_PART_ROTATION_ERROR_DEG,
        step.part_orientation,
        BOARD_PLACEMENT_INSPECTION_ARTIFACT,
    )
    .map_err(|error| error.to_string())?;
    persist_placement_rgb_artifact(
        state,
        run.id,
        BOARD_PLACEMENT_INSPECTION_ARTIFACT,
        &top_inspection.preview,
    )?;
    report
        .artifact_names
        .push(BOARD_PLACEMENT_INSPECTION_ARTIFACT.into());
    let active_inspection = if let Some(learned) = analyze_and_persist_placement_verification(
        state,
        run.id,
        &board_after,
        &top_inspection,
        top_mapping,
        step.body_width_mm,
        step.body_length_mm,
        step.board_place.rotation_deg,
        placement_center_tolerance_mm,
        step.part_orientation,
    )
    .await
    {
        report.artifact_names.extend([
            learned.comparison.report_artifact_name.clone(),
            learned.comparison.preview_artifact_name.clone(),
            learned.comparison.crop_artifact_name.clone(),
        ]);
        report.top_inspection_comparison = Some(learned.comparison);
        learned.active
    } else {
        top_inspection.report.clone()
    };
    report.top_inspection = Some(active_inspection.clone());
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::TopInspection,
        passed: active_inspection.passed,
        message: if active_inspection.passed {
            "top vision confirmed the recovered resistor at the target".into()
        } else {
            "top vision did not confirm the recovered resistor".into()
        },
    });
    persist_placement_progress(state, run, report)?;
    if !active_inspection.passed {
        return Err("top vision did not confirm the recovered resistor placement".into());
    }
    Ok(())
}

fn record_retained_part_recovery_attempt(
    state: &AppState,
    source_execution_id: Uuid,
    recovery: &PlacementExecutionRun,
) -> Result<(), String> {
    let Some(report) = recovery.report.as_ref() else {
        return Ok(());
    };
    for mut job_run in state
        .store
        .list_job_executions()
        .map_err(|error| error.to_string())?
        .into_iter()
        .filter(|run| run.job_id == recovery.job_id)
    {
        let Some(source_step_index) = job_run
            .steps
            .iter()
            .position(|step| step.attempt_execution_ids.contains(&source_execution_id))
        else {
            continue;
        };
        let Some(target_step_index) = job_run
            .steps
            .iter()
            .position(|step| step.step_index == recovery.step_index)
        else {
            continue;
        };
        let step = &mut job_run.steps[target_step_index];
        if !step.attempt_execution_ids.contains(&recovery.id) {
            step.attempt_execution_ids.push(recovery.id);
        }
        step.execution_id = Some(recovery.id);
        step.board_contacted = report
            .stages
            .iter()
            .any(|stage| stage.stage == PlacementExecutionStage::Placement && stage.passed);
        let (disposition, _) = classify_placement_outcome(report);
        step.outcome_disposition = Some(disposition);
        if recovery.status == OperationStatus::Succeeded {
            step.status = JobExecutionStepStatus::Succeeded;
            step.message = Some("retained-part recovery passed bottom and top vision".into());
        } else {
            step.message = recovery.message.clone();
        }
        if recovery.status == OperationStatus::Succeeded && source_step_index != target_step_index {
            let source_step = &mut job_run.steps[source_step_index];
            source_step.message = Some(format!(
                "retained part was redirected to {}; this target remains unfilled",
                report.placement_reference,
            ));
        }
        job_run.updated_at = Utc::now();
        state
            .store
            .put_job_execution(&job_run)
            .map_err(|error| error.to_string())?;
    }
    Ok(())
}

async fn execute_guarded_placement_task(
    state: AppState,
    mut run: PlacementExecutionRun,
    step: PlanStep,
    lease_id: Uuid,
    motion_planner: MotionPlanner,
    physical: Option<PreparedStripFeederPickup>,
    promote_feeder: bool,
) -> Result<Option<String>, String> {
    let _motion_guard = state.workspace_scan_motion_lock.lock().await;
    run.status = OperationStatus::Running;
    run.updated_at = Utc::now();
    let mut report = PlacementExecutionReport {
        algorithm_version: PLACEMENT_EXECUTION_ALGORITHM.into(),
        simulated: physical.is_none(),
        board_instance_id: Some(step.board_instance_id),
        placement_reference: step.placement_reference.clone(),
        part_key: step.part_key.clone(),
        feeder_id: step.feeder_id,
        feeder_registration_id: physical.as_ref().map(|prepared| prepared.registration.id),
        nozzle_id: step.nozzle_id.clone(),
        part_orientation: step.part_orientation,
        feeder_part_rotation_deg: step.feeder_part_rotation_deg,
        feeder_pick: step.feeder_pick,
        board_place: step.board_place,
        part_height_mm: step.part_height_mm,
        placement_surface_offset_mm: step.placement_surface_offset_mm,
        placement_seating_offset_mm: step.placement_seating_offset_mm,
        placement_release_seating_offsets_mm: step.placement_release_seating_offsets_mm.clone(),
        successful_placement_seating_offset_mm: None,
        placement_release_attempts: Vec::new(),
        pocket_index: physical.as_ref().map(|prepared| prepared.run.pocket_index),
        pickup_open_nozzle_raw_values: Vec::new(),
        pickup_search_samples: Vec::new(),
        pickup_attempts: Vec::new(),
        source_pose_inspection: None,
        pickup_report: None,
        board_target_registration: None,
        top_inspection: None,
        top_inspection_comparison: None,
        artifact_names: Vec::new(),
        corrected_move_count: 0,
        passed: false,
        stages: vec![PlacementExecutionStageReport {
            stage: PlacementExecutionStage::Preflight,
            passed: true,
            message: "job, board, feeder, calibration, and single-step gates passed".into(),
        }],
        findings: if physical.is_none() {
            vec!["simulation does not consume a physical feeder pocket or place a component".into()]
        } else {
            Vec::new()
        },
    };
    run.report = Some(report.clone());
    state
        .store
        .put_placement_execution(&run)
        .map_err(|error| error.to_string())?;
    let result = if let Some(prepared) = physical.as_ref() {
        let (result, _camera_timing) = with_profiled_camera_reuse(
            &state,
            execute_physical_guarded_placement(
                &state,
                &run,
                &step,
                lease_id,
                &motion_planner,
                prepared,
                &mut report,
            ),
        )
        .await;
        result
    } else {
        execute_guarded_placement_motion(
            &state,
            &run,
            &step,
            lease_id,
            &motion_planner,
            &mut report,
        )
        .await
    };
    match result {
        Ok(()) => {
            report.passed = true;
            report.stages.push(PlacementExecutionStageReport {
                stage: PlacementExecutionStage::Complete,
                passed: true,
                message: if physical.is_some() {
                    "one production physical placement completed".into()
                } else {
                    "one production simulated placement completed".into()
                },
            });
            run.status = OperationStatus::Succeeded;
            run.message = Some(format!(
                "{} production placement {}",
                if physical.is_some() {
                    "Completed"
                } else {
                    "Simulated"
                },
                step.placement_reference
            ));
            if let Some(prepared) = physical.as_ref().filter(|_| promote_feeder) {
                if let Err(error) = promote_strip_feeder_after_placement(
                    &state,
                    prepared.registration.id,
                    run.id,
                    &report,
                ) {
                    report.findings.push(error.clone());
                    run.status = OperationStatus::Failed;
                    run.message = Some(format!(
                        "Placement completed, but feeder promotion failed: {error}"
                    ));
                    run.report = Some(report);
                    run.updated_at = Utc::now();
                    state
                        .store
                        .put_placement_execution(&run)
                        .map_err(|store_error| store_error.to_string())?;
                    return Err(error);
                }
            }
            run.report = Some(report);
            run.updated_at = Utc::now();
            state
                .store
                .put_placement_execution(&run)
                .map_err(|error| error.to_string())?;
            persist_automatic_placement_outcome(&state, &run).map_err(|error| error.to_string())?;
            Ok(run.message)
        }
        Err(error) => {
            if let Some(sensor_id) = sensor_id_for_nozzle(&step.nozzle_id) {
                let _ = state.machine.disable_actuator(sensor_id.into()).await;
            }
            report.findings.push(error.clone());
            let pocket_approach_started = report
                .stages
                .iter()
                .any(|stage| stage.stage == PlacementExecutionStage::PickApproach && stage.passed);
            run.status = OperationStatus::Failed;
            run.message = Some(error.clone());
            run.report = Some(report);
            run.updated_at = Utc::now();
            state
                .store
                .put_placement_execution(&run)
                .map_err(|store_error| store_error.to_string())?;
            if let Some(prepared) = physical.as_ref() {
                let reservation_is_active = state
                    .store
                    .get_strip_feeder_registration(prepared.registration.id)
                    .map_err(|store_error| store_error.to_string())?
                    .is_some_and(|registration| {
                        registration.pockets.iter().any(|pocket| {
                            pocket.reservation_id == Some(run.id)
                                && pocket.pocket_index == prepared.run.pocket_index
                        })
                    });
                if reservation_is_active {
                    let recovery = if pocket_approach_started {
                        state.store.settle_strip_feeder_pocket(
                            prepared.registration.id,
                            run.id,
                            StripFeederPocketOutcome::Interrupted,
                            false,
                        )
                    } else {
                        state.store.release_strip_feeder_pocket_reservation(
                            prepared.registration.id,
                            run.id,
                        )
                    };
                    if let Err(store_error) = recovery {
                        tracing::error!(%store_error, execution_id = %run.id, "failed to recover interrupted placement pocket");
                    }
                }
            }
            persist_automatic_placement_outcome(&state, &run)
                .map_err(|store_error| store_error.to_string())?;
            Err(error)
        }
    }
}

async fn execute_guarded_placement_motion(
    state: &AppState,
    run: &PlacementExecutionRun,
    step: &PlanStep,
    lease_id: Uuid,
    planner: &MotionPlanner,
    report: &mut PlacementExecutionReport,
) -> Result<(), String> {
    let sensor_id = sensor_id_for_nozzle(&step.nozzle_id)
        .ok_or_else(|| format!("placement nozzle {} has no vacuum sensor", step.nozzle_id))?;
    let controller_pose = state
        .machine
        .status()
        .pose
        .ok_or_else(|| "single placement lost the controller pose".to_string())?;
    let mut motion_state = planner
        .initial_state(controller_pose)
        .map_err(|error| error.to_string())?;
    let pick_safe = Pose {
        z_mm: step.safe_z_mm,
        ..step.feeder_pick
    };
    let place_safe = Pose {
        z_mm: step.safe_z_mm,
        ..step.board_place
    };
    let planned = execute_job_motion(
        &state.machine,
        lease_id,
        planner,
        &mut motion_state,
        pick_safe,
        300.0,
        MotionMode::Calibrated,
    )
    .await?;
    report.corrected_move_count += u32::from(planned.correction.applied());
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::PickApproach,
        passed: true,
        message: "moved to the feeder at safe Z through the calibrated planner".into(),
    });
    persist_placement_progress(state, run, report)?;

    let planned = execute_job_motion(
        &state.machine,
        lease_id,
        planner,
        &mut motion_state,
        step.feeder_pick,
        120.0,
        MotionMode::Calibrated,
    )
    .await?;
    report.corrected_move_count += u32::from(planned.correction.applied());
    state
        .machine
        .actuate(lease_id, sensor_id.into(), true)
        .await
        .map_err(|error| error.to_string())?;
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::Pickup,
        passed: true,
        message: format!(
            "simulator activated {} vacuum at the planned feeder pose",
            step.nozzle_id
        ),
    });

    let planned = execute_job_motion(
        &state.machine,
        lease_id,
        planner,
        &mut motion_state,
        pick_safe,
        120.0,
        MotionMode::Calibrated,
    )
    .await?;
    report.corrected_move_count += u32::from(planned.correction.applied());
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::BottomInspection,
        passed: true,
        message: "simulator consumed the feeder's retained bottom-vision qualification gate".into(),
    });
    persist_placement_progress(state, run, report)?;

    let planned = execute_job_motion(
        &state.machine,
        lease_id,
        planner,
        &mut motion_state,
        place_safe,
        300.0,
        MotionMode::Calibrated,
    )
    .await?;
    report.corrected_move_count += u32::from(planned.correction.applied());
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::PlaceApproach,
        passed: true,
        message: "moved above the registered board placement at safe Z".into(),
    });

    let planned = execute_job_motion(
        &state.machine,
        lease_id,
        planner,
        &mut motion_state,
        step.board_place,
        120.0,
        MotionMode::Calibrated,
    )
    .await?;
    report.corrected_move_count += u32::from(planned.correction.applied());
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::Placement,
        passed: true,
        message: "reached the planned component placement pose".into(),
    });
    state
        .machine
        .actuate(lease_id, sensor_id.into(), false)
        .await
        .map_err(|error| error.to_string())?;
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::Release,
        passed: true,
        message: format!(
            "simulator disabled {} vacuum at the placement pose",
            step.nozzle_id
        ),
    });

    let planned = execute_job_motion(
        &state.machine,
        lease_id,
        planner,
        &mut motion_state,
        place_safe,
        120.0,
        MotionMode::Calibrated,
    )
    .await?;
    report.corrected_move_count += u32::from(planned.correction.applied());
    let top_inspection_pose = Pose {
        x_mm: step.board_place.x_mm,
        y_mm: step.board_place.y_mm,
        z_mm: step.safe_z_mm,
        rotation_deg: step.board_place.rotation_deg,
    };
    let planned = execute_job_motion(
        &state.machine,
        lease_id,
        planner,
        &mut motion_state,
        top_inspection_pose,
        300.0,
        MotionMode::Calibrated,
    )
    .await?;
    report.corrected_move_count += u32::from(planned.correction.applied());
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::TopInspection,
        passed: true,
        message: "simulator reached the top-inspection pose; no image was captured".into(),
    });
    persist_placement_progress(state, run, report)?;
    Ok(())
}

struct AcquiredPlacementPart {
    current_tip_offset: CurrentTipOffset,
    bottom_pose: Pose,
    bare: GrayFrame,
    pickup_center_machine_mm: [f64; 2],
    pickup_head_machine_mm: [f64; 2],
    contact: VacuumProbeSample,
    open_nozzle_raw_values: Vec<i64>,
    pickup_samples: Vec<VacuumProbeSample>,
    held_raw_values: Vec<i64>,
    held_median_raw_value: Option<f64>,
    inspection: HeldPartInspectionReport,
    alignment: HeldPartAlignmentReport,
    artifact_names: Vec<String>,
}

fn resolved_physical_place_head_xy(
    nominal_target_mm: [f64; 2],
    local_target_correction_mm: [f64; 2],
    current_tip_offset: CurrentTipOffset,
    height_correction_mm: [f64; 2],
    alignment: &HeldPartAlignmentReport,
) -> Result<[f64; 2], String> {
    if !alignment.passed || alignment.observations.is_empty() {
        return Err("placement requires a verified final bottom-camera pose".into());
    }
    let values = [
        nominal_target_mm[0],
        nominal_target_mm[1],
        local_target_correction_mm[0],
        local_target_correction_mm[1],
        current_tip_offset.x_mm,
        current_tip_offset.y_mm,
        height_correction_mm[0],
        height_correction_mm[1],
        alignment.commanded_x_mm,
        alignment.commanded_y_mm,
    ];
    if !values.into_iter().all(f64::is_finite) {
        return Err("placement XY transform contains a non-finite value".into());
    }
    // The live tip offset is measured at the bottom-camera reference pose.
    // The verified alignment translation includes part offset and any runout
    // caused by the commanded nozzle rotation. The height model then transfers
    // that observed pose to the placement Z, including nozzle-axis tilt.
    Ok([
        nominal_target_mm[0] + local_target_correction_mm[0]
            - current_tip_offset.x_mm
            - height_correction_mm[0]
            + alignment.commanded_x_mm,
        nominal_target_mm[1] + local_target_correction_mm[1]
            - current_tip_offset.y_mm
            - height_correction_mm[1]
            + alignment.commanded_y_mm,
    ])
}

fn placement_height_correction(
    prepared: &PreparedStripFeederPickup,
    nozzle_z_mm: f64,
) -> Result<[f64; 2], String> {
    let base = prepared
        .height_model
        .as_ref()
        .and_then(|model| model.tip_offset_correction_at(nozzle_z_mm))
        .ok_or_else(|| "placement Z is outside the calibrated height model".to_string())?;
    let correction = [
        base[0] + prepared.placement_transfer_correction_mm[0],
        base[1] + prepared.placement_transfer_correction_mm[1],
    ];
    correction
        .iter()
        .all(|value| value.is_finite())
        .then_some(correction)
        .ok_or_else(|| "combined placement-transfer correction is invalid".to_string())
}

#[allow(clippy::too_many_arguments)]
async fn execute_physical_guarded_placement(
    state: &AppState,
    run: &PlacementExecutionRun,
    step: &PlanStep,
    lease_id: Uuid,
    planner: &MotionPlanner,
    prepared: &PreparedStripFeederPickup,
    report: &mut PlacementExecutionReport,
) -> Result<(), String> {
    let pickup = state.profile.strip_feeder_pickup.as_ref().unwrap();
    let sensor_id = prepared.vacuum_characterization.sensor_id.as_str();
    execute_visual_home(
        state,
        VisualHomingRequest {
            lease_id: prepared.lease_id,
            apply_offset: true,
            move_to_seed: true,
        },
    )
    .await
    .map_err(|error| error.message)?;
    let (board_before, _) = capture_top_pocket_mean(
        state,
        prepared,
        [step.board_place.x_mm, step.board_place.y_mm],
        pickup.inspection_sample_count,
    )
    .await?;
    persist_placement_gray_artifact(
        state,
        run.id,
        BOARD_PLACEMENT_BEFORE_ARTIFACT,
        &board_before,
    )?;
    report
        .artifact_names
        .push(BOARD_PLACEMENT_BEFORE_ARTIFACT.into());
    let top_mapping = local_planar_camera_mapping(
        &prepared.top_camera_model,
        prepared.top_camera_model.center_x_px,
        prepared.top_camera_model.center_y_px,
    )
    .ok_or_else(|| "top-camera placement mapping is invalid".to_string())?;
    let target_registration = register_two_terminal_placement_target(
        &board_before,
        [
            prepared.top_camera_model.center_x_px,
            prepared.top_camera_model.center_y_px,
        ],
        top_mapping,
        step.body_width_mm,
        step.body_length_mm,
        step.board_place.rotation_deg,
        BOARD_TARGET_REGISTRATION_ARTIFACT,
    )
    .map_err(|error| error.to_string())?;
    persist_placement_rgb_artifact(
        state,
        run.id,
        BOARD_TARGET_REGISTRATION_ARTIFACT,
        &target_registration.preview,
    )?;
    let target_report = target_registration.report;
    report
        .artifact_names
        .push(BOARD_TARGET_REGISTRATION_ARTIFACT.into());
    report.board_target_registration = Some(target_report.clone());
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::BoardTargetRegistration,
        passed: target_report.passed,
        message: target_report.findings[0].clone(),
    });
    persist_placement_progress(state, run, report)?;
    if !target_report.passed {
        return Err("top vision did not register the local placement pad pair".into());
    }
    let local_target_correction_mm = [
        target_report
            .correction_x_mm
            .ok_or_else(|| "local placement target has no X correction".to_string())?,
        target_report
            .correction_y_mm
            .ok_or_else(|| "local placement target has no Y correction".to_string())?,
    ];

    let acquired = acquire_physical_placement_part(
        state,
        run,
        prepared,
        step.board_place.rotation_deg,
        report,
    )
    .await;
    let acquired = match acquired {
        Ok(acquired) => acquired,
        Err(error) => {
            report.stages.push(PlacementExecutionStageReport {
                stage: PlacementExecutionStage::Pickup,
                passed: false,
                message: error.clone(),
            });
            persist_placement_progress(state, run, report)?;
            return Err(error);
        }
    };
    report.feeder_pick = Pose {
        x_mm: acquired.pickup_center_machine_mm[0],
        y_mm: acquired.pickup_center_machine_mm[1],
        z_mm: acquired.contact.nozzle_z_mm,
        rotation_deg: prepared.registration.part_rotation_deg.unwrap_or(0.0),
    };
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::Pickup,
        passed: true,
        message: format!(
            "vacuum acquired the part at nozzle Z{:.3}",
            acquired.contact.nozzle_z_mm,
        ),
    });
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::BottomInspection,
        passed: acquired.inspection.passed && acquired.alignment.passed,
        message: format!(
            "bottom vision aligned the part to {:.3} degrees with {:.3} mm center residual",
            step.board_place.rotation_deg,
            acquired
                .alignment
                .final_centering_residual_mm
                .unwrap_or_default(),
        ),
    });
    report
        .artifact_names
        .extend(acquired.artifact_names.clone());
    persist_placement_progress(state, run, report)?;

    let mut part_no_longer_safe_for_source_return = false;
    let placement_result: Result<(), String> = async {
        let z_kinematics = state.profile.z_kinematics.as_ref().unwrap();
        let vacuum = state.profile.vacuum_calibration.as_ref().unwrap();
        let height_correction = placement_height_correction(prepared, step.board_place.z_mm)?;
        let [place_head_x_mm, place_head_y_mm] = resolved_physical_place_head_xy(
            [step.board_place.x_mm, step.board_place.y_mm],
            local_target_correction_mm,
            acquired.current_tip_offset,
            height_correction,
            &acquired.alignment,
        )?;
        let place_controller_z_mm = z_kinematics
            .controller_z(&step.nozzle_id, step.board_place.z_mm)
            .ok_or_else(|| "placement Z is outside controller bounds".to_string())?;
        let current_pose = state
            .machine
            .status()
            .pose
            .ok_or_else(|| "physical placement lost the controller pose".to_string())?;
        let mut motion_state = planner
            .initial_state(current_pose)
            .map_err(|error| error.to_string())?;
        let place_level = Pose {
            x_mm: place_head_x_mm,
            y_mm: place_head_y_mm,
            z_mm: z_kinematics.level_controller_z_mm,
            rotation_deg: current_pose.rotation_deg,
        };
        let place_contact = Pose {
            z_mm: place_controller_z_mm,
            ..place_level
        };
        let planned = execute_job_motion(
            &state.machine,
            lease_id,
            planner,
            &mut motion_state,
            place_level,
            prepared.carried_xy_feed_mm_per_min,
            MotionMode::Calibrated,
        )
        .await?;
        report.corrected_move_count += u32::from(planned.correction.applied());
        report.stages.push(PlacementExecutionStageReport {
            stage: PlacementExecutionStage::PlaceApproach,
            passed: true,
            message: format!(
                "moved the aligned part above the local pad target at X{:+.3} Y{:+.3} mm from nominal",
                local_target_correction_mm[0], local_target_correction_mm[1],
            ),
        });
        approach_z_with_slow_finish(
            state,
            lease_id,
            place_contact.z_mm,
            prepared.carried_z_feed_mm_per_min,
            vacuum.z_approach_feed_mm_per_min,
            prepared.precision_z_approach_mm,
        )
        .await?;
        report.stages.push(PlacementExecutionStageReport {
            stage: PlacementExecutionStage::Placement,
            passed: true,
            message: format!(
                "reached nozzle-contact Z{:.3}: part {:.3}, surface offset {:+.3}, seating offset {:+.3} mm",
                step.board_place.z_mm,
                step.part_height_mm,
                step.placement_surface_offset_mm,
                step.placement_seating_offset_mm,
            ),
        });
        persist_placement_progress(state, run, report)?;

        let board_release = release_part_at_board_and_verify(
            state,
            run.id,
            step,
            lease_id,
            planner,
            place_level,
            place_contact,
            local_target_correction_mm,
            prepared,
            &acquired,
        )
        .await?;
        let VerifiedBoardRelease {
            release_raw_values,
            verification: release_verification,
            corrected_move_count,
            sensor_released,
            successful_seating_offset_mm,
            attempts,
            retained_part_secured,
        } = board_release;
        report.corrected_move_count += corrected_move_count;
        report.successful_placement_seating_offset_mm = successful_seating_offset_mm;
        report.placement_release_attempts = attempts;
        let nozzle_clear = release_verification.nozzle_clear;
        report
            .artifact_names
            .extend(release_verification.artifact_names.clone());
        report.stages.push(PlacementExecutionStageReport {
            stage: PlacementExecutionStage::Release,
            passed: nozzle_clear,
            message: release_verification.findings[0].clone(),
        });
        if !nozzle_clear {
            report.pickup_report = Some(build_placement_pickup_report(
                prepared,
                &acquired,
                [
                    step.board_place.x_mm + local_target_correction_mm[0],
                    step.board_place.y_mm + local_target_correction_mm[1],
                ],
                release_raw_values,
                release_verification,
                false,
            ));
            persist_placement_progress(state, run, report)?;
            part_no_longer_safe_for_source_return = !retained_part_secured;
            return Err(if sensor_released {
                "vacuum confirmed release, but bottom vision did not confirm a clear nozzle".into()
            } else {
                "placement release did not confirm a clear nozzle".into()
            });
        }
        part_no_longer_safe_for_source_return = true;

        let board_after = capture_post_contact_board_frame(
            state,
            run,
            step,
            prepared,
            pickup.inspection_sample_count,
            report,
        )
        .await?;
        let placement_center_tolerance_mm = (0.5 * step.body_width_mm)
            .max(0.25)
            .min(pickup.maximum_part_offset_mm);
        let top_inspection = inspect_placed_part_with_orientation(
            &board_before,
            &board_after,
            [
                prepared.top_camera_model.center_x_px,
                prepared.top_camera_model.center_y_px,
            ],
            top_mapping,
            step.body_width_mm,
            step.body_length_mm,
            step.board_place.rotation_deg,
            placement_center_tolerance_mm,
            MAX_PLACED_PART_ROTATION_ERROR_DEG,
            step.part_orientation,
            BOARD_PLACEMENT_INSPECTION_ARTIFACT,
        )
        .map_err(|error| error.to_string())?;
        persist_placement_rgb_artifact(
            state,
            run.id,
            BOARD_PLACEMENT_INSPECTION_ARTIFACT,
            &top_inspection.preview,
        )?;
        report
            .artifact_names
            .push(BOARD_PLACEMENT_INSPECTION_ARTIFACT.into());
        let active_inspection = if let Some(learned) =
            analyze_and_persist_placement_verification(
                state,
                run.id,
                &board_after,
                &top_inspection,
                top_mapping,
                step.body_width_mm,
                step.body_length_mm,
                step.board_place.rotation_deg,
                placement_center_tolerance_mm,
                step.part_orientation,
            )
            .await
        {
            report.artifact_names.extend([
                learned.comparison.report_artifact_name.clone(),
                learned.comparison.preview_artifact_name.clone(),
                learned.comparison.crop_artifact_name.clone(),
            ]);
            report.top_inspection_comparison = Some(learned.comparison);
            learned.active
        } else {
            top_inspection.report.clone()
        };
        report.top_inspection = Some(active_inspection.clone());
        report.pickup_report = Some(build_placement_pickup_report(
            prepared,
            &acquired,
            [
                step.board_place.x_mm + local_target_correction_mm[0],
                step.board_place.y_mm + local_target_correction_mm[1],
            ],
            release_raw_values,
            release_verification,
            true,
        ));
        report.stages.push(PlacementExecutionStageReport {
            stage: PlacementExecutionStage::TopInspection,
            passed: active_inspection.passed,
            message: if active_inspection.passed {
                "top vision detected the placed component at the planned location".into()
            } else {
                "top vision did not confirm the placed component".into()
            },
        });
        state
            .store
            .settle_strip_feeder_pocket(
                prepared.registration.id,
                run.id,
                StripFeederPocketOutcome::Consumed,
                true,
            )
            .map_err(|error| error.to_string())?;
        decrement_feeder_remaining(state, step.feeder_id)?;
        persist_placement_progress(state, run, report)?;
        if !active_inspection.passed {
            return Err("top vision did not confirm the physical placement".into());
        }
        report.findings.push(format!(
            "consumed feeder pocket {} only after pickup and release evidence passed",
            prepared.run.pocket_index,
        ));
        report.findings.push(format!(
            "placed from the verified bottom-camera pose with X{:+.3} Y{:+.3} mm height correction; no unverified residual move was added",
            height_correction[0], height_correction[1],
        ));
        Ok(())
    }
    .await;
    if placement_result.is_err() && placement_post_contact_image_is_missing(report) {
        if let Err(capture_error) = capture_post_contact_board_frame(
            state,
            run,
            step,
            prepared,
            pickup.inspection_sample_count,
            report,
        )
        .await
        {
            report.findings.push(format!(
                "top-camera post-contact evidence capture failed: {capture_error}"
            ));
            let _ = persist_placement_progress(state, run, report);
        }
    }
    match placement_result {
        Ok(()) => Ok(()),
        Err(error) if part_no_longer_safe_for_source_return => Err(error),
        Err(error) => {
            let cleanup = drop_interrupted_production_pickup(
                state,
                prepared,
                sensor_id,
                acquired.pickup_head_machine_mm,
                acquired.current_tip_offset,
                acquired.contact.controller_z_mm,
            )
            .await;
            Err(match cleanup {
                Ok(()) => {
                    format!("{error}; any held part was dropped at the production reject location")
                }
                Err(cleanup) => format!("{error}; placement recovery also failed: {cleanup}"),
            })
        }
    }
}

fn placement_post_contact_image_is_missing(report: &PlacementExecutionReport) -> bool {
    let board_contacted = report
        .stages
        .iter()
        .any(|stage| stage.stage == PlacementExecutionStage::Placement && stage.passed);
    let board_after_retained = report
        .artifact_names
        .iter()
        .any(|name| name == BOARD_PLACEMENT_AFTER_ARTIFACT);
    board_contacted && !board_after_retained
}

struct VerifiedBoardRelease {
    release_raw_values: Vec<i64>,
    verification: NozzleReleaseVerificationReport,
    corrected_move_count: u32,
    sensor_released: bool,
    successful_seating_offset_mm: Option<f64>,
    attempts: Vec<PlacementReleaseAttemptReport>,
    retained_part_secured: bool,
}

fn placement_release_offsets(step: &PlanStep) -> Vec<f64> {
    if step.placement_release_seating_offsets_mm.is_empty() {
        vec![step.placement_seating_offset_mm]
    } else {
        step.placement_release_seating_offsets_mm.clone()
    }
}

fn placement_release_nozzle_z_mm(step: &PlanStep, seating_offset_mm: f64) -> f64 {
    step.board_place.z_mm + seating_offset_mm - step.placement_seating_offset_mm
}

fn blowoff_actuator_id_for_nozzle(nozzle_id: &str) -> Option<&'static str> {
    match nozzle_id {
        "N1" => Some("blowoff_1"),
        "N2" => Some("blowoff_2"),
        _ => None,
    }
}

#[allow(clippy::too_many_arguments)]
async fn release_part_at_board_and_verify(
    state: &AppState,
    execution_id: Uuid,
    step: &PlanStep,
    lease_id: Uuid,
    planner: &MotionPlanner,
    place_level: Pose,
    place_contact: Pose,
    local_target_correction_mm: [f64; 2],
    prepared: &PreparedStripFeederPickup,
    acquired: &AcquiredPlacementPart,
) -> Result<VerifiedBoardRelease, String> {
    let pickup = state.profile.strip_feeder_pickup.as_ref().unwrap();
    let vacuum = state.profile.vacuum_calibration.as_ref().unwrap();
    let bottom = state.profile.bottom_vision.as_ref().unwrap();
    let sensor_id = prepared.vacuum_characterization.sensor_id.as_str();
    let bottom_profile =
        stored_camera_profile(state, CameraRole::BottomCamera).map_err(|error| error.message)?;
    let bottom_path =
        camera_path_for_role(CameraRole::BottomCamera).map_err(|error| error.message)?;
    let mut release_raw_values = Vec::new();
    let mut observations = Vec::new();
    let mut artifact_names = Vec::new();
    let mut findings = Vec::new();
    let mut nozzle_clear = false;
    let mut release_sensor_confirmed = false;
    let mut corrected_move_count = 0;
    let mut attempts = Vec::new();
    let mut successful_seating_offset_mm = None;
    let mut retained_part_secured = false;
    let mut active_alignment = acquired.alignment.clone();
    let mut active_tip_offset = acquired.current_tip_offset;
    let blowoff_id = blowoff_actuator_id_for_nozzle(&step.nozzle_id)
        .ok_or_else(|| "placement nozzle has no blowoff actuator".to_string())?;
    let release_offsets = placement_release_offsets(step);

    for (attempt_index, seating_offset_mm) in release_offsets.iter().copied().enumerate() {
        let attempt = attempt_index as u32 + 1;
        let nozzle_z_mm = placement_release_nozzle_z_mm(step, seating_offset_mm);
        let controller_z_mm = state
            .profile
            .z_kinematics
            .as_ref()
            .and_then(|kinematics| kinematics.controller_z(&step.nozzle_id, nozzle_z_mm))
            .ok_or_else(|| "placement release Z is outside controller bounds".to_string())?;
        let (attempt_level, attempt_contact) = if attempt == 1 {
            (place_level, place_contact)
        } else {
            let height_correction = placement_height_correction(prepared, nozzle_z_mm)?;
            let [head_x_mm, head_y_mm] = resolved_physical_place_head_xy(
                [step.board_place.x_mm, step.board_place.y_mm],
                local_target_correction_mm,
                active_tip_offset,
                height_correction,
                &active_alignment,
            )?;
            let current_pose =
                state.machine.status().pose.ok_or_else(|| {
                    "placement release retry lost the controller pose".to_string()
                })?;
            let level = Pose {
                x_mm: head_x_mm,
                y_mm: head_y_mm,
                z_mm: state
                    .profile
                    .z_kinematics
                    .as_ref()
                    .unwrap()
                    .level_controller_z_mm,
                rotation_deg: current_pose.rotation_deg,
            };
            (
                level,
                Pose {
                    z_mm: controller_z_mm,
                    ..level
                },
            )
        };
        if attempt > 1 {
            let current_pose =
                state.machine.status().pose.ok_or_else(|| {
                    "placement release retry lost the controller pose".to_string()
                })?;
            let mut motion_state = planner
                .initial_state(current_pose)
                .map_err(|error| error.to_string())?;
            let planned = execute_job_motion(
                &state.machine,
                lease_id,
                planner,
                &mut motion_state,
                attempt_level,
                prepared.carried_xy_feed_mm_per_min,
                MotionMode::Calibrated,
            )
            .await?;
            corrected_move_count += u32::from(planned.correction.applied());
            approach_z_with_slow_finish(
                state,
                lease_id,
                attempt_contact.z_mm,
                prepared.carried_z_feed_mm_per_min,
                vacuum.z_approach_feed_mm_per_min,
                prepared.precision_z_approach_mm,
            )
            .await?;
            findings.push(format!(
                "release attempt {attempt} used seating offset {seating_offset_mm:+.3} mm at nozzle Z{nozzle_z_mm:.3}"
            ));
        }
        state
            .machine
            .disable_actuator(sensor_id.into())
            .await
            .map_err(|error| error.to_string())?;
        state
            .machine
            .actuate(lease_id, blowoff_id.into(), true)
            .await
            .map_err(|error| error.to_string())?;
        tokio::time::sleep(Duration::from_millis(pickup.board_release_valve_pulse_ms)).await;
        state
            .machine
            .disable_actuator(blowoff_id.into())
            .await
            .map_err(|error| error.to_string())?;
        findings.push(format!(
            "pulsed the {} blowoff valve during board release attempt {attempt}",
            step.nozzle_id,
        ));
        tokio::time::sleep(Duration::from_millis(pickup.release_settle_ms)).await;
        move_vertical_at_current_xy(
            state,
            lease_id,
            attempt_level.z_mm,
            prepared.clear_z_feed_mm_per_min,
        )
        .await?;
        let raw_values =
            collect_sensor_values(state, lease_id, sensor_id, pickup.release_sample_count).await?;
        let sensor_released = median_raw(&raw_values).is_some_and(|value| {
            vacuum_value_is_released(&prepared.vacuum_characterization, value)
        });
        release_sensor_confirmed |= sensor_released;
        release_raw_values.extend(raw_values.iter().copied());
        let retry_bottom_pose = execute_pickup_xy_transit(
            state,
            prepared,
            translation_only_jog_target(acquired.bottom_pose),
            prepared.clear_xy_feed_mm_per_min,
        )
        .await?;
        let post_release = capture_bottom_mean_with_lights(
            state,
            lease_id,
            &bottom_profile,
            &bottom_path,
            pickup.inspection_sample_count,
        )
        .await?;
        let raw_artifact = if attempt == 1 {
            POST_RELEASE_NOZZLE_ARTIFACT.to_string()
        } else {
            format!("post-release-nozzle-attempt-{attempt}.png")
        };
        let inspection_artifact = if attempt == 1 {
            POST_RELEASE_NOZZLE_INSPECTION_ARTIFACT.to_string()
        } else {
            format!("post-release-nozzle-inspection-attempt-{attempt}.png")
        };
        persist_placement_gray_artifact(state, execution_id, &raw_artifact, &post_release)?;
        let mut inspection = inspect_held_part_difference_with_orientation(
            &acquired.bare,
            &post_release,
            [bottom.frame_center_x_px, bottom.frame_center_y_px],
            prepared.head_reference.bottom_camera_mapping,
            pickup.maximum_part_offset_mm,
            pickup.minimum_part_size_mm,
            pickup.maximum_part_size_mm,
            prepared.part_orientation,
            &inspection_artifact,
        )
        .map_err(|error| error.to_string())?;
        persist_placement_rgb_artifact(
            state,
            execution_id,
            &inspection_artifact,
            &inspection.preview,
        )?;
        let release_shadow = analyze_and_persist_held_part_shadow(
            state,
            prepared,
            &acquired.bare,
            &post_release,
            &inspection,
            [bottom.frame_center_x_px, bottom.frame_center_y_px],
            &inspection_artifact,
            HeldPartControlPolicy::ReleaseNozzleClear,
        )
        .await;
        let model_confirmed_clear = release_shadow
            .as_ref()
            .is_some_and(|shadow| shadow.control_authorized);
        let retained_part = !model_confirmed_clear
            && post_release_matches_held_part(
                release_reference_inspection(&acquired.alignment, &acquired.inspection),
                &inspection.report,
            );
        if model_confirmed_clear && inspection.report.detected {
            findings.push(format!(
                "the held-part model overrode a deterministic false-positive release detection on attempt {attempt}"
            ));
        }
        nozzle_clear = nozzle_release_attempt_passed(sensor_released, retained_part);
        retained_part_secured = false;
        observations.push(inspection.report.clone());
        artifact_names.extend([raw_artifact.clone(), inspection_artifact.clone()]);
        if let Some(shadow) = release_shadow.as_ref() {
            artifact_names.extend([
                shadow.report_artifact_name.clone(),
                shadow.preview_artifact_name.clone(),
            ]);
        }
        let mut attempt_artifact_names = vec![raw_artifact, inspection_artifact];
        if let Some(shadow) = release_shadow {
            attempt_artifact_names
                .extend([shadow.report_artifact_name, shadow.preview_artifact_name]);
        }
        let mut attempt_report = PlacementReleaseAttemptReport {
            attempt_index: attempt,
            seating_offset_mm,
            nozzle_z_mm,
            controller_z_mm,
            release_raw_values: raw_values,
            sensor_released,
            retained_part_detected: retained_part,
            nozzle_clear,
            vacuum_reacquired: None,
            hold_raw_values: Vec::new(),
            realignment: None,
            artifact_names: attempt_artifact_names,
        };
        if nozzle_clear {
            successful_seating_offset_mm = Some(seating_offset_mm);
            findings.push(format!(
                "bottom vision confirmed a clear nozzle after board release attempt {attempt} at seating offset {seating_offset_mm:+.3} mm"
            ));
            attempts.push(attempt_report);
            break;
        }
        if !retained_part {
            findings.push(format!(
                "release attempt {attempt} was ambiguous because vacuum and bottom vision did not prove either transfer or retention"
            ));
            attempts.push(attempt_report);
            break;
        }

        state
            .machine
            .actuate(lease_id, sensor_id.into(), true)
            .await
            .map_err(|error| error.to_string())?;
        tokio::time::sleep(Duration::from_millis(vacuum.vacuum_settle_ms)).await;
        let hold_raw_values =
            collect_sensor_values(state, lease_id, sensor_id, pickup.held_sample_count).await?;
        let vacuum_reacquired = median_raw(&hold_raw_values).is_some_and(|value| {
            vacuum_value_is_acquired(&prepared.vacuum_characterization, value)
        });
        attempt_report.vacuum_reacquired = Some(vacuum_reacquired);
        attempt_report.hold_raw_values = hold_raw_values;
        retained_part_secured = vacuum_reacquired;
        if !vacuum_reacquired {
            findings.push(format!(
                "release attempt {attempt} found a retained part but could not restore vacuum hold"
            ));
            attempts.push(attempt_report);
            break;
        }

        if attempt_index + 1 < release_offsets.len() {
            apply_expected_held_part_size_gate(
                &mut inspection.report,
                prepared.expected_part_size_mm,
                prepared.expected_part_size_source,
            );
            apply_registered_orientation_fallback(
                &mut inspection.report,
                prepared.part_orientation,
                step.board_place.rotation_deg,
                prepared.expected_part_size_mm,
                pickup,
            );
            let controller_angle_deg = state
                .machine
                .calibration_rotation_reference(lease_id, step.nozzle_id.clone())
                .await
                .map_err(|error| error.to_string())?;
            let [runout_x_mm, runout_y_mm] = prepared
                .geometry
                .runout_correction_at(controller_angle_deg)
                .ok_or_else(|| "retained-part runout correction is invalid".to_string())?;
            active_tip_offset = CurrentTipOffset {
                x_mm: prepared.geometry.head_offset_x_mm - runout_x_mm,
                y_mm: prepared.geometry.head_offset_y_mm - runout_y_mm,
            };
            let suffix = format!("release-attempt-{attempt}");
            let realignment = align_held_part(
                state,
                prepared,
                &acquired.bare,
                inspection,
                retry_bottom_pose,
                &bottom_profile,
                &bottom_path,
                step.board_place.rotation_deg,
                true,
                Some(&suffix),
            )
            .await;
            let (_, realignment) = match realignment {
                Ok(realignment) => realignment,
                Err(error) => {
                    findings.push(format!(
                        "release attempt {attempt} retained the part, but bottom-camera realignment failed: {error}"
                    ));
                    attempts.push(attempt_report);
                    break;
                }
            };
            for name in &realignment.artifact_names {
                if !artifact_names.contains(name) {
                    artifact_names.push(name.clone());
                }
                if !attempt_report.artifact_names.contains(name) {
                    attempt_report.artifact_names.push(name.clone());
                }
            }
            if !realignment.passed {
                attempt_report.realignment = Some(realignment);
                findings.push(format!(
                    "release attempt {attempt} retained the part, but bottom vision could not realign it"
                ));
                attempts.push(attempt_report);
                break;
            }
            findings.push(format!(
                "release attempt {attempt} retained the part; vacuum hold and bottom-camera realignment passed before the next depth"
            ));
            active_alignment = realignment.clone();
            attempt_report.realignment = Some(realignment);
        }
        attempts.push(attempt_report);
        if attempt_index + 1 < release_offsets.len() {
            findings.push(format!(
                "board release attempt {attempt} did not confirm transfer; continuing to the next configured seating offset"
            ));
        }
    }
    state
        .machine
        .calibration_rotate_nozzle(lease_id, step.nozzle_id.clone(), 0.0)
        .await
        .map_err(|error| format!("placement rotation restore failed: {error}"))?;
    if !nozzle_clear {
        findings.push("bounded board release attempts did not prove a clear nozzle".into());
    }
    let attempt_count = observations.len() as u32;
    Ok(VerifiedBoardRelease {
        release_raw_values,
        verification: NozzleReleaseVerificationReport {
            algorithm_version: NOZZLE_RELEASE_VERIFICATION_ALGORITHM.into(),
            attempt_count,
            retry_performed: attempt_count > 1,
            nozzle_clear,
            passed: nozzle_clear,
            observations,
            artifact_names,
            findings,
        },
        corrected_move_count,
        sensor_released: release_sensor_confirmed,
        successful_seating_offset_mm,
        attempts,
        retained_part_secured,
    })
}

fn translation_only_jog_target(pose: Pose) -> JogTarget {
    JogTarget {
        x_mm: pose.x_mm,
        y_mm: pose.y_mm,
        z_mm: pose.z_mm,
        rotation_deg: None,
    }
}

fn bounded_pickup_feedback_correction(offsets_mm: &[[f64; 2]]) -> Option<[f64; 2]> {
    if offsets_mm.len() < MINIMUM_PICKUP_FEEDBACK_SAMPLE_COUNT
        || offsets_mm.len() > MAXIMUM_PICKUP_FEEDBACK_SAMPLE_COUNT
        || offsets_mm.iter().flatten().any(|value| !value.is_finite())
    {
        return None;
    }
    let spread_mm = offsets_mm
        .iter()
        .enumerate()
        .flat_map(|(index, left)| {
            offsets_mm[index + 1..]
                .iter()
                .map(move |right| (left[0] - right[0]).hypot(left[1] - right[1]))
        })
        .fold(0.0_f64, f64::max);
    if spread_mm > MAXIMUM_PICKUP_FEEDBACK_SPREAD_MM {
        return None;
    }
    let divisor = offsets_mm.len() as f64;
    let observed = offsets_mm.iter().fold([0.0, 0.0], |sum, offset| {
        [sum[0] + offset[0], sum[1] + offset[1]]
    });
    let correction = [-observed[0] / divisor, -observed[1] / divisor];
    let magnitude_mm = correction[0].hypot(correction[1]);
    (MINIMUM_PICKUP_FEEDBACK_CORRECTION_MM..=MAXIMUM_PICKUP_FEEDBACK_CORRECTION_MM)
        .contains(&magnitude_mm)
        .then_some(correction)
}

fn recent_pickup_feedback_correction(
    state: &AppState,
    run: &PlacementExecutionRun,
    nozzle_id: &str,
    part_key: &str,
) -> Option<([f64; 2], usize)> {
    let mut prior = state.store.list_placement_executions().ok()?;
    prior.sort_by(|left, right| right.updated_at.cmp(&left.updated_at));
    let offsets = prior
        .iter()
        .filter(|prior| prior.id != run.id && prior.job_id == run.job_id)
        .filter(|prior| prior.status == OperationStatus::Succeeded)
        .filter_map(|prior| prior.report.as_ref())
        .filter(|report| report.nozzle_id == nozzle_id && report.part_key == part_key)
        .filter_map(|report| report.top_inspection.as_ref())
        .filter(|inspection| inspection.passed)
        .filter_map(|inspection| inspection.offset_x_mm.zip(inspection.offset_y_mm))
        .map(|(x_mm, y_mm)| [x_mm, y_mm])
        .take(MAXIMUM_PICKUP_FEEDBACK_SAMPLE_COUNT)
        .collect::<Vec<_>>();
    bounded_pickup_feedback_correction(&offsets).map(|correction| (correction, offsets.len()))
}

async fn acquire_physical_placement_part(
    state: &AppState,
    run: &PlacementExecutionRun,
    prepared: &PreparedStripFeederPickup,
    target_rotation_deg: f64,
    report: &mut PlacementExecutionReport,
) -> Result<AcquiredPlacementPart, String> {
    let nozzle_id = &prepared.run.nozzle_id;
    let sensor_id = &prepared.vacuum_characterization.sensor_id;
    let pickup = state.profile.strip_feeder_pickup.as_ref().unwrap();
    let vacuum = state.profile.vacuum_calibration.as_ref().unwrap();
    let z_kinematics = state.profile.z_kinematics.as_ref().unwrap();
    let bottom = state.profile.bottom_vision.as_ref().unwrap();
    let camera_profile =
        stored_camera_profile(state, CameraRole::BottomCamera).map_err(|error| error.message)?;
    let camera_path =
        camera_path_for_role(CameraRole::BottomCamera).map_err(|error| error.message)?;
    let nominal_pocket_machine_mm = prepared
        .registration
        .selected_pocket_machine_mm
        .ok_or_else(|| "physical placement has no reserved pocket center".to_string())?;
    let contact_z_mm = prepared
        .reference_contact
        .contact_nozzle_z_mm
        .ok_or_else(|| "placement pickup has no reference contact".to_string())?;
    let search = VacuumProbeSearch {
        start_nozzle_z_mm: contact_z_mm + pickup.search_start_above_reference_mm,
        end_nozzle_z_mm: contact_z_mm + pickup.search_end_above_reference_mm,
    };
    state
        .machine
        .disable_actuator(sensor_id.clone())
        .await
        .map_err(|error| error.to_string())?;
    let current_tip_offset = measure_current_tip_offset(
        state,
        prepared.lease_id,
        nozzle_id,
        &prepared.head_reference,
        None,
    )
    .await?;
    let bottom_pose = state
        .machine
        .status()
        .pose
        .ok_or_else(|| "placement pickup lost the bottom-camera pose".to_string())?;
    let bare = capture_bottom_mean_with_lights(
        state,
        prepared.lease_id,
        &camera_profile,
        &camera_path,
        pickup.inspection_sample_count,
    )
    .await?;
    persist_transfer_gray_artifact(state, prepared, BARE_NOZZLE_ARTIFACT, &bare)?;
    let (source_before, source_before_pose) = capture_top_pocket_mean(
        state,
        prepared,
        nominal_pocket_machine_mm,
        pickup.inspection_sample_count,
    )
    .await?;
    persist_transfer_gray_artifact(
        state,
        prepared,
        SOURCE_POCKET_BEFORE_ARTIFACT,
        &source_before,
    )?;
    let source_control_frame = source_before.clone();
    let source_after = source_before.clone();
    let source_inspection_frame = source_before.clone();
    let registration = prepared.registration.clone();
    let camera_model = prepared.top_camera_model.clone();
    let source_inspection = tokio::task::spawn_blocking(move || {
        inspect_strip_feeder_pocket_return(
            &source_before,
            source_before_pose,
            &source_after,
            source_before_pose,
            &camera_model,
            &registration,
            nominal_pocket_machine_mm,
            SOURCE_POCKET_PICK_INSPECTION_ARTIFACT,
        )
    })
    .await
    .map_err(|error| error.to_string())?
    .map_err(|error| error.to_string())?;
    persist_transfer_rgb_artifact(
        state,
        prepared,
        SOURCE_POCKET_PICK_INSPECTION_ARTIFACT,
        &source_inspection.preview,
    )?;
    for artifact in [
        SOURCE_POCKET_BEFORE_ARTIFACT,
        SOURCE_POCKET_PICK_INSPECTION_ARTIFACT,
    ] {
        if !report.artifact_names.iter().any(|name| name == artifact) {
            report.artifact_names.push(artifact.into());
        }
    }
    let deterministic_center_machine_mm = source_inspection
        .report
        .before_measured_center_machine_mm
        .unwrap_or(nominal_pocket_machine_mm);
    let source_control = select_source_component_pick_center(
        state,
        prepared,
        &source_control_frame,
        source_before_pose,
        nominal_pocket_machine_mm,
        deterministic_center_machine_mm,
    )
    .await?;
    for artifact_name in &source_control.artifact_names {
        if !report.artifact_names.contains(artifact_name) {
            report.artifact_names.push(artifact_name.clone());
        }
    }
    report
        .findings
        .extend(source_control.findings.iter().cloned());
    if let Some(rejection) = &source_control.rejection {
        if rejection.observed_empty {
            settle_source_component_empty(state, prepared.registration.id, run.id)?;
            report.findings.push(format!(
                "marked feeder pocket {} empty from the confident source-model result",
                prepared.run.pocket_index,
            ));
            persist_placement_progress(state, run, report)?;
        }
        return Err(rejection.message.clone());
    }
    let mut pocket_machine_mm = source_control.center_machine_mm;
    let source_pose_inspection = if let Ok(references) =
        load_source_pose_references(state, &prepared.registration)
    {
        let candidate_pose = source_before_pose;
        let candidate_pocket = nominal_pocket_machine_mm;
        let source_pose_registration = prepared.registration.clone();
        let source_pose_camera_model = prepared.top_camera_model.clone();
        let allow_face_texture_change =
            matches!(prepared.part_orientation, PartOrientation::AxisSymmetric);
        let inspection = tokio::task::spawn_blocking(move || {
            inspect_source_pose_against_references(
                references,
                &source_inspection_frame,
                candidate_pose,
                candidate_pocket,
                &source_pose_camera_model,
                &source_pose_registration,
                allow_face_texture_change,
                SOURCE_POCKET_POSE_INSPECTION_ARTIFACT,
            )
        })
        .await
        .map_err(|error| error.to_string())??;
        persist_transfer_rgb_artifact(
            state,
            prepared,
            SOURCE_POCKET_POSE_INSPECTION_ARTIFACT,
            &inspection.preview,
        )?;
        if !report
            .artifact_names
            .iter()
            .any(|name| name == SOURCE_POCKET_POSE_INSPECTION_ARTIFACT)
        {
            report
                .artifact_names
                .push(SOURCE_POCKET_POSE_INSPECTION_ARTIFACT.into());
        }
        report
            .findings
            .extend(inspection.report.findings.iter().cloned());
        report.source_pose_inspection = Some(inspection.report.clone());
        Some(inspection)
    } else {
        report.findings.push(
            "production pickup used direct source vision without a qualification reference".into(),
        );
        None
    };
    persist_placement_progress(state, run, report)?;
    if source_control.learned_control_authorized {
        if source_pose_inspection
            .as_ref()
            .is_some_and(|inspection| !inspection.report.passed)
            || source_inspection.report.before_occupancy != StripPocketOccupancy::Occupied
        {
            report.findings.push(
                "the confident flat-part model controlled pickup while deterministic source vision remained audit-only"
                    .into(),
            );
        }
    } else {
        if source_pose_inspection
            .as_ref()
            .is_some_and(|inspection| !inspection.report.passed)
        {
            return Err("top vision rejected the source package pose before nozzle descent".into());
        }
        if source_inspection.report.before_occupancy != StripPocketOccupancy::Occupied {
            return Err("top vision did not confirm a part in the reserved pocket".into());
        }
        let deterministic_center_machine_mm = source_pose_inspection
            .as_ref()
            .and_then(|inspection| inspection.report.candidate_measured_center_machine_mm)
            .unwrap_or(deterministic_center_machine_mm);
        let pocket_center_correction_mm = (deterministic_center_machine_mm[0]
            - nominal_pocket_machine_mm[0])
            .hypot(deterministic_center_machine_mm[1] - nominal_pocket_machine_mm[1]);
        let production_source_center_limit_mm = pickup
            .maximum_part_offset_mm
            .max(0.4 * prepared.registration.tape_pitch_mm);
        if pocket_center_correction_mm > production_source_center_limit_mm {
            return Err(format!(
                "reserved-pocket part center correction \
                 {pocket_center_correction_mm:.3} mm exceeds the \
                 {production_source_center_limit_mm:.3} mm production bound"
            ));
        }
        pocket_machine_mm = deterministic_center_machine_mm;
    }
    persist_placement_progress(state, run, report)?;
    let alignment_nozzle_z_mm = 0.5 * (search.start_nozzle_z_mm + search.end_nozzle_z_mm);
    let height_correction = prepared
        .height_model
        .as_ref()
        .filter(|_| prepared.height_model_has_working_plane_transfer)
        .and_then(|model| model.tip_offset_correction_at(alignment_nozzle_z_mm))
        .ok_or_else(|| "placement pickup Z is outside the height model".to_string())?;
    let nominal_pickup_head = [
        pocket_machine_mm[0] - current_tip_offset.x_mm - height_correction[0],
        pocket_machine_mm[1] - current_tip_offset.y_mm - height_correction[1],
    ];
    let approach_controller_z_mm = z_kinematics
        .controller_z(nozzle_id, search.start_nozzle_z_mm)
        .ok_or_else(|| "placement pickup approach Z is outside bounds".to_string())?;
    let feedback =
        recent_pickup_feedback_correction(state, run, nozzle_id, report.part_key.as_str());
    let mut center_corrections = vec![[0.0, 0.0]];
    if let Some((correction, sample_count)) = feedback {
        center_corrections.push(correction);
        report.findings.push(format!(
            "prepared one bounded pickup retry at X{:+.3} Y{:+.3} mm from {sample_count} recent placement residuals",
            correction[0], correction[1],
        ));
    }
    for offset in &prepared.calibration_pickup_retry_offsets_mm {
        if !center_corrections.contains(offset) {
            center_corrections.push(*offset);
        }
    }
    if !prepared.calibration_pickup_retry_offsets_mm.is_empty() {
        report.findings.push(format!(
            "prepared {} calibration-only pickup search offsets after the vision center",
            prepared.calibration_pickup_retry_offsets_mm.len(),
        ));
    }
    report.stages.push(PlacementExecutionStageReport {
        stage: PlacementExecutionStage::PickApproach,
        passed: true,
        message: format!(
            "reserved pocket {} and prepared {} bounded pickup-center attempt(s)",
            prepared.run.pocket_index,
            center_corrections.len(),
        ),
    });
    let current_rotation_deg = state
        .machine
        .status()
        .pose
        .map_or(0.0, |pose| pose.rotation_deg);
    let mut acquired_probe = None;
    for (attempt_index, center_correction_mm) in center_corrections.iter().copied().enumerate() {
        let pickup_head = [
            nominal_pickup_head[0] + center_correction_mm[0],
            nominal_pickup_head[1] + center_correction_mm[1],
        ];
        let level_target = JogTarget {
            x_mm: pickup_head[0],
            y_mm: pickup_head[1],
            z_mm: z_kinematics.level_controller_z_mm,
            rotation_deg: None,
        };
        for z_mm in [z_kinematics.level_controller_z_mm, approach_controller_z_mm] {
            if !state.profile.bounds.contains(Pose {
                x_mm: pickup_head[0],
                y_mm: pickup_head[1],
                z_mm,
                rotation_deg: current_rotation_deg,
            }) {
                return Err("pickup-center retry is outside machine bounds".into());
            }
        }
        execute_pickup_xy_transit(
            state,
            prepared,
            level_target,
            prepared.clear_xy_feed_mm_per_min,
        )
        .await?;
        move_vertical_at_current_xy(
            state,
            prepared.lease_id,
            approach_controller_z_mm,
            prepared.clear_z_feed_mm_per_min,
        )
        .await?;
        state
            .machine
            .actuate(prepared.lease_id, sensor_id.clone(), true)
            .await
            .map_err(|error| error.to_string())?;
        tokio::time::sleep(Duration::from_millis(vacuum.vacuum_settle_ms)).await;
        let (open_nozzle_raw_values, pickup_samples, contact) = match execute_vacuum_probe_descent(
            state,
            prepared.lease_id,
            nozzle_id,
            sensor_id,
            pickup_head[0],
            pickup_head[1],
            search,
            Some(&prepared.vacuum_characterization),
            None,
        )
        .await
        {
            Ok(result) => result,
            Err(error) => {
                return Err(cleanup_unconfirmed_pickup(state, prepared, sensor_id, error).await)
            }
        };
        report.pickup_open_nozzle_raw_values = open_nozzle_raw_values.clone();
        report
            .pickup_search_samples
            .extend(pickup_samples.iter().cloned());
        report.pickup_attempts.push(PlacementPickupAttemptReport {
            attempt_index: attempt_index as u32 + 1,
            center_correction_mm,
            head_machine_mm: pickup_head,
            open_nozzle_raw_values: open_nozzle_raw_values.clone(),
            samples: pickup_samples.clone(),
            contact: contact.clone(),
            held_raw_values: Vec::new(),
            held_median_raw_value: None,
            vacuum_held_after_transfer: None,
            transfer_hold_accepted: None,
            held_part_inspection: None,
            artifact_names: Vec::new(),
        });
        persist_placement_progress(state, run, report)?;
        if let Some(contact) = contact {
            if !vacuum_value_is_acquired(
                &prepared.vacuum_characterization,
                contact.median_raw_value,
            ) {
                return Err(cleanup_unconfirmed_pickup(
                    state,
                    prepared,
                    sensor_id,
                    "placement pickup did not pass the calibrated acquire threshold".into(),
                )
                .await);
            }
            if prepared.calibration_pickup_seating_depth_mm > 0.0 {
                let seated_nozzle_z_mm = (contact.nozzle_z_mm
                    - prepared.calibration_pickup_seating_depth_mm)
                    .max(search.end_nozzle_z_mm);
                if seated_nozzle_z_mm < contact.nozzle_z_mm - f64::EPSILON {
                    let seated_controller_z_mm = z_kinematics
                        .controller_z(nozzle_id, seated_nozzle_z_mm)
                        .ok_or_else(|| {
                            "calibration pickup seating depth is outside Z bounds".to_string()
                        })?;
                    move_vertical_at_current_xy(
                        state,
                        prepared.lease_id,
                        seated_controller_z_mm,
                        vacuum.z_feed_mm_per_min,
                    )
                    .await?;
                    tokio::time::sleep(Duration::from_millis(vacuum.vacuum_settle_ms)).await;
                    report.findings.push(format!(
                        "calibration pickup seated {:.3} mm below the first vacuum transition",
                        contact.nozzle_z_mm - seated_nozzle_z_mm,
                    ));
                    persist_placement_progress(state, run, report)?;
                }
            }
            acquired_probe = Some((
                pickup_head,
                level_target,
                open_nozzle_raw_values,
                pickup_samples,
                contact,
            ));
            break;
        }
        if attempt_index + 1 < center_corrections.len() {
            move_vertical_at_current_xy(
                state,
                prepared.lease_id,
                level_target.z_mm,
                prepared.clear_z_feed_mm_per_min,
            )
            .await?;
            state
                .machine
                .disable_actuator(sensor_id.clone())
                .await
                .map_err(|error| error.to_string())?;
            report.findings.push(format!(
                "pickup-center attempt {} found no vacuum transition; continuing to the next bounded correction",
                attempt_index + 1,
            ));
            persist_placement_progress(state, run, report)?;
        }
    }
    let Some((pickup_head, level_target, open_nozzle_raw_values, pickup_samples, contact)) =
        acquired_probe
    else {
        return Err(cleanup_unconfirmed_pickup(
            state,
            prepared,
            sensor_id,
            format!(
                "placement pickup found no vacuum transition after {} bounded center attempt(s)",
                center_corrections.len(),
            ),
        )
        .await);
    };
    let pickup_controller_z_mm = contact.controller_z_mm;
    let result: Result<AcquiredPlacementPart, String> = async {
        move_vertical_at_current_xy(
            state,
            prepared.lease_id,
            level_target.z_mm,
            prepared.carried_z_feed_mm_per_min,
        )
        .await?;
        execute_pickup_xy_transit(
            state,
            prepared,
            JogTarget {
                x_mm: bottom_pose.x_mm,
                y_mm: bottom_pose.y_mm,
                z_mm: bottom_pose.z_mm,
                rotation_deg: None,
            },
            prepared.carried_xy_feed_mm_per_min,
        )
        .await?;
        let held_raw_values = collect_sensor_values(
            state,
            prepared.lease_id,
            sensor_id,
            pickup.held_sample_count,
        )
        .await?;
        let held_median_raw_value = median_raw(&held_raw_values);
        let vacuum_held_after_transfer = held_median_raw_value
            .is_some_and(|value| vacuum_value_is_acquired(&prepared.vacuum_characterization, value));
        if let Some(attempt) = report.pickup_attempts.last_mut() {
            attempt.held_raw_values = held_raw_values.clone();
            attempt.held_median_raw_value = held_median_raw_value;
            attempt.vacuum_held_after_transfer = Some(vacuum_held_after_transfer);
        }
        persist_placement_progress(state, run, report)?;
        let held = capture_bottom_mean_with_lights(
            state,
            prepared.lease_id,
            &camera_profile,
            &camera_path,
            pickup.inspection_sample_count,
        )
        .await?;
        persist_transfer_gray_artifact(state, prepared, HELD_PART_ARTIFACT, &held)?;
        let mut initial = inspect_held_part_difference_with_orientation(
            &bare,
            &held,
            [bottom.frame_center_x_px, bottom.frame_center_y_px],
            prepared.head_reference.bottom_camera_mapping,
            pickup.maximum_part_offset_mm,
            pickup.minimum_part_size_mm,
            pickup.maximum_part_size_mm,
            prepared.part_orientation,
            HELD_PART_INITIAL_INSPECTION_ARTIFACT,
        )
        .map_err(|error| error.to_string())?;
        apply_expected_held_part_size_gate(
            &mut initial.report,
            prepared.expected_part_size_mm,
            prepared.expected_part_size_source,
        );
        apply_registered_orientation_fallback(
            &mut initial.report,
            prepared.part_orientation,
            prepared.source_rotation_deg,
            prepared.expected_part_size_mm,
            pickup,
        );
        persist_transfer_rgb_artifact(
            state,
            prepared,
            HELD_PART_INITIAL_INSPECTION_ARTIFACT,
            &initial.preview,
        )?;
        let initial_shadow = analyze_and_persist_held_part_shadow(
            state,
            prepared,
            &bare,
            &held,
            &initial,
            [bottom.frame_center_x_px, bottom.frame_center_y_px],
            HELD_PART_INITIAL_INSPECTION_ARTIFACT,
            HeldPartControlPolicy::ShadowOnly,
        )
        .await;
        for artifact in [HELD_PART_ARTIFACT, HELD_PART_INITIAL_INSPECTION_ARTIFACT] {
            if !report.artifact_names.iter().any(|name| name == artifact) {
                report.artifact_names.push(artifact.into());
            }
        }
        if let Some(attempt) = report.pickup_attempts.last_mut() {
            attempt.held_part_inspection = Some(initial.report.clone());
            let mut attempt_artifacts = vec![
                HELD_PART_ARTIFACT.into(),
                HELD_PART_INITIAL_INSPECTION_ARTIFACT.into(),
            ];
            if let Some(shadow) = initial_shadow.as_ref() {
                attempt_artifacts.extend([
                    shadow.report_artifact_name.clone(),
                    shadow.preview_artifact_name.clone(),
                ]);
            }
            attempt.artifact_names = attempt_artifacts;
        }
        if let Some(shadow) = initial_shadow {
            report.artifact_names.extend([
                shadow.report_artifact_name,
                shadow.preview_artifact_name,
            ]);
        }
        let transfer_hold_accepted = vacuum_held_after_transfer
            || (initial.report.passed
                && marginal_transfer_vacuum_is_separated(
                    &prepared.vacuum_characterization.pump_on_open,
                    prepared.vacuum_characterization.signal_polarity,
                    prepared.vacuum_characterization.minimum_signal_delta_counts,
                    prepared
                        .vacuum_characterization
                        .minimum_distribution_gap_counts,
                    &held_raw_values,
                ));
        if let Some(attempt) = report.pickup_attempts.last_mut() {
            attempt.transfer_hold_accepted = Some(transfer_hold_accepted);
        }
        if transfer_hold_accepted && !vacuum_held_after_transfer {
            report.findings.push(
                "bottom vision and a separated vacuum distribution accepted a marginal transfer hold"
                    .into(),
            );
        }
        persist_placement_progress(state, run, report)?;
        if !transfer_hold_accepted {
            return Err(format!(
                "placement pickup did not retain calibrated vacuum hold; bottom vision {} a held part",
                if initial.report.passed {
                    "confirmed"
                } else {
                    "did not confirm"
                },
            ));
        }
        state
            .machine
            .calibration_rotation_reference(prepared.lease_id, nozzle_id.clone())
            .await
            .map_err(|error| error.to_string())?;
        if !initial.report.passed {
            return Err(
                "bottom vision did not confirm a usable held-part pose; placement is not allowed"
                    .into(),
            );
        }
        let (_, mut alignment) = align_held_part(
            state,
            prepared,
            &bare,
            initial,
            bottom_pose,
            &camera_profile,
            &camera_path,
            target_rotation_deg,
            true,
            None,
        )
        .await?;
        if !alignment.passed {
            let final_inspection = alignment
                .observations
                .last()
                .map(|observation| &observation.inspection);
            let production_translation_limit_mm = pickup
                .maximum_part_offset_mm
                .min(0.25);
            let production_pose_is_usable = alignment
                .observations
                .first()
                .is_some_and(|observation| observation.inspection.passed)
                && final_inspection.is_some_and(|inspection| inspection.detected)
                && alignment.final_centering_residual_mm.is_some_and(|residual| {
                    residual.is_finite() && residual <= production_translation_limit_mm
                })
                && alignment.final_rotation_residual_deg.is_some_and(|residual| {
                    residual.is_finite()
                        && residual.abs() <= MAX_PLACED_PART_ROTATION_ERROR_DEG
                });
            if !production_pose_is_usable {
                return Err("bottom vision did not align the held part".into());
            }
            alignment.passed = true;
            alignment.findings.push(format!(
                "production placement accepted the detected final held-part pose within \
                 {production_translation_limit_mm:.3} mm translation and \
                 {MAX_PLACED_PART_ROTATION_ERROR_DEG:.1} degree rotation limits",
            ));
        }
        let inspection = alignment
            .observations
            .last()
            .map(|observation| observation.inspection.clone())
            .ok_or_else(|| "held-part alignment has no inspection".to_string())?;
        let mut artifact_names = vec![
            BARE_NOZZLE_ARTIFACT.into(),
            SOURCE_POCKET_BEFORE_ARTIFACT.into(),
            SOURCE_POCKET_PICK_INSPECTION_ARTIFACT.into(),
            SOURCE_POCKET_POSE_INSPECTION_ARTIFACT.into(),
            HELD_PART_ARTIFACT.into(),
            HELD_PART_INITIAL_INSPECTION_ARTIFACT.into(),
        ];
        for name in &alignment.artifact_names {
            if !artifact_names.contains(name) {
                artifact_names.push(name.clone());
            }
        }
        Ok(AcquiredPlacementPart {
            current_tip_offset,
            bottom_pose,
            bare,
            pickup_center_machine_mm: pocket_machine_mm,
            pickup_head_machine_mm: pickup_head,
            contact,
            open_nozzle_raw_values,
            pickup_samples,
            held_raw_values,
            held_median_raw_value,
            inspection,
            alignment,
            artifact_names,
        })
    }
    .await;
    match result {
        Ok(acquired) => Ok(acquired),
        Err(error) => {
            let cleanup = drop_interrupted_production_pickup(
                state,
                prepared,
                sensor_id,
                pickup_head,
                current_tip_offset,
                pickup_controller_z_mm,
            )
            .await;
            Err(match cleanup {
                Ok(()) => {
                    format!("{error}; any held part was dropped at the production reject location")
                }
                Err(cleanup) => format!("{error}; pickup recovery also failed: {cleanup}"),
            })
        }
    }
}

async fn cleanup_unconfirmed_pickup(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    sensor_id: &str,
    error: String,
) -> String {
    let disable = state
        .machine
        .disable_actuator(sensor_id.into())
        .await
        .err()
        .map(|failure| failure.to_string());
    let lift = lift_and_restore_after_pickup(state, prepared.lease_id)
        .await
        .err();
    let cleanup = [disable, lift]
        .into_iter()
        .flatten()
        .collect::<Vec<_>>()
        .join("; ");
    if cleanup.is_empty() {
        error
    } else {
        format!("{error}; pickup cleanup also failed: {cleanup}")
    }
}

async fn drop_interrupted_production_pickup(
    state: &AppState,
    prepared: &PreparedStripFeederPickup,
    sensor_id: &str,
    pickup_head_machine_mm: [f64; 2],
    current_tip_offset: CurrentTipOffset,
    pickup_controller_z_mm: f64,
) -> Result<(), String> {
    let mut last_error = None;
    for _ in 0..MAXIMUM_RELEASE_ATTEMPTS {
        match release_pickup_part(
            state,
            prepared,
            sensor_id,
            pickup_head_machine_mm,
            current_tip_offset,
            pickup_controller_z_mm,
            true,
        )
        .await
        {
            Ok((_, _, _, true)) => {
                let _ = state
                    .machine
                    .calibration_rotate_nozzle(
                        prepared.lease_id,
                        prepared.run.nozzle_id.clone(),
                        0.0,
                    )
                    .await;
                return Ok(());
            }
            Ok(_) => last_error = Some("vacuum did not confirm release".into()),
            Err(error) => last_error = Some(error),
        }
    }
    let _ = state.machine.disable_actuator(sensor_id.into()).await;
    Err(last_error.unwrap_or_else(|| "pickup recovery did not run".into()))
}

fn build_placement_pickup_report(
    prepared: &PreparedStripFeederPickup,
    acquired: &AcquiredPlacementPart,
    release_surface_machine_mm: [f64; 2],
    release_raw_values: Vec<i64>,
    release_verification: NozzleReleaseVerificationReport,
    released: bool,
) -> StripFeederPickupQualificationReport {
    let mut artifact_names = acquired.artifact_names.clone();
    for name in &release_verification.artifact_names {
        if !artifact_names.contains(name) {
            artifact_names.push(name.clone());
        }
    }
    StripFeederPickupQualificationReport {
        algorithm_version: STRIP_FEEDER_PICKUP_ALGORITHM.into(),
        clear_xy_feed_mm_per_min: prepared.clear_xy_feed_mm_per_min,
        carried_xy_feed_mm_per_min: prepared.carried_xy_feed_mm_per_min,
        clear_z_feed_mm_per_min: prepared.clear_z_feed_mm_per_min,
        carried_z_feed_mm_per_min: prepared.carried_z_feed_mm_per_min,
        precision_z_approach_mm: prepared.precision_z_approach_mm,
        nozzle_id: prepared.run.nozzle_id.clone(),
        tip_id: prepared.geometry.tip_id.clone(),
        sensor_id: prepared.vacuum_characterization.sensor_id.clone(),
        pocket_machine_mm: acquired.pickup_center_machine_mm,
        pickup_nozzle_z_mm: Some(acquired.contact.nozzle_z_mm),
        pickup_controller_z_mm: Some(acquired.contact.controller_z_mm),
        open_nozzle_raw_values: acquired.open_nozzle_raw_values.clone(),
        pickup_samples: acquired.pickup_samples.clone(),
        held_raw_values: acquired.held_raw_values.clone(),
        held_median_raw_value: acquired.held_median_raw_value,
        vacuum_acquired: true,
        vacuum_held_after_transfer: true,
        inspection: Some(acquired.inspection.clone()),
        alignment: Some(acquired.alignment.clone()),
        rotation_captures: Vec::new(),
        disposition: if released {
            StripFeederPickupDisposition::PlacedOnBoard
        } else {
            StripFeederPickupDisposition::NotReleased
        },
        release_surface_machine_mm: Some(release_surface_machine_mm),
        release_raw_values,
        released,
        nozzle_release_verification: Some(release_verification),
        return_verification: None,
        passed: released,
        artifact_names,
        findings: vec![
            "physical placement used live top-pocket centering and bottom-vision evidence".into(),
        ],
    }
}

fn local_planar_camera_mapping(
    model: &PlanarCameraModel,
    x_px: f64,
    y_px: f64,
) -> Option<[[f64; 2]; 2]> {
    let center = model.correction_at(x_px, y_px)?;
    let x = model.correction_at(x_px + 1.0, y_px)?;
    let y = model.correction_at(x_px, y_px + 1.0)?;
    Some([
        [x[0] - center[0], y[0] - center[0]],
        [x[1] - center[1], y[1] - center[1]],
    ])
}

fn decrement_feeder_remaining(state: &AppState, feeder_id: Uuid) -> Result<(), String> {
    let feeder = state
        .store
        .list_feeders()
        .map_err(|error| error.to_string())?
        .into_iter()
        .find(|feeder| feeder.id() == feeder_id)
        .ok_or_else(|| "placement feeder disappeared".to_string())?;
    let feeder = match feeder {
        Feeder::Strip {
            id,
            name,
            part_key,
            first_pick,
            tape_pitch_mm,
            tape_width_mm,
            tape_rotation_deg,
            remaining,
        } => Feeder::Strip {
            id,
            name,
            part_key,
            first_pick,
            tape_pitch_mm,
            tape_width_mm,
            tape_rotation_deg,
            remaining: remaining.map(|value| value.saturating_sub(1)),
        },
        _ => return Err("physical placement feeder is not a strip feeder".into()),
    };
    state
        .store
        .put_feeder(&feeder)
        .map_err(|error| error.to_string())
}

fn persist_placement_progress(
    state: &AppState,
    run: &PlacementExecutionRun,
    report: &PlacementExecutionReport,
) -> Result<(), String> {
    let mut updated = run.clone();
    updated.report = Some(report.clone());
    updated.updated_at = Utc::now();
    state
        .store
        .put_placement_execution(&updated)
        .map_err(|error| error.to_string())
}

async fn capture_post_contact_board_frame(
    state: &AppState,
    run: &PlacementExecutionRun,
    step: &PlanStep,
    prepared: &PreparedStripFeederPickup,
    sample_count: u32,
    report: &mut PlacementExecutionReport,
) -> Result<GrayFrame, String> {
    let (frame, _) = capture_top_pocket_mean(
        state,
        prepared,
        [step.board_place.x_mm, step.board_place.y_mm],
        sample_count,
    )
    .await?;
    persist_placement_gray_artifact(state, run.id, BOARD_PLACEMENT_AFTER_ARTIFACT, &frame)?;
    if !report
        .artifact_names
        .iter()
        .any(|name| name == BOARD_PLACEMENT_AFTER_ARTIFACT)
    {
        report
            .artifact_names
            .push(BOARD_PLACEMENT_AFTER_ARTIFACT.into());
    }
    report
        .findings
        .push("retained a top-camera board image after physical contact".into());
    persist_placement_progress(state, run, report)?;
    Ok(frame)
}

fn ensure_no_active_placement_executions(state: &AppState) -> ApiResult<()> {
    let active = state
        .store
        .list_placement_executions()
        .map_err(ApiError::internal)?
        .into_iter()
        .any(|run| {
            matches!(
                run.status,
                OperationStatus::Pending | OperationStatus::Running
            )
        });
    if active {
        return Err(ApiError::bad_request(
            "a production single-placement execution is already active",
        ));
    }
    Ok(())
}

fn ensure_no_active_job_executions(state: &AppState) -> ApiResult<()> {
    let active = state
        .store
        .list_job_executions()
        .map_err(ApiError::internal)?
        .into_iter()
        .any(|run| {
            !matches!(
                run.status,
                JobExecutionStatus::Succeeded
                    | JobExecutionStatus::CompletedWithSkips
                    | JobExecutionStatus::Cancelled
            )
        });
    if active {
        return Err(ApiError::bad_request(
            "an unfinished job execution already exists; resume or cancel it first",
        ));
    }
    Ok(())
}

async fn get_placement_execution(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<PlacementExecutionRun>> {
    state
        .store
        .get_placement_execution(id)
        .map_err(ApiError::internal)?
        .map(Json)
        .ok_or_else(|| ApiError::not_found("placement execution not found"))
}

fn persist_automatic_placement_outcome(
    state: &AppState,
    run: &PlacementExecutionRun,
) -> anyhow::Result<Option<PlacementOutcomeRecord>> {
    let Some(report) = run.report.as_ref().filter(|report| !report.simulated) else {
        return Ok(None);
    };
    let part = state
        .store
        .list_parts()?
        .into_iter()
        .find(|part| part.key == report.part_key)
        .context("placement outcome part is not in the part library")?;
    let previous = state.store.get_placement_outcome(run.id)?;
    let (automatic_disposition, automatic_confidence) = classify_placement_outcome(report);
    let inspection = report.top_inspection.as_ref();
    let now = Utc::now();
    let outcome = PlacementOutcomeRecord {
        id: run.id,
        execution_id: run.id,
        job_id: run.job_id,
        placement_reference: report.placement_reference.clone(),
        part_key: report.part_key.clone(),
        package: part.package,
        nozzle_id: report.nozzle_id.clone(),
        placement_surface_offset_mm: report.placement_surface_offset_mm,
        placement_seating_offset_mm: report
            .successful_placement_seating_offset_mm
            .unwrap_or(report.placement_seating_offset_mm),
        automatic_algorithm_version: PLACEMENT_OUTCOME_ALGORITHM.into(),
        automatic_disposition,
        automatic_confidence: automatic_confidence.clamp(0.0, 1.0),
        operator_disposition: previous
            .as_ref()
            .and_then(|outcome| outcome.operator_disposition),
        operator_note: previous
            .as_ref()
            .and_then(|outcome| outcome.operator_note.clone()),
        measured_offset_x_mm: inspection.and_then(|inspection| inspection.offset_x_mm),
        measured_offset_y_mm: inspection.and_then(|inspection| inspection.offset_y_mm),
        measured_rotation_error_deg: inspection
            .and_then(|inspection| inspection.rotation_error_deg),
        created_at: previous.map_or(run.created_at, |outcome| outcome.created_at),
        updated_at: now,
    };
    state.store.put_placement_outcome(&outcome)?;
    Ok(Some(outcome))
}

#[derive(Debug, Serialize)]
struct PlacementOutcomeList {
    outcomes: Vec<PlacementOutcomeRecord>,
}

async fn list_placement_outcomes(
    State(state): State<AppState>,
) -> ApiResult<Json<PlacementOutcomeList>> {
    Ok(Json(PlacementOutcomeList {
        outcomes: state
            .store
            .list_placement_outcomes()
            .map_err(ApiError::internal)?,
    }))
}

async fn get_placement_outcome(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<PlacementOutcomeRecord>> {
    if let Some(outcome) = state
        .store
        .get_placement_outcome(id)
        .map_err(ApiError::internal)?
    {
        return Ok(Json(outcome));
    }
    let run = state
        .store
        .get_placement_execution(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("placement execution not found"))?;
    persist_automatic_placement_outcome(&state, &run)
        .map_err(ApiError::internal)?
        .map(Json)
        .ok_or_else(|| ApiError::bad_request("simulated placement has no physical outcome"))
}

#[derive(Debug, Deserialize)]
struct ReviewPlacementOutcomeRequest {
    disposition: PlacementOutcomeDisposition,
    #[serde(default)]
    note: Option<String>,
}

async fn review_placement_outcome(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    Json(body): Json<ReviewPlacementOutcomeRequest>,
) -> ApiResult<Json<PlacementOutcomeRecord>> {
    if body.note.as_ref().is_some_and(|note| note.len() > 500) {
        return Err(ApiError::bad_request(
            "placement outcome note must not exceed 500 bytes",
        ));
    }
    let run = state
        .store
        .get_placement_execution(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("placement execution not found"))?;
    if matches!(
        run.status,
        OperationStatus::Pending | OperationStatus::Running
    ) {
        return Err(ApiError::bad_request("placement outcome is not complete"));
    }
    let mut outcome = if let Some(outcome) = state
        .store
        .get_placement_outcome(id)
        .map_err(ApiError::internal)?
    {
        outcome
    } else {
        persist_automatic_placement_outcome(&state, &run)
            .map_err(ApiError::internal)?
            .ok_or_else(|| ApiError::bad_request("simulated placement has no physical outcome"))?
    };
    outcome.operator_disposition = Some(body.disposition);
    outcome.operator_note = body
        .note
        .map(|note| note.trim().to_string())
        .filter(|note| !note.is_empty());
    outcome.updated_at = Utc::now();
    state
        .store
        .put_placement_outcome(&outcome)
        .map_err(ApiError::internal)?;
    Ok(Json(outcome))
}

async fn get_part_placement_process(
    State(state): State<AppState>,
    Path((id, nozzle_id, surface_offset_mm)): Path<(Uuid, String, f64)>,
) -> ApiResult<Json<PlacementProcessEstimate>> {
    if nozzle_id.trim().is_empty() {
        return Err(ApiError::bad_request("placement process needs a nozzle ID"));
    }
    if !surface_offset_mm.is_finite() || !(0.0..=10.0).contains(&surface_offset_mm) {
        return Err(ApiError::bad_request(
            "placement surface offset must be finite and between 0.0 and 10.0 mm",
        ));
    }
    let part = state
        .store
        .get_part(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("part not found"))?;
    let outcomes = state
        .store
        .list_placement_outcomes()
        .map_err(ApiError::internal)?;
    Ok(Json(estimate_placement_process(
        &part,
        &nozzle_id,
        surface_offset_mm,
        &outcomes,
    )))
}

async fn reanalyze_placement_source_pose(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<PlacementExecutionRun>> {
    let mut run = state
        .store
        .get_placement_execution(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("placement execution not found"))?;
    if matches!(
        run.status,
        OperationStatus::Pending | OperationStatus::Running
    ) {
        return Err(ApiError::bad_request("placement evidence is not complete"));
    }
    let mut report = run
        .report
        .clone()
        .ok_or_else(|| ApiError::bad_request("placement has no retained report"))?;
    if report.simulated {
        return Err(ApiError::bad_request(
            "simulated placement has no retained source image",
        ));
    }
    let registration = state
        .store
        .list_strip_feeder_registrations()
        .map_err(ApiError::internal)?
        .into_iter()
        .find(|registration| {
            registration.calibration_id == run.calibration_id
                && registration.active_feeder_id == Some(report.feeder_id)
        })
        .ok_or_else(|| ApiError::bad_request("placement feeder registration is missing"))?;
    let pocket_index = report
        .pocket_index
        .ok_or_else(|| ApiError::bad_request("placement has no retained pocket index"))?;
    let candidate_pocket_machine_mm = report
        .source_pose_inspection
        .as_ref()
        .map(|inspection| inspection.candidate_nominal_center_machine_mm)
        .or_else(|| {
            registration
                .pockets
                .iter()
                .find(|pocket| pocket.pocket_index == pocket_index)
                .map(|pocket| {
                    pocket
                        .measured_center_machine_mm
                        .unwrap_or(pocket.nominal_center_machine_mm)
                })
        })
        .or_else(|| {
            registration
                .pocket_centers_machine_mm
                .get(pocket_index as usize)
                .copied()
        })
        .ok_or_else(|| ApiError::bad_request("placement pocket center is not retained"))?;
    let candidate_camera_pose = report
        .source_pose_inspection
        .as_ref()
        .map(|inspection| inspection.candidate_camera_pose)
        .unwrap_or(Pose {
            x_mm: candidate_pocket_machine_mm[0],
            y_mm: candidate_pocket_machine_mm[1],
            z_mm: state.profile.safe_z_mm,
            rotation_deg: 0.0,
        });
    let (media_type, data) = state
        .store
        .get_placement_execution_artifact(id, SOURCE_POCKET_BEFORE_ARTIFACT)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("placement source-pocket image not found"))?;
    if media_type != "image/png" {
        return Err(ApiError::bad_request(
            "placement source-pocket artifact is not a PNG",
        ));
    }
    let candidate = decode_gray_png(&data).map_err(ApiError::internal)?;
    let references =
        load_source_pose_references(&state, &registration).map_err(ApiError::bad_request)?;
    let (_, camera_model) = load_workspace_camera_model(&state, run.calibration_id)?;
    let allow_face_texture_change = matches!(
        registration_part_orientation(&state, &registration)?.0,
        PartOrientation::AxisSymmetric
    );
    let source_pose_registration = registration.clone();
    let inspection = tokio::task::spawn_blocking(move || {
        inspect_source_pose_against_references(
            references,
            &candidate,
            candidate_camera_pose,
            candidate_pocket_machine_mm,
            &camera_model,
            &source_pose_registration,
            allow_face_texture_change,
            SOURCE_POCKET_POSE_INSPECTION_ARTIFACT,
        )
    })
    .await
    .map_err(ApiError::internal)?
    .map_err(ApiError::internal)?;
    persist_placement_rgb_artifact(
        &state,
        id,
        SOURCE_POCKET_POSE_INSPECTION_ARTIFACT,
        &inspection.preview,
    )
    .map_err(ApiError::internal)?;
    if let Some(prior) = report.source_pose_inspection.as_ref() {
        report
            .findings
            .retain(|finding| !prior.findings.contains(finding));
    }
    report
        .findings
        .retain(|finding| !finding.contains("retained source-pose reanalysis"));
    report.findings.extend(inspection.report.findings.clone());
    report.findings.push(if inspection.report.passed {
        "retained source-pose reanalysis passed".into()
    } else {
        "retained source-pose reanalysis failed".into()
    });
    if !report
        .artifact_names
        .iter()
        .any(|name| name == SOURCE_POCKET_POSE_INSPECTION_ARTIFACT)
    {
        report
            .artifact_names
            .push(SOURCE_POCKET_POSE_INSPECTION_ARTIFACT.into());
    }
    report.source_pose_inspection = Some(inspection.report);
    run.report = Some(report);
    run.updated_at = Utc::now();
    state
        .store
        .put_placement_execution(&run)
        .map_err(ApiError::internal)?;
    Ok(Json(run))
}

async fn reanalyze_placement_execution(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> ApiResult<Json<PlacementExecutionRun>> {
    let mut run = state
        .store
        .get_placement_execution(id)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("placement execution not found"))?;
    if matches!(
        run.status,
        OperationStatus::Pending | OperationStatus::Running
    ) {
        return Err(ApiError::bad_request("placement evidence is not complete"));
    }
    let report = run
        .report
        .clone()
        .ok_or_else(|| ApiError::bad_request("placement has no retained report"))?;
    if report.simulated {
        return Err(ApiError::bad_request(
            "simulated placement has no retained camera evidence",
        ));
    }
    let part = state
        .store
        .list_parts()
        .map_err(ApiError::internal)?
        .into_iter()
        .find(|part| part.key == report.part_key)
        .ok_or_else(|| ApiError::bad_request("placement part is not in the part library"))?;
    let body_width_mm = part
        .body_width_mm
        .filter(|value| value.is_finite() && *value > 0.0)
        .ok_or_else(|| ApiError::bad_request("placement part has no valid body width"))?;
    let body_length_mm = part
        .body_length_mm
        .filter(|value| value.is_finite() && *value > 0.0)
        .ok_or_else(|| ApiError::bad_request("placement part has no valid body length"))?;
    let (body_width_mm, body_length_mm) = if body_width_mm <= body_length_mm {
        (body_width_mm, body_length_mm)
    } else {
        (body_length_mm, body_width_mm)
    };
    let load_frame = |name: &str| -> ApiResult<GrayFrame> {
        let (media_type, data) = state
            .store
            .get_placement_execution_artifact(id, name)
            .map_err(ApiError::internal)?
            .ok_or_else(|| ApiError::not_found(format!("placement artifact {name} not found")))?;
        if media_type != "image/png" {
            return Err(ApiError::bad_request(format!(
                "placement artifact {name} is not a PNG"
            )));
        }
        decode_gray_png(&data).map_err(ApiError::internal)
    };
    let before = load_frame(BOARD_PLACEMENT_BEFORE_ARTIFACT)?;
    let after = load_frame(BOARD_PLACEMENT_AFTER_ARTIFACT)?;
    let (_, top_camera_model) = load_workspace_camera_model(&state, run.calibration_id)?;
    let expected_center_px = [top_camera_model.center_x_px, top_camera_model.center_y_px];
    let top_mapping = local_planar_camera_mapping(
        &top_camera_model,
        expected_center_px[0],
        expected_center_px[1],
    )
    .ok_or_else(|| ApiError::bad_request("top-camera placement mapping is invalid"))?;
    let pickup_center_offset_mm = state
        .profile
        .strip_feeder_pickup
        .as_ref()
        .map(|profile| profile.maximum_part_offset_mm)
        .unwrap_or(1.0);
    let maximum_center_offset_mm = (0.5 * body_width_mm).max(0.25).min(pickup_center_offset_mm);
    let after_for_model = after.clone();
    let expected_rotation_deg = report.board_place.rotation_deg;
    let orientation = report.part_orientation;
    let inspection = tokio::task::spawn_blocking(move || {
        inspect_placed_part_with_orientation(
            &before,
            &after,
            expected_center_px,
            top_mapping,
            body_width_mm,
            body_length_mm,
            report.board_place.rotation_deg,
            maximum_center_offset_mm,
            MAX_PLACED_PART_ROTATION_ERROR_DEG,
            report.part_orientation,
            BOARD_PLACEMENT_INSPECTION_ARTIFACT,
        )
        .map(|inspection| (report, inspection))
    })
    .await
    .map_err(ApiError::internal)?
    .map_err(ApiError::internal)?;
    let (mut report, inspection) = inspection;
    persist_placement_rgb_artifact(
        &state,
        id,
        BOARD_PLACEMENT_INSPECTION_ARTIFACT,
        &inspection.preview,
    )
    .map_err(ApiError::internal)?;
    let active_inspection = if let Some(learned) = analyze_and_persist_placement_verification(
        &state,
        id,
        &after_for_model,
        &inspection,
        top_mapping,
        body_width_mm,
        body_length_mm,
        expected_rotation_deg,
        maximum_center_offset_mm,
        orientation,
    )
    .await
    {
        for name in [
            learned.comparison.report_artifact_name.clone(),
            learned.comparison.preview_artifact_name.clone(),
            learned.comparison.crop_artifact_name.clone(),
        ] {
            if !report.artifact_names.contains(&name) {
                report.artifact_names.push(name);
            }
        }
        report.top_inspection_comparison = Some(learned.comparison);
        learned.active
    } else {
        report.top_inspection_comparison = None;
        inspection.report.clone()
    };
    report.top_inspection = Some(active_inspection.clone());
    if let Some(stage) = report
        .stages
        .iter_mut()
        .find(|stage| stage.stage == PlacementExecutionStage::TopInspection)
    {
        stage.passed = active_inspection.passed;
        stage.message = if active_inspection.passed {
            "top vision confirmed the placed component".into()
        } else {
            "top vision did not confirm the placed component".into()
        };
    }
    report
        .findings
        .retain(|finding| !finding.contains("retained package-aware placement reanalysis"));
    report.findings.push(if active_inspection.passed {
        "retained placement reanalysis passed".into()
    } else {
        "retained placement reanalysis failed".into()
    });
    report.passed = active_inspection.passed
        && report
            .stages
            .iter()
            .filter(|stage| stage.stage != PlacementExecutionStage::Complete)
            .all(|stage| stage.passed);
    run.status = if report.passed {
        OperationStatus::Succeeded
    } else {
        OperationStatus::Failed
    };
    run.message = Some(if report.passed {
        "Retained package-aware placement reanalysis passed".into()
    } else {
        "Retained package-aware placement reanalysis failed".into()
    });
    run.report = Some(report);
    run.updated_at = Utc::now();
    state
        .store
        .put_placement_execution(&run)
        .map_err(ApiError::internal)?;
    persist_automatic_placement_outcome(&state, &run).map_err(ApiError::internal)?;
    Ok(Json(run))
}

async fn get_placement_execution_artifact(
    State(state): State<AppState>,
    Path((id, name)): Path<(Uuid, String)>,
) -> ApiResult<Response> {
    let (media_type, data) = state
        .store
        .get_placement_execution_artifact(id, &name)
        .map_err(ApiError::internal)?
        .ok_or_else(|| ApiError::not_found("placement execution artifact not found"))?;
    Response::builder()
        .status(StatusCode::OK)
        .header(header::CONTENT_TYPE, media_type)
        .header(header::CACHE_CONTROL, "no-store")
        .body(axum::body::Body::from(data))
        .map_err(ApiError::internal)
}

