    #[tokio::test]
    async fn profiled_camera_reuse_joins_an_existing_scope() {
        let state = test_state();
        let mut seeded = ProfiledCaptureContext::default();
        seeded.timing.insert(
            "top_camera".into(),
            ProfiledCameraTiming {
                open_count: 1,
                ..ProfiledCameraTiming::default()
            },
        );
        let context = Arc::new(tokio::sync::Mutex::new(seeded));

        let (value, timing) = PROFILED_CAPTURE_CONTEXT
            .scope(
                context,
                with_profiled_camera_reuse(&state, async {
                    let context = PROFILED_CAPTURE_CONTEXT.with(Arc::clone);
                    context
                        .lock()
                        .await
                        .timing
                        .entry("top_camera".into())
                        .or_default()
                        .capture_count += 2;
                    42_u32
                }),
            )
            .await;

        assert_eq!(value, 42);
        assert_eq!(timing["top_camera"]["open_count"], 0);
        assert_eq!(timing["top_camera"]["capture_count"], 2);
    }

