    #[test]
    fn inventory_registration_match_rejects_a_false_tape_width() {
        let lane = test_inventory_lane(0, 100.0);
        let mut registration = test_pickup_registration(Utc::now());
        registration.pick_centerline_machine_mm = [[100.2, 204.0], [100.2, 184.0]];
        registration.tape_rotation_deg = -90.0;
        assert!(inventory_registration_distance_mm(&lane, &registration).is_some());

        registration.tape_width_mm = 12.0;
        assert!(inventory_registration_distance_mm(&lane, &registration).is_none());
    }

    #[test]
    fn inventory_capture_selection_balances_classes_across_lanes() {
        let inventory = test_inventory_report(vec![
            test_inventory_lane(0, 100.0),
            test_inventory_lane(1, 112.0),
            test_inventory_lane(2, 124.0),
        ]);
        let bindings = inventory
            .lanes
            .iter()
            .map(|lane| {
                let mut registration = test_pickup_registration(Utc::now());
                registration.id = Uuid::new_v4();
                InventoryRegistrationBinding {
                    inventory_index: lane.inventory_index,
                    created: false,
                    registration,
                }
            })
            .collect::<Vec<_>>();
        let targets =
            select_inventory_source_capture_targets(&inventory, &bindings, &BTreeSet::new(), 6, 6)
                .unwrap();

        assert_eq!(targets.len(), 12);
        for inventory_index in 0..3 {
            assert_eq!(
                targets
                    .iter()
                    .filter(|target| target.inventory_index == inventory_index)
                    .count(),
                4
            );
        }
        assert_eq!(
            targets
                .iter()
                .filter(|target| { target.observation.occupancy == StripPocketOccupancy::Occupied })
                .count(),
            6
        );
    }

    #[test]
    fn live_holdout_defaults_to_the_first_available_occupied_pocket() {
        let now = Utc::now();
        let mut registration = test_pickup_registration(now);
        registration.ensure_pocket_state();
        for pocket in &mut registration.pockets {
            pocket.occupancy = StripPocketOccupancy::Occupied;
            pocket.status = StripFeederPocketStatus::Available;
        }
        registration.pockets[0].status = StripFeederPocketStatus::Consumed;
        registration.pockets[1].status = StripFeederPocketStatus::NeedsReview;

        assert_eq!(live_holdout_pocket_index(&registration, None).unwrap(), 2);
        assert_eq!(
            live_holdout_pocket_index(&registration, Some(3)).unwrap(),
            3
        );
    }

    #[test]
    fn stable_placement_residuals_produce_opposite_pickup_correction() {
        let correction =
            bounded_pickup_feedback_correction(&[[0.22, -0.32], [0.30, -0.18]]).unwrap();

        assert!((correction[0] + 0.26).abs() < 1e-9);
        assert!((correction[1] - 0.25).abs() < 1e-9);
    }

    #[test]
    fn pickup_feedback_rejects_weak_divergent_or_large_evidence() {
        assert!(bounded_pickup_feedback_correction(&[[0.20, -0.20]]).is_none());
        assert!(bounded_pickup_feedback_correction(&[[0.10, 0.10], [0.35, 0.35],]).is_none());
        assert!(bounded_pickup_feedback_correction(&[[0.40, 0.30], [0.40, 0.30],]).is_none());
    }

