    #[test]
    fn vacuum_probe_moves_laterally_at_level_and_retracts_before_return() {
        let motion = VacuumProbeMotion {
            probe_head_x_mm: 242.0,
            probe_head_y_mm: 261.0,
            return_head_x_mm: 220.0,
            return_head_y_mm: 190.0,
            approach_controller_z_mm: 5.0,
            level_controller_z_mm: 31.5,
            xy_feed_mm_per_min: 300.0,
            z_approach_feed_mm_per_min: 300.0,
            z_retract_feed_mm_per_min: 1200.0,
        };

        assert_eq!(
            motion.level_probe_target(),
            JogTarget {
                x_mm: 242.0,
                y_mm: 261.0,
                z_mm: 31.5,
                rotation_deg: None,
            }
        );
        assert_eq!(motion.approach_probe_target().z_mm, 5.0);
        let restore = motion.restore_targets();
        assert_eq!(restore[0].0, motion.level_probe_target());
        assert_eq!(restore[0].1, 1200.0);
        assert_eq!(restore[1].0, motion.level_return_target());
    }

    #[test]
    fn narrowed_vacuum_search_keeps_clear_open_sampling_and_contact_bound() {
        let search = VacuumProbeSearch {
            start_nozzle_z_mm: 3.5,
            end_nozzle_z_mm: 3.2,
        };
        let targets = search.descent_targets(5.0, 0.1);
        assert_eq!(targets.len(), 4);
        assert!((targets[0] - 3.5).abs() < 1e-9);
        assert!((targets[3] - 3.2).abs() < 1e-9);
        assert!(targets.iter().all(|value| *value >= 3.2));
    }

    #[test]
    fn characterization_search_uses_the_full_approved_interval() {
        let search = VacuumProbeSearch::around_characterization_contact(3.4, 0.3, 5.0, 3.0);
        let targets = search.descent_targets(5.0, 0.1);

        assert!((search.start_nozzle_z_mm - 3.7).abs() < 1e-9);
        assert!((search.end_nozzle_z_mm - 3.0).abs() < 1e-9);
        assert!((targets[0] - 3.7).abs() < 1e-9);
        assert!((targets[7] - 3.0).abs() < 1e-9);
    }

    #[test]
    fn characterization_search_does_not_exceed_the_profile_z_limit() {
        let search = VacuumProbeSearch::around_characterization_contact(3.0, 0.3, 5.0, 3.0);

        assert!((search.end_nozzle_z_mm - 3.0).abs() < 1e-9);
    }

    #[test]
    fn fine_home_search_uses_the_full_allowed_correction_range() {
        let search = VacuumProbeSearch::around_fine_home_contact(3.4, 5.0, 3.0);
        assert!((search.start_nozzle_z_mm - 3.9).abs() < 1e-9);
        assert!((search.end_nozzle_z_mm - 3.0).abs() < 1e-9);
    }

    #[test]
    fn failed_fine_home_message_keeps_sensor_evidence() {
        let search = VacuumProbeSearch {
            start_nozzle_z_mm: 3.9,
            end_nozzle_z_mm: 3.0,
        };
        let samples = [VacuumProbeSample {
            nozzle_z_mm: 3.0,
            controller_z_mm: 3.0,
            raw_values: vec![231, 230, 230],
            median_raw_value: 230.0,
            signal_delta_counts: 7.0,
        }];
        let message = fine_home_missing_contact_message(search, &[237, 237, 238], &samples);
        assert!(message.contains("nozzle Z3.900 to Z3.000"));
        assert!(message.contains("open median 237.0"));
        assert!(message.contains("signal deltas [Z3.000:7.0]"));
        assert!(message.starts_with("Fine home"));
        assert!(message.ends_with('.'));
    }

    #[test]
    fn failed_characterization_message_keeps_sensor_evidence() {
        let search = VacuumProbeSearch {
            start_nozzle_z_mm: 3.7,
            end_nozzle_z_mm: 3.3,
        };
        let samples = [VacuumProbeSample {
            nozzle_z_mm: 3.3,
            controller_z_mm: 3.3,
            raw_values: vec![231, 230, 230],
            median_raw_value: 230.0,
            signal_delta_counts: 7.0,
        }];
        let message = characterization_missing_contact_message(search, &[237, 237, 238], &samples);

        assert!(message.contains("nozzle Z3.700 to Z3.300"));
        assert!(message.contains("open median 237.0"));
        assert!(message.contains("signal deltas [Z3.300:7.0]"));
        assert!(message.starts_with("Vacuum characterization"));
        assert!(message.ends_with('.'));
    }

    #[test]
    fn vacuum_tip_offset_uses_the_common_bottom_camera_reference() {
        let reference = CalibratedHeadReference {
            top_camera_controller_x_mm: 218.83592009024375,
            top_camera_controller_y_mm: 146.87577636371486,
            top_camera_working_plane_mapping: [[-0.0135, 0.0], [0.0, 0.0135]],
            bottom_camera_mapping: [[-0.036, 0.0], [0.0, -0.036]],
        };
        let offset = reference
            .current_tip_offset(Pose {
                x_mm: 242.33309363338415,
                y_mm: 215.49237867055368,
                z_mm: 31.5,
                rotation_deg: 720.0,
            })
            .unwrap();
        assert!((offset.x_mm + 23.4971735431404).abs() < 1e-12);
        assert!((offset.y_mm + 68.61660230683882).abs() < 1e-12);

        let wrong_reciprocal_x_mm = 220.28236097458588 - 242.33309363338415;
        let wrong_reciprocal_y_mm = 144.6764269848319 - 215.49237867055368;
        assert!((offset.x_mm - wrong_reciprocal_x_mm + 1.44644088434213).abs() < 1e-12);
        assert!((offset.y_mm - wrong_reciprocal_y_mm - 2.19934937888296).abs() < 1e-12);
    }

    #[test]
    fn vacuum_target_averages_camera_observations() {
        let target = mean_fiducial_detection(&[
            FiducialDetection {
                x_px: 650.0,
                y_px: 358.0,
                diameter_px: 376.0,
                confidence: 0.8,
            },
            FiducialDetection {
                x_px: 652.0,
                y_px: 360.0,
                diameter_px: 378.0,
                confidence: 0.9,
            },
        ])
        .unwrap();
        assert_eq!(target.x_px, 651.0);
        assert_eq!(target.y_px, 359.0);
        assert_eq!(target.diameter_px, 377.0);
        assert!((target.confidence - 0.85).abs() < 1e-12);
        assert!(mean_fiducial_detection(&[]).is_none());
    }

